import React from "react";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { commonUtils } from "_helpers";
import workItemUtils from "_helpers/workitem.utils";
import LuxCreateSectionCard from "views/common/create/LuxCreateSectionCard";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";
import { CREATE_EMPLOYEE_SECTIONS } from "./createEmployee.sections";
import CreateEmployeeSkillsPanel from "./CreateEmployeeSkillsPanel";

function CreateEmployeeForm({
  employeeRequest,
  readOnly,
  editMode,
  fieldConfig,
  createConfig,
  projectAppConfig,
  allEmployees,
  allSubRoles,
  allTeams,
  allProjectTeamAccounts,
  onChange,
  onFormError,
  permission,
  isPageView,
  enabledExitDateUpdateButton,
  onUpdateExitDate,
  getSortedTeamNames,
  isSectionVisible,
}) {
  if (!employeeRequest) return null;

  const meta = CREATE_EMPLOYEE_SECTIONS;
  const formProps = {
    readOnly,
    fieldConfig,
    mappingObject: employeeRequest,
    onChange,
    onFormError,
  };

  return (
    <>
      {isSectionVisible("basic") && (
        <LuxCreateSectionCard
          icon={meta.basic.icon}
          title={meta.basic.title}
          hint={meta.basic.hint}
          description={meta.basic.description}
        >
          <LuxCreateFieldGroup
            title="Identity & contact"
            description="Name and work email are used for login, notifications, and the employee directory."
          >
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                inputtype="text"
                label="Employee name"
                name="name"
                placeholder="Full name"
                datatype="alpnumspace"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                inputtype="email"
                label="Work email"
                name="email"
                placeholder="name@company.com"
                datatype="email"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                inputtype="text"
                label="Mobile number"
                name="mobileNumber"
                placeholder="Mobile"
                datatype="num"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Gender"
                name="gender"
                placeholder="Gender"
                options={[
                  { value: "male", label: "Male" },
                  { value: "female", label: "Female" },
                ]}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="dateselect"
                label="Date of birth"
                name="dateOfBirth"
                time={false}
                minDate={new Date(1960, 0, 1)}
                maxDate={new Date(2000, 0, 1)}
                currentDate={new Date(1980, 0, 1)}
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          <LuxCreateFieldGroup
            title="Employment"
            description="Codes and dates that drive HR reports, tenure, and compliance."
          >
            <LuxCreateField>
              <CustomInput
                {...formProps}
                inputtype="text"
                label="Employee code"
                name="empCode"
                placeholder="Code"
                datatype="alpnum"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Employee type"
                name="empType"
                placeholder="Type"
                isAppConfig={true}
                createConfig={createConfig}
                configName="empType"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="dateselect"
                label="Date of joining"
                name="dateOfJoin"
                time={false}
                minDate={new Date(1980, 0, 1)}
                maxDate={new Date()}
                currentDate={new Date()}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Location"
                name="location"
                placeholder="Location"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Qualification"
                name="qualification"
                placeholder="Qualification"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Designation"
                name="designation"
                placeholder="Designation"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          {isPageView &&
            permission &&
            permission.updateUserExitDateEnabled && (
              <LuxCreateFieldGroup
                title="Exit date (admin)"
                description="Set a future exit date for offboarding workflows. Requires a separate update action."
                columns={1}
              >
                <div className="lux-create-exit-row">
                  <LuxCreateField>
                    <CustomInput
                      {...formProps}
                      className="colorRed"
                      type="dateselect"
                      label="Exit date"
                      name="exitDate"
                      time={false}
                      minDate={new Date(2022, 0, 1)}
                      maxDate={new Date(2050, 0, 1)}
                      currentDate={new Date()}
                    />
                  </LuxCreateField>
                  <button
                    type="button"
                    disabled={!enabledExitDateUpdateButton}
                    className="lux-create-exit-row__btn"
                    onClick={onUpdateExitDate}
                  >
                    Update exit date
                  </button>
                </div>
              </LuxCreateFieldGroup>
            )}
        </LuxCreateSectionCard>
      )}

      {isSectionVisible("access") && (
        <LuxCreateSectionCard
          icon={meta.access.icon}
          title={meta.access.title}
          hint={meta.access.hint}
          description={meta.access.description}
        >
          <LuxCreateFieldGroup
            title="Application access"
            description="Default team scopes data and menus; the user role defines permissions within that team."
          >
            <LuxCreateField>
              <CustomInput
                {...formProps}
                readOnlyValue={
                  employeeRequest.defaultUserTeamDetails &&
                  employeeRequest.defaultUserTeamDetails.name
                }
                type="select"
                label="Default team"
                name="userTeamId"
                isIdAsSelectValue={false}
                placeholder="Team"
                options={
                  allTeams && commonUtils.convertObjectToSelectObject(allTeams)
                }
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                readOnly={
                  readOnly ||
                  (editMode &&
                    allSubRoles &&
                    allSubRoles.find(
                      (role) => employeeRequest.userRole === role.id
                    ) === undefined)
                }
                readOnlyValue={
                  employeeRequest.userAccessDetails &&
                  employeeRequest.userAccessDetails.name
                }
                type="select"
                label="User role"
                name="userRole"
                placeholder="Role"
                options={
                  allSubRoles &&
                  commonUtils.convertObjectToSelectObject(allSubRoles)
                }
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          <LuxCreateFieldGroup
            title="Extended team visibility"
            description="Grant read or work access to additional teams beyond the default."
          >
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                readOnlyValue={getSortedTeamNames(
                  employeeRequest.additionalUserTeamDetails
                )}
                type="select"
                label="Additional team access"
                name="additionalUserTeamIds"
                placeholder="Teams"
                options={
                  allTeams && commonUtils.convertObjectToSelectObject(allTeams)
                }
                multi={true}
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>
        </LuxCreateSectionCard>
      )}

      {isSectionVisible("signIn") && (
        <LuxCreateSectionCard
          icon={meta.signIn.icon}
          title={meta.signIn.title}
          hint={meta.signIn.hint}
          description={meta.signIn.description}
        >
          <LuxCreateFieldGroup
            title="Authentication & sync"
            description="Toggle login and integration options according to your organization's policy."
            columns={3}
          >
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="radios"
                label="App login disabled"
                name="appLoginDisabled"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="radios"
                label="Device login enabled"
                name="deviceAppEnabled"
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="radios"
                label="Leave sync enabled"
                name="extLeaveSyncEnabled"
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>
        </LuxCreateSectionCard>
      )}

      {isSectionVisible("organization") && (
        <LuxCreateSectionCard
          icon={meta.organization.icon}
          title={meta.organization.title}
          hint={meta.organization.hint}
          description={meta.organization.description}
        >
          <LuxCreateFieldGroup
            title="Reporting structure"
            description="Optional leadership links for org charts and approvals."
          >
            <LuxCreateField>
              <CustomInput
                {...formProps}
                readOnlyValue={
                  (employeeRequest.managerDetails &&
                    employeeRequest.managerDetails.name) ||
                  "Nil"
                }
                type="select"
                label="Reporting manager"
                name="managerId"
                placeholder="Manager"
                options={
                  allEmployees &&
                  commonUtils.convertObjectToSelectObject(allEmployees)
                }
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                readOnlyValue={
                  (employeeRequest.departmentLeadDetails &&
                    employeeRequest.departmentLeadDetails.name) ||
                  "Nil"
                }
                type="select"
                label="Department lead"
                name="deptLeadId"
                placeholder="Department lead"
                options={
                  allEmployees &&
                  commonUtils.convertObjectToSelectObject(allEmployees)
                }
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                readOnlyValue={
                  (employeeRequest.lobHeadDetails &&
                    employeeRequest.lobHeadDetails.name) ||
                  "Nil"
                }
                type="select"
                label="LOB head"
                name="lobHeadId"
                placeholder="LOB head"
                options={
                  allEmployees &&
                  commonUtils.convertObjectToSelectObject(allEmployees)
                }
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          <LuxCreateFieldGroup
            title="Practice & service"
            description="Align the employee with how work is categorized in projects and reporting."
          >
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                type="select"
                label="Service lines"
                name="serviceLines"
                placeholder="Service lines"
                multi={true}
                options={
                  projectAppConfig &&
                  workItemUtils.getServiceLines(projectAppConfig)
                }
              />
            </LuxCreateField>
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                type="select"
                label="Service category"
                name="serviceCategory"
                placeholder="Category"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Primary practice"
                name="department"
                placeholder="Practice"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Secondary practice"
                name="subDepartment"
                placeholder="Secondary practice"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Division"
                name="division"
                placeholder="Division"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Primary client"
                name="primaryClient"
                placeholder="Client"
                options={
                  allProjectTeamAccounts &&
                  commonUtils.getAccountOptions(allProjectTeamAccounts)
                }
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          <LuxCreateFieldGroup
            title="Career & credentials"
            description="Band, grade, domains, and certifications for capacity and staffing views."
          >
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Band"
                name="band"
                placeholder="Band"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField>
              <CustomInput
                {...formProps}
                type="select"
                label="Grade"
                name="grade"
                placeholder="Grade"
                isAppConfig={true}
                createConfig={createConfig}
              />
            </LuxCreateField>
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                type="select"
                label="Domains"
                name="domains"
                placeholder="Domains"
                isAppConfig={true}
                createConfig={createConfig}
                multi={true}
              />
            </LuxCreateField>
            <LuxCreateField span="full">
              <CustomInput
                {...formProps}
                type="select"
                label="Certifications"
                name="certifications"
                placeholder="Certifications"
                isAppConfig={true}
                createConfig={createConfig}
                multi={true}
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>
        </LuxCreateSectionCard>
      )}

      {isSectionVisible("skills") && (
        <LuxCreateSectionCard
          className="lux-create-section--menu-visible"
          icon={meta.skills.icon}
          title={meta.skills.title}
          hint={meta.skills.hint}
          description={meta.skills.description}
        >
          <CreateEmployeeSkillsPanel
            name="skills"
            onChange={onChange}
            readOnly={readOnly}
            createConfig={createConfig}
            fieldConfig={fieldConfig}
            mappingObject={employeeRequest}
            onFormError={onFormError}
          />
        </LuxCreateSectionCard>
      )}
    </>
  );
}

export default CreateEmployeeForm;
