export function ResourcesHeroActions({ dataSource, demoLabel, children }) {
  useReportPageDataSource(dataSource);
  return (
    <div className="lux-resources-hero__actions">
      <div className="lux-resources-hero__buttons">{children}</div>
    </div>
  );
}

export function ResourcesActionButton({
  to,
  onClick,
  children,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
}) {
  const classes = classNames("lux-onb-action lux-resources-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );

  if (to) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function ResourcesKpiStrip({ cards, loading, className }) {
  return (
    <LuxKpiStrip
      cards={cards}
      loading={loading}
      className={classNames("lux-resources-kpi-strip", className)}
    />
  );
}

/**
 * Luxury section header for Resources consoles — icon tile, eyebrow, title, lede, actions.
 */
export function ResourcesSectionHead({
  eyebrow,
  title,
  subtitle,
  icon = "fe fe-layers",
  tone = "violet",
  badge,
  actions,
  className,
}) {
  return (
    <header className={classNames("lux-resources-section-head", tone && `is-${tone}`, className)}>
      <div className="lux-resources-section-head__main">
        <span className="lux-resources-section-head__icon" aria-hidden="true">
          <i className={icon} />
        </span>
        <div className="lux-resources-section-head__copy">
          {(eyebrow || badge != null) && (
            <div className="lux-resources-section-head__meta">
              {eyebrow ? (
                <span className="lux-resources-section-head__eyebrow">{sanitizeUiCopy(eyebrow)}</span>
              ) : null}
              {badge != null && badge !== "" ? (
                <span className="lux-resources-section-head__badge">{badge}</span>
              ) : null}
            </div>
          )}
          <h2 className="lux-resources-section-head__title">{title}</h2>
          {subtitle ? (
            <p className="lux-resources-section-head__sub">{sanitizeUiCopy(subtitle)}</p>
          ) : null}
        </div>
      </div>
      {actions ? <div className="lux-resources-section-head__actions">{actions}</div> : null}
    </header>
  );
}

/**
 * Compact luxury register shell (matches staffing Demand queue atelier).
 */
export function ResourcesRegisterAtelier(props) {
  return <LuxRegisterAtelier {...props} />;
}
