import originalMoment from "moment";
import { extendMoment } from "moment-range";
import dateUtils from "_helpers/date.utils";
import { readSummaryExpanded } from "_helpers/summaryExpandedStorage";

const moment = extendMoment(originalMoment);

export function parseJoinMoment(val) {
  if (!val) return null;
  let m = moment(val, moment.ISO_8601, true);
  if (m.isValid()) return m;
  m = moment(val, dateUtils.CLIENT_DATE_FORMAT, true);
  if (m.isValid()) return m;
  m = moment(val);
  return m.isValid() ? m : null;
}

export function getTenureLabel(dateOfJoin) {
  const join = parseJoinMoment(dateOfJoin);
  if (!join) return null;
  const months = moment().diff(join, "months");
  if (months < 1) return "New joiner";
  if (months < 12) return `${months} mo tenure`;
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (rem === 0) return `${years} yr${years > 1 ? "s" : ""} tenure`;
  return `${years}y ${rem}m tenure`;
}

export function getTenureMonths(dateOfJoin) {
  const join = parseJoinMoment(dateOfJoin);
  if (!join) return 0;
  return Math.max(0, moment().diff(join, "months"));
}

export function getTenureProgress(dateOfJoin) {
  const months = getTenureMonths(dateOfJoin);
  const pct = Math.min(100, Math.round((months / 60) * 100));
  return { months, pct, yearsDisplay: (months / 12).toFixed(1) };
}

export function formatProfileDate(val) {
  if (!val) return null;
  try {
    return dateUtils.convertDateFormat(val);
  } catch (e) {
    return val;
  }
}

export function parseDisplayValueList(val) {
  const formatted = formatDisplayValue(val);
  if (!formatted) return [];
  return formatted
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

export function formatDisplayValue(val) {
  if (val == null || val === "") return null;
  if (Array.isArray(val)) {
    const items = val
      .map((item) => {
        if (item == null || item === "") return null;
        if (typeof item === "object") return item.name || item.label || item.value;
        return String(item);
      })
      .filter(Boolean);
    return items.length ? items.join(", ") : null;
  }
  if (typeof val === "object") {
    return val.name || val.label || val.value || null;
  }
  if (typeof val === "boolean") return val ? "Yes" : "No";
  return String(val);
}

export function isAppLoginEnabled(employee) {
  if (!employee) return false;
  return employee.appLoginDisabled === false || employee.appLoginDisabled === "false";
}

export function getEmployeeStatusMeta(employee) {
  if (!employee) return { label: "Unknown", tone: "slate" };
  if (employee.deleted) return { label: "Deleted", tone: "rose" };
  if (!employee.active) return { label: "Inactive", tone: "slate" };
  return { label: "Active", tone: "green" };
}

export function getSkillLabel(employee, key) {
  if (!employee) return null;
  const nested = employee.skills && employee.skills[key];
  if (nested) return formatDisplayValue(nested);
  return formatDisplayValue(employee[key]);
}

export function collectSkillChips(employee) {
  if (!employee) return [];
  const chips = [];
  ["primarySkill", "secondarySkill", "tertiarySkill"].forEach((key) => {
    const label = getSkillLabel(employee, key);
    if (label) chips.push({ key, label, tier: key.replace("Skill", "") });
  });
  const additional =
    employee.skills &&
    employee.skills.additionalSkills &&
    Array.isArray(employee.skills.additionalSkills)
      ? employee.skills.additionalSkills
      : [];
  additional.forEach((skill, index) => {
    const label = formatDisplayValue(skill);
    if (label) chips.push({ key: `add-${index}`, label, tier: "additional" });
  });
  return chips;
}

export function buildTenureChart(progress) {
  return {
    series: [progress.pct],
    options: {
      chart: { type: "radialBar", sparkline: { enabled: true } },
      plotOptions: {
        radialBar: {
          hollow: { size: "58%" },
          track: { background: "rgba(226,232,240,0.9)" },
          dataLabels: {
            name: { show: true, fontSize: "10px", fontWeight: 700, color: "#64748b", offsetY: 20 },
            value: {
              fontSize: "18px",
              fontWeight: 900,
              color: "#0f172a",
              formatter: () => `${progress.months}m`,
            },
          },
        },
      },
      colors: ["#5b5ff4"],
      labels: ["Tenure"],
    },
  };
}

export function buildAccessFlagsChart(employee) {
  const flags = [
    {
      label: "App login",
      on: employee.appLoginDisabled === false || employee.appLoginDisabled === "false",
    },
    {
      label: "Device",
      on: employee.deviceAppEnabled === true || employee.deviceAppEnabled === "true",
    },
    {
      label: "Leave sync",
      on: employee.extLeaveSyncEnabled === true || employee.extLeaveSyncEnabled === "true",
    },
  ];

  return {
    series: [{ name: "Enabled", data: flags.map((f) => (f.on ? 100 : 18)) }],
    options: {
      chart: { type: "bar", toolbar: { show: false } },
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "52%",
          distributed: true,
        },
      },
      colors: flags.map((f) => (f.on ? "#059669" : "#cbd5e1")),
      dataLabels: {
        enabled: true,
        formatter: (val, opts) => (flags[opts.dataPointIndex].on ? "On" : "Off"),
        style: { fontSize: "11px", fontWeight: 800, colors: ["#fff"] },
      },
      xaxis: {
        categories: flags.map((f) => f.label),
        max: 100,
        labels: { show: false },
      },
      yaxis: {
        labels: { style: { fontSize: "11px", fontWeight: 700, colors: "#475569" } },
      },
      grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4 },
      legend: { show: false },
    },
  };
}

export function getSortedTeamNames(teamDetails) {
  if (!teamDetails || !teamDetails.length) return null;
  return [...teamDetails]
    .sort((a, b) => (a.name || "").localeCompare(b.name || "", undefined, { sensitivity: "base" }))
    .map((team) => team.name);
}

export const PROFILE_HERO_STORAGE_KEY = "famstack-profile-hero-expanded";

export function readProfileHeroExpanded() {
  return readSummaryExpanded(PROFILE_HERO_STORAGE_KEY);
}

/** Collapsed hero — no fields that appear in expanded KPI cards or personal tab headers. */
export function buildProfileHeroContextLine(employee) {
  if (!employee) return "";
  const parts = [
    formatDisplayValue(employee.designation),
    employee.userAccessDetails && employee.userAccessDetails.name,
    employee.managerDetails && employee.managerDetails.name && `Reports to ${employee.managerDetails.name}`,
  ].filter(Boolean);
  return parts.join(" · ");
}

/**
 * At-a-glance KPIs for expanded hero only.
 * Dates and skills render in hero panels; teams stay in the sidebar.
 */
export function buildProfileHeroKpis(employee) {
  if (!employee) return [];

  const managerName = employee.managerDetails && employee.managerDetails.name;
  const band = formatDisplayValue(employee.band);
  const grade = formatDisplayValue(employee.grade);
  const level =
    band && grade ? `${band} · ${grade}` : band || grade || null;

  const accessEnabled = [
    employee.appLoginDisabled === false || employee.appLoginDisabled === "false",
    employee.deviceAppEnabled === true || employee.deviceAppEnabled === "true",
    employee.extLeaveSyncEnabled === true || employee.extLeaveSyncEnabled === "true",
  ].filter(Boolean).length;

  const rows = [
    {
      key: "tenure",
      label: "Tenure",
      value: getTenureLabel(employee.dateOfJoin),
      icon: "fe fe-clock",
      tone: "primary",
    },
    {
      key: "manager",
      label: "Reports to",
      value: managerName,
      icon: "fe fe-user",
    },
    {
      key: "location",
      label: "Location",
      value: formatDisplayValue(employee.location),
      icon: "fe fe-map-pin",
    },
    {
      key: "level",
      label: "Band & grade",
      value: level,
      icon: "fe fe-bar-chart-2",
    },
    {
      key: "access",
      label: "Platform access",
      value: `${accessEnabled} of 3 active`,
      hint: "App login · device · leave sync",
      icon: "fe fe-shield",
      tone: accessEnabled === 3 ? "green" : "amber",
    },
  ];

  return rows.filter((row) => row.value);
}
