import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import AttendanceAnomalyRecommendationPanel from "./AttendanceAnomalyRecommendationPanel";

const METRICS = [
  { key: "missingPunchCount", label: "Missing checkout", icon: "fe-clock", tone: "warning" },
  { key: "lateTrendCount", label: "Late arrivals", icon: "fe-watch", tone: "warning" },
  { key: "regularizationCount", label: "Regularizations", icon: "fe-edit-2", tone: "info" },
  { key: "pendingRegularizations", label: "Pending requests", icon: "fe-inbox", tone: "pending" },
  { key: "exceptionPending", label: "Exception queue", icon: "fe-alert-circle", tone: "pending" },
  {
    key: "teamCoveragePct",
    altKey: "presentPct",
    label: "Team present %",
    icon: "fe-users",
    tone: "success",
    suffix: "%",
  },
];

function MetricCard({ label, value, tone, icon, suffix }) {
  return (
    <article className={classNames("lux-att-intel__metric", `is-${tone || "neutral"}`)}>
      <i className={classNames("fe", icon, "lux-att-intel__metric-icon")} aria-hidden="true" />
      <div>
        <span>{label}</span>
        <strong>
          <CountUp end={value || 0} duration={0.5} />
          {suffix || ""}
        </strong>
      </div>
    </article>
  );
}

export default function AttendanceIntelligencePanel({ intelligence, recommendation, loading }) {
  if (loading) {
    return (
      <section className="lux-att-intel is-loading" aria-busy="true" aria-label="Loading attendance intelligence">
        <div className="lux-att-intel__skeleton" />
      </section>
    );
  }
  if (!intelligence) return null;

  return (
    <section className="lux-att-intel" aria-label="Attendance intelligence">
      <div className="lux-att-intel__glow" aria-hidden="true" />

      <header className="lux-att-intel__hero">
        <div className="lux-att-intel__hero-copy">
          <LuxSummaryEyebrow variant="attendance" className="lux-att-intel__eyebrow">
            Attendance intelligence
          </LuxSummaryEyebrow>
          <h3 className="lux-att-intel__title">Team attendance insights</h3>
          <p className="lux-att-intel__subtitle">
            Late trends, missing punches, regularization frequency, and payroll-impacting exceptions
          </p>
        </div>
        {intelligence.source && (
          <span className={classNames("lux-att-intel__source", `is-${intelligence.source}`)}>
            {intelligence.source === "api" ? "Live API" : "Client computed"}
          </span>
        )}
      </header>

      <div className="lux-att-intel__metrics">
        {METRICS.map((metric) => (
          <MetricCard
            key={metric.key}
            label={metric.label}
            icon={metric.icon}
            tone={metric.tone}
            suffix={metric.suffix}
            value={
              intelligence[metric.key] != null
                ? intelligence[metric.key]
                : (metric.altKey ? intelligence[metric.altKey] : 0)
            }
          />
        ))}
      </div>

      {intelligence.dailyLate && intelligence.dailyLate.length > 0 && (
        <section className="lux-att-intel__chart">
          <header className="lux-att-intel__chart-head">
            <h4>
              <i className="fe fe-activity" aria-hidden="true" />
              Daily present rate
            </h4>
            <span>Last {Math.min(intelligence.dailyLate.length, 14)} elapsed days</span>
          </header>
          <ul className="lux-att-intel__chart-list">
            {intelligence.dailyLate.slice(0, 14).map((day) => (
              <li key={day.label} className="lux-att-intel__chart-row">
                <span className="lux-att-intel__chart-label">{day.label}</span>
                <div className="lux-att-intel__bar-track">
                  <div
                    className={classNames("lux-att-intel__bar-fill", {
                      "is-strong": (day.rate || 0) >= 80,
                      "is-weak": (day.rate || 0) < 60,
                    })}
                    style={{ width: `${day.rate || 0}%` }}
                  />
                </div>
                <span className="lux-att-intel__chart-value">{day.rate || 0}%</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      <AttendanceAnomalyRecommendationPanel recommendation={recommendation} />
    </section>
  );
}
