/**
 * Redux middleware — sends GA4 events for user-initiated store actions.
 */
import { trackEvent } from './analytics.utils';

const SKIP_TYPES = new Set([
  'NOTIFICATION_SUCCESS',
  'NOTIFICATION_INFO',
  'NOTIFICATION_WARNING',
  'NOTIFICATION_ERROR',
  'NOTIFICATION_PAGEMESSAGE',
  'NOTIFICATION_CLEAR',
]);

const SKIP_PATTERNS = [
  /^@@redux/,
  /_SUCCESS$/,
  /_FAILURE$/,
  /^(GETALL|GET)_/i,
  /_GETALL_/i,
  /_GET_/i,
];

const MUTATION_PATTERN =
  /CREATE|UPDATE|DELETE|REMOVE|ENABLE|DISABLE|LOGIN|LOGOUT|CHANGE|SAVE|ADD|ASSIGN|MOVE|ARCHIVE|APPROVE|REJECT|UPLOAD|DOWNLOAD|EXPORT|IMPORT|SEND|SUBMIT|TOGGLE|ACTIVATE|VALIDATE|REFRESH|COPY|MERGE|RESTORE|CANCEL|COMPLETE|START|STOP|PAUSE|RESUME|INVOKE|TRIGGER|REGISTER|UNREGISTER|LINK|UNLINK|SHARE|COMMENT|REPLY|PIN|UNPIN|FAVORITE|STAR|RATE|VOTE|ESCALATE|DEESCALATE/i;

function shouldTrackAction(type) {
  if (!type || typeof type !== 'string') return false;
  if (SKIP_TYPES.has(type)) return false;
  if (SKIP_PATTERNS.some((pattern) => pattern.test(type))) return false;
  if (type.endsWith('_REQUEST') && MUTATION_PATTERN.test(type)) return true;
  if (!type.endsWith('_REQUEST') && MUTATION_PATTERN.test(type)) return true;
  return false;
}

export function analyticsMiddleware() {
  return (next) => (action) => {
    if (!action || typeof action.type !== 'string') {
      return action === undefined ? undefined : next(action);
    }
    const result = next(action);
    if (shouldTrackAction(action.type)) {
      trackEvent(
        'redux_action',
        'redux',
        action.type,
        undefined,
        { action_type: action.type }
      );
    }
    return result;
  };
}
