import React, { Component } from "react";
import { Link } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientProjectsPage extends Component {
  state = { loading: false, error: null, projects: [] };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client projects");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, error: null });
    try {
      const result = await clientPortalService.listProjects();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: result && result.reason === "clientUserId-required"
            ? "Sign in at /client/login first."
            : "Unable to load projects.",
          projects: [],
        });
        return;
      }
      this.setState({
        loading: false,
        projects: (result.payload && result.payload.projects) || [],
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load projects.", projects: [] });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage testId="client-projects-flag-off">
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, error, projects } = this.state;
    return (
      <ClientLuxPage
        testId="client-projects-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-briefcase",
          eyebrow: "Client portal",
          titleLead: "Projects",
          titleAccent: "workspace",
          lede: "Only projects granted via client portal access bridge.",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.load} disabled={loading}>
            {loading ? "Loading…" : "Refresh"}
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load projects">
            {error}
          </LuxInlineAlert>
        ) : null}
        <ClientLuxPanel title="Permitted projects" icon="fe fe-list" meta={`${projects.length} project${projects.length === 1 ? "" : "s"}`}>
          {projects.length > 0 ? (
            <ul className="lux-client-portal-list">
              {projects.map((row) => (
                <li key={row.id}>
                  <Link to={`/client/projects/${row.id}`}>{row.name || row.id}</Link>
                  <span className="small text-muted ms-2">{row.accessLevel}</span>
                </li>
              ))}
            </ul>
          ) : null}
          {!loading && projects.length === 0 && !error ? (
            <LuxRegisterEmptyState title="No permitted projects" description="Sign in and ensure access bridges are configured." showCreate={false} />
          ) : null}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientProjectsPage;
