/**
 * Resolve menu module flag keys for routes.js entries.
 * Param segments (:id) are ignored so detail URLs reuse their parent feature flag.
 *
 * Hyphenated path segments (e.g. leave-policies) are converted to camelCase
 * flags (leavePoliciesEnabled) so they match adminModules / menuAccess keys.
 * PATH_SEGMENT_FLAG_ALIASES covers segments that share a parent flag or
 * use a non-derived name.
 */

const PATH_SEGMENT_FLAG_ALIASES = {
  employees: "employeesEnabled",
  details: "detailsEnabled",
  bidrequest: "bidrequestsEnabled",
  purchaseorder: "purchaseordersEnabled",
  deliverables: "listEnabled",
  deliverable: "listEnabled",
  workitems: "activitesEnabled",
  // Shared / non-derived admin flags (hyphen → camel would be wrong)
  "employee-leave-config": "leavePoliciesEnabled",
  "leave-policies": "leavePoliciesEnabled",
  "global-policy-center": "globalLeavePoliciesEnabled",
  "shift-policies": "shiftPoliciesEnabled",
  "approval-policies": "approvalPoliciesEnabled",
  "audit-logs": "auditEnabled",
};

/** Employee profile — not the employees register list. */
const EMPLOYEE_PROFILE_PATH_RE = /^\/employees\/[^/]+$/;

/** leave-policies → leavePoliciesEnabled */
function pathSegmentToFlagKey(segment) {
  if (PATH_SEGMENT_FLAG_ALIASES[segment]) {
    return PATH_SEGMENT_FLAG_ALIASES[segment];
  }
  const camel = segment.replace(/-([a-z])/g, (_, ch) => ch.toUpperCase());
  return `${camel}Enabled`;
}

export function resolveRouteFlagKey(routeProp) {
  if (!routeProp) {
    return null;
  }
  if (routeProp.routeFlag) {
    return routeProp.routeFlag;
  }

  const path = routeProp.path || "";
  if (EMPLOYEE_PROFILE_PATH_RE.test(path)) {
    return null;
  }

  const staticSegments = path
    .split("/")
    .filter((seg) => seg && !seg.startsWith(":"));

  const anchor = staticSegments[staticSegments.length - 1];
  if (!anchor) {
    return null;
  }

  return pathSegmentToFlagKey(anchor);
}

export function isRouteFlagEnabledForModule(routeProp, moduleConfig) {
  if (!moduleConfig) {
    return false;
  }

  const flagKey = resolveRouteFlagKey(routeProp);
  if (!flagKey) {
    return true;
  }

  return moduleConfig[flagKey] === true;
}
