import React from "react";
import classNames from "classnames/bind";
import { buildActingForBadge } from "_helpers/approvalAuthority.utils";

const ApprovalActingForBadge = ({ record, actingDelegations, employees, className }) => {
  const badge = buildActingForBadge(record, {
    actingDelegations: actingDelegations,
    employees: employees,
  });
  if (!badge) {
    return null;
  }

  return (
    <span
      className={classNames("lux-approval-acting-for", className)}
      title={`You are approving as a delegate for ${badge.managerName || "this manager"}`}
    >
      <span className="lux-approval-acting-for__dot" aria-hidden="true" />
      <i className="fe fe-shield" aria-hidden="true" />
      <span>{badge.label}</span>
    </span>
  );
};

export default ApprovalActingForBadge;
