import React from "react";
import LuxActionButton from "views/common/lux/LuxActionButton";

/**
 * People lifecycle CTA — LuxActionButton with lux-people-action tone.
 * API-compatible with the former local Link/button implementation.
 */
function normalizeIcon(icon) {
  if (!icon) return undefined;
  if (icon.startsWith("fe ") || /\s/.test(icon)) return icon;
  return `fe ${icon}`;
}

function LifecycleActionLink({
  to,
  href,
  onClick,
  children,
  icon,
  variant = "primary",
  className,
  type = "button",
  form,
  disabled = false,
  testId,
  "data-testid": dataTestId,
  ...rest
}) {
  return (
    <LuxActionButton
      to={to}
      href={href}
      // Prefer navigation when `to` is set (legacy Link behavior ignored onClick).
      onClick={to ? undefined : onClick}
      icon={normalizeIcon(icon)}
      variant={variant}
      type={type}
      form={form}
      disabled={disabled}
      className={className}
      moduleClass="lux-people-action"
      testId={testId || dataTestId}
      {...rest}
    >
      {children}
    </LuxActionButton>
  );
}

export default LifecycleActionLink;
