import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { exportTicketsCsv as buildTicketsCsv } from "config/ticket-management.utils";

export const ticketManagementService = {
  listTickets,
  getTicket,
  createTicket,
  updateTicket,
  assignTicket,
  resolveTicket,
  escalateTicket,
  listQueues,
  getOverview,
  getTicketAiSuggestions,
  exportTicketsCsv,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

/** Ticket list supports ticketType, projectId, employeeId and employeeRole query filters (EA08). */
async function listTickets(filters) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function getTicket(ticketId) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}`,
    teamQuery()
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function createTicket(payload) {
  const response = await axiosUtils.post(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    payload || {}
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function updateTicket(ticketId, payload) {
  const response = await axiosUtils.put(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    payload
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function assignTicket(ticketId, assigneeName) {
  const response = await axiosUtils.post(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}/assign?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    { assigneeName }
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function resolveTicket(ticketId) {
  const response = await axiosUtils.post(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}/resolve?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    {}
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function escalateTicket(ticketId) {
  const response = await axiosUtils.post(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}/escalate?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    {}
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function listQueues() {
  const response = await axiosUtils.getWithParam(`${urlConfig.TICKET_MANAGEMENT_API_PATH}/queues`, teamQuery());
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function getOverview(filters) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/overview`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function getTicketAiSuggestions(ticketId) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.TICKET_MANAGEMENT_API_PATH}/tickets/${ticketId}/ai-suggestions`,
    teamQuery()
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function exportTicketsCsv(filters) {
  const result = await listTickets(filters);
  return { payload: buildTicketsCsv(result.payload || []), source: "api" };
}
