import React, { Component } from "react";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import FileDropZone from "views/common/plugins/FileDropZone";
import TimesheetLuxuryDialog from "views/hrms/components/timesheet/TimesheetLuxuryDialog";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import { validationUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";

const fieldConfig = [
  { name: "id", mandatory: true, enabled: true },
  { name: "actualStartTime", mandatory: true, enabled: true },
];

function formatDateTime(value) {
  return dateUtils.convertDateTimeFormat(value) || "—";
}

function MetaTile({ label, value, tone, icon }) {
  return (
    <article className={`lux-task-complete__meta${tone ? ` is-${tone}` : ""}`}>
      {icon && (
        <span className="lux-task-complete__meta-icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
      )}
      <div className="lux-task-complete__meta-copy">
        <span>{label}</span>
        <strong>{value}</strong>
      </div>
    </article>
  );
}

class TaskCompletionModel extends Component {
  constructor() {
    super();
    this.state = {
      taskCompletionDurationTimeInMs: null,
      workItemStatusRequest: {},
      formErrors: {},
      hasFormError: false,
      expandPreviousTimeSection: false,
    };
  }

  componentDidMount() {
    this.bootstrapFromWorkItem();
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.workItem !== this.props.workItem ||
      prevProps.modalType !== this.props.modalType ||
      prevProps.show !== this.props.show
    ) {
      if (this.props.show) {
        this.bootstrapFromWorkItem();
      }
    }
  }

  bootstrapFromWorkItem = () => {
    if (!this.props.workItem) {
      return;
    }
    const workItemMinDates = workItemUtils.getWorkItemCreateStartMinDate(
      dateUtils.convertDateStringToMoment(
        this.props.workItem.taskEstStartTime ||
          dateUtils.getCurrentTime().clone().subtract(30, "days")
      ),
      this.props.permission
    );
    const workItemMaxDates = workItemUtils.getWorkItemCreateEndMaxDate(
      dateUtils.convertDateStringToMoment(
        this.props.workItem.taskEstCompletionTime ||
          dateUtils.getCurrentTime().clone().add(30, "days")
      ),
      this.props.permission
    );
    this.setState(
      {
        workItemMinDates,
        workItemMaxDates,
        workItemStatusRequest: {
          ...this.props.workItem,
          actualStartTime: this.props.workItem.actualStartTime || this.getTaskStartTime(),
          durationInHrs:
            this.props.modalType === "COMPLETED"
              ? dateUtils.minuteToHourDecimal(this.getCompletionDurationInMins())
              : null,
          durationInMins:
            this.props.modalType === "COMPLETED" ? this.getCompletionDurationInMins() || 0 : null,
          actualEndTime:
            this.props.modalType === "COMPLETED"
              ? this.props.workItem.taskPausedTime ||
                this.getActualCompletionTime(this.props.workItem.estDurationInMins)
              : null,
        },
        formErrors: {},
        hasFormError: false,
      },
      () => {
        this.validateDateSelection();
        this.calculateEndDateTime();
      }
    );
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onResetFormError = () => {
    this.setState({
      hasFormError: false,
    });
  };

  toggleExpandPreviousTimeSection = (isActive) => {
    this.setState({
      expandPreviousTimeSection: isActive,
    });
  };

  closeActionHandler = () => {
    if (this.props.isPlay === true) {
      this.props.playAction(
        this.state.workItemStatusRequest,
        this.props.modalType,
        false,
        this.props.callbackFunction
      );
    } else {
      this.props.cancelAction(this.props.workItem);
    }
  };

  onCommentChange = (fieldName, value) => {
    this.onChange(fieldName, value);
    this.onChange(
      this.props.modalType === "COMPLETED" ? "completionComment" : "inprogressComment",
      value
    );
  };

  onChange = (fieldName, value) => {
    this.setState((prevState) => ({
      workItemStatusRequest: {
        ...prevState.workItemStatusRequest,
        [fieldName]: value,
      },
    }));
  };

  onDateChange = (fieldName, value) => {
    this.setState(
      (prevState) => ({
        workItemStatusRequest: {
          ...prevState.workItemStatusRequest,
          [fieldName]: value,
        },
      }),
      () => {
        this.calculateEndDateTime();
      }
    );
  };

  calculateEndDateTime = () => {
    this.onChange(
      "actualEndTime",
      this.props.modalType === "COMPLETED"
        ? dateUtils.convertMomentToString(
            dateUtils.addXToMoments(
              dateUtils.convertDateStringToMoment(
                this.state.workItemStatusRequest.actualStartTime
              ),
              "minutes",
              this.state.workItemStatusRequest.durationInMins
            )
          )
        : null
    );
  };

  getTaskStartTime = () => {
    const estTaskCompletionTimeMoment = dateUtils.getCurrentDayEnd(
      dateUtils.convertDateStringToMoment(this.props.workItem.taskEstCompletionTime)
    );
    const estStartTimeMoment = dateUtils.convertDateStringToMoment(
      this.props.workItem.estStartTime
    );
    const currentTimeMoment = dateUtils.getCurrentTime();
    if (
      estStartTimeMoment.diff(currentTimeMoment) >= 0 &&
      estTaskCompletionTimeMoment.diff(currentTimeMoment) <= 0
    ) {
      return currentTimeMoment.clone().format(dateUtils.SERVER_DATE_FORMAT);
    }
    return estStartTimeMoment.format(dateUtils.SERVER_DATE_FORMAT);
  };

  onTimeEntryValueChange = (valueInHours) => {
    if (
      !validationUtils.validateDecimalNumberic(valueInHours) ||
      (valueInHours &&
        (this.props.permission.maxHoursAllowedToEnter < parseFloat(valueInHours) ||
          parseFloat(valueInHours) - parseInt(valueInHours) > 0.59))
    ) {
      return;
    }
    let valueInMins = 0;
    if (valueInHours !== "") {
      valueInMins =
        parseInt(valueInHours) * 60 +
        Math.round((parseFloat(valueInHours) - parseInt(valueInHours)) * 100);
    }
    this.onDateChange("durationInMins", valueInMins);
    this.onDateChange("durationInHrs", valueInHours);
  };

  getCompletionDurationInMins = () => {
    const actualStartTimeMoment = dateUtils.convertDateStringToMoment(
      this.props.workItem.actualStartTime || this.getTaskStartTime()
    );
    const currentMoment = dateUtils.getCurrentTime().clone();
    const timeDiffInMins = currentMoment.diff(actualStartTimeMoment, "minutes");
    const maxHoursAllowedToEnterInMins =
      parseInt(this.props.permission.maxHoursAllowedToEnter) * 60;
    return maxHoursAllowedToEnterInMins < timeDiffInMins || timeDiffInMins < 0
      ? this.props.workItem.estDurationInMins === 0
        ? maxHoursAllowedToEnterInMins
        : 0
      : timeDiffInMins;
  };

  getActualCompletionTime = () => {
    const actualStartTimeMoment = dateUtils.convertDateStringToMoment(
      this.props.workItem.actualStartTime || this.getTaskStartTime()
    );
    return dateUtils.convertMomentToString(
      dateUtils.addXToMoments(
        actualStartTimeMoment,
        "minutes",
        this.props.workItem.estDurationInMins
      )
    );
  };

  getDateSelectionMinDate = () => {
    const minDateObject = this.state.workItemMinDates;
    let workItemStartDate = null;
    if (minDateObject && this.props.workItem && this.props.workItem.taskType === "NON_PROJECT") {
      if (
        this.props.permission.allowLeaveAndHolidayForPast &&
        this.props.workItem.taskActCategory &&
        (this.props.workItem.taskActCategory.toLowerCase() === "leave" ||
          this.props.workItem.taskActCategory.toLowerCase() === "holiday")
      ) {
        workItemStartDate = minDateObject.actualStartDate;
      } else {
        workItemStartDate = minDateObject.nonProjectStart;
      }
    } else if (minDateObject && this.props.workItem && this.props.workItem.taskType !== "NON_PROJECT") {
      workItemStartDate = minDateObject.projectStart;
    }
    return workItemStartDate;
  };

  getDateSelectionMaxDate = () => {
    const maxDateObject = this.state.workItemMaxDates;
    let workItemEndDate = null;
    if (maxDateObject && this.props.workItem && this.props.workItem.taskType === "NON_PROJECT") {
      if (
        this.props.permission.allowLeaveAndHolidayForPast &&
        this.props.workItem.taskActCategory &&
        (this.props.workItem.taskActCategory.toLowerCase() === "leave" ||
          this.props.workItem.taskActCategory.toLowerCase() === "holiday")
      ) {
        workItemEndDate = maxDateObject.actualEndDate;
      } else {
        workItemEndDate = maxDateObject.nonProjectEnd;
      }
    } else if (maxDateObject && this.props.workItem && this.props.workItem.taskType !== "NON_PROJECT") {
      workItemEndDate = maxDateObject.projectEnd;
    }
    return workItemEndDate;
  };

  validateDateSelection = () => {
    let dateMinDateMoment = this.getDateSelectionMinDate(this.props.workItem.taskEstStartTime);
    let dateMaxDateMoment = this.getDateSelectionMaxDate(this.props.workItem.taskEstCompletionTime);
    const workItemStartDate = dateUtils.convertDateStringToMoment(
      this.state.workItemStatusRequest.actualStartTime
    );
    let isValid = true;
    if (dateMinDateMoment && dateMaxDateMoment) {
      dateMinDateMoment = dateMinDateMoment.clone().startOf("day");
      dateMaxDateMoment = dateMaxDateMoment.clone().endOf("day");
      if (
        workItemStartDate &&
        (workItemStartDate.diff(dateMinDateMoment) < 0 ||
          workItemStartDate.diff(dateMaxDateMoment) > 0)
      ) {
        this.onChange("actualStartTime", null);
        isValid = false;
      }
    }
    return isValid;
  };

  handleSubmit = () => {
    let isValid = validationUtils.isValidRequest(
      fieldConfig,
      this.state.workItemStatusRequest,
      this.state.formErrors
    );
    if (
      this.props.modalType === "COMPLETED" &&
      this.state.workItemStatusRequest.durationInMins === 0
    ) {
      isValid = false;
    }
    if (isValid) {
      if (this.props.isPlay === true) {
        this.props.playAction(
          this.state.workItemStatusRequest,
          this.props.modalType,
          true,
          this.props.callbackFunction
        );
      } else {
        this.props.updateAction(this.state.workItemStatusRequest, this.props.modalType);
      }
    } else {
      this.setState({
        hasFormError: true,
      });
    }
  };

  render() {
    const { modalType, workItem, show, clonedByItems } = this.props;
    if (!show || !workItem) {
      return null;
    }

    const isComplete = modalType === "COMPLETED";
    const req = this.state.workItemStatusRequest;
    const durationLabel =
      req.durationInMins != null
        ? dateUtils.minuteToHourString(req.durationInMins) || `${req.durationInHrs || 0}h`
        : "—";
    const primaryCta = this.props.isPlay
      ? "Complete paused & start this"
      : isComplete
        ? "Complete task"
        : "Start task";
    const secondaryCta = this.props.isPlay
      ? "Ignore paused & continue"
      : "Cancel";

    return (
      <TimesheetLuxuryDialog
        show={show}
        onClose={this.closeActionHandler}
        ariaLabel={isComplete ? "Complete task" : "Start task"}
        kicker="Taskboard"
        kickerIcon="fe-check-square"
        title={isComplete ? "Complete task" : "Start task"}
        subtitle={
          isComplete
            ? "Confirm actual time, notes, and billing context before moving this card to Done."
            : "Record when work started and any notes before moving to In progress."
        }
        badge={{
          tone: isComplete ? "green" : "blue",
          label: isComplete ? "Complete" : "Start",
        }}
        wide
        panelClassName="lux-task-complete-dialog"
        footer={
          <LuxCreateFooter
            handleSubmit={this.handleSubmit}
            editMode={this.props.editMode}
            createButtonLabel={primaryCta}
            closeButtonLabel={secondaryCta}
            disableKeepMeOpen
            initializeRequest={this.closeActionHandler}
            hasFormError={this.state.hasFormError}
            onResetFormError={this.onResetFormError}
          />
        }
      >
        <div className="lux-task-complete lux-create-form">
          <section className="lux-task-complete__hero" aria-label="Work item">
            <div className="lux-task-complete__hero-main">
              <div className="lux-task-complete__chips">
                {workItem.taskActCategory && (
                  <span className="lux-task-complete__chip is-category">{workItem.taskActCategory}</span>
                )}
                {workItem.taskType && (
                  <span className="lux-task-complete__chip is-type">
                    {workItem.taskType === "NON_PROJECT" ? "Non-project" : "Project"}
                  </span>
                )}
              </div>
              <h4 className="lux-task-complete__name">{workItem.name}</h4>
              {workItem.taskName && (
                <p className="lux-task-complete__deliverable">
                  <i className="fe fe-layers" aria-hidden="true" />
                  {workItem.taskName}
                </p>
              )}
              {workItem.description && (
                <p className="lux-task-complete__desc">{workItem.description}</p>
              )}
            </div>
            <div className="lux-task-complete__hero-glow" aria-hidden="true" />
          </section>

          <div className={`lux-task-complete__meta-grid${isComplete ? " is-complete" : ""}`}>
            <MetaTile
              label="Estimated start"
              value={formatDateTime(workItem.estStartTime)}
              icon="fe-calendar"
            />
            <MetaTile
              label="Actual start"
              value={formatDateTime(workItem.actualStartTime || req.actualStartTime)}
              tone="blue"
              icon="fe-play"
            />
            <MetaTile
              label="Recorded start"
              value={formatDateTime(workItem.recordedStartTime || dateUtils.getCurrentTime())}
              icon="fe-clock"
            />
            {isComplete && (
              <>
                <MetaTile
                  label="Duration"
                  value={durationLabel}
                  tone="green"
                  icon="fe-watch"
                />
                <MetaTile
                  label="Recorded end"
                  value={formatDateTime(dateUtils.getCurrentTime())}
                  icon="fe-flag"
                />
                <MetaTile
                  label="Actual end"
                  value={formatDateTime(req.actualEndTime)}
                  tone="amber"
                  icon="fe-check-circle"
                />
              </>
            )}
          </div>

          <LuxCreateFieldGroup
            title="Adjust timing"
            description={
              isComplete
                ? "Set the adjusted start and duration used for timesheet and completion."
                : "Set the adjusted start time before this card moves to In progress."
            }
            columns={isComplete ? 3 : 2}
          >
            <LuxCreateField span={isComplete ? 2 : "full"}>
              <CustomInput
                type="dateselect"
                label="Adjusted start time"
                name="actualStartTime"
                fieldConfig={fieldConfig}
                mappingObject={req}
                onChange={this.onDateChange}
                time
                minDate={
                  workItem &&
                  this.state.workItemMinDates &&
                  dateUtils.toMomentToDate(this.getDateSelectionMinDate())
                }
                maxDate={
                  workItem &&
                  this.state.workItemMinDates &&
                  dateUtils.toMomentToDate(this.getDateSelectionMaxDate())
                }
                format={dateUtils.DATE_TIME_PICKER_FORMAT}
                onFormError={this.onFormError}
              />
            </LuxCreateField>
            {isComplete && (
              <LuxCreateField>
                <CustomInput
                  inputtype="text"
                  mandatory
                  label="Duration (h.mm)"
                  name="durationInHrs"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={req}
                  onChange={(name, value) => this.onTimeEntryValueChange(value)}
                  onFormError={this.onFormError}
                  placeholder="0.00"
                />
              </LuxCreateField>
            )}
          </LuxCreateFieldGroup>

          <LuxCreateFieldGroup
            title={isComplete ? "Completion notes" : "Progress notes"}
            description="Optional context for reviewers and your timesheet history."
            columns={1}
          >
            <LuxCreateField span="full">
              <CustomInput
                type="textarea"
                label={isComplete ? "Completion comment" : "In progress comment"}
                name="comments"
                height="72px"
                fieldConfig={fieldConfig}
                mappingObject={req}
                onChange={this.onCommentChange}
                placeholder={
                  isComplete
                    ? "What was finished, blockers cleared, or handoff notes…"
                    : "What you are starting and any setup notes…"
                }
                onFormError={this.onFormError}
                datatype="alpnumspl"
              />
            </LuxCreateField>
          </LuxCreateFieldGroup>

          {isComplete && workItem.taskType !== "NON_PROJECT" && (
            <LuxCreateFieldGroup
              title="Delivery context"
              description="Skill and quantity used for billing and capacity."
              columns={2}
            >
              <LuxCreateField>
                <div className="lux-task-complete__readonly">
                  <span className="lux-task-complete__readonly-label">Skill</span>
                  <strong>{req.skill || "—"}</strong>
                </div>
              </LuxCreateField>
              <LuxCreateField>
                <CustomInput
                  type="text"
                  label="Quantity"
                  name="quantity"
                  fieldConfig={fieldConfig}
                  mappingObject={req}
                  onChange={this.onChange}
                  onFormError={this.onFormError}
                />
              </LuxCreateField>
            </LuxCreateFieldGroup>
          )}

          {isComplete && workItem.taskType === "NON_PROJECT" && (
            <LuxCreateFieldGroup
              title="Charge context"
              description="Account and team attributes for this non-project activity."
              columns={2}
            >
              <LuxCreateField>
                <div className="lux-task-complete__readonly">
                  <span className="lux-task-complete__readonly-label">Account</span>
                  <strong>{req.account || "—"}</strong>
                </div>
              </LuxCreateField>
              <LuxCreateField>
                <div className="lux-task-complete__readonly">
                  <span className="lux-task-complete__readonly-label">Division</span>
                  <strong>{req.division || "—"}</strong>
                </div>
              </LuxCreateField>
              <LuxCreateField>
                <div className="lux-task-complete__readonly">
                  <span className="lux-task-complete__readonly-label">Requesting team</span>
                  <strong>{req.teamName || "—"}</strong>
                </div>
              </LuxCreateField>
              <LuxCreateField>
                <div className="lux-task-complete__readonly">
                  <span className="lux-task-complete__readonly-label">Client partner</span>
                  <strong>{req.clientPartner || "—"}</strong>
                </div>
              </LuxCreateField>
            </LuxCreateFieldGroup>
          )}

          {clonedByItems && clonedByItems.length > 0 && (
            <section className="lux-task-complete__history">
              <button
                type="button"
                className="lux-task-complete__history-toggle"
                onClick={() =>
                  this.toggleExpandPreviousTimeSection(!this.state.expandPreviousTimeSection)
                }
                aria-expanded={this.state.expandPreviousTimeSection}
              >
                <span>
                  <i className="fe fe-clock" aria-hidden="true" />
                  Previously recorded time
                  <em>{clonedByItems.length}</em>
                </span>
                <i
                  className={`fe ${
                    this.state.expandPreviousTimeSection ? "fe-chevron-up" : "fe-chevron-down"
                  }`}
                  aria-hidden="true"
                />
              </button>
              {this.state.expandPreviousTimeSection && (
                <ul className="lux-task-complete__history-list">
                  {clonedByItems.map((item) => (
                    <li key={item.id}>
                      <span>{formatDateTime(item.actualStartTime)}</span>
                      <strong>
                        {dateUtils.minuteToHourString(item.durationInMins) || "—"}
                      </strong>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          )}

          <LuxCreateFieldGroup
            title="Attachments"
            description="Add supporting files if needed for this status change."
            columns={1}
          >
            <LuxCreateField span="full">
              <div className="lux-task-complete__dropzone">
                <FileDropZone />
              </div>
            </LuxCreateField>
          </LuxCreateFieldGroup>
        </div>
      </TimesheetLuxuryDialog>
    );
  }
}

export default TaskCompletionModel;
