export function isFinanceIntelligenceEnabled() {
  return shouldUseFinanceIntelligence();
}

export function shouldUseFinanceIntelligenceApi() {
  return envconfig.USE_FINANCE_INTELLIGENCE_API !== false;
}

export const FINANCE_MARGIN_BANDS = {
  HEALTHY: "HEALTHY",
  WATCH: "WATCH",
  CRITICAL: "CRITICAL",
};

export const FINANCE_BILLING_STATUSES = {
  CURRENT: "CURRENT",
  PARTIAL: "PARTIAL",
  OVERDUE: "OVERDUE",
  READY: "READY",
};

export function deriveFinanceMarginBand(marginPct) {
  if (marginPct == null || Number.isNaN(Number(marginPct))) {
    return null;
  }
  const value = Number(marginPct);
  if (value >= 25) {
    return FINANCE_MARGIN_BANDS.HEALTHY;
  }
  if (value >= 15) {
    return FINANCE_MARGIN_BANDS.WATCH;
  }
  return FINANCE_MARGIN_BANDS.CRITICAL;
}

export function normalizeProjectFinancialSnapshot(row) {
  if (!row) {
    return null;
  }
  const marginPct = row.marginPct != null ? Number(row.marginPct) : null;
  return {
    id: row.id,
    projectId: row.projectId,
    projectCode: row.projectCode || "",
    projectName: row.projectName || "Project",
    programId: row.programId || null,
    programName: row.programName || null,
    ownerName: row.ownerName || "",
    healthLabel: row.healthLabel || null,
    marginPct,
    marginBand: row.marginBand || deriveFinanceMarginBand(marginPct),
    revenueUsd: row.revenueUsd != null ? Number(row.revenueUsd) : null,
    costUsd: row.costUsd != null ? Number(row.costUsd) : null,
    unbilledUsd: row.unbilledUsd != null ? Number(row.unbilledUsd) : null,
    billedUsd: row.billedUsd != null ? Number(row.billedUsd) : null,
    forecastVariancePct: row.forecastVariancePct != null ? Number(row.forecastVariancePct) : null,
    billingStatus: row.billingStatus || FINANCE_BILLING_STATUSES.CURRENT,
    collectionPct: row.collectionPct != null ? Number(row.collectionPct) : null,
    poBurnPct: row.poBurnPct != null ? Number(row.poBurnPct) : null,
    poRemainingUsd: row.poRemainingUsd != null ? Number(row.poRemainingUsd) : null,
    dsoDays: row.dsoDays != null ? Number(row.dsoDays) : null,
    billingReadinessPct: row.billingReadinessPct != null ? Number(row.billingReadinessPct) : null,
    sensitive: row.sensitive === true,
    updatedAt: row.updatedAt || null,
  };
}

