import envconfig from "env.config";
import React, { Component } from "react";
import LegalDocumentModal from "views/common/legal/LegalDocumentModal";
import { LEGAL_DOC_TYPES } from "views/common/legal/legalDocuments";

class LoginPageFooter extends Component {
  state = {
    legalDocType: null,
  };

  openLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  closeLegal = () => {
    this.setState({ legalDocType: null });
  };

  switchLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  render() {
    const year = new Date().getFullYear();
    const appName = (envconfig.APP_NAME || "tracopus").toLowerCase();
    const version = envconfig.APP_VERSION || "8.0.11";
    const { legalDocType } = this.state;

    return (
      <>
        <footer className="auth-screen__footer" role="contentinfo">
          <div className="auth-screen__footer-divider" aria-hidden="true" />
          <div className="auth-screen__footer-brand">
            <p className="auth-screen__footer-tagline">
              {appName} · Enterprise work intelligence
            </p>
            <span className="auth-screen__footer-version">v {version}</span>
          </div>
          <p className="auth-screen__footer-legal">
            © {year} Infleca Innovation Pvt Ltd. All rights reserved.
          </p>
          <nav className="auth-screen__footer-nav" aria-label="Legal">
            <button
              type="button"
              className="auth-screen__footer-link"
              data-testid="login-footer-privacy-link"
              onClick={() => this.openLegal(LEGAL_DOC_TYPES.PRIVACY)}
            >
              Privacy Policy
            </button>
            <span className="auth-screen__footer-sep" aria-hidden="true">·</span>
            <button
              type="button"
              className="auth-screen__footer-link"
              data-testid="login-footer-terms-link"
              onClick={() => this.openLegal(LEGAL_DOC_TYPES.TERMS)}
            >
              Terms of Service
            </button>
          </nav>
        </footer>

        <LegalDocumentModal
          show={!!legalDocType}
          docType={legalDocType || LEGAL_DOC_TYPES.PRIVACY}
          onClose={this.closeLegal}
          onSwitchDoc={this.switchLegal}
        />
      </>
    );
  }
}

export default LoginPageFooter;
