import { shouldUseResourcePlanning } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const ALLOCATION_STATUSES = {
  ACTIVE: "ACTIVE",
  PLANNED: "PLANNED",
  ROLLOFF: "ROLLOFF",
};

export const STAFFING_REQUEST_STATUSES = {
  PENDING: "Pending",
  APPROVED: "Approved",
  FULFILLED: "Fulfilled",
  REJECTED: "Rejected",
};

export const BENCH_STATUSES = {
  ON_BENCH: "ON_BENCH",
  ROLLING_OFF: "ROLLING_OFF",
  PARTIAL: "PARTIAL",
  PLACED: "PLACED",
};

export const SIMULATION_ADJUSTMENT_TYPES = {
  FULFILL_REQUEST: "FULFILL_REQUEST",
  PLACE_BENCH: "PLACE_BENCH",
  SHIFT_ALLOCATION: "SHIFT_ALLOCATION",
};

export const SKILL_PROFICIENCY_LEVELS = {
  BEGINNER: { id: "BEGINNER", label: "Beginner", score: 1 },
  INTERMEDIATE: { id: "INTERMEDIATE", label: "Intermediate", score: 2 },
  ADVANCED: { id: "ADVANCED", label: "Advanced", score: 3 },
  EXPERT: { id: "EXPERT", label: "Expert", score: 4 },
};

export function isResourcePlanningEnabled() {
  return shouldUseResourcePlanning();
}

export function shouldUseResourcePlanningApi() {
  return envconfig.USE_RESOURCE_PLANNING_API === true;
}

export function normalizeAllocation(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    projectId: row.projectId || null,
    projectCode: row.projectCode || "",
    projectName: row.projectName || "Unnamed project",
    role: row.role || "",
    allocationPct: row.allocationPct != null ? row.allocationPct : 100,
    startDate: row.startDate || null,
    endDate: row.endDate || null,
    status: row.status || ALLOCATION_STATUSES.ACTIVE,
    billable: row.billable !== false,
    health: row.health || "",
    schedule: row.schedule || "",
    notes: row.notes || "",
    sourceLinks: Array.isArray(row.sourceLinks) ? row.sourceLinks : [],
    bridgeType: row.bridgeType || null,
  };
}

export function normalizeStaffingRequest(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    title: row.title || "Staffing request",
    requesterId: row.requesterId || null,
    requesterName: row.requesterName || "",
    projectId: row.projectId || null,
    projectName: row.projectName || "",
    roleNeeded: row.roleNeeded || "",
    skillNeeded: row.skillNeeded || "",
    candidateEmployeeIds: Array.isArray(row.candidateEmployeeIds) ? row.candidateEmployeeIds : [],
    sourceLinks: Array.isArray(row.sourceLinks) ? row.sourceLinks : [],
    headcount: row.headcount != null ? row.headcount : 1,
    status: row.status || STAFFING_REQUEST_STATUSES.PENDING,
    priority: row.priority || "NORMAL",
    submittedAt: row.submittedAt || null,
    dueAt: row.dueAt || null,
    notes: row.notes || "",
  };
}

export function normalizeCapacitySummary(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id || "cap-snap-latest",
    snapshotDate: row.snapshotDate || null,
    rosterSize: row.rosterSize != null ? row.rosterSize : 0,
    assignmentCount: row.assignmentCount != null ? row.assignmentCount : 0,
    avgUtilizationPct: row.avgUtilizationPct != null ? row.avgUtilizationPct : 0,
    allocatedHours: row.allocatedHours != null ? row.allocatedHours : 0,
    freeHours: row.freeHours != null ? row.freeHours : 0,
    overbookedResources: row.overbookedResources != null ? row.overbookedResources : 0,
    benchCount: row.benchCount != null ? row.benchCount : 0,
    openStaffingRequests: row.openStaffingRequests != null ? row.openStaffingRequests : 0,
  };
}

export function getProficiencyLabel(level) {
  const meta = SKILL_PROFICIENCY_LEVELS[normalizeProficiencyLevel(level)];
  return (meta && meta.label) || level || "Intermediate";
}

export function normalizeProficiencyLevel(level) {
  if (!level) {
    return "INTERMEDIATE";
  }
  const normalized = String(level).trim().toUpperCase();
  if (normalized === "BASIC" || normalized === "BEGINNER") {
    return "BEGINNER";
  }
  if (normalized === "ADVANCE" || normalized === "ADVANCED") {
    return "ADVANCED";
  }
  if (normalized === "EXPERT") {
    return "EXPERT";
  }
  if (normalized === "INTERMEDIATE") {
    return "INTERMEDIATE";
  }
  return normalized;
}

export function normalizeBenchRecord(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    role: row.role || "",
    department: row.department || "",
    status: row.status || BENCH_STATUSES.ON_BENCH,
    availabilityPct: row.availabilityPct != null ? row.availabilityPct : 100,
    lastProjectId: row.lastProjectId || null,
    lastProjectName: row.lastProjectName || "",
    lastProjectEndDate: row.lastProjectEndDate || null,
    availableFrom: row.availableFrom || null,
    daysOnBench: row.daysOnBench != null ? row.daysOnBench : 0,
    primarySkills: row.primarySkills || "",
    location: row.location || "",
    notes: row.notes || "",
    updatedAt: row.updatedAt || null,
    derived: row.derived === true,
    derivationMode: row.derivationMode || null,
    sourceLinks: Array.isArray(row.sourceLinks) ? row.sourceLinks : [],
  };
}

export function normalizeSkillProfile(row) {
  if (!row) {
    return null;
  }
  const level = normalizeProficiencyLevel(row.proficiencyLevel);
  return {
    id: row.id,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    skillName: row.skillName || "Unnamed skill",
    skillMasterRef: row.skillMasterRef || null,
    skillCategory: (row.skillCategory || "General").trim(),
    sourceLinks: Array.isArray(row.sourceLinks) ? row.sourceLinks : [],
    proficiencyLevel: level,
    proficiencyLabel: getProficiencyLabel(level),
    proficiencyScore: row.proficiencyScore != null ? row.proficiencyScore : 2,
    yearsExperience: row.yearsExperience != null ? row.yearsExperience : null,
    lastUsedDate: row.lastUsedDate || null,
    certified: row.certified === true,
    notes: row.notes || "",
  };
}
