import React from "react";
import classNames from "classnames/bind";

export default function TicketQueueBoard({ queues = [], tickets = [], loading, activeQueue, onQueueSelect }) {
  if (loading) {
    return <div className="lux-ticket-register__skeleton" aria-busy="true" />;
  }

  return (
    <div className="lux-ticket-queue-grid">
      {queues.map((queue) => {
        const queueTickets = tickets.filter((row) => row.queue === queue.id);
        return (
          <article
            key={queue.id}
            className={classNames("lux-ticket-queue-card", queue.tone && `is-${queue.tone}`, {
              "is-active": activeQueue === queue.id,
            })}
            onClick={() => onQueueSelect && onQueueSelect(queue.id)}
          >
            <header>
              <strong>{queue.label}</strong>
              <span className="lux-ticket-queue-card__count">{queue.openCount} open</span>
            </header>
            <div className="lux-ticket-queue-card__metrics">
              <span>
                In view <strong>{queueTickets.length}</strong>
              </span>
              <span>
                At risk <strong>{queue.slaAtRisk}</strong>
              </span>
            </div>
            <ul className="lux-ticket-queue-card__list">
              {queueTickets.slice(0, 3).map((row) => (
                <li key={row.id}>
                  <span>{row.number}</span>
                  <small>{row.title}</small>
                </li>
              ))}
            </ul>
          </article>
        );
      })}
    </div>
  );
}
