import { PAYROLL_ADMIN_PERSONAS } from "config/payroll-security.utils";

export const EMPLOYEE_FINANCE_SENSITIVE_FIELDS = ["ctcUsd", "baseSalaryUsd", "billingRateUsd", "costRateUsd"];

export function canViewEmployeeFinanceSensitive(activePersona) {
  return PAYROLL_ADMIN_PERSONAS.includes(activePersona);
}

export function maskEmployeeFinanceProfile(row, activePersona) {
  if (!row) {
    return null;
  }
  if (canViewEmployeeFinanceSensitive(activePersona)) {
    return { ...row, masked: false };
  }
  return {
    ...row,
    baseSalaryUsd: null,
    ctcUsd: null,
    billingRateUsd: null,
    costRateUsd: null,
    openAdvanceUsd: null,
    openLoanUsd: null,
    masked: true,
  };
}

export function maskEmployeeFinanceProfiles(rows = [], activePersona = "ADMIN") {
  return (rows || []).map((row) => maskEmployeeFinanceProfile(row, activePersona));
}

export function canExportEmployeeFinanceCompensation(activePersona) {
  return canViewEmployeeFinanceSensitive(activePersona);
}
