import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import {
  isServerRuntimeConfigured,
  summarizeConnectionConfig,
} from "config/integrations-connections.config";
import { INTEGRATION_CONNECTIONS_PAGE_META } from "config/integration-center-nav.config";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import IntegrationConnectionConfigDrawer from "views/integrations/components/IntegrationConnectionConfigDrawer";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class IntegrationConnectionsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    connections: [],
    busyKey: null,
    configOpen: false,
    selectedConnection: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await integrationCenterService.listLegacyConnections();
      this.setState({
        loading: false,
        dataSource: result.source,
        connections: result.payload || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load integration connections.",
      });
    }
  };

  handleToggle = async (connection) => {
    const nextEnabled = !connection.integrationCenterEnabled;
    this.setState({ busyKey: connection.legacyKey, loadError: null });
    try {
      await integrationCenterService.updateLegacyConnection(connection.legacyKey, { enabled: nextEnabled });
      await this.loadData();
    } catch (error) {
      this.setState({
        loadError: (error && error.message) || "Unable to update connection.",
      });
    } finally {
      this.setState({ busyKey: null });
    }
  };

  handleOpenConfig = (connection) => {
    this.setState({ configOpen: true, selectedConnection: connection });
  };

  handleSaveConfig = async (legacyKey, payload) => {
    await integrationCenterService.updateLegacyConnection(legacyKey, payload);
    await this.loadData();
  };

  renderConnectionRow(connection) {
    const enabled = connection.integrationCenterEnabled === true;
    const busy = this.state.busyKey === connection.legacyKey;
    const configSummary = summarizeConnectionConfig(connection);
    const serverReady = isServerRuntimeConfigured(connection);
    return (
      <article key={connection.legacyKey} className="lux-int-connection-card">
        <div className="lux-int-connection-card__main">
          <h3>{connection.name}</h3>
          <p>{connection.summary}</p>
          <p className="lux-int-connection-card__config-line">
            <strong>Config:</strong> {configSummary}
          </p>
          <p className="lux-int-connection-card__config-line">
            <strong>Server:</strong> {serverReady ? "Runtime configured" : "Runtime pending"}
          </p>
          <div className="lux-int-connection-card__meta">
            <span>Connector: {connection.connectorId}</span>
            {(connection.scheduleTypes || []).length ? (
              <span>Schedulers: {(connection.scheduleTypes || []).join(", ")}</span>
            ) : null}
          </div>
        </div>
        <div className="lux-int-connection-card__actions">
          <label className="lux-int-toggle">
            <input
              type="checkbox"
              checked={enabled}
              disabled={busy || this.state.loading}
              onChange={() => this.handleToggle(connection)}
            />
            <span>{enabled ? "Enabled" : "Disabled"}</span>
          </label>
          <IntegrationActionButton icon="fe fe-sliders" onClick={() => this.handleOpenConfig(connection)}>
            Configure
          </IntegrationActionButton>
          {connection.legacyUiPath ? (
            <Link to={connection.legacyUiPath} className="lux-int-connection-card__link">
              Legacy UI
            </Link>
          ) : null}
        </div>
      </article>
    );
  }

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied featureLabel="Integration connections" />;
    }

    const { loading, loadError, dataSource, connections, configOpen, selectedConnection } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_CONNECTIONS_PAGE_META}
        pageId="integration-connections"
        shellTitle="Connections"
        dataSource={dataSource}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <IntegrationActionButton to="/integrations/adapters" icon="fe fe-package">
              Adapters
            </IntegrationActionButton>
            <IntegrationActionButton to="/integrations/jobs" icon="fe fe-repeat">
              Jobs
            </IntegrationActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        <IntegrationLuxPanel
          title="Salesforce, ZingHR & email"
          meta="Configure integration settings here; legacy flows stay enabled by default"
          icon="fe fe-settings"
          accent="blue"
          featured
        >
          {loading ? <p>Loading connections…</p> : connections.map((row) => this.renderConnectionRow(row))}
        </IntegrationLuxPanel>
        <IntegrationConnectionConfigDrawer
          open={configOpen}
          connection={selectedConnection}
          onClose={() => this.setState({ configOpen: false, selectedConnection: null })}
          onSave={this.handleSaveConfig}
          onSaved={this.loadData}
        />
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationConnectionsPage;
