import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_SYNC_PAGE_META } from "config/integration-center-nav.config";
import { buildIntegrationHubKpis } from "config/integration-center.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationInsightPanel,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import ConnectorRegister from "views/integrations/components/ConnectorRegister";
import { SyncHealthSnapshot, SyncJobsRegister } from "views/integrations/components/IntegrationRegisters";

class IntegrationSyncHealthPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    kpiCards: [],
    insights: [],
    connectors: [],
    summary: null,
    jobs: [],
    busyId: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await integrationCenterService.getSyncHealthOverview();
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        kpiCards: buildIntegrationHubKpis(payload.summary),
        insights: payload.insights || [],
        connectors: payload.connectors || [],
        summary: payload.summary || null,
        jobs: payload.jobs || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load sync monitor.",
      });
    }
  };

  handleRetry = async (jobId) => {
    this.setState({ busyId: jobId, loadError: null });
    try {
      await integrationCenterService.retrySyncJob(jobId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to retry job." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied title="Sync monitor" message="Integration center is not enabled for this organization." />;
    }

    const { loading, loadError, dataSource, kpiCards, insights, connectors, summary, jobs, busyId } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_SYNC_PAGE_META}
        pageId="sync-health"
        shellTitle="Sync monitor"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationInsightPanel insights={insights} />
        <SyncHealthSnapshot summary={summary} loading={loading} />

        <div className="lux-integ-layout">
          <IntegrationLuxPanel title="Connector health" meta="Latency and error rates" icon="fe fe-link" accent="blue" featured>
            <ConnectorRegister connectors={connectors} loading={loading} />
          </IntegrationLuxPanel>

          <IntegrationLuxPanel title="Sync jobs" meta="Retry failed jobs" icon="fe fe-repeat" accent="amber">
            <SyncJobsRegister jobs={jobs} loading={loading} onRetry={this.handleRetry} busyId={busyId} />
          </IntegrationLuxPanel>
        </div>
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationSyncHealthPage;
