import React from "react";
import { withRouter } from "react-router-dom";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";

/**
 * In-page tab strip for Admin hubs (Developer portal, Workflow automation).
 * Deep-link routes stay registered; sidebar shows a single hub row.
 */
function AdminHubTabs({ tabs, location, className, ariaLabel }) {
  if (!tabs || tabs.length === 0) {
    return null;
  }
  const pathname = (location && location.pathname) || "";
  const items = tabs.map((tab) => ({
    id: tab.path,
    path: tab.path,
    label: tab.label,
    icon: tab.icon,
    matchPrefix: tab.matchPrefix,
  }));
  const activeTab = items.find(
    (item) => pathname === item.path || (item.matchPrefix && pathname.startsWith(item.matchPrefix))
  );

  return (
    <LuxSegmentNav
      items={items}
      activeId={activeTab && activeTab.id}
      ariaLabel={ariaLabel || "Section"}
      className={className}
      testId="admin-hub-tabs"
    />
  );
}

export default withRouter(AdminHubTabs);

export const DEVELOPER_HUB_TABS = [
  { path: "/admin/developer", label: "Overview", icon: "fe fe-code", flag: "developerPortalOverviewEnabled" },
  { path: "/admin/api-keys", label: "API keys", icon: "fe fe-key", flag: "apiKeysEnabled" },
  { path: "/admin/webhooks", label: "Webhooks", icon: "fe fe-link-2", flag: "webhooksEnabled" },
];

export function filterDeveloperHubTabs(menuAccessControl) {
  const mod = (menuAccessControl && menuAccessControl.adminModules) || {};
  return DEVELOPER_HUB_TABS.filter((tab) => !tab.flag || mod[tab.flag] === true);
}

export const WORKFLOW_HUB_TABS = [
  { path: "/admin/workflows", label: "Studio", icon: "fe fe-git-branch" },
  { path: "/admin/automation-rules", label: "Rule builder", icon: "fe fe-sliders" },
];
