import React, { Component } from "react";
import { NavLink, withRouter } from "react-router-dom";
import classNames from "classnames/bind";
import envconfig from "env.config";
import { accessUtils } from "_helpers/access.utils";
import LegalDocumentModal from "views/common/legal/LegalDocumentModal";
import { LEGAL_DOC_TYPES } from "views/common/legal/legalDocuments";
import {
  FOOTER_MODULES,
  getActiveFooterModule,
  getFooterModuleHref,
} from "./pageFooter.utils";

class PageFooter extends Component {
  constructor(props) {
    super(props);
    this.state = {
      permission: accessUtils.getMenuAccessControl(),
      legalDocType: null,
    };
  }

  openLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  closeLegal = () => {
    this.setState({ legalDocType: null });
  };

  switchLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  render() {
    const currentYear = new Date().getFullYear();
    const appName = (envconfig.APP_NAME || "tracopus").toLowerCase();
    const appVersion = envconfig.APP_VERSION || "8.0.11";
    const { permission, legalDocType } = this.state;
    const activeModule = getActiveFooterModule(this.props.location.pathname);

    return (
      <>
        <footer className="lux-page-footer page-footer-modern" role="contentinfo">
          <div className="lux-page-footer__bar container-fluid">
            <div className="lux-page-footer__left">
              <span className="lux-page-footer__copy">
                © {currentYear}{" "}
                <a href="https://infleca.com" target="_blank" rel="noopener noreferrer">
                  Infleca Innovation Pvt Ltd
                </a>
              </span>
              <span className="lux-page-footer__sep" aria-hidden="true">·</span>
            </div>

            <nav className="lux-page-footer__context" aria-label="Switch module context">
              {FOOTER_MODULES.map((module) => {
                const href = getFooterModuleHref(module, permission);
                if (!href) return null;
                const isActive = activeModule && activeModule.id === module.id;
                return (
                  <NavLink
                    key={module.id}
                    to={href}
                    className={classNames("lux-page-footer__ctx", { "is-active": isActive })}
                    title={module.description}
                  >
                    <i className={`fe ${module.icon}`} aria-hidden="true" />
                    {module.label}
                  </NavLink>
                );
              })}
            </nav>

            <div className="lux-page-footer__right">
              <a
                href="/documentation/index.html"
                className="lux-page-footer__link"
                target="_blank"
                rel="noopener noreferrer"
              >
                <i className="fe fe-book-open" aria-hidden="true" />
                Docs
              </a>
              <button
                type="button"
                className="lux-page-footer__link"
                data-testid="footer-privacy-link"
                onClick={() => this.openLegal(LEGAL_DOC_TYPES.PRIVACY)}
              >
                Privacy
              </button>
              <button
                type="button"
                className="lux-page-footer__link"
                data-testid="footer-terms-link"
                onClick={() => this.openLegal(LEGAL_DOC_TYPES.TERMS)}
              >
                Terms
              </button>
              <span className="lux-page-footer__meta" title={`${appName} release`}>
                v{appVersion}
              </span>
              {envconfig.ENV_NAME && (
                <span className="lux-page-footer__meta is-env">{envconfig.ENV_NAME}</span>
              )}
            </div>
          </div>
        </footer>

        <LegalDocumentModal
          show={!!legalDocType}
          docType={legalDocType || LEGAL_DOC_TYPES.PRIVACY}
          onClose={this.closeLegal}
          onSwitchDoc={this.switchLegal}
        />
      </>
    );
  }
}

export default withRouter(PageFooter);
