import React, { useMemo, useState, useEffect } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import Skeleton from "react-loading-skeleton";
import dateUtils from "_helpers/date.utils";
import DashboardApexChart from "../dashboard/DashboardApexChart";
import {
  buildTimesheetContextLine,
  buildTimesheetDailyChart,
  buildTimesheetDistributionChart,
  buildTimesheetStatusChart,
  buildTimesheetUtilizationChart,
  buildTimesheetDailyTargetChart,
  buildTimesheetWeekComplianceChart,
  buildApprovalKpiDefs,
  buildDataQualityCollapsedSummary,
  computeTimesheetSummary,
  convertMinsToDisplay,
  TIMESHEET_KPI_DEFS,
} from "./timesheetSummary.utils";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-timesheet-summary-expanded";

function TimesheetStatusBadge({ statusMeta, showLabel, compact }) {
  if (!statusMeta) return null;

  return (
    <span
      className={classNames("lux-ts-summary__status-badge", `is-${statusMeta.tone}`, {
        "is-compact": compact,
      })}
      title={statusMeta.hint}
    >
      <i className={`fe ${statusMeta.icon}`} aria-hidden="true" />
      {statusMeta.label}
      {showLabel && <small>{showLabel}</small>}
    </span>
  );
}

function TimesheetKpi({ def, summary, loading }) {
  const value = summary ? summary[def.valueKey] : "—";
  const numeric = summary ? summary[def.numericKey] : 0;
  const overTarget = summary && def.maxValue < numeric;

  return (
    <article className={classNames("lux-ts-summary__kpi", def.tone && `is-${def.tone}`)}>
      <div className="lux-ts-summary__kpi-top">
        <span className="lux-ts-summary__kpi-label">{def.label}</span>
        <span className="lux-ts-summary__kpi-icon" aria-hidden="true">
          <i className={`fe ${def.icon}`} />
        </span>
      </div>
      <strong className={classNames("lux-ts-summary__kpi-value", { "is-alert": overTarget })}>
        {loading ? "—" : value}
      </strong>
      {def.hint && <span className="lux-ts-summary__kpi-hint">{def.hint}</span>}
    </article>
  );
}

function TimesheetSummaryPanel({ timeSheetData, applicableDates, loading, addEntryOpen, employees }) {
  const [expanded, setExpanded] = useState(function () {
    return readSummaryExpanded(SUMMARY_STORAGE_KEY);
  });
  const [deferredSheetData, setDeferredSheetData] = useState(timeSheetData);

  useEffect(() => {
    if (!addEntryOpen) {
      return undefined;
    }
    const timer = window.setTimeout(() => {
      setExpanded(false);
      writeSummaryExpanded(SUMMARY_STORAGE_KEY, false);
    }, 240);
    return () => window.clearTimeout(timer);
  }, [addEntryOpen]);

  // Keep KPI/chart work off the hour-typing path so cell edits stay responsive.
  // First paint uses live sheet data; deferred updates lag slightly for chart/KPI work.
  useEffect(() => {
    if (!timeSheetData) {
      setDeferredSheetData(null);
      return undefined;
    }
    setDeferredSheetData((prev) => (prev == null ? timeSheetData : prev));
    const timer = window.setTimeout(() => {
      setDeferredSheetData(timeSheetData);
    }, 180);
    return () => window.clearTimeout(timer);
  }, [timeSheetData]);

  const summarySource = deferredSheetData || timeSheetData;
  const summary = useMemo(
    () =>
      summarySource ? computeTimesheetSummary(summarySource, applicableDates, employees) : null,
    [summarySource, applicableDates, employees]
  );

  const distributionChart = useMemo(
    () => (summary ? buildTimesheetDistributionChart(summary) : null),
    [summary]
  );
  const utilizationChart = useMemo(
    () => (summary ? buildTimesheetUtilizationChart(summary) : null),
    [summary]
  );
  const dailyTargetChart = useMemo(
    () => (summary ? buildTimesheetDailyTargetChart(summary) : null),
    [summary]
  );
  const weekComplianceChart = useMemo(
    () => (summary ? buildTimesheetWeekComplianceChart(summary) : null),
    [summary]
  );
  const dailyChart = useMemo(() => (summary ? buildTimesheetDailyChart(summary) : null), [summary]);
  const statusChart = useMemo(() => (summary ? buildTimesheetStatusChart(summary) : null), [summary]);
  const contextLine = summary ? buildTimesheetContextLine(summary) : "";
  const dataQualityCollapsedHint = summary ? buildDataQualityCollapsedSummary(summary) : null;
  const approvalKpis = useMemo(() => buildApprovalKpiDefs(summary), [summary]);
  const isLoading = loading || !timeSheetData || !summary;
  const hasCriticalDataQuality = !!(summary && summary.dataQualityCriticalCount > 0);

  const toggleExpanded = () => {
    setExpanded((prev) => {
      const next = !prev;
      writeSummaryExpanded(SUMMARY_STORAGE_KEY, next);
      return next;
    });
  };

  const renderStatusStrip = () => {
    if (!summary || isLoading) return null;

    return (
      <div className="lux-ts-summary__status-strip">
        <div className="lux-ts-summary__status-main">
          <TimesheetStatusBadge
            statusMeta={summary.weekStatusMeta}
            showLabel={summary.rootShow}
          />
          {summary.weekStatusMeta.hint && (
            <span className="lux-ts-summary__status-hint">{summary.weekStatusMeta.hint}</span>
          )}
          {summary.weekStatus === "REJECTED" && summary.weekRejectionComment && (
            <p className="lux-ts-summary__rejection-comment" role="note">
              <i className="fe fe-message-square" aria-hidden="true" />
              {summary.weekRejectionComment}
            </p>
          )}
          {summary.weekStatus === "APPROVED" && summary.approvalHistory && (
            <div className="lux-ts-summary__approval-history-wrap">
              <span className="lux-approval-history lux-approval-history--compact">
                <i className="fe fe-user-check" aria-hidden="true" />
                {summary.approvalHistory.label}
              </span>
            </div>
          )}
        </div>
        {summary.statusBreakdown.length > 0 && (
          <ul className="lux-ts-summary__status-list" aria-label="Entry status breakdown">
            {summary.statusBreakdown.map((row) => (
              <li key={row.statusKey} className={classNames("lux-ts-summary__status-chip", `is-${row.tone}`)}>
                <span>{row.label}</span>
                <strong>{row.count}</strong>
              </li>
            ))}
          </ul>
        )}
      </div>
    );
  };

  const renderDailyStatusRow = () => {
    if (!summary || !summary.dailyStatuses || !summary.dailyStatuses.length) return null;

    return (
      <div className="lux-ts-summary__day-status" role="list" aria-label="Daily entry status">
        {summary.dailyStatuses.map((day) => {
          const dayLabel = dateUtils.convertDateStringToMoment(day.dateString);
          const label = dayLabel && dayLabel.isValid() ? dayLabel.format("ddd") : day.dateString.slice(5);
          return (
            <article
              key={day.dateString}
              className={classNames("lux-ts-summary__day-status-cell", `is-${day.tone}`)}
              role="listitem"
              title={`${label}: ${day.label}`}
            >
              <span className="lux-ts-summary__day-status-label">{label}</span>
              <span className="lux-ts-summary__day-status-value">{day.label}</span>
            </article>
          );
        })}
      </div>
    );
  };

  const renderDataQuality = () => {
    if (!summary || isLoading) return null;

    const issues = summary.dataQualityIssues || [];
    const hasCritical = (summary.dataQualityCriticalCount || 0) > 0;

    if (summary.dataQualityClear) {
      return (
        <div className="lux-ts-summary__data-quality lux-ts-summary__data-quality--clear">
          <i className="fe fe-shield" aria-hidden="true" />
          <div>
            <strong>Data quality clear</strong>
            <span>No duplicate entries or open conflicts detected this week.</span>
          </div>
        </div>
      );
    }

    return (
      <div
        className={classNames("lux-ts-summary__data-quality", {
          "has-critical": hasCritical,
        })}
        role="region"
        aria-label="Timesheet data quality"
      >
        <div className="lux-ts-summary__data-quality-head">
          <div>
            <span className="lux-ts-summary__data-quality-eyebrow">Data quality</span>
            <h3 className="lux-ts-summary__data-quality-title">
              <i className="fe fe-alert-octagon" aria-hidden="true" />
              Action required before submit
            </h3>
            <p className="lux-ts-summary__data-quality-sub">
              {hasCritical
                ? "Critical conflicts block manager approval. Resolve these first."
                : "Potential duplicate rows detected — review and merge before submitting."}
            </p>
          </div>
          <div className="lux-ts-summary__data-quality-badges">
            {summary.dataQualityCriticalCount > 0 && (
              <span className="lux-ts-summary__data-quality-badge is-critical">
                <i className="fe fe-zap" aria-hidden="true" />
                {summary.dataQualityCriticalCount} critical
              </span>
            )}
            {summary.dataQualityHighCount > 0 && (
              <span className="lux-ts-summary__data-quality-badge is-high">
                <i className="fe fe-alert-triangle" aria-hidden="true" />
                {summary.dataQualityHighCount} high
              </span>
            )}
            <span className="lux-ts-summary__data-quality-badge is-important">Important</span>
          </div>
        </div>
        <ul className="lux-ts-summary__data-quality-list" aria-label="Data quality issues">
          {issues.map((issue) => (
            <li
              key={issue.id}
              className={classNames("lux-ts-summary__data-quality-item", `is-${issue.priority}`)}
            >
              <div className="lux-ts-summary__data-quality-item-main">
                <span className="lux-ts-summary__data-quality-priority">
                  {issue.priority === "critical" ? "Critical" : "High priority"}
                </span>
                <strong>{issue.label}</strong>
                <span className="lux-ts-summary__data-quality-entry">{issue.entryLabel}</span>
                <em>{issue.reason}</em>
              </div>
              <div className="lux-ts-summary__data-quality-item-meta">
                <span>{issue.dayLabel}</span>
                <strong>{issue.totalDisplay}</strong>
                {issue.rowCount > 1 && (
                  <small>{issue.rowCount} rows</small>
                )}
              </div>
            </li>
          ))}
        </ul>
      </div>
    );
  };

  const renderDaysAttention = () => {
    if (!summary || isLoading) return null;

    const attentionDays = summary.daysNeedingAttention || [];

    if (!attentionDays.length) {
      return (
        <div className="lux-ts-summary__attention lux-ts-summary__attention--clear">
          <i className="fe fe-check-circle" aria-hidden="true" />
          <div>
            <strong>All days meet the 8-hour target</strong>
            <span>Every day this week has 8 hours logged.</span>
          </div>
        </div>
      );
    }

    return (
      <div className="lux-ts-summary__attention">
        <div className="lux-ts-summary__attention-head">
          <h3 className="lux-ts-summary__attention-title">
            <i className="fe fe-alert-triangle" aria-hidden="true" />
            Days needing attention
          </h3>
          <span className="lux-ts-summary__attention-count">
            {attentionDays.length} of {summary.weekDates.length}
          </span>
        </div>
        <ul className="lux-ts-summary__attention-list" aria-label="Days below or above 8 hour target">
          {attentionDays.map((day) => (
            <li
              key={day.dateString}
              className={classNames("lux-ts-summary__attention-item", `is-${day.level}`)}
            >
              <span className="lux-ts-summary__attention-day">{day.dayLabel}</span>
              <span className="lux-ts-summary__attention-hours">{day.totalDisplay}</span>
              <span className="lux-ts-summary__attention-reason">{day.reason}</span>
            </li>
          ))}
        </ul>
      </div>
    );
  };

  const renderMixBar = () => {
    if (!summary) return null;
    const total = summary.billableMins + summary.nonProjectMins + summary.leaveOrHolidayMins;
    if (total <= 0) {
      return <div className="lux-ts-summary__mix-bar lux-ts-summary__mix-bar--empty">No hours logged this week</div>;
    }

    const segments = [
      { key: "billable", mins: summary.billableMins, tone: "green", label: "Billable" },
      { key: "nonProject", mins: summary.nonProjectMins, tone: "blue", label: "Non-billable" },
      { key: "leave", mins: summary.leaveOrHolidayMins, tone: "amber", label: "Leave / holiday" },
    ];

    return (
      <div className="lux-ts-summary__mix-bar" role="img" aria-label="Weekly time breakdown">
        {segments.map((segment) => (
          <span
            key={segment.key}
            className={classNames("lux-ts-summary__mix-segment", `is-${segment.tone}`)}
            style={{ width: `${Math.max((segment.mins / total) * 100, segment.mins > 0 ? 3 : 0)}%` }}
            title={`${segment.label}: ${convertMinsToDisplay(segment.mins)}`}
          />
        ))}
      </div>
    );
  };

  return (
    <section
      className={classNames("lux-ts-summary", {
        "is-collapsed": !expanded,
        "has-data-quality-alert": !!dataQualityCollapsedHint,
        "has-data-quality-critical": hasCriticalDataQuality,
      })}
      aria-label="Weekly timesheet summary"
    >
      <div className="lux-ts-summary__header-bar">
        <div className="lux-ts-summary__header-main">
          <LuxSummaryEyebrow variant="timesheet" className="lux-ts-summary__eyebrow">
            Week summary intelligence
          </LuxSummaryEyebrow>
          <h2 className="lux-ts-summary__title">
            {isLoading || !summary ? (
              <Skeleton width={200} height={22} />
            ) : (
              <>
                {summary.totalString} logged
                <TimesheetStatusBadge
                  statusMeta={summary.weekStatusMeta}
                  showLabel={summary.rootShow}
                  compact
                />
                <span className="lux-ts-summary__title-badge">
                  {summary.utilizationString} utilization
                </span>
                {dataQualityCollapsedHint && (
                  <span
                    className={classNames("lux-ts-summary__title-badge", "is-data-quality", {
                      "is-critical": hasCriticalDataQuality,
                    })}
                    title={dataQualityCollapsedHint}
                  >
                    <i className="fe fe-alert-octagon" aria-hidden="true" />
                    {dataQualityCollapsedHint}
                  </span>
                )}
              </>
            )}
          </h2>
          {!expanded && dataQualityCollapsedHint && (
            <p className="lux-ts-summary__collapsed-alert" role="alert">
              <i className="fe fe-zap" aria-hidden="true" />
              <strong>Important — data quality:</strong>
              <span>{dataQualityCollapsedHint}</span>
            </p>
          )}
          {!expanded && (
            <p className="lux-ts-summary__collapsed-line">
              {isLoading ? <Skeleton width="80%" height={14} /> : contextLine}
            </p>
          )}
        </div>
        <button
          type="button"
          className="lux-ts-summary__toggle"
          onClick={toggleExpanded}
          aria-expanded={expanded}
        >
          {getSummaryToggleLabel(expanded)}
          <i className={`fe fe-chevron-${expanded ? "up" : "down"}`} aria-hidden="true" />
        </button>
      </div>

      <div className="lux-ts-summary__body" aria-hidden={!expanded}>
          <p className="lux-ts-summary__context">
            {isLoading ? <Skeleton width="70%" height={14} /> : contextLine}
          </p>

          {renderStatusStrip()}
          {renderDailyStatusRow()}
          {renderMixBar()}
          {renderDataQuality()}
          {renderDaysAttention()}

          {approvalKpis.length > 0 && (
            <div className="lux-ts-summary__kpi-strip lux-ts-summary__kpi-strip--approval">
              {approvalKpis.map((def) => (
                <TimesheetKpi key={def.key} def={def} summary={summary} loading={isLoading} />
              ))}
            </div>
          )}

          <div className="lux-ts-summary__kpi-strip">
            {TIMESHEET_KPI_DEFS.map((def) => (
              <TimesheetKpi key={def.key} def={def} summary={summary} loading={isLoading} />
            ))}
          </div>

          <div className="lux-ts-summary__charts">
            <article className="lux-ts-summary__chart-panel">
              <div className="lux-ts-summary__panel-head">
                <div>
                  <h3 className="lux-ts-summary__panel-title">Entry status mix</h3>
                  <p className="lux-ts-summary__panel-sub">
                    Approved, pending, draft, and other entry states this week
                  </p>
                </div>
              </div>
              <div className="lux-ts-summary__chart-body">
                {isLoading && <Skeleton height={260} borderRadius={12} />}
                {!isLoading && !statusChart && (
                  <p className="lux-ts-summary__empty">No status-tracked entries yet.</p>
                )}
                {!isLoading && statusChart && (
                  <DashboardApexChart
                    type="donut"
                    series={statusChart.series}
                    options={statusChart.options}
                    height={260}
                  />
                )}
              </div>
            </article>

            <article className="lux-ts-summary__chart-panel">
              <div className="lux-ts-summary__panel-head">
                <div>
                  <h3 className="lux-ts-summary__panel-title">Time distribution</h3>
                  <p className="lux-ts-summary__panel-sub">
                    How this week splits across billable, non-billable, and time off
                  </p>
                </div>
              </div>
              <div className="lux-ts-summary__chart-body">
                {isLoading && <Skeleton height={260} borderRadius={12} />}
                {!isLoading && !distributionChart && (
                  <p className="lux-ts-summary__empty">No hours logged this week yet.</p>
                )}
                {!isLoading && distributionChart && (
                  <DashboardApexChart
                    type="donut"
                    series={distributionChart.series}
                    options={distributionChart.options}
                    height={260}
                  />
                )}
              </div>
            </article>

            <article className="lux-ts-summary__chart-panel lux-ts-summary__chart-panel--split">
              <div className="lux-ts-summary__panel-head">
                <div>
                  <h3 className="lux-ts-summary__panel-title">Utilization vs 40h</h3>
                  <p className="lux-ts-summary__panel-sub">
                    Billable, non-billable, and overall work utilization
                  </p>
                </div>
              </div>
              <div className="lux-ts-summary__chart-split">
                <div className="lux-ts-summary__chart-split-main">
                  {isLoading && <Skeleton height={220} borderRadius={12} />}
                  {!isLoading && utilizationChart && (
                    <DashboardApexChart
                      type="bar"
                      series={utilizationChart.series}
                      options={utilizationChart.options}
                      height={220}
                    />
                  )}
                </div>
                <div className="lux-ts-summary__chart-split-side">
                  <p className="lux-ts-summary__split-label">Daily vs 8h target</p>
                  {isLoading && <Skeleton height={220} borderRadius={12} />}
                  {!isLoading && dailyTargetChart && (
                    <DashboardApexChart
                      type="bar"
                      series={dailyTargetChart.series}
                      options={dailyTargetChart.options}
                      height={200}
                    />
                  )}
                  {!isLoading && !dailyTargetChart && weekComplianceChart && (
                    <DashboardApexChart
                      type="donut"
                      series={weekComplianceChart.series}
                      options={weekComplianceChart.options}
                      height={200}
                    />
                  )}
                </div>
              </div>
            </article>

            <article className="lux-ts-summary__chart-panel lux-ts-summary__chart-panel--wide">
              <div className="lux-ts-summary__panel-head">
                <div>
                  <h3 className="lux-ts-summary__panel-title">Daily breakdown</h3>
                  <p className="lux-ts-summary__panel-sub">Stacked hours by day for the selected week</p>
                </div>
              </div>
              <div className="lux-ts-summary__chart-body">
                {isLoading && <Skeleton height={280} borderRadius={12} />}
                {!isLoading && !dailyChart && (
                  <p className="lux-ts-summary__empty">No daily entries to chart yet.</p>
                )}
                {!isLoading && dailyChart && (
                  <DashboardApexChart
                    type="bar"
                    series={dailyChart.series}
                    options={dailyChart.options}
                    height={280}
                  />
                )}
              </div>
            </article>
          </div>
        </div>
    </section>
  );
}

export default TimesheetSummaryPanel;
