import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import {
  enrichSetupChecklistItems,
  getSetupPhaseMeta,
  groupSetupChecklistByPhase,
} from "config/customer-setup-checklist.config";

const AUTOMATION_LABEL = {
  automate: "Can automate",
  assisted: "Assisted",
  manual: "Manual",
};

/**
 * Luxury phased checklist register with docs + console actions.
 */
export default function SetupChecklistRegister({ items, saving, onToggle, filter = "ALL" }) {
  const enriched = enrichSetupChecklistItems(items);
  const filtered = enriched.filter((row) => {
    if (filter === "OPEN") return !row.done;
    if (filter === "DONE") return row.done;
    if (filter === "AUTOMATE") return row.automation === "automate";
    return true;
  });
  const phases = groupSetupChecklistByPhase(filtered);

  if (!filtered.length) {
    return (
      <p className="lux-setup-checklist__empty" role="status">
        No checklist steps match this filter.
      </p>
    );
  }

  return (
    <div className="lux-setup-checklist" data-testid="setup-checklist-register">
      {phases.map((phase) => (
        <section
          key={phase.id}
          className={classNames("lux-setup-checklist__phase", `is-${phase.tone}`, {
            "is-complete": phase.complete,
          })}
          aria-label={`${phase.label} phase`}
        >
          <header className="lux-setup-checklist__phase-head">
            <span className="lux-setup-checklist__phase-icon" aria-hidden="true">
              <i className={phase.icon} />
            </span>
            <div className="lux-setup-checklist__phase-copy">
              <strong>{phase.label}</strong>
              <em>{phase.copy}</em>
            </div>
            <span className="lux-setup-checklist__phase-count">
              {phase.done}/{phase.total}
            </span>
          </header>

          <ul className="lux-setup-checklist__list">
            {phase.items.map((row) => {
              const done = Boolean(row.done);
              const phaseMeta = getSetupPhaseMeta(row.phase);
              return (
                <li
                  key={row.id}
                  className={classNames("lux-setup-checklist__row", done && "is-done")}
                >
                  <div className="lux-setup-checklist__row-main">
                    <label className="lux-setup-checklist__label">
                      <input
                        type="checkbox"
                        className="lux-setup-checklist__check"
                        checked={done}
                        disabled={saving}
                        onChange={() => onToggle && onToggle(row.id)}
                        data-testid={`setup-checklist-${row.id}`}
                        aria-label={`${row.id} ${row.label}`}
                      />
                      <span className="lux-setup-checklist__copy">
                        <span className="lux-setup-checklist__meta">
                          <span className="lux-setup-checklist__id">{row.id}</span>
                          <span
                            className={classNames(
                              "lux-setup-checklist__auto",
                              `is-${row.automation || "manual"}`
                            )}
                          >
                            {AUTOMATION_LABEL[row.automation] || "Manual"}
                          </span>
                          <span className="lux-setup-checklist__phase-pill">{phaseMeta.label}</span>
                        </span>
                        <strong className="lux-setup-checklist__title">{row.label}</strong>
                        {row.summary ? (
                          <p className="lux-setup-checklist__summary">{row.summary}</p>
                        ) : null}
                      </span>
                    </label>
                    <span
                      className={classNames(
                        "lux-setup-checklist__badge",
                        done ? "is-done" : "is-open"
                      )}
                    >
                      {done ? "Done" : "Open"}
                    </span>
                  </div>

                  <div className="lux-setup-checklist__detail">
                    {row.why ? (
                      <p>
                        <strong>Why</strong> {row.why}
                      </p>
                    ) : null}
                    {row.how ? (
                      <p>
                        <strong>How</strong> {row.how}
                      </p>
                    ) : null}
                    {row.automationHint ? (
                      <p className="lux-setup-checklist__auto-hint">
                        <i className="fe fe-cpu" aria-hidden="true" />
                        {row.automationHint}
                      </p>
                    ) : null}

                    <div className="lux-setup-checklist__links">
                      {(row.actions || []).map((action) => (
                        <Link
                          key={`${row.id}-${action.to}`}
                          to={action.to}
                          className="lux-setup-checklist__action"
                        >
                          <i className={action.icon || "fe fe-arrow-right"} aria-hidden="true" />
                          {action.label}
                        </Link>
                      ))}
                      {(row.docs || []).map((doc) => (
                        <a
                          key={`${row.id}-${doc.href}`}
                          href={doc.href}
                          className="lux-setup-checklist__doc"
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          <i className="fe fe-book-open" aria-hidden="true" />
                          {doc.label}
                        </a>
                      ))}
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
        </section>
      ))}
    </div>
  );
}
