import React from "react";
import classNames from "classnames/bind";
import { getGateStatusTone } from "config/project-governance.utils";

export default function GateCompliancePanel({ model, loading }) {
  if (loading || !model || !model.rows.length) {
    return (
      <div className="lux-gov-gate-compliance lux-gov-gate-compliance--empty">
        <p>No stage gates to chart. Add gates to track compliance by delivery stage.</p>
      </div>
    );
  }

  return (
    <div className="lux-gov-gate-compliance">
      <div className="lux-gov-gate-compliance__summary">
        <strong>{model.overallApprovedPct}%</strong>
        <span>overall gate approval rate</span>
      </div>
      <div className="lux-gov-gate-compliance__grid">
        {model.rows.map((row) => (
          <article key={row.stage} className="lux-gov-gate-compliance__card">
            <header>
              <h3>{row.stage}</h3>
              <span>{row.approvedPct}% approved</span>
            </header>
            <div className="lux-gov-gate-compliance__counts">
              {model.statuses.map((status) => {
                const count = row.counts[status] || 0;
                const tone = getGateStatusTone(status);
                return (
                  <span
                    key={`${row.stage}-${status}`}
                    className={classNames("lux-gov-gate-compliance__chip", `is-${tone}`, {
                      "is-active": count > 0,
                    })}
                  >
                    {status.toLowerCase()} · {count}
                  </span>
                );
              })}
            </div>
          </article>
        ))}
      </div>
    </div>
  );
}
