import React from "react";
import { Link } from "react-router-dom";
import { usePersonaContext } from "hooks/usePersonaContext";
import { canShowEmployee360Entry } from "config/employee360.utils";
import { buildEmployee360Link } from "views/people/employee360Navigation.utils";

/**
 * Profile back-nav action — Employee 360 when feature and persona allow it.
 */
export default function Employee360ProfileEntryLink({ employeeId, location }) {
  const { menuAccessControl, activePersona } = usePersonaContext();

  if (!employeeId || !canShowEmployee360Entry(menuAccessControl, activePersona)) {
    return null;
  }

  return (
    <Link
      to={buildEmployee360Link(employeeId, location, "Profile")}
      className="lux-back-nav__action-link lux-employee-360-entry-link"
    >
      <i className="fe fe-layers" aria-hidden="true" />
      <span>Employee 360</span>
    </Link>
  );
}
