import React from "react";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { getEmployeeDisplayName } from "config/employee360.utils";

function buildLearningTabStats(learning, assignments) {
  const assigned =
    learning.assignedCount != null ? learning.assignedCount : assignments.length;
  const completed =
    learning.completedCount != null
      ? learning.completedCount
      : assignments.filter((row) => String(row.status || "").toUpperCase() === "COMPLETED").length;
  const inProgress = assignments.filter((row) => {
    const status = String(row.status || "").toUpperCase();
    return status.includes("PROGRESS") || status.includes("ACTIVE");
  }).length;

  return [
    {
      key: "assigned",
      label: "Assigned",
      value: String(assigned),
      hint: "LMS assignments",
      tone: assigned > 0 ? "indigo" : "slate",
    },
    {
      key: "progress",
      label: "In progress",
      value: String(inProgress),
      hint: "Active courses",
      tone: inProgress > 0 ? "amber" : "slate",
    },
    {
      key: "completed",
      label: "Completed",
      value: String(completed),
      hint: "Finished courses",
      tone: completed > 0 ? "green" : "slate",
    },
  ];
}

export default function Employee360LearningTab({ employee, summary }) {
  if (!employee) {
    return null;
  }

  const learning = (summary && summary.learning) || {};
  const assignments = Array.isArray(learning.assignments) ? learning.assignments : [];
  const stats = buildLearningTabStats(learning, assignments);
  const displayName = getEmployeeDisplayName(employee);

  return (
    <ProjectDetailsTabShell
      icon="fe fe-book-open"
      eyebrow="Learning"
      title="Learning assignments"
      subtitle={`Read-only LMS progress for ${displayName}. Employee source of truth is unchanged.`}
      stats={stats}
      className="lux-employee-360__embed lux-employee-360__embed--learning"
    >
      <div className="lux-employee-360__embed-toolbar" data-testid="employee360-learning-tab">
        <strong className="lux-employee-360__embed-period">
          {assignments.length} assignment{assignments.length === 1 ? "" : "s"}
        </strong>
        <Link to="/learning/my-learning" className="lux-employee-360__embed-link">
          Open My Learning
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
        <Link to="/learning/assignments" className="lux-employee-360__embed-link">
          Assignments
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
      </div>

      {assignments.length === 0 ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__embed-empty"
          icon="fe fe-book-open"
          title="No learning assignments"
          description="No LMS assignments are linked for this employee yet. Assign courses from Learning when a curriculum is ready."
        />
      ) : (
        <div className="lux-employee-360__register-wrap">
          <table className="lux-employee-360__register">
            <thead>
              <tr>
                <th>Assignment</th>
                <th>Status</th>
                <th>Progress</th>
                <th>Due</th>
              </tr>
            </thead>
            <tbody>
              {assignments.map((row) => (
                <tr key={row.assignmentRef || row.assignmentId || row.id}>
                  <td>{row.assignmentRef || row.title || "—"}</td>
                  <td>
                    <span className="lux-employee-360__badge">{row.status || "—"}</span>
                  </td>
                  <td>
                    {row.percentComplete != null ? `${row.percentComplete}%` : "—"}
                  </td>
                  <td>{row.dueDate || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </ProjectDetailsTabShell>
  );
}
