import React, { Component } from "react";
import { commonUtils } from "_helpers";
import {
  getOrgCategoryLabel,
  getOrgNodeIcon,
  normalizeSearch,
  treeHasMatch,
} from "./appConfigTree.utils";

class ApplicationConfigTree extends Component {
  constructor(props) {
    super(props);
    this.state = {
      expanded: {},
      createValues: {},
    };
  }

  componentDidMount() {
    this.expandDefaults();
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.searchQuery !== this.props.searchQuery &&
      normalizeSearch(this.props.searchQuery)
    ) {
      this.expandAllForSearch();
    }
    if (prevProps.type !== this.props.type || prevProps.rootNode !== this.props.rootNode) {
      this.expandDefaults();
    }
  }

  expandDefaults = () => {
    const { rootNode, type } = this.props;
    if (!rootNode || !rootNode.nodes) return;

    const expanded = { ...this.state.expanded };
    rootNode.nodes.forEach((node, index) => {
      if (node && node.id != null) {
        expanded[this.nodeKey(node.id)] = index === 0 || expanded[this.nodeKey(node.id)];
      }
    });
    this.setState({ expanded });
  };

  expandAllForSearch = () => {
    const { rootNode } = this.props;
    const query = normalizeSearch(this.props.searchQuery);
    if (!query || !rootNode) return;

    const expanded = { ...this.state.expanded };
    const walk = (node) => {
      if (!node) return;
      if (node.id != null && node.nodes && node.nodes.length > 0) {
        if (treeHasMatch(node, query)) {
          expanded[this.nodeKey(node.id)] = true;
        }
      }
      (node.nodes || []).forEach(walk);
    };
    walk(rootNode);
    this.setState({ expanded });
  };

  nodeKey = (id) => `${this.props.type}-${id}`;

  isExpanded = (id, hasChildren) => {
    if (!hasChildren) return false;
    const query = normalizeSearch(this.props.searchQuery);
    if (query) {
      const node = this.findNodeById(this.props.rootNode, id);
      if (node && treeHasMatch(node, query)) return true;
    }
    return Boolean(this.state.expanded[this.nodeKey(id)]);
  };

  findNodeById = (node, id) => {
    if (!node) return null;
    if (node.id === id) return node;
    for (const child of node.nodes || []) {
      const found = this.findNodeById(child, id);
      if (found) return found;
    }
    return null;
  };

  toggleExpanded = (event, id) => {
    event.stopPropagation();
    const key = this.nodeKey(id);
    this.setState((prev) => ({
      expanded: {
        ...prev.expanded,
        [key]: !prev.expanded[key],
      },
    }));
  };

    handleSelect = (node, disabled) => {
        if (disabled || !node || node.id == null) return;
        this.props.onSelect(node.id, this.props.type, node.category);
        requestAnimationFrame(() => {
            const el = document.getElementById(`lux-ac-node-${this.props.type}-${node.id}`);
            if (el && typeof el.scrollIntoView === "function") {
                el.scrollIntoView({ block: "nearest", behavior: "smooth" });
            }
        });
    };

    expandAll = () => {
        const { rootNode } = this.props;
        if (!rootNode) return;
        const expanded = {};
        const walk = (node) => {
            if (!node) return;
            if (node.id != null && node.nodes && node.nodes.length > 0) {
                expanded[this.nodeKey(node.id)] = true;
            }
            (node.nodes || []).forEach(walk);
        };
        walk(rootNode);
        this.setState({ expanded });
    };

    collapseAll = () => {
        this.setState({ expanded: {} }, this.expandDefaults);
    };

  handleCreateInput = (parentId, value) => {
    this.setState((prev) => ({
      createValues: {
        ...prev.createValues,
        [this.nodeKey(parentId)]: value,
      },
    }));
  };

  handleCreateSubmit = (parentId) => {
    const value = (this.state.createValues[this.nodeKey(parentId)] || "").trim();
    if (value.length <= 3) return;
    this.props.onCreateItem(value, parentId);
    this.props.onClearCreate();
    this.setState((prev) => ({
      createValues: {
        ...prev.createValues,
        [this.nodeKey(parentId)]: "",
      },
    }));
  };

  renderCreateRow = (parentId, depth) => {
    const key = this.nodeKey(parentId);
    const value = this.state.createValues[key] || "";

    return (
      <div className="lux-ac-tree-create">
        <input
          type="text"
          className="lux-ac-tree-create__input"
          placeholder="New item name..."
          value={value}
          autoFocus
          onChange={(e) => this.handleCreateInput(parentId, e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") this.handleCreateSubmit(parentId);
            if (e.key === "Escape") this.props.onClearCreate();
          }}
        />
        <button
          type="button"
          className="lux-ac-tree-create__btn lux-ac-tree-create__btn--save"
          disabled={value.trim().length <= 3}
          onClick={() => this.handleCreateSubmit(parentId)}
          title="Save"
        >
          <i className="fe fe-check" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-ac-tree-create__btn"
          onClick={this.props.onClearCreate}
          title="Cancel"
        >
          <i className="fe fe-x" aria-hidden="true" />
        </button>
      </div>
    );
  };

  renderNode = (node, depth, isRootDisabled) => {
    if (!node) return null;

    const query = normalizeSearch(this.props.searchQuery);
    if (query && !treeHasMatch(node, query)) return null;

    const children = (node.nodes || []).filter(Boolean);
    const hasChildren = children.length > 0;
    const isSelected =
      this.props.selection &&
      this.props.selection.id === node.id &&
      this.props.selection.type === this.props.type;

    if (!node.name) {
      return (
        <div className="lux-ac-tree-branch" key={`branch-${depth}-root`}>
          {children.map((child, index) =>
            this.renderNode(
              child,
              depth,
              this.props.isRootTree && index === 0 && commonUtils.getCurrentUser().userRole != 2
            )
          )}
        </div>
      );
    }

    const isDefault =
      this.props.type === "role"
        ? node.id === commonUtils.getCurrentUser().userRole
        : node.id === commonUtils.getCurrentUserTeamId();

    const isCreating =
      this.props.createParentItem &&
      this.props.createParentItem.id === node.id &&
      this.props.createParentItem.type === this.props.type;

    const expanded = this.isExpanded(node.id, hasChildren);
    const icon =
      this.props.type === "role" ? "fe-shield" : getOrgNodeIcon(node.category);

    return (
      <div className="lux-ac-tree-node" key={`${this.props.type}-${node.id}`}>
        <div
          id={`lux-ac-node-${this.props.type}-${node.id}`}
          className={`lux-ac-tree-row${isSelected ? " is-selected" : ""}${isRootDisabled ? " is-disabled" : ""}`}
        >
          {hasChildren ? (
            <button
              type="button"
              className={`lux-ac-tree-toggle${expanded ? " is-open" : ""}`}
              aria-expanded={expanded}
              aria-label={expanded ? "Collapse" : "Expand"}
              onClick={(e) => this.toggleExpanded(e, node.id)}
            >
              <i className="fe fe-chevron-right" aria-hidden="true" />
            </button>
          ) : (
            <span className="lux-ac-tree-toggle lux-ac-tree-toggle--spacer" aria-hidden="true" />
          )}

          <button
            type="button"
            className="lux-ac-tree-label"
            disabled={isRootDisabled}
            onClick={() => this.handleSelect(node, isRootDisabled)}
          >
            <span className={`lux-ac-tree-icon lux-ac-tree-icon--${this.props.type}`}>
              <i className={`fe ${icon}`} aria-hidden="true" />
            </span>
            <span className="lux-ac-tree-copy">
              <span className="lux-ac-tree-name" title={node.name}>{node.name}</span>
              {this.props.type === "org" && node.category && (
                <span className="lux-ac-tree-badge">{getOrgCategoryLabel(node.category)}</span>
              )}
              {isDefault && (
                <span className="lux-ac-tree-current" title="Your current context">
                  Current
                </span>
              )}
            </span>
          </button>
        </div>

        {isCreating && this.renderCreateRow(node.id, depth + 1)}

        {hasChildren && expanded && (
          <div className="lux-ac-tree-children">
            {children.map((child, index) =>
              this.renderNode(child, depth + 1, false)
            )}
          </div>
        )}
      </div>
    );
  };

  render() {
    const { rootNode } = this.props;
    if (!rootNode) {
      return <p className="lux-ac-tree-empty">No items available.</p>;
    }

    return (
      <div className="lux-ac-tree" role="tree">
        {this.renderNode(rootNode, 0, false)}
      </div>
    );
  }
}

export default ApplicationConfigTree;