import React from "react";
import classNames from "classnames/bind";
import { DeveloperLuxPanel, DeveloperStatusBadge } from "views/developer/components/DeveloperLuxShared";

export default function AppRegistryPanel({ apps, loading }) {
  const rows = apps || [];

  return (
    <DeveloperLuxPanel title="App registry" meta="Installed apps and sandboxes" icon="fe fe-package" accent="cyan" featured>
      {loading ? (
        <div className="lux-dev-skeleton lux-dev-skeleton--panel" />
      ) : !rows.length ? (
        <div className="lux-dev-empty">No apps installed yet.</div>
      ) : (
        <div className="lux-dev-register">
          {rows.map((row, index) => (
            <article key={row.id} className={classNames("lux-dev-register__row", row.tone && `is-${row.tone}`)}>
              <span className="lux-dev-register__index">{String(index + 1).padStart(2, "0")}</span>
              <span className="lux-dev-register__rail">
                <i className="fe fe-box" aria-hidden="true" />
              </span>
              <div className="lux-dev-register__main">
                <span className="lux-dev-register__eyebrow">
                  {row.environment || "production"} · {(Number(row.apiCalls30d) || 0).toLocaleString()} calls / 30d
                </span>
                <h3>{row.name}</h3>
                <div className="lux-dev-register__meta">
                  <DeveloperStatusBadge status={row.status} />
                  <span>{Number(row.webhookCount) || 0} webhooks</span>
                  <span>{row.ownerName}</span>
                </div>
              </div>
            </article>
          ))}
        </div>
      )}
    </DeveloperLuxPanel>
  );
}
