import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { GOVERNANCE_MODULE_NAV } from "config/project-governance-nav.config";

export function GovernanceDrawerLinks({ links, onNavigate }) {
  if (!links || !links.length) {
    return null;
  }

  return (
    <nav className="lux-gov-drawer__links" aria-label="Related workspaces">
      {links.map((link) => (
        <Link
          key={`${link.to}-${link.label}`}
          to={link.to}
          className="lux-gov-drawer__link-card"
          onClick={onNavigate}
        >
          <span className="lux-gov-drawer__link-icon" aria-hidden="true">
            <i className={link.icon || "fe fe-arrow-up-right"} />
          </span>
          <span className="lux-gov-drawer__link-copy">
            <strong>{link.label}</strong>
            {link.hint ? <small>{link.hint}</small> : null}
          </span>
          <i className="fe fe-chevron-right lux-gov-drawer__link-chevron" aria-hidden="true" />
        </Link>
      ))}
    </nav>
  );
}

export function GovernanceDrawerStatStrip({ stats }) {
  if (!stats || !stats.length) {
    return null;
  }

  return (
    <div className="lux-gov-drawer__stat-strip" role="list">
      {stats.map((stat) => (
        <article
          key={stat.label}
          className={classNames("lux-gov-drawer__stat", stat.tone && `is-${stat.tone}`)}
          role="listitem"
        >
          <span className="lux-gov-drawer__stat-label">{stat.label}</span>
          <strong className="lux-gov-drawer__stat-value">{stat.value}</strong>
          {stat.hint ? <small className="lux-gov-drawer__stat-hint">{stat.hint}</small> : null}
        </article>
      ))}
    </div>
  );
}

export function GovernanceDrawerCard({ title, subtitle, children, className, tone }) {
  return (
    <section className={classNames("lux-gov-drawer__card", tone && `is-${tone}`, className)}>
      <header className="lux-gov-drawer__card-head">
        <h3>{title}</h3>
        {subtitle ? <p>{subtitle}</p> : null}
      </header>
      <div className="lux-gov-drawer__card-body">{children}</div>
    </section>
  );
}

export function GovernanceDrawerMeta({ items }) {
  if (!items || !items.length) {
    return null;
  }

  return (
    <dl className="lux-gov-drawer__meta-grid">
      {items.map((item) => (
        <div key={item.label}>
          <dt>{item.label}</dt>
          <dd>{item.value != null ? item.value : "—"}</dd>
        </div>
      ))}
    </dl>
  );
}

export function GovernanceDrawerField({ label, children }) {
  return (
    <label className="lux-gov-drawer__field">
      <span>{label}</span>
      {children}
    </label>
  );
}

export function GovernanceDrawerBanner({ icon = "fe-info", tone = "info", children }) {
  const iconClass = icon.startsWith("fe-") ? icon : `fe-${icon}`;

  return (
    <div className={classNames("lux-gov-drawer__banner", tone && `is-${tone}`)}>
      <span className="lux-gov-drawer__banner-icon" aria-hidden="true">
        <i className={classNames("fe", iconClass)} />
      </span>
      <div className="lux-gov-drawer__banner-copy">{children}</div>
    </div>
  );
}

export function GovernanceDrawerModuleLink({ to, label, onNavigate }) {
  if (!to) {
    return null;
  }

  return (
    <Link to={to} className="lux-gov-drawer__module-link" onClick={onNavigate}>
      <i className="fe fe-external-link" aria-hidden="true" />
      {label}
    </Link>
  );
}

/** Quick links to sibling governance modules (excludes current page id). */
export function buildGovernanceQuickLinks(excludePageId, extraLinks = []) {
  const moduleLinks = GOVERNANCE_MODULE_NAV.filter((item) => item.id !== excludePageId).map((item) => ({
    to: item.path,
    label: item.label,
    hint: item.shortLabel,
    icon: item.icon,
  }));

  return [...extraLinks, ...moduleLinks];
}
