import { UNIVERSAL_APPROVAL_DOMAINS } from "config/universal-approval.config";
import { shouldUseApprovalPolicyAdmin } from "config/tracopus-pilot.config";

export function isApprovalPolicyAdminEnabled() {
  return shouldUseApprovalPolicyAdmin();
}

export function getApprovalPolicyDomainOptions() {
  return UNIVERSAL_APPROVAL_DOMAINS.filter((domain) => domain.planned !== true).map((domain) => ({
    id: domain.id,
    label: domain.label,
    planned: domain.planned === true,
  }));
}

export function getApprovalPolicyStatusTone(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "active") {
    return "success";
  }
  if (normalized === "draft") {
    return "warning";
  }
  return "slate";
}

export function buildApprovalPolicyMetrics(policies) {
  const rows = policies || [];
  const active = rows.filter((row) => String(row.status).toLowerCase() === "active");
  const draft = rows.filter((row) => String(row.status).toLowerCase() === "draft");
  const withEscalation = rows.filter((row) => row.autoEscalate);
  const withReminders = rows.filter((row) => row.reminderEnabled);
  const domains = new Set(rows.map((row) => row.domain));

  return {
    total: rows.length,
    active: active.length,
    draft: draft.length,
    autoEscalate: withEscalation.length,
    reminders: withReminders.length,
    domains: domains.size,
  };
}

export function filterApprovalPolicies(policies, filters = {}) {
  const { status, domain, query } = filters;
  return (policies || []).filter((row) => {
    if (status && status !== "ALL" && String(row.status).toLowerCase() !== String(status).toLowerCase()) {
      return false;
    }
    if (domain && domain !== "ALL" && row.domain !== domain) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [
        row.name,
        row.description,
        row.domain,
        ...(row.approverLevels || []),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildApprovalPolicyInsights(policies) {
  const rows = policies || [];
  const draft = rows.filter((row) => String(row.status).toLowerCase() === "draft");
  const noEscalation = rows.filter((row) => !row.autoEscalate && String(row.status).toLowerCase() === "active");
  const insights = [];

  if (draft.length > 0) {
    insights.push({
      id: "draft",
      tone: "amber",
      icon: "fe fe-edit-3",
      eyebrow: "Publish",
      stat: draft.length,
      title: `${draft.length} draft polic${draft.length === 1 ? "y" : "ies"}`,
      copy: "Review and publish before they govern live approvals.",
      hint: "Draft rules never resolve runtime authority.",
    });
  }
  if (noEscalation.length > 0) {
    insights.push({
      id: "escalation",
      tone: "blue",
      icon: "fe fe-clock",
      eyebrow: "SLA",
      stat: noEscalation.length,
      title: "Active without auto-escalate",
      copy: `${noEscalation.length} live polic${noEscalation.length === 1 ? "y" : "ies"} rely on manual follow-up.`,
      hint: "Enable auto-escalate for time-sensitive domains.",
    });
  }
  const noReminder = rows.filter(
    (row) => !row.reminderEnabled && String(row.status).toLowerCase() === "active"
  );
  if (noReminder.length > 0) {
    insights.push({
      id: "reminders",
      tone: "slate",
      icon: "fe fe-bell-off",
      eyebrow: "Nudges",
      stat: noReminder.length,
      title: "Reminders off",
      copy: `${noReminder.length} active polic${noReminder.length === 1 ? "y" : "ies"} skip reminder nudges.`,
      hint: "Reminders reduce stalled approval queues.",
    });
  }
  if (rows.length > 0 && draft.length === 0 && insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-shield",
      eyebrow: "Status",
      stat: rows.length,
      title: "All policies published",
      copy: `${rows.length} domain rule(s) active in the approval engine.`,
      hint: "Keep SLA and escalation aligned with delegation coverage.",
    });
  }
  return insights.slice(0, 6);
}

export function buildApprovalPolicySummary(policies) {
  const metrics = buildApprovalPolicyMetrics(policies);
  const rows = policies || [];
  const domainCounts = {};
  rows.forEach((row) => {
    const key = row.domain || "unknown";
    domainCounts[key] = (domainCounts[key] || 0) + 1;
  });
  const domainRows = Object.entries(domainCounts)
    .map(([label, count]) => ({
      key: label,
      label,
      count,
      pct: rows.length ? Math.round((count / rows.length) * 100) : 0,
      tone: "indigo",
      icon: "fe fe-git-branch",
      meta: String(count),
      value: count,
    }))
    .sort((a, b) => b.count - a.count);

  const statusTotal = Math.max(metrics.active + metrics.draft, 1);
  return {
    metrics,
    attention: buildApprovalPolicyInsights(policies),
    mixInsights: [
      {
        key: "status",
        icon: "fe fe-toggle-right",
        title: "Policy status mix",
        subtitle: `${metrics.active} active · ${metrics.draft} draft`,
        mix: [
          {
            key: "active",
            label: "Active",
            count: metrics.active,
            pct: Math.round((metrics.active / statusTotal) * 100),
            tone: "green",
          },
          {
            key: "draft",
            label: "Draft",
            count: metrics.draft,
            pct: Math.round((metrics.draft / statusTotal) * 100),
            tone: "amber",
          },
        ],
      },
      {
        key: "controls",
        icon: "fe fe-sliders",
        title: "Control coverage",
        subtitle: "Escalation and reminder enablement",
        mix: [
          {
            key: "escalate",
            label: "Auto-escalate",
            count: metrics.autoEscalate,
            pct: rows.length ? Math.round((metrics.autoEscalate / rows.length) * 100) : 0,
            tone: "blue",
          },
          {
            key: "reminders",
            label: "Reminders",
            count: metrics.reminders,
            pct: rows.length ? Math.round((metrics.reminders / rows.length) * 100) : 0,
            tone: "violet",
          },
          {
            key: "plain",
            label: "Neither",
            count: rows.filter((row) => !row.autoEscalate && !row.reminderEnabled).length,
            pct: rows.length
              ? Math.round(
                  (rows.filter((row) => !row.autoEscalate && !row.reminderEnabled).length /
                    rows.length) *
                    100
                )
              : 0,
            tone: "slate",
          },
        ],
      },
    ],
    series: [
      {
        id: "domains",
        title: "By domain",
        subtitle: `${metrics.domains} domain surface(s)`,
        rows: domainRows,
        emptyLabel: "No policies yet",
      },
    ],
    kpis: [
      {
        key: "total",
        label: "Policies",
        value: metrics.total,
        hint: `${metrics.domains} domains`,
        tone: "primary",
        icon: "fe fe-layers",
      },
      {
        key: "active",
        label: "Active",
        value: metrics.active,
        hint: "Governing live queues",
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        key: "draft",
        label: "Draft",
        value: metrics.draft,
        hint: "Not yet published",
        tone: "amber",
        icon: "fe fe-edit-3",
      },
      {
        key: "escalate",
        label: "Auto-escalate",
        value: metrics.autoEscalate,
        hint: `${metrics.reminders} with reminders`,
        tone: "blue",
        icon: "fe fe-zap",
      },
    ],
    highlights: [
      {
        key: "domains",
        label: "Domains covered",
        value: metrics.domains,
        hint: "Distinct approval surfaces",
        tone: "indigo",
        icon: "fe fe-git-branch",
      },
      {
        key: "reminders",
        label: "Reminders on",
        value: metrics.reminders,
        hint: "Nudge-enabled policies",
        tone: "violet",
        icon: "fe fe-bell",
      },
    ],
  };
}

export function formatApprovalPolicySla(policy) {
  if (!policy || policy.slaHours == null) {
    return "—";
  }
  const base = `${policy.slaHours}h SLA`;
  if (policy.escalationHours != null) {
    return `${base} · esc ${policy.escalationHours}h`;
  }
  return base;
}

export function normalizeApprovalPolicy(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    domain: row.domain,
    name: row.name,
    description: row.description || "",
    slaHours: row.slaHours != null ? row.slaHours : null,
    escalationHours: row.escalationHours != null ? row.escalationHours : null,
    approverLevels: Array.isArray(row.approverLevels) ? row.approverLevels : [],
    autoEscalate: row.autoEscalate === true,
    reminderEnabled: row.reminderEnabled === true,
    status: row.status || "Draft",
    updatedAt: row.updatedAt || null,
  };
}
