import {
  toAreaChart,
  toDonutChart,
  toGroupedBarChart,
} from "views/hrms/components/dashboard/employeeDashboard.utils";

const STATUS_COLORS = {
  NEW: "#0ea5e9",
  CREATED: "#6366f1",
  INPROGRESS: "#f59e0b",
  IN_PROGRESS: "#f59e0b",
  COMPLETED: "#10b981",
  CLOSED: "#475569",
};

const TIMELINE_COLORS = {
  OVERDUE: "#f43f5e",
  DUE_SOON: "#f59e0b",
  ON_TRACK: "#10b981",
  NO_DATE: "#94a3b8",
};

const SOURCE_COLORS = { SF: "#0ea5e9", MANUAL: "#6366f1" };

const TYPE_COLORS = [
  "#5b5ff4",
  "#8b5cf6",
  "#0ea5e9",
  "#f59e0b",
  "#14b8a6",
  "#10b981",
  "#64748b",
];

const LUX_CHART_FONT = {
  fontFamily: "Inter, system-ui, sans-serif",
  fontSize: "11px",
  fontWeight: 600,
};

function applyLuxChartBase(options) {
  return {
    ...options,
    chart: {
      ...(options.chart || {}),
      fontFamily: LUX_CHART_FONT.fontFamily,
      toolbar: { show: false },
    },
    grid: {
      borderColor: "rgba(226,232,240,0.85)",
      strokeDashArray: 4,
      ...(options.grid || {}),
    },
  };
}

function withDonutCenter(chart, centerLabel, centerValue) {
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "76%",
        labels: {
          show: true,
          name: { show: true, fontSize: "11px", fontWeight: 600, color: "#64748b" },
          value: {
            show: true,
            fontSize: "15px",
            fontWeight: 800,
            color: "#0f172a",
          },
          total: {
            show: true,
            label: centerLabel,
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(centerValue),
          },
        },
      },
    },
  };
  chart.options.legend = {
    position: "bottom",
    fontSize: "10px",
    fontWeight: 600,
    offsetY: 0,
    itemMargin: { horizontal: 6, vertical: 2 },
    labels: { colors: "#475569" },
  };
  chart.options.chart = {
    ...chart.options.chart,
    sparkline: { enabled: false },
    parentHeightOffset: 0,
    fontFamily: LUX_CHART_FONT.fontFamily,
  };
  chart.options.stroke = { width: 2, colors: ["#fff"] };
  return chart;
}

export function buildPoStatusDonutChart(stat) {
  if (!stat.statusMix || !stat.statusMix.length) return null;
  const labels = stat.statusMix.map((s) => s.label);
  const series = stat.statusMix.map((s) => s.count);
  const colors = stat.statusMix.map((s) => STATUS_COLORS[s.key] || "#94a3b8");
  const chart = toDonutChart(labels, series, colors);
  return withDonutCenter(chart, "Active contracts", stat.active);
}

export function buildPoOutcomeDonutChart(stat) {
  const { outcomes } = stat;
  const segments = [
    { label: "Open pipeline", value: outcomes.open, color: "#6366f1" },
    { label: "Completed", value: outcomes.completed, color: "#10b981" },
    { label: "Closed", value: outcomes.closed, color: "#94a3b8" },
    { label: "Archived", value: outcomes.other, color: "#f43f5e" },
  ].filter((s) => s.value > 0);

  if (!segments.length) return null;

  const chart = toDonutChart(
    segments.map((s) => s.label),
    segments.map((s) => s.value),
    segments.map((s) => s.color)
  );
  const total = segments.reduce((a, s) => a + s.value, 0);
  return withDonutCenter(chart, "Portfolio", total);
}

export function buildPoSourceDonutChart(stat) {
  if (!stat.sourceMix || !stat.sourceMix.length) return null;
  const labels = stat.sourceMix.map((s) => s.label);
  const series = stat.sourceMix.map((s) => s.count);
  const colors = stat.sourceMix.map((s) => SOURCE_COLORS[s.key] || "#94a3b8");
  const chart = toDonutChart(labels, series, colors);
  return withDonutCenter(chart, "Channels", stat.active);
}

export function buildPoTimelineHealthDonutChart(stat) {
  if (!stat.timelineMix || !stat.timelineMix.length) return null;
  const labels = stat.timelineMix.map((s) => s.label);
  const series = stat.timelineMix.map((s) => s.count);
  const colors = stat.timelineMix.map((s) => TIMELINE_COLORS[s.key] || "#94a3b8");
  const total = series.reduce((a, b) => a + b, 0);
  const chart = toDonutChart(labels, series, colors);
  return withDonutCenter(chart, "Open delivery", total);
}

export function buildPoBidLinkDonutChart(stat) {
  const linked = stat.bidLinkedCount || 0;
  const standalone = Math.max((stat.active || 0) - linked, 0);
  if (!linked && !standalone) return null;

  const chart = toDonutChart(
    ["Bid linked", "Standalone"],
    [linked, standalone],
    ["#6366f1", "#94a3b8"]
  );
  return withDonutCenter(chart, "Linkage", stat.active);
}

export function buildPoProjectTypeBarChart(stat) {
  if (!stat.projectTypeMix || !stat.projectTypeMix.length) return null;

  const categories = stat.projectTypeMix.map((s) => s.label);
  const data = stat.projectTypeMix.map((s) => s.count);
  const chart = toGroupedBarChart(
    categories,
    [{ name: "Contracts", data }],
    TYPE_COLORS
  );

  chart.options = applyLuxChartBase({
    ...chart.options,
    plotOptions: {
      bar: {
        horizontal: false,
        borderRadius: 8,
        columnWidth: "48%",
        distributed: true,
      },
    },
    xaxis: {
      categories,
      labels: {
        style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" },
        rotate: -20,
        trim: true,
      },
    },
    yaxis: {
      labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      tickAmount: 4,
    },
    legend: { show: false },
    colors: stat.projectTypeMix.map((_, i) => TYPE_COLORS[i % TYPE_COLORS.length]),
    grid: { padding: { top: -8, right: 4, bottom: -4, left: 4 } },
  });

  return chart;
}

export function buildPoAccountBarChart(stat) {
  if (!stat.accountMix || !stat.accountMix.length) return null;
  return buildPoHorizontalBarChart(stat.accountMix, "Contracts", "account");
}

export function buildPoTeamBarChart(stat) {
  if (!stat.teamMix || !stat.teamMix.length) return null;
  return buildPoHorizontalBarChart(stat.teamMix, "By team", "team");
}

function buildPoHorizontalBarChart(mix, seriesName, _kind) {
  const categories = mix.map((s) => s.label);
  const data = mix.map((s) => s.count);

  return {
    series: [{ name: seriesName, data }],
    options: applyLuxChartBase({
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "62%",
          distributed: true,
          dataLabels: { position: "center" },
        },
      },
      colors: categories.map((_, i) => TYPE_COLORS[i % TYPE_COLORS.length]),
      dataLabels: {
        enabled: true,
        style: { fontSize: "10px", fontWeight: 800, colors: ["#fff"] },
        formatter: (val) => (val > 0 ? String(val) : ""),
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" } },
      },
      yaxis: {
        labels: {
          style: { fontSize: "10px", colors: "#475569" },
          maxWidth: 120,
        },
      },
      legend: { show: false },
      tooltip: {
        theme: "light",
        y: { formatter: (val) => `${val} contract${val === 1 ? "" : "s"}` },
      },
      grid: { padding: { left: 4, right: 8 } },
    }),
  };
}

export function buildPoFunnelBarChart(stat) {
  if (!stat.funnel || !stat.funnel.some((f) => f.count > 0)) return null;

  const categories = stat.funnel.map((f) => f.label);
  const data = stat.funnel.map((f) => f.count);
  const colors = stat.funnel.map((f) => STATUS_COLORS[f.key] || "#94a3b8");

  return {
    series: [{ name: "Contracts", data }],
    options: applyLuxChartBase({
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "62%",
          distributed: true,
          dataLabels: { position: "center" },
        },
      },
      colors,
      dataLabels: {
        enabled: true,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#fff"] },
        formatter: (val) => (val > 0 ? String(val) : ""),
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "11px", fontWeight: 600, colors: "#475569" } },
      },
      yaxis: {
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      },
      legend: { show: false },
      tooltip: {
        theme: "light",
        y: { formatter: (val) => `${val} contract${val === 1 ? "" : "s"}` },
      },
      grid: { padding: { left: 8, right: 12 } },
    }),
  };
}

export function buildPoCreatedTrendAreaChart(stat) {
  if (!stat.createdTrend || !stat.createdTrend.length) return null;
  if (!stat.createdTrend.some((b) => b.count > 0)) return null;

  const categories = stat.createdTrend.map((b) => b.label);
  const data = stat.createdTrend.map((b) => b.count);
  const chart = toAreaChart(
    categories,
    [{ name: "New contracts", data }],
    ["#5b5ff4"]
  );

  chart.options = applyLuxChartBase({
    ...chart.options,
    stroke: { curve: "smooth", width: 2.5 },
    fill: {
      type: "gradient",
      gradient: {
        shadeIntensity: 0.9,
        opacityFrom: 0.45,
        opacityTo: 0.06,
        stops: [0, 92, 100],
      },
    },
    markers: {
      size: 4,
      strokeWidth: 2,
      strokeColors: "#fff",
      hover: { size: 5 },
    },
    xaxis: {
      categories,
      labels: {
        style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" },
      },
      axisBorder: { show: false },
      axisTicks: { show: false },
    },
    yaxis: {
      labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      tickAmount: 4,
      min: 0,
      forceNiceScale: true,
    },
    legend: { show: false },
    tooltip: {
      theme: "light",
      y: { formatter: (val) => `${val} contract${val === 1 ? "" : "s"}` },
    },
    grid: { padding: { top: 4, right: 8, bottom: 0, left: 4 } },
  });

  return chart;
}
