import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import BidPipelineFunnelDiagram from "views/sales/components/fragments/BidPipelineFunnelDiagram";
import { TASKBOARD_COLUMNS } from "./taskboard.utils";
import {
  buildTaskBoardStageDonutChart,
  buildTaskBoardTypeDonutChart,
  buildTaskBoardCategoryBarChart,
  buildTaskBoardFlowBarChart,
} from "./taskboard.charts";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const STORAGE_KEY = "famstack-taskboard-summary-expanded";

class TaskBoardPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  buildContextLine = (stats, boardName, selectedEmployeeName) => {
    const parts = [];
    if (boardName) parts.push(boardName);
    if (selectedEmployeeName) parts.push(selectedEmployeeName);
    parts.push(
      `${stats.total} on board · ${stats.active} active · ${stats.completionRate}% in done · ${stats.estimatedHours}h planned`
    );
    if (stats.overdueCount > 0) parts.push(`${stats.overdueCount} overdue`);
    if (stats.inTimerCount > 0) parts.push(`${stats.inTimerCount} timer running`);
    return parts.join(" · ");
  };

  renderKpiStrip = (stats, isLoading) => {
    const kpis = [
      { key: "total", label: "On the board", value: stats.total, tone: "indigo", icon: "fe fe-layers", hint: "All cards in view" },
      { key: "active", label: "Active now", value: stats.active, tone: "amber", icon: "fe fe-zap", hint: "To do + in progress" },
      { key: "done", label: "Completion", value: stats.completionRate, tone: "green", icon: "fe fe-trending-up", hint: "Share in done column", suffix: "%" },
      { key: "billable", label: "Billable", value: stats.billablePct, tone: "sky", icon: "fe fe-briefcase", hint: "Project-linked work", suffix: "%" },
      { key: "hours", label: "Est. load", value: stats.estimatedHours, tone: "slate", icon: "fe fe-clock", hint: "Planned hours today", suffix: "h", decimals: 1 },
      { key: "overdue", label: "Past due", value: stats.overdueCount, tone: "rose", icon: "fe fe-alert-triangle", hint: "Not completed, due passed" },
    ];
    return (
      <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Task board metrics">
        {kpis.map((kpi) => (
          <article
            key={kpi.key}
            className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
            role="listitem"
          >
            <div className="lux-bid-summary__kpi-top">
              <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
              <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
                <i className={kpi.icon} />
              </span>
            </div>
            <strong className="lux-bid-summary__kpi-value">
              {isLoading ? (
                <Skeleton width={40} />
              ) : (
                <>
                  <CountUp end={Number(kpi.value) || 0} duration={0.75} decimals={kpi.decimals || 0} />
                  {kpi.suffix || ""}
                </>
              )}
            </strong>
            {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
          </article>
        ))}
      </div>
    );
  };

  renderHighlights = (stats, isLoading) => {
    const items = [
      {
        key: "planned",
        label: "Planned",
        value: stats.plannedCount,
        tone: "slate",
        icon: "fe fe-calendar",
        hint: "Scheduled, not started",
      },
      {
        key: "todo",
        label: "To do",
        value: stats.todoCount,
        tone: "sky",
        icon: "fe fe-flag",
        hint: "Ready to pick up",
      },
      {
        key: "progress",
        label: "In progress",
        value: stats.inProgressCount,
        tone: "amber",
        icon: "fe fe-play-circle",
        hint: `${stats.inProgressHours}h in this column`,
      },
      {
        key: "done",
        label: "Completed",
        value: stats.completedCount,
        tone: "green",
        icon: "fe fe-check-circle",
        hint: `${stats.completedHours}h logged`,
      },
    ];
    return (
      <div className="lux-po-summary__highlights" role="list" aria-label="Column highlights">
        {items.map((item) => (
          <article
            key={item.key}
            className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)}
            role="listitem"
          >
            <span className="lux-po-summary__highlight-icon" aria-hidden="true">
              <i className={item.icon} />
            </span>
            <div className="lux-po-summary__highlight-copy">
              <span className="lux-po-summary__highlight-label">{item.label}</span>
              <strong>
                {isLoading ? <Skeleton width={28} /> : <CountUp end={item.value} duration={0.7} />}
              </strong>
              <span className="lux-po-summary__highlight-hint">{item.hint}</span>
            </div>
          </article>
        ))}
      </div>
    );
  };

  renderInsightCards = (stats) =>
    (stats.insights || []).map((insight, index) => (
      <article
        key={`${insight.title}-${index}`}
        className={classNames("lux-bid-summary__insight lux-po-summary__insight", insight.tone && `is-${insight.tone}`)}
      >
        <header>
          <i className={`fe ${insight.icon}`} aria-hidden="true" />
          <div>
            <strong>{insight.title}</strong>
            <span>{insight.detail}</span>
          </div>
        </header>
      </article>
    ));

  renderStageFlow = (stats, isLoading) => (
    <div className="lux-bid-summary__stage-flow" aria-label="Kanban column flow">
      {TASKBOARD_COLUMNS.map((col, index, arr) => (
        <React.Fragment key={col.key}>
          <div className={classNames("lux-bid-summary__stage-node", `is-${col.tone}`)}>
            <span className="lux-bid-summary__stage-node-label">{col.name}</span>
            <strong>
              {isLoading ? "—" : <CountUp end={stats.byStage[col.stage] || 0} duration={0.7} />}
            </strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-bid-summary__stage-arrow" aria-hidden="true">
              <i className="fe fe-arrow-right" />
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  renderChartPanel = (title, subtitle, chart, emptyLabel, opts = {}) => (
    <article
      className={classNames("lux-bid-summary__chart-panel", {
        "lux-bid-summary__chart-panel--wide": opts.wide,
        "lux-bid-summary__chart-panel--compact": opts.compactHead,
      })}
    >
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {!opts.compactHead && subtitle && <p className="lux-bid-summary__panel-sub">{subtitle}</p>}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body" style={{ minHeight: opts.height || 168 }}>
        {this.props.isLoading ? (
          <Skeleton height={opts.height || 168} borderRadius={12} />
        ) : chart ? (
          <DashboardApexChart {...chart} />
        ) : (
          <p className="lux-bid-summary__chart-empty">{emptyLabel}</p>
        )}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-bid-summary lux-taskboard-summary is-loading">
        <Skeleton height={72} borderRadius={16} />
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stats, isLoading, boardName, selectedEmployeeName, onConfigure, configureEnabled } = this.props;
    const { expanded } = this.state;

    if (isLoading && (!stats || !stats.total)) {
      return this.renderSkeleton();
    }
    if (!stats) return null;

    const charts = {
      stageDonut: buildTaskBoardStageDonutChart(stats),
      typeDonut: buildTaskBoardTypeDonutChart(stats),
      categoryBar: buildTaskBoardCategoryBarChart(stats),
      flowBar: buildTaskBoardFlowBarChart(stats),
    };

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-taskboard-summary", { "is-collapsed": !expanded })}
        aria-label="Task board overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="taskboard" className="lux-bid-summary__eyebrow">
              Execution board intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={stats.total} duration={0.75} />{" "}
                <span>
                  tasks · {stats.active} active · {stats.completionRate}% done
                  {stats.overdueCount > 0 ? ` · ${stats.overdueCount} overdue` : ""}
                </span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Today&apos;s task flow</h2>
            )}
          </div>
          <div className="lux-taskboard-summary__header-actions">
            {configureEnabled && onConfigure && (
              <button
                type="button"
                className="lux-taskboard-summary__configure-btn"
                onClick={onConfigure}
                title="Configure task boards"
              >
                <i className="fe fe-settings" aria-hidden="true" />
                <span>Board workspace</span>
              </button>
            )}
            <button
              type="button"
              className="lux-bid-summary__toggle"
              onClick={this.toggleExpanded}
              aria-expanded={expanded}
              aria-controls="lux-taskboard-summary-body"
              title={expanded ? "Collapse summary" : "Insights"}
            >
              <span>{getSummaryToggleLabel(expanded)}</span>
              <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
            </button>
          </div>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">
              {this.buildContextLine(stats, boardName, selectedEmployeeName)}
            </p>
          </div>
        )}

        <div id="lux-taskboard-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <p className="lux-bid-summary__subtitle">
            {this.buildContextLine(stats, boardName, selectedEmployeeName)}
            {" · "}
            Drag cards across columns to advance work — start timers on in-progress items and log time on completion.
          </p>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row">
            {this.renderKpiStrip(stats, isLoading)}
          </div>

          {this.renderHighlights(stats, isLoading)}

          <div className="lux-bid-summary__insights lux-po-summary__insights">{this.renderInsightCards(stats)}</div>

          {this.renderStageFlow(stats, isLoading)}

          <div className="lux-po-summary__analytics lux-po-summary__analytics--primary">
            <article className="lux-bid-summary__chart-panel lux-bid-summary__chart-panel--funnel lux-bid-summary__chart-panel--funnel-compact">
              <div className="lux-bid-summary__panel-head">
                <h3 className="lux-bid-summary__panel-title">Delivery funnel</h3>
                <p className="lux-bid-summary__panel-sub">How work is distributed across kanban columns today</p>
              </div>
              <BidPipelineFunnelDiagram funnel={stats.funnel} totalActive={stats.total} layout="horizontal" />
            </article>
            {this.renderChartPanel("Workflow mix", "Tasks per kanban column", charts.stageDonut, "No tasks on the board yet.", {
              compactHead: true,
            })}
            {this.renderChartPanel("Billable scope", "Project vs non-project work", charts.typeDonut, "No scope breakdown.", {
              compactHead: true,
            })}
            {this.renderChartPanel(
              "Flow snapshot",
              "Column counts at a glance",
              charts.flowBar,
              "Add work items to see flow.",
              { height: 140, compactHead: true }
            )}
          </div>

          <div className="lux-po-summary__analytics lux-po-summary__analytics--secondary">
            {this.renderChartPanel(
              "Top categories",
              "Where effort clusters today",
              charts.categoryBar,
              "No categories in range.",
              { height: 168, compactHead: true }
            )}
          </div>
        </div>
      </section>
    );
  }
}

export default TaskBoardPageSummary;
