import React, { Component } from "react";
import classNames from "classnames/bind";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";

const EMPTY_FORM = {
  name: "",
  description: "",
  slippageDeltaDays: 0,
  riskDelta: 0,
  marginDeltaPct: 0,
  assumptions: "",
};

export default class PortfolioScenarioPanel extends Component {
  state = {
    selectedScenarioId: null,
    form: { ...EMPTY_FORM },
    saving: false,
    saveError: null,
  };

  componentDidUpdate(prevProps) {
    const scenarios = this.props.scenarios || [];
    if (!this.state.selectedScenarioId && scenarios.length) {
      this.setState({ selectedScenarioId: scenarios[0].id });
    }
    if (prevProps.scenarios !== this.props.scenarios && scenarios.length && !scenarios.find((row) => row.id === this.state.selectedScenarioId)) {
      this.setState({ selectedScenarioId: scenarios[0].id });
    }
  }

  selectScenario = (scenarioId) => {
    this.setState({ selectedScenarioId: scenarioId, saveError: null });
    if (this.props.onSelectScenario) {
      this.props.onSelectScenario(scenarioId);
    }
  };

  handleFormChange = (field) => (event) => {
    const value = event.target.type === "number" ? Number(event.target.value) : event.target.value;
    this.setState((prev) => ({ form: { ...prev.form, [field]: value }, saveError: null }));
  };

  handleSave = async (event) => {
    event.preventDefault();
    const { form } = this.state;
    const { portfolioId, onSaveScenario } = this.props;
    if (!onSaveScenario) return;

    this.setState({ saving: true, saveError: null });
    try {
      const assumptions = String(form.assumptions || "")
        .split("\n")
        .map((row) => row.trim())
        .filter(Boolean);
      const result = await onSaveScenario({
        portfolioId,
        name: form.name,
        description: form.description,
        slippageDeltaDays: form.slippageDeltaDays,
        riskDelta: form.riskDelta,
        marginDeltaPct: form.marginDeltaPct,
        assumptions,
      });
      this.setState({ saving: false, form: { ...EMPTY_FORM }, selectedScenarioId: result.payload.id });
      if (this.props.onSelectScenario) {
        this.props.onSelectScenario(result.payload.id);
      }
    } catch (error) {
      this.setState({
        saving: false,
        saveError: (error && error.message) || "Unable to save scenario.",
      });
    }
  };

  renderComparison(comparison) {
    if (!comparison) {
      return (
        <div className="lux-portfolio-scenario__comparison-empty">
          <i className="fe fe-sliders" aria-hidden="true" />
          <p className="lux-portfolio-scenario__hint">Select a scenario to compare against the live portfolio baseline.</p>
        </div>
      );
    }

    const scenarios = this.props.scenarios || [];
    const selected = scenarios.find((row) => row.id === this.state.selectedScenarioId);
    const scenarioName = (selected && selected.name) || "Selected scenario";

    const deltaTone = (value, invert) => {
      if (!value) return "slate";
      const positive = invert ? value < 0 : value > 0;
      const negative = invert ? value > 0 : value < 0;
      if (positive) return "green";
      if (negative) return "rose";
      return "slate";
    };

    return (
      <div className="lux-portfolio-scenario__comparison">
        <header className="lux-portfolio-scenario__comparison-head">
          <span className="lux-portfolio-scenario__label">Scenario vs baseline</span>
          <span className="lux-portfolio-scenario__comparison-name">{scenarioName}</span>
        </header>
        <div className="lux-portfolio-scenario__delta-grid">
          <div>
            <span>Baseline health</span>
            <strong>{comparison.baselineHealth}%</strong>
          </div>
          <div>
            <span>Scenario health</span>
            <strong>{comparison.scenarioHealth}%</strong>
          </div>
          <div className={classNames("is-tone", `is-${deltaTone(comparison.healthDelta)}`)}>
            <span>Health delta</span>
            <strong>{comparison.healthDelta > 0 ? "+" : ""}{comparison.healthDelta}%</strong>
          </div>
          <div className={classNames("is-tone", `is-${deltaTone(comparison.slippageDeltaDays, true)}`)}>
            <span>Slippage delta</span>
            <strong>{comparison.slippageDeltaDays > 0 ? "+" : ""}{comparison.slippageDeltaDays}d</strong>
          </div>
          <div className={classNames("is-tone", `is-${deltaTone(comparison.riskDelta, true)}`)}>
            <span>Risk delta</span>
            <strong>{comparison.riskDelta > 0 ? "+" : ""}{comparison.riskDelta}</strong>
          </div>
          <div className={classNames("is-tone", `is-${deltaTone(comparison.marginDeltaPct)}`)}>
            <span>Margin delta</span>
            <strong>{comparison.marginDeltaPct > 0 ? "+" : ""}{comparison.marginDeltaPct}%</strong>
          </div>
        </div>
        {(comparison.assumptions || []).length ? (
          <ul className="lux-portfolio-scenario__assumptions">
            {comparison.assumptions.map((row, index) => (
              <li key={index}>{row}</li>
            ))}
          </ul>
        ) : null}
      </div>
    );
  }

  render() {
    const { scenarios = [], comparison, loading } = this.props;
    const { selectedScenarioId, form, saving, saveError } = this.state;

    if (loading) {
      return (
        <div className="lux-portfolio-scenario lux-portfolio-scenario--loading" aria-busy="true">
          <span className="lux-portfolio-scenario__skeleton lux-portfolio-scenario__skeleton--wide" />
          <span className="lux-portfolio-scenario__skeleton" />
          <span className="lux-portfolio-scenario__skeleton" />
        </div>
      );
    }

    return (
      <div className="lux-portfolio-scenario">
        <div className="lux-portfolio-scenario__ambient" aria-hidden="true">
          <span className="lux-portfolio-scenario__orb lux-portfolio-scenario__orb--a" />
          <span className="lux-portfolio-scenario__orb lux-portfolio-scenario__orb--b" />
        </div>

        <div className="lux-portfolio-scenario__list-wrap">
          <header className="lux-portfolio-scenario__section-head">
            <span className="lux-portfolio-scenario__label">Saved scenarios</span>
            <span className="lux-portfolio-scenario__section-meta">{scenarios.length} trajectories</span>
          </header>
          <div className="lux-portfolio-scenario__list">
            {scenarios.length ? (
              scenarios.map((row) => (
                <button
                  key={row.id}
                  type="button"
                  className={classNames("lux-portfolio-scenario__card", selectedScenarioId === row.id && "is-active")}
                  onClick={() => this.selectScenario(row.id)}
                >
                  <span className="lux-portfolio-scenario__card-icon" aria-hidden="true">
                    <i className="fe fe-git-branch" />
                  </span>
                  <strong>{row.name}</strong>
                  <small>{row.description}</small>
                  <span className="lux-portfolio-badge is-violet">{row.status || "SAVED"}</span>
                </button>
              ))
            ) : (
              <p className="lux-portfolio-scenario__hint">No scenarios saved yet. Create one below.</p>
            )}
          </div>
        </div>

        {this.renderComparison(comparison)}

        <form className="lux-portfolio-scenario__form" onSubmit={this.handleSave}>
          <header className="lux-portfolio-scenario__section-head">
            <span className="lux-portfolio-scenario__label">Create scenario</span>
            <span className="lux-portfolio-scenario__section-meta">Model what-if deltas</span>
          </header>
          <div className="lux-portfolio-scenario__form-grid">
            <label>
              Name
              <input type="text" value={form.name} onChange={this.handleFormChange("name")} required />
            </label>
            <label>
              Slippage delta (days)
              <input type="number" value={form.slippageDeltaDays} onChange={this.handleFormChange("slippageDeltaDays")} />
            </label>
            <label className="is-wide">
              Description
              <input type="text" value={form.description} onChange={this.handleFormChange("description")} />
            </label>
            <label>
              Risk delta
              <input type="number" value={form.riskDelta} onChange={this.handleFormChange("riskDelta")} />
            </label>
            <label>
              Margin delta (%)
              <input type="number" value={form.marginDeltaPct} onChange={this.handleFormChange("marginDeltaPct")} />
            </label>
            <label className="is-wide">
              Assumptions (one per line)
              <textarea rows={3} value={form.assumptions} onChange={this.handleFormChange("assumptions")} />
            </label>
          </div>
          {saveError ? <p className="lux-portfolio-scenario__error">{saveError}</p> : null}
          <div className="lux-portfolio-scenario__form-actions">
            <ResourcesActionButton type="submit" icon="fe fe-save" variant="primary" disabled={saving}>
              {saving ? "Saving…" : "Save scenario"}
            </ResourcesActionButton>
          </div>
        </form>
      </div>
    );
  }
}
