import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled, shouldUsePayrollApi } from "config/payroll.config";
import { buildSalaryStructureMetrics, formatEmployeeCount, formatPayrollDate } from "config/payroll.utils";
import { validateSalaryStructurePayload } from "config/payroll-schema.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { PayrollStructuresRegister } from "views/payroll/components/PayrollRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

const EMPTY_FORM = {
  name: "",
  code: "",
  currency: "INR",
  payFrequency: "Monthly",
  status: "Active",
};

class SalaryStructuresPage extends Component {
  state = {
    structures: [],
    loading: true,
    loadError: null,
    dataSource: null,
    showForm: false,
    form: { ...EMPTY_FORM },
    formError: null,
    saving: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Salary structures");
    this.loadStructures();
  }

  loadStructures = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.listSalaryStructures();
      this.setState({ structures: result.payload || [], loading: false, dataSource: result.source || null });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load salary structures.", structures: [] });
    }
  };

  closeForm = () => {
    this.setState({ showForm: false, formError: null, saving: false, form: { ...EMPTY_FORM } });
  };

  openCreateForm = () => {
    if (!shouldUsePayrollApi()) {
      this.setState({
        showForm: true,
        form: { ...EMPTY_FORM },
        formError: "Payroll API is disabled. Enable REACT_APP_USE_PAYROLL_API to create structures.",
      });
      return;
    }
    this.setState({ showForm: true, form: { ...EMPTY_FORM }, formError: null });
  };

  handleFormChange = (field, value) => {
    this.setState((prev) => ({ form: { ...prev.form, [field]: value }, formError: null }));
  };

  handleSave = async (event) => {
    event.preventDefault();
    if (!shouldUsePayrollApi()) {
      this.setState({ formError: "Payroll API is disabled." });
      return;
    }
    const { form } = this.state;
    const payload = {
      name: form.name,
      code: form.code,
      currency: form.currency,
      payFrequency: form.payFrequency,
      status: form.status || "Active",
    };
    const validation = validateSalaryStructurePayload(payload);
    if (!validation.valid) {
      this.setState({ formError: validation.errors.join(" ") });
      return;
    }
    this.setState({ saving: true, formError: null });
    try {
      await payrollService.createSalaryStructure(payload);
      this.closeForm();
      await this.loadStructures();
    } catch (e) {
      this.setState({
        saving: false,
        formError: (e && e.message) || "Unable to create salary structure.",
      });
    }
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Salary structures" reason="Payroll management is not enabled." />;
    }

    const { structures, loading, loadError, dataSource, showForm, form, formError, saving } = this.state;
    const metrics = buildSalaryStructureMetrics(structures);
    const kpiCards = [
      { id: "total", label: "Structures", value: metrics.total, hint: "Component templates", tone: "primary", icon: "fe fe-sliders" },
      { id: "active", label: "Active", value: metrics.active, hint: "In production use", tone: "green", icon: "fe fe-check-circle" },
      {
        id: "employees",
        label: "Employees mapped",
        value: metrics.employees != null ? metrics.employees : "—",
        hint: metrics.employees != null ? "Across all structures" : "Count not on catalog",
        tone: "blue",
        icon: "fe fe-users",
      },
      { id: "components", label: "Avg components", value: metrics.avgComponents, hint: `${metrics.draft} draft structure(s)`, tone: "violet", icon: "fe fe-grid" },
    ];

    return (
      <PayrollLuxPage
        dataSource={dataSource}
        pageMeta={DENSE_PAGE_META.salaryStructures}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton to="/payroll/dashboard" icon="fe fe-pie-chart" variant="ghost">
              Dashboard
            </PayrollActionButton>
            <PayrollActionButton type="button" icon="fe fe-plus" variant="primary" onClick={this.openCreateForm}>
              New structure
            </PayrollActionButton>
          </>
        }
      >
        {loadError && <div className="lux-employee-360__error" role="alert">{loadError}</div>}

        {showForm ? (
          <section className="lux-hrms-dash__panel lux-payroll-panel">
            <PayrollPanelHead title="New salary structure" subtitle="Name, code, currency, and pay frequency for this template" />
            <form className="lux-hrms-dash__panel-body" onSubmit={this.handleSave} data-testid="salary-structure-form">
              {formError ? (
                <LuxInlineAlert tone="warning" title="Unable to save structure">
                  {formError}
                </LuxInlineAlert>
              ) : null}
              <div className="lux-payroll-summary-grid">
                <label>
                  Name
                  <input
                    value={form.name}
                    onChange={(e) => this.handleFormChange("name", e.target.value)}
                    required
                  />
                </label>
                <label>
                  Code
                  <input
                    value={form.code}
                    onChange={(e) => this.handleFormChange("code", e.target.value)}
                    required
                  />
                </label>
                <label>
                  Currency
                  <input
                    value={form.currency}
                    onChange={(e) => this.handleFormChange("currency", e.target.value)}
                  />
                </label>
                <label>
                  Pay frequency
                  <select
                    value={form.payFrequency}
                    onChange={(e) => this.handleFormChange("payFrequency", e.target.value)}
                  >
                    <option value="Monthly">Monthly</option>
                    <option value="Bi-weekly">Bi-weekly</option>
                    <option value="Weekly">Weekly</option>
                  </select>
                </label>
              </div>
              <div className="lux-payroll-groups__empty-actions">
                <PayrollActionButton type="button" variant="ghost" onClick={this.closeForm} disabled={saving}>
                  Cancel
                </PayrollActionButton>
                <PayrollActionButton type="submit" variant="primary" icon="fe fe-check" disabled={saving || !shouldUsePayrollApi()}>
                  {saving ? "Saving…" : "Create structure"}
                </PayrollActionButton>
              </div>
            </form>
          </section>
        ) : null}

        {!loading && structures.length > 0 && (
          <div className="lux-payroll-summary-grid">
            {structures.map((row) => (
              <article key={row.id} className="lux-payroll-summary-card">
                <div className="lux-payroll-summary-card__head">
                  <span className={classNames("lux-doc-badge", row.status === "Active" ? "is-success" : "is-warning")}>{row.status}</span>
                  <span className="lux-payroll-summary-card__code">{row.code}</span>
                </div>
                <h3 className="lux-payroll-summary-card__title">{row.name}</h3>
                <p className="lux-payroll-summary-card__meta">{row.payFrequency} · {row.currency}</p>
                <dl className="lux-payroll-summary-card__stats">
                  <div><dt>Components</dt><dd>{row.componentCount}</dd></div>
                  <div><dt>Employees</dt><dd>{formatEmployeeCount(row.employeeCount)}</dd></div>
                  <div><dt>Updated</dt><dd>{formatPayrollDate(row.updatedAt)}</dd></div>
                </dl>
              </article>
            ))}
          </div>
        )}

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead
            title="Structure register"
            subtitle="Base component, pay frequency, and employee mapping per template"
            actions={
              <PayrollActionButton type="button" icon="fe fe-plus" variant="primary" onClick={this.openCreateForm}>
                New structure
              </PayrollActionButton>
            }
          />
          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading structures" description="Fetching salary structure catalog." />
            ) : structures.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-sliders" title="No salary structures" description="Configure earnings and deduction components." />
            ) : (
              <PayrollStructuresRegister structures={structures} />
            )}
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default SalaryStructuresPage;
