import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isPolicyHubEnabled,
  POLICY_VERSION_STATUSES,
  shouldUsePolicyAi,
  shouldUsePolicyCampaigns,
  shouldUsePolicyVersioning,
} from "config/policy-hub.config";
import { policyHubService } from "_services/policyHub.service";
import { getLatestPublishedVersion } from "config/policy-hub.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import PolicyAiSummaryPanel from "views/people/components/policy/PolicyAiSummaryPanel";
import { PeopleActionButton } from "views/people/components/PeopleLuxShared";

class PolicyDetailPage extends Component {
  state = {
    policy: null,
    campaigns: [],
    loading: true,
    loadError: null,
    publishing: false,
    publishSummary: "",
    dataSource: null,
  };

  componentDidMount() {
    this.loadPolicy();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.match.params.policyId !== this.props.match.params.policyId) {
      this.loadPolicy();
    }
  }

  loadPolicy = async () => {
    const { policyId } = this.props.match.params;
    this.setState({ loading: true, loadError: null });
    try {
      const [policyResult, campaignsResult] = await Promise.all([
        policyHubService.getPolicy(policyId),
        policyHubService.listCampaigns(),
      ]);
      const policy = policyResult.payload;
      this.props.pageHeaderNameChangeHandler(policy ? policy.title : "Policy");
      this.setState({
        policy,
        campaigns: (campaignsResult.payload || []).filter((row) => row.policyId === policyId),
        loading: false,
        dataSource: policyResult.source,
        publishSummary: (policy && policy.summary) || "",
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load policy details." });
    }
  };

  handlePublish = async () => {
    const { policy, publishSummary } = this.state;
    if (!policy || !shouldUsePolicyVersioning()) {
      return;
    }
    this.setState({ publishing: true });
    try {
      await policyHubService.publishVersion(policy.id, {
        summary: publishSummary,
        publishedBy: "HR Admin",
      });
      await this.loadPolicy();
    } finally {
      this.setState({ publishing: false });
    }
  };

  renderVersionHistory = () => {
    const { policy } = this.state;
    const versions = (policy && policy.versions) || [];
    if (!versions.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No versions"
          description="Version history will appear after the first publish."
        />
      );
    }
    return (
      <div className="lux-policy-detail__versions">
        {versions.map((version) => (
          <article
            key={version.id}
            className={classNames("lux-policy-detail__version", {
              "is-current": version.version === policy.currentVersion,
            })}
          >
            <header>
              <strong>v{version.version}</strong>
              <span className={classNames("lux-doc-badge", {
                "is-success": version.status === POLICY_VERSION_STATUSES.PUBLISHED,
                "is-slate": version.status === POLICY_VERSION_STATUSES.ARCHIVED,
              })}
              >
                {version.status}
              </span>
            </header>
            <p>{version.summary}</p>
            {version.changes && version.changes.length > 0 && (
              <ul>
                {version.changes.map((change) => (
                  <li key={change}>{change}</li>
                ))}
              </ul>
            )}
            <footer>
              <span>{version.publishedAt || "—"}</span>
              <span>{version.publishedBy || "—"}</span>
            </footer>
          </article>
        ))}
      </div>
    );
  };

  renderCampaigns = () => {
    const { campaigns } = this.state;
    if (!shouldUsePolicyCampaigns()) {
      return null;
    }
    if (!campaigns.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No campaigns"
          description="Launch an acknowledgment campaign after publishing a version."
        />
      );
    }
    return (
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Campaign</th>
              <th>Version</th>
              <th>Due</th>
              <th>Progress</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {campaigns.map((row) => (
              <tr key={row.id}>
                <td>
                  <strong>{row.audience}</strong>
                  <span className="lux-doc-register__meta">{row.description}</span>
                </td>
                <td>{row.version}</td>
                <td>{row.dueDate || "—"}</td>
                <td>
                  {row.acknowledgedCount}/{row.assignedCount}
                </td>
                <td>
                  <span className="lux-doc-badge is-slate">{row.status}</span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  render() {
    if (!isPolicyHubEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Policy detail"
          reason="Policy hub is not enabled for your organization."
        />
      );
    }

    const { policy, loading, loadError, publishing, publishSummary, dataSource } = this.state;
    const latest = getLatestPublishedVersion(policy);

    return (
      <div className="lux-policy-detail-page lux-people-page lux-register-page" data-testid="page-policy-detail">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
                  eyebrow="Policy"
                  titleLead={policy ? policy.title : "Policy detail"}
                  lede={policy ? policy.summary : "Version history, campaigns, and publish workflow."}
                  icon="fe fe-book"
                  tone="indigo"
                  actions={
                    <PeopleActionButton to="/people/policies" variant="ghost" icon="fe fe-arrow-left">
                      Back to hub
                    </PeopleActionButton>
                  }
                />

        <div className="lux-register-page__body">
        {loadError ? <LuxInlineAlert message={loadError} tone="danger" /> : null}

        {loading ? (
          <LuxRegisterEmptyState title="Loading policy" description="Fetching version history." />
        ) : !policy ? (
          <LuxRegisterEmptyState title="Policy not found" description="Return to the policy hub." />
        ) : (
          <>
            <div className="lux-policy-detail__meta-strip">
              <span>Current v{policy.currentVersion}</span>
              <span>{policy.category}</span>
              <span>Owner {policy.owner}</span>
              <span>Updated {policy.updatedAt || "—"}</span>
            </div>

            <div className="lux-policy-detail__layout">
              <section className="lux-hrms-dash__panel lux-doc-panel">
                <header className="lux-hrms-dash__panel-head">
                  <h2 className="lux-hrms-dash__panel-title">Version history</h2>
                </header>
                <div className="lux-hrms-dash__panel-body">{this.renderVersionHistory()}</div>
              </section>

              <aside className="lux-policy-detail__aside">
                {shouldUsePolicyAi() && <PolicyAiSummaryPanel policy={policy} />}

                {shouldUsePolicyVersioning() && (
                  <section className="lux-hrms-dash__panel lux-doc-panel">
                    <header className="lux-hrms-dash__panel-head">
                      <h2 className="lux-hrms-dash__panel-title">Publish draft</h2>
                    </header>
                    <div className="lux-hrms-dash__panel-body lux-policy-detail__publish">
                      <p>Publish a new version from the current summary. Previous published versions are archived.</p>
                      <textarea
                        className="form-control"
                        rows={4}
                        value={publishSummary}
                        onChange={(e) => this.setState({ publishSummary: e.target.value })}
                        placeholder="Summary of changes for employees"
                      />
                      <PeopleActionButton
                        variant="primary"
                        icon="fe fe-upload-cloud"
                        disabled={publishing || !publishSummary.trim()}
                        onClick={this.handlePublish}
                      >
                        {publishing ? "Publishing…" : "Publish version"}
                      </PeopleActionButton>
                      {latest && (
                        <p className="lux-policy-detail__publish-hint">
                          Latest: v{latest.version} — {latest.summary}
                        </p>
                      )}
                    </div>
                  </section>
                )}

                {shouldUsePolicyCampaigns() && (
                  <section className="lux-hrms-dash__panel lux-doc-panel">
                    <header className="lux-hrms-dash__panel-head">
                      <h2 className="lux-hrms-dash__panel-title">Campaigns</h2>
                    </header>
                    <div className="lux-hrms-dash__panel-body">{this.renderCampaigns()}</div>
                  </section>
                )}
              </aside>
            </div>
          </>
        )}
        </div>
      </div>
    );
  }
}

export default PolicyDetailPage;
