import React from "react";
import classNames from "classnames/bind";

export default function TicketAnalyticsPanel({ analytics, loading }) {
  if (loading) {
    return <div className="lux-ticket-snapshot lux-ticket-snapshot--loading" aria-busy="true" />;
  }
  const a = analytics || {};
  return (
    <section className="lux-ticket-snapshot">
      <div className="lux-ticket-snapshot__badge">
        <i className="fe fe-bar-chart-2" aria-hidden="true" />
        <span>Service analytics</span>
      </div>
      <div className="lux-ticket-snapshot__metrics">
        <article className="lux-ticket-snapshot__metric is-indigo">
          <span>Backlog</span>
          <strong>{a.backlog != null ? a.backlog : 0}</strong>
        </article>
        <article className="lux-ticket-snapshot__metric is-green">
          <span>SLA compliance</span>
          <strong>{a.slaCompliancePct != null ? a.slaCompliancePct : 0}%</strong>
        </article>
        <article className="lux-ticket-snapshot__metric is-blue">
          <span>Avg resolution</span>
          <strong>{a.avgResolutionHrs != null ? a.avgResolutionHrs : 0}h</strong>
        </article>
        <article className="lux-ticket-snapshot__metric is-amber">
          <span>Billable support</span>
          <strong>{a.billableSupportHrs != null ? a.billableSupportHrs : 0}h</strong>
        </article>
      </div>
      {(a.categories || []).length ? (
        <div className="lux-ticket-category-strip">
          {a.categories.map((cat) => (
            <span key={cat.id} className="lux-ticket-category-chip">
              {cat.label} <strong>{cat.count}</strong>
            </span>
          ))}
        </div>
      ) : null}
    </section>
  );
}
