import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isWorkGraphEnabled } from "config/work-graph.config";
import { WORK_GRAPH_ANALYTICS_PAGE_META } from "config/work-graph-nav.config";
import { workGraphService } from "_services/workGraph.service";
import WorkGraphLuxPage, {
  WorkGraphActionButton,
  WorkGraphInsightPanel,
} from "views/workgraph/components/WorkGraphLuxShared";
import GraphAnalyticsPanel from "views/workgraph/components/GraphAnalyticsPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class AnalyticsWorkGraphPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    analytics: null,
    insights: [],
    kpiCards: [],
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await workGraphService.getOverview({});
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        analytics: payload.analytics || null,
        insights: payload.insights || [],
        kpiCards: payload.kpiCards || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load graph analytics.",
      });
    }
  };

  render() {
    if (!isWorkGraphEnabled()) {
      return <PersonaAccessDenied featureLabel="Work graph analytics" />;
    }

    const { loading, loadError, dataSource, analytics, insights, kpiCards } = this.state;

    return (
    <WorkGraphLuxPage
      pageMeta={WORK_GRAPH_ANALYTICS_PAGE_META}
      dataSource={dataSource}
      kpiCards={kpiCards}
      loading={loading}
      pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
      shellTitle="Work graph analytics"
      heroActions={
        <WorkGraphActionButton to="/workspace/work-graph" icon="fe fe-git-merge">
          Open graph
        </WorkGraphActionButton>
      }
    >
      {loadError ? <LuxInlineAlert message={loadError} /> : null}
      <WorkGraphInsightPanel insights={insights} loading={loading} />
      <GraphAnalyticsPanel analytics={analytics} loading={loading} />
    </WorkGraphLuxPage>
    );
  }
}

export default AnalyticsWorkGraphPage;
