import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { REVIEWS_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import ReviewRegister from "views/performance/components/ReviewRegister";
import { ManagerReviewDrawer, SelfReviewDrawer } from "views/performance/components/ReviewDrawers";

class PerformanceReviewsPage extends Component {
  state = {
    loading: true,
    reviews: [],
    kpiCards: [],
    dataSource: null,
    statusFilter: "ALL",
    busy: false,
    selfDrawerOpen: false,
    managerDrawerOpen: false,
    managerReadOnly: false,
    selectedReview: null,
    loadError: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const [overview, reviewsResult] = await Promise.all([
        performanceManagementService.getOverview(filters),
        performanceManagementService.listReviews(filters),
      ]);
      this.setState({
        loading: false,
        dataSource: reviewsResult.source,
        reviews: reviewsResult.payload || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        reviews: [],
        loadError: (error && error.message) || "Unable to load reviews.",
      });
    }
  };

  closeDrawers = () => {
    this.setState({
      selfDrawerOpen: false,
      managerDrawerOpen: false,
      managerReadOnly: false,
      selectedReview: null,
    });
  };

  handleOpenSelfReview = (review) => {
    this.setState({ selectedReview: review, selfDrawerOpen: true, managerDrawerOpen: false });
  };

  handleOpenManagerReview = (review) => {
    this.setState({ selectedReview: review, managerDrawerOpen: true, selfDrawerOpen: false, managerReadOnly: false });
  };

  handleViewReview = (review) => {
    this.setState({ selectedReview: review, managerDrawerOpen: true, selfDrawerOpen: false, managerReadOnly: true });
  };

  handleSubmitSelf = async (payload) => {
    const { selectedReview } = this.state;
    if (!selectedReview) {
      return;
    }
    this.setState({ busy: true });
    try {
      await performanceManagementService.submitSelfReview(selectedReview.id, payload);
      this.closeDrawers();
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to submit self review." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleSubmitManager = async (payload) => {
    const { selectedReview } = this.state;
    if (!selectedReview) {
      return;
    }
    this.setState({ busy: true });
    try {
      await performanceManagementService.submitManagerReview(selectedReview.id, payload);
      this.closeDrawers();
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to finalize manager review." });
    } finally {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Performance reviews" />;
    }

    const {
      loading,
      reviews,
      kpiCards,
      dataSource,
      statusFilter,
      busy,
      selfDrawerOpen,
      managerDrawerOpen,
      managerReadOnly,
      selectedReview,
      loadError,
    } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={REVIEWS_PAGE_META}
        pageId="reviews"
        shellTitle="Performance reviews"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
      >
        {loadError ? <div className="lux-perf-alert">{loadError}</div> : null}
        <PerformanceLuxPanel title="Review register" meta="Self and manager workflow" icon="fe fe-clipboard" accent="indigo" featured>
          <div className="lux-perf-filter-row">
            <label htmlFor="review-status-filter">Status</label>
            <select
              id="review-status-filter"
              className="lux-perf-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All</option>
              <option value="not_started">Not started</option>
              <option value="self_review">Self review</option>
              <option value="manager_review">Manager review</option>
              <option value="completed">Completed</option>
            </select>
          </div>
          <ReviewRegister
            reviews={reviews}
            loading={loading}
            onOpenSelfReview={this.handleOpenSelfReview}
            onOpenManagerReview={this.handleOpenManagerReview}
            onViewReview={this.handleViewReview}
          />
        </PerformanceLuxPanel>
        <SelfReviewDrawer
          open={selfDrawerOpen}
          review={selectedReview}
          onClose={this.closeDrawers}
          onSubmit={this.handleSubmitSelf}
          busy={busy}
        />
        <ManagerReviewDrawer
          open={managerDrawerOpen}
          review={selectedReview}
          readOnly={managerReadOnly}
          onClose={this.closeDrawers}
          onSubmit={this.handleSubmitManager}
          busy={busy}
        />
      </PerformanceLuxPage>
    );
  }
}

export default PerformanceReviewsPage;
