import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { WORKFLOW_ROUTES } from "config/workflow-automation.config";
import { WorkflowStatusBadge } from "views/automation/components/WorkflowLuxShared";

export default function WorkflowRuleRegister({ rules, loading, selectedId, onSelect, onPublish, onPause }) {
  if (loading) {
    return (
      <div className="lux-wf-register lux-wf-register--loading">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-wf-skeleton lux-wf-skeleton--row" />
        ))}
      </div>
    );
  }

  const rows = rules || [];
  if (!rows.length) {
    return (
      <div className="lux-wf-empty">
        <i className="fe fe-git-branch" aria-hidden="true" />
        <p>No workflow rules yet.</p>
      </div>
    );
  }

  return (
    <div className="lux-wf-register">
      {rows.map((row, index) => (
        <article
          key={row.id}
          className={classNames("lux-wf-register__row", row.tone && `is-${row.tone}`, selectedId === row.id && "is-selected")}
        >
          <span className="lux-wf-register__index" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className="lux-wf-register__rail" aria-hidden="true">
            <i className="fe fe-zap" />
          </span>
          <button type="button" className="lux-wf-register__main" onClick={() => onSelect && onSelect(row)}>
            <span className="lux-wf-register__eyebrow">{row.triggerLabel} · {row.runCount} runs</span>
            <h3>{row.name}</h3>
            <p>{row.description}</p>
            <div className="lux-wf-register__meta">
              <WorkflowStatusBadge status={row.status} />
              <span>{row.successRate}% success</span>
              <span>{row.ownerName}</span>
            </div>
          </button>
          <div className="lux-wf-register__actions">
            <Link to={`${WORKFLOW_ROUTES.RULES}?rule=${row.id}`} className="lux-onb-action lux-onb-action--ghost lux-wf-action">
              Edit
            </Link>
            {row.status === "draft" && onPublish ? (
              <button type="button" className="lux-onb-action lux-onb-action--primary lux-wf-action" onClick={() => onPublish(row)}>
                Publish
              </button>
            ) : null}
            {row.status === "published" && onPause ? (
              <button type="button" className="lux-onb-action lux-wf-action" onClick={() => onPause(row)}>
                Pause
              </button>
            ) : null}
          </div>
        </article>
      ))}
    </div>
  );
}
