import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import PropTypes from "prop-types";
import classNames from "classnames/bind";
import envconfig from "env.config";
import { getLegalDocument, LEGAL_DOC_TYPES } from "./legalDocuments";

function LegalDocumentModal({ show, docType, onClose, onSwitchDoc }) {
  const appName = envconfig.APP_NAME || "Tracopus";
  const doc = getLegalDocument(docType);

  useEffect(() => {
    if (!show) return undefined;

    const onKeyDown = (event) => {
      if (event.key === "Escape") onClose();
    };

    document.addEventListener("keydown", onKeyDown);
    document.body.classList.add("lux-legal-modal-open");

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.classList.remove("lux-legal-modal-open");
    };
  }, [show, onClose]);

  if (!show || typeof document === "undefined") return null;

  return createPortal(
    <div
      className="lux-legal-modal"
      role="dialog"
      aria-modal="true"
      aria-labelledby="lux-legal-modal-title"
      data-testid="legal-document-modal"
    >
      <button
        type="button"
        className="lux-legal-modal__backdrop"
        onClick={onClose}
        aria-label="Close legal document"
      />
      <div className="lux-legal-modal__panel">
        <header className="lux-legal-modal__head">
          <div className="lux-legal-modal__head-copy">
            <p className="lux-legal-modal__eyebrow">{doc.eyebrow}</p>
            <h2 id="lux-legal-modal-title" className="lux-legal-modal__title">
              {doc.title}
            </h2>
            <p className="lux-legal-modal__lede">
              {appName} · Infleca Innovation Pvt Ltd
            </p>
          </div>
          <div className="lux-legal-modal__head-actions">
            {typeof onSwitchDoc === "function" && (
              <div className="lux-legal-modal__tabs" role="tablist" aria-label="Legal documents">
                <button
                  type="button"
                  role="tab"
                  aria-selected={docType === LEGAL_DOC_TYPES.PRIVACY}
                  className={classNames("lux-legal-modal__tab", {
                    "is-active": docType === LEGAL_DOC_TYPES.PRIVACY,
                  })}
                  onClick={() => onSwitchDoc(LEGAL_DOC_TYPES.PRIVACY)}
                  data-testid="legal-tab-privacy"
                >
                  Privacy
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={docType === LEGAL_DOC_TYPES.TERMS}
                  className={classNames("lux-legal-modal__tab", {
                    "is-active": docType === LEGAL_DOC_TYPES.TERMS,
                  })}
                  onClick={() => onSwitchDoc(LEGAL_DOC_TYPES.TERMS)}
                  data-testid="legal-tab-terms"
                >
                  Terms
                </button>
              </div>
            )}
            <button
              type="button"
              className="lux-legal-modal__close"
              onClick={onClose}
              aria-label="Close"
              data-testid="legal-modal-close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        </header>
        <div className="lux-legal-modal__body">{doc.body}</div>
        <footer className="lux-legal-modal__footer">
          <button
            type="button"
            className="lux-legal-modal__done"
            onClick={onClose}
            data-testid="legal-modal-done"
          >
            Done
          </button>
        </footer>
      </div>
    </div>,
    document.body
  );
}

LegalDocumentModal.propTypes = {
  show: PropTypes.bool,
  docType: PropTypes.oneOf([LEGAL_DOC_TYPES.PRIVACY, LEGAL_DOC_TYPES.TERMS]),
  onClose: PropTypes.func.isRequired,
  onSwitchDoc: PropTypes.func,
};

LegalDocumentModal.defaultProps = {
  show: false,
  docType: LEGAL_DOC_TYPES.PRIVACY,
  onSwitchDoc: null,
};

export default LegalDocumentModal;
