import React, { Component } from "react";
import { npdService } from "_services/npd/npd.service";
import NpdLuxPage, {
  NpdActionButton,
  NpdLuxPanel,
} from "views/npd/components/NpdLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class NpdIdeaDetailPage extends Component {
  state = {
    loading: true,
    loadError: null,
    idea: null,
    gates: [],
    checklist: [],
    links: [],
    assessmentJson: '{"score":7}',
    businessCaseJson: '{"roi":"medium"}',
    linkType: "PROJECT",
    linkId: "",
  };

  get ideaRef() {
    return this.props.match && this.props.match.params
      ? this.props.match.params.id
      : null;
  }

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("NPD idea");
    }
    this.load();
  }

  load = async () => {
    const ideaRef = this.ideaRef;
    if (!ideaRef) {
      this.setState({ loading: false, loadError: new Error("Missing idea ref") });
      return;
    }
    this.setState({ loading: true, loadError: null });
    const [ideaRes, gatesRes, chkRes, linkRes] = await Promise.all([
      npdService.getIdea(ideaRef),
      npdService.listGates(ideaRef),
      npdService.listChecklist(ideaRef),
      npdService.listGovernanceLinks(ideaRef),
    ]);
    if (ideaRes.source !== "api") {
      this.setState({
        loading: false,
        loadError: ideaRes.error || new Error("Unable to load idea"),
      });
      return;
    }
    this.setState({
      loading: false,
      idea: ideaRes.payload,
      gates: gatesRes.source === "api" ? gatesRes.payload : [],
      checklist: chkRes.source === "api" ? chkRes.payload : [],
      links: linkRes.source === "api" ? linkRes.payload : [],
    });
  };

  assess = async () => {
    const result = await npdService.assessIdea(this.ideaRef, {
      assessmentJson: this.state.assessmentJson,
    });
    if (result.source === "api") this.load();
    else this.setState({ loadError: result.error || new Error("Assess failed") });
  };

  businessCase = async () => {
    const result = await npdService.businessCase(this.ideaRef, {
      businessCaseJson: this.state.businessCaseJson,
    });
    if (result.source === "api") this.load();
    else this.setState({ loadError: result.error || new Error("Business case failed") });
  };

  addLink = async (e) => {
    e.preventDefault();
    const { linkType, linkId } = this.state;
    if (!linkId) return;
    const result = await npdService.createGovernanceLink(this.ideaRef, { linkType, linkId });
    if (result.source === "api") {
      this.setState({ linkId: "" });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Link failed") });
    }
  };

  render() {
    const {
      loading,
      loadError,
      idea,
      gates,
      checklist,
      links,
      assessmentJson,
      businessCaseJson,
      linkType,
      linkId,
    } = this.state;
    return (
      <NpdLuxPage
        testId="npd-idea-detail-page"
        dataSource={idea ? "api" : loadError ? "api-error" : null}
        loading={loading}
        pageMeta={{
          tone: "violet",
          icon: "fe fe-zap",
          eyebrow: "Projects · NPD",
          titleLead: "NPD idea",
          titleAccent: this.ideaRef || "",
          lede: idea
            ? `${idea.title} — ${idea.status}${idea.linkedProjectId ? ` · project ${idea.linkedProjectId}` : ""}`
            : "Idea detail, assessment, gates, and governance links.",
        }}
        heroActions={
          <NpdActionButton to="/npd/ideas" icon="fe fe-arrow-left" variant="ghost">
            Ideas
          </NpdActionButton>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load idea">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
        {!loading && !idea && !loadError ? (
          <LuxRegisterEmptyState title="Idea not found" description="No idea loaded for this reference." showCreate={false} />
        ) : null}
        {idea ? (
          <>
            <NpdLuxPanel title="Assessment & business case" icon="fe fe-edit-3">
              <textarea
                className="form-control mb-2"
                rows={2}
                value={assessmentJson}
                onChange={(e) => this.setState({ assessmentJson: e.target.value })}
              />
              <NpdActionButton type="button" variant="secondary" className="lux-onb-action--compact mr-2" onClick={this.assess}>
                Assess
              </NpdActionButton>
              <textarea
                className="form-control mb-2 mt-2"
                rows={2}
                value={businessCaseJson}
                onChange={(e) => this.setState({ businessCaseJson: e.target.value })}
              />
              <NpdActionButton type="button" variant="secondary" className="lux-onb-action--compact" onClick={this.businessCase}>
                Save business case
              </NpdActionButton>
            </NpdLuxPanel>
            <NpdLuxPanel title="Gates" meta={`${gates.length} gate${gates.length === 1 ? "" : "s"}`} icon="fe fe-git-branch">
              {gates.length === 0 ? (
                <p className="text-muted small mb-0">No gates configured.</p>
              ) : (
                <ul className="mb-0">
                  {gates.map((g) => (
                    <li key={g.gateRef}>
                      {g.gateOrder}. {g.gateName} — {g.status}
                    </li>
                  ))}
                </ul>
              )}
            </NpdLuxPanel>
            <NpdLuxPanel title="Checklist" meta={`${checklist.length} item${checklist.length === 1 ? "" : "s"}`} icon="fe fe-check-square">
              {checklist.length === 0 ? (
                <p className="text-muted small mb-0">No checklist items.</p>
              ) : (
                <ul className="mb-0">
                  {checklist.map((c) => (
                    <li key={c.itemRef}>
                      {c.title} — {c.status}
                    </li>
                  ))}
                </ul>
              )}
            </NpdLuxPanel>
            <NpdLuxPanel title="Governance links" meta="IDs only" icon="fe fe-link">
              {links.length === 0 ? (
                <p className="text-muted small">No governance links.</p>
              ) : (
                <ul>
                  {links.map((l) => (
                    <li key={l.linkRef}>
                      {l.linkType}:{l.linkId}
                    </li>
                  ))}
                </ul>
              )}
              <form className="lux-module-inline-form" onSubmit={this.addLink}>
                <div className="form-row align-items-center">
                  <div className="col-md-3">
                    <select
                      className="form-control"
                      value={linkType}
                      onChange={(e) => this.setState({ linkType: e.target.value })}
                    >
                      <option value="PROJECT">PROJECT</option>
                      <option value="TASK">TASK</option>
                      <option value="RISK">RISK</option>
                      <option value="ISSUE">ISSUE</option>
                    </select>
                  </div>
                  <div className="col-md-3">
                    <input
                      className="form-control"
                      placeholder="Existing id"
                      value={linkId}
                      onChange={(e) => this.setState({ linkId: e.target.value })}
                    />
                  </div>
                  <div className="col-md-2">
                    <NpdActionButton type="submit">Link</NpdActionButton>
                  </div>
                </div>
              </form>
            </NpdLuxPanel>
          </>
        ) : null}
      </NpdLuxPage>
    );
  }
}

export default NpdIdeaDetailPage;
