import React, { Component } from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import CronJobSelectionMenu from "views/common/fragments/CronJobSelectionMenu";
import LuxFeedbackRecipientEmailPanel from "./LuxFeedbackRecipientEmailPanel";

function LuxFormSection({ icon, title, hint, children, className }) {
  return (
    <section className={classNames("lux-fb-create-section", className)}>
      <header className="lux-fb-create-section__head">
        <span className="lux-fb-create-section__icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
        <div>
          <h4>{title}</h4>
          {hint && <p>{hint}</p>}
        </div>
      </header>
      <div className="lux-fb-create-section__body">{children}</div>
    </section>
  );
}

export default class LuxFeedbackRequestCreateForm extends Component {
  renderRecurringCronPanel = () => {
    const { feedbackRequest } = this.props;
    const recurring = feedbackRequest.recurring === true;
    if (!recurring) return null;

    return (
      <div className="lux-fb-create-recurring">
          <div className="lux-fb-create-recurring__schedule">
            <p className="lux-fb-create-recurring__schedule-label">
              Schedule <span className="form-required">*</span>
            </p>
            <div className="lux-feedback-config-cron">
              <button
                type="button"
                className="lux-feedback-config-cron__btn"
                onClick={() =>
                  this.props.onToggleCronMenu(!this.props.showCronMenu)
                }
                aria-label="Edit schedule"
              >
                <i className="fe fe-repeat" aria-hidden="true" />
              </button>
              <span
                className="lux-feedback-config-cron__value"
                role="button"
                tabIndex={0}
                onClick={() =>
                  this.props.onToggleCronMenu(!this.props.showCronMenu)
                }
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    this.props.onToggleCronMenu(!this.props.showCronMenu);
                  }
                }}
              >
                {feedbackRequest.scheduleData && feedbackRequest.scheduleData.cronString}
              </span>
              <CronJobSelectionMenu
                showDropDown={this.props.showCronMenu}
                closeDropDwonMenu={this.props.onToggleCronMenu}
                onChange={this.props.onCronValueChange}
                cronValue={
                  feedbackRequest.scheduleData && feedbackRequest.scheduleData.cronValue
                }
              />
            </div>
          </div>
      </div>
    );
  };

  render() {
    const {
      feedbackRequest,
      fieldConfig,
      emailInfoFieldConfig,
      editMode,
      onChange,
      onFormError,
      feedbackTypeOptions,
      feedbackSubTypeOptions,
      feedbackTemplateDataList,
      feedbackTemplateOptions,
      itemOptions,
      projectModuleConfig,
      hasFormError,
      onResetFormError,
      closeCreateItemWindow,
      handleSubmit,
      createButtonLabel,
    } = this.props;

    const inputProps = {
      fieldConfig,
      mappingObject: feedbackRequest,
      onChange,
      onFormError,
      menuPortal: true,
      menuPortalZIndex: 10150,
      datePortal: true,
      datePopperPlacement: "top-start",
    };

    const recurring = feedbackRequest.recurring === true;
    const scheduleDateProps = {
      fieldConfig,
      onFormError,
      time: false,
      minDate: new Date(),
      currentDate: new Date(),
      datePortal: true,
      datePopperPlacement: "top-start",
    };

    return (
      <div className="lux-fb-create-form lux-fb-create-form--panel">
        <div className="lux-fb-create-form__scroll">
        <div className="lux-fb-create-form__layout">
          <div className="lux-fb-create-form__main">
            <LuxFormSection
              icon="fe-message-square"
              title="Campaign"
              hint="Name and messaging for this feedback request."
            >
              <div className="lux-fb-create-grid lux-fb-create-grid--2">
                <div className="lux-fb-create-grid__full">
                  <CustomInput
                    inputtype="text"
                    label="Campaign name"
                    name="name"
                    placeholder="e.g. Q2 client satisfaction pulse"
                    datatype="alpnumspl"
                    {...inputProps}
                  />
                </div>
                <div className="lux-fb-create-grid__full">
                  <CustomInput
                    label="Description"
                    name="description"
                    type="textarea"
                    height="64px"
                    placeholder="Internal notes for your team"
                    datatype="alpnumspl"
                    {...inputProps}
                  />
                </div>
                <div className="lux-fb-create-grid__full">
                  <CustomInput
                    label="Email subject"
                    name="emailSubject"
                    type="textarea"
                    height="36px"
                    rows={1}
                    placeholder="Subject line recipients see in their inbox"
                    datatype="alpnumspl"
                    {...inputProps}
                  />
                </div>
              </div>
            </LuxFormSection>

            <LuxFormSection
              icon="fe-layers"
              title="Classification"
              hint="Type, template, and service context."
            >
              <div className="lux-fb-create-grid lux-fb-create-grid--2">
                {feedbackTypeOptions && (
                  <CustomInput
                    type="select"
                    label="Feedback type"
                    name="type"
                    placeholder="Select type"
                    options={feedbackTypeOptions}
                    {...inputProps}
                  />
                )}
                <CustomInput
                  type="select"
                  label="Item"
                  name="itemId"
                  placeholder="Linked item"
                  options={itemOptions}
                  {...inputProps}
                />
                <CustomInput
                  type="select"
                  label="Sub type"
                  name="subType"
                  placeholder="Select sub type"
                  options={feedbackSubTypeOptions}
                  {...inputProps}
                />
                {feedbackTemplateDataList && (
                  <CustomInput
                    type="select"
                    label="Feedback template"
                    name="templateId"
                    placeholder="Select template"
                    options={feedbackTemplateOptions}
                    {...inputProps}
                  />
                )}
                <div className="lux-fb-create-grid__full">
                  <CustomInput
                    type="select"
                    label="Service lines"
                    name="serviceLines"
                    placeholder="Select service lines"
                    isAppConfig
                    configName="feedbackServiceLines"
                    multi
                    createConfig={projectModuleConfig}
                    {...inputProps}
                  />
                </div>
              </div>
            </LuxFormSection>

            <LuxFormSection
              icon="fe-calendar"
              title="Schedule"
              hint="Expiry, draft mode, and optional recurrence."
              className="lux-fb-create-section--schedule"
            >
              <div className="lux-fb-create-grid lux-fb-create-grid--2 lux-fb-create-schedule__dates">
                <CustomInput
                  type="dateselect"
                  label="Expiry date"
                  name="expiryDate"
                  mappingObject={feedbackRequest}
                  onChange={onChange}
                  {...scheduleDateProps}
                />
                <div
                  className={classNames("lux-fb-create-schedule__end-date", {
                    "is-inactive": !recurring,
                  })}
                >
                  <CustomInput
                    readOnly={!recurring}
                    type="dateselect"
                    label="End date"
                    name="endDate"
                    mappingObject={feedbackRequest.scheduleData || {}}
                    onChange={this.props.onChangeScheduleData}
                    onFormError={onFormError}
                    {...scheduleDateProps}
                  />
                  {!recurring && (
                    <p className="lux-fb-create-schedule__end-hint">Enabled when recurring is on</p>
                  )}
                </div>
              </div>
              <div className="lux-fb-create-grid lux-fb-create-grid--2 lux-fb-create-schedule__toggles">
                <CustomInput
                  type="radios"
                  label="Recurring campaign"
                  name="recurring"
                  {...inputProps}
                />
                <CustomInput
                  type="radios"
                  label="Save as draft"
                  name="draft"
                  {...inputProps}
                />
              </div>
              {this.renderRecurringCronPanel()}
            </LuxFormSection>
          </div>

          <aside className="lux-fb-create-form__aside">
            <LuxFeedbackRecipientEmailPanel
              recipients={feedbackRequest.feedbackRequestInfos}
              fieldConfig={emailInfoFieldConfig}
              onChange={onChange}
            />
          </aside>
        </div>
        </div>

        <LuxCreateFooter
          handleSubmit={handleSubmit}
          editMode={editMode}
          initializeRequest={closeCreateItemWindow}
          hasFormError={hasFormError}
          onResetFormError={onResetFormError}
          createButtonLabel={createButtonLabel}
        />
      </div>
    );
  }
}
