/**
 * W24 — NPD FE service. Real API only (no mock fallback).
 * Lifecycle specialization on Project/Task/Gate/Risk/Issue — not a second project SoT.
 */
import { axiosUtils, commonUtils } from "../../_helpers";
import urlConfig from "url.config";

export const npdService = {
  listIdeas,
  getIdea,
  createIdea,
  updateIdea,
  assessIdea,
  businessCase,
  listGates,
  configureGates,
  approveGate,
  rejectGate,
  listChecklist,
  addChecklistItem,
  completeChecklistItem,
  listGovernanceLinks,
  createGovernanceLink,
  dashboardSummary,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function withWrite(params = {}) {
  return {
    ...params,
    userTeamId: resolveUserTeamId(),
    productOrPmOrExec: true,
  };
}

async function listIdeas() {
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.NPD_API_PATH}/ideas`, withWrite());
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function getIdea(ideaRef) {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.NPD_API_PATH}/ideas/${encodeURIComponent(ideaRef)}`,
      withWrite()
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createIdea(body = {}) {
  try {
    const response = await axiosUtils.post(`${urlConfig.NPD_API_PATH}/ideas`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      productOrPmOrExec: true,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

