import React, { Component } from "react";
import classNames from "classnames/bind";
import { GOVERNANCE_PAGE_IDS } from "config/project-governance-nav.config";
import { canDecideChangeRequest, getChangeStatusTone } from "config/project-governance.utils";
import GovernanceLuxDrawerShell from "views/project/components/GovernanceLuxDrawerShell";
import {
  GovernanceDrawerBanner,
  GovernanceDrawerCard,
  GovernanceDrawerField,
  GovernanceDrawerMeta,
  GovernanceDrawerModuleLink,
  GovernanceDrawerStatStrip,
  buildGovernanceQuickLinks,
} from "views/project/components/GovernanceLuxDrawerShared";

export default class ChangeRequestDrawer extends Component {
  state = {
    impactSummary: "",
    baselineScope: "",
    proposedScope: "",
    decisionNotes: "",
    saving: false,
    deciding: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    const { change, open } = this.props;
    if (open && change && change !== prevProps.change) {
      this.setState({
        impactSummary: change.impactSummary || "",
        baselineScope: change.baselineScope || "",
        proposedScope: change.proposedScope || "",
        decisionNotes: change.decisionNotes || "",
        saving: false,
        deciding: false,
        error: null,
      });
    }
  }

  handleSave = async () => {
    const { change, onSave, onClose } = this.props;
    const { impactSummary, baselineScope, proposedScope, decisionNotes } = this.state;
    if (!change || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(change.id, { impactSummary, baselineScope, proposedScope, decisionNotes });
      onClose();
    } catch (e) {
      this.setState({ saving: false, error: (e && e.message) || "Unable to update change request." });
    }
  };

  handleDecision = async (action) => {
    const { change, onApprove, onReject, onClose } = this.props;
    const { decisionNotes } = this.state;
    if (!change || !canDecideChangeRequest(change)) {
      return;
    }
    const handler = action === "approve" ? onApprove : onReject;
    if (!handler) {
      return;
    }
    this.setState({ deciding: true, error: null });
    try {
      await handler(change.id, { decisionNotes });
      onClose();
    } catch (e) {
      this.setState({ deciding: false, error: (e && e.message) || "Unable to process change request." });
    }
  };

  render() {
    const { open, change, onClose } = this.props;
    const { impactSummary, baselineScope, proposedScope, decisionNotes, saving, deciding, error } = this.state;

    if (!open || !change) {
      return null;
    }

    const statusTone = getChangeStatusTone(change.status);
    const canDecide = canDecideChangeRequest(change);

    return (
      <GovernanceLuxDrawerShell
        open={open}
        onClose={onClose}
        wide
        accent="warning"
        icon="fe-git-pull-request"
        eyebrow={change.projectName}
        title={change.title}
        badges={
          <>
            <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{change.status}</span>
            <span>Requested by {change.requestedBy || "—"}</span>
            {change.submittedAt ? <span>Submitted {change.submittedAt}</span> : null}
          </>
        }
        quickLinks={buildGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.GOVERNANCE, [
          { to: "/project/timeline", label: "Delivery timeline", hint: "Impact", icon: "fe fe-bar-chart-2" },
        ])}
        ariaLabel="Change request detail"
        footer={
          <div className="lux-gov-drawer__foot-bar">
            <GovernanceDrawerModuleLink
              to="/project/governance"
              label="Open change register"
              onNavigate={onClose}
            />
            {canDecide ? (
              <div className="lux-gov-change-decisions">
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--primary"
                  disabled={deciding}
                  onClick={() => this.handleDecision("approve")}
                >
                  Approve change
                </button>
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--ghost is-danger"
                  disabled={deciding}
                  onClick={() => this.handleDecision("reject")}
                >
                  Reject
                </button>
              </div>
            ) : null}
            <div className="lux-onb-drawer__foot-actions">
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary"
                disabled={saving || deciding}
                onClick={this.handleSave}
              >
                {saving ? "Saving…" : "Save"}
              </button>
            </div>
          </div>
        }
      >
        <GovernanceDrawerStatStrip
          stats={[
            { label: "Status", value: change.status, tone: statusTone },
            { label: "Requester", value: change.requestedBy || "—" },
            { label: "Submitted", value: change.submittedAt || "—" },
          ]}
        />

        <GovernanceDrawerCard title="Change impact" subtitle="Summary of scope delta and delivery implications">
          <GovernanceDrawerField label="Impact summary">
            <textarea
              rows={2}
              value={impactSummary}
              onChange={(e) => this.setState({ impactSummary: e.target.value })}
            />
          </GovernanceDrawerField>
          {canDecide ? (
            <GovernanceDrawerBanner icon="fe-git-pull-request" tone="warning">
              Pending steering review — document decision notes before approving or rejecting.
            </GovernanceDrawerBanner>
          ) : null}
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Scope comparison" subtitle="Baseline versus proposed delivery boundary">
          <GovernanceDrawerMeta
            items={[
              { label: "Project", value: change.projectName },
              { label: "Status", value: <span className={classNames("lux-doc-badge", `is-${statusTone}`)}>{change.status}</span> },
              { label: "Submitted", value: change.submittedAt || "—" },
              { label: "Requester", value: change.requestedBy || "—" },
            ]}
          />
          <GovernanceDrawerField label="Baseline scope">
            <textarea
              rows={2}
              value={baselineScope}
              onChange={(e) => this.setState({ baselineScope: e.target.value })}
            />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Proposed scope">
            <textarea
              rows={2}
              value={proposedScope}
              onChange={(e) => this.setState({ proposedScope: e.target.value })}
            />
          </GovernanceDrawerField>
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Decision record" subtitle="Steering committee notes and outcome">
          <GovernanceDrawerField label="Decision notes">
            <textarea
              rows={2}
              value={decisionNotes}
              onChange={(e) => this.setState({ decisionNotes: e.target.value })}
              placeholder="Rationale for approve, reject, or defer"
            />
          </GovernanceDrawerField>
          {error ? <p className="lux-gov-drawer__error">{error}</p> : null}
        </GovernanceDrawerCard>
      </GovernanceLuxDrawerShell>
    );
  }
}
