import React from "react";
import classNames from "classnames/bind";
import { PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default function FeedbackRegister({ feedback, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!feedback || !feedback.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-message-circle" aria-hidden="true" />
        <p>No feedback entries yet.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {feedback.map((row, index) => (
        <article key={row.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", row.tone && `is-${row.tone}`)}>
            <i className="fe fe-message-circle" aria-hidden="true" />
          </span>
          <div className="lux-perf-register__main">
            <span className="lux-perf-register__eyebrow">{row.fromName} → {row.toName}</span>
            <h3>{row.message}</h3>
            <div className="lux-perf-register__meta">
              <PerformanceStatusBadge status={row.type} />
              {row.goalTitle ? <span>{row.goalTitle}</span> : null}
              {row.createdAt ? <span>{new Date(row.createdAt).toLocaleDateString()}</span> : null}
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}
