/**
 * F06-T2/T5 — Timesheet recommendation builder + agent Accept / Reject / Defer workflow.
 */
import { writeTimesheetAgentDecision } from "config/timesheet-agent-decision.storage";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { shouldUseAiWorkIntelligenceApi } from "config/ai-work-intelligence.config";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";

export function buildTimesheetRecommendationDraft(intelligence, billability, context = {}) {
  if (!intelligence) {
    return null;
  }

  const evidence = [];
  if (intelligence.daysNeedingAttention > 0) {
    evidence.push(`${intelligence.daysNeedingAttention} day(s) below daily target or missing entries`);
  }
  if (intelligence.dataQualityIssues > 0) {
    evidence.push(`${intelligence.dataQualityIssues} data quality issue(s) detected`);
  }
  if (intelligence.pendingApprovals > 0) {
    evidence.push(`${intelligence.pendingApprovals} timesheet(s) awaiting manager approval`);
  }
  if (intelligence.openConflicts > 0) {
    evidence.push(`${intelligence.openConflicts} open approval conflict(s)`);
  }
  if (intelligence.defaulterCount > 0) {
    evidence.push(`${intelligence.defaulterCount} team defaulter(s) this week`);
  }
  if (billability && billability.leakagePct > 35) {
    evidence.push(`non-billable leakage at ${billability.leakagePct}% of work hours`);
  }
  if (billability && billability.billablePct >= 70 && (billability.workMins || 0) > 0) {
    evidence.push(`billable share at ${billability.billablePct}% of work hours`);
  }

  const summary = evidence.length
    ? evidence.join("; ")
    : "This week looks compliant — no major anomalies detected.";

  let recommendation = "Continue monitoring daily totals and submit before the approval deadline.";
  let primaryAction = "monitor";
  let nextStep = "Stay on the weekly grid and keep entries current.";

  if (intelligence.defaulterCount > 0) {
    recommendation = "Follow up with defaulters and lock approved weeks before payroll processing.";
    primaryAction = "follow_defaulters";
    nextStep = "Review the compliance queue, then nudge employees who have not submitted.";
  } else if (intelligence.openConflicts > 0) {
    recommendation = "Resolve open approval conflicts before locking the week.";
    primaryAction = "resolve_conflicts";
    nextStep = "Open conflict details from the pending approvals list.";
  } else if (intelligence.pendingApprovals > 0) {
    recommendation = "Clear the pending approval queue before week lock.";
    primaryAction = "clear_approvals";
    nextStep = "Switch to the board view and process pending timesheet approvals.";
  } else if (billability && billability.leakagePct > 35) {
    recommendation = "Review non-billable categories and reassign internal time where project work applies.";
    primaryAction = "reduce_leakage";
    nextStep = "Open the weekly grid and reclassify elevated non-billable entries.";
  } else if (intelligence.daysNeedingAttention > 0) {
    recommendation = "Backfill missing days or add notes on under-target days before submit.";
    primaryAction = "backfill_days";
    nextStep = "Return to the weekly grid and complete days needing attention.";
  }

  const weekId =
    (context.timeSheetRequest && context.timeSheetRequest.weekId) ||
    context.weekStartDate ||
    null;

  return {
    id: weekId ? `ts-rec-${weekId}` : `ts-rec-${intelligence.weekStartDate || "week"}`,
    draftOnly: false,
    summary,
    recommendation,
    evidence,
    primaryAction,
    nextStep,
    confidence: intelligence.dataQualityIssues > 2 ? 0.72 : 0.86,
    disclaimer:
      "Session decision only — Accept/Reject does not change timesheet hours or status.",
    actions: ["accept", "reject", "defer"],
    sourceEntityType: "TIMESHEET_WEEK",
    sourceEntityId: weekId,
  };
}

/**
 * Apply Accept / Reject / Defer: persist decision, audit, optional F17 decision, return UI entry.
 */
export async function applyAgentDraftAction(recommendation, action, context = {}) {
  if (!recommendation || !action) {
    return null;
  }
  const verb = String(action).toLowerCase();
  if (!["accept", "reject", "defer"].includes(verb)) {
    return null;
  }

  const labels = {
    accept: "Accepted for this session — timesheet hours and status are unchanged",
    reject: "Rejected for this session — timesheet hours and status are unchanged",
    defer: "Deferred for this session — timesheet hours and status are unchanged",
  };

  const entry = {
    action: verb,
    message: labels[verb],
    at: new Date().toISOString(),
    recommendation: recommendation.summary,
    primaryAction: recommendation.primaryAction,
    nextStep: recommendation.nextStep,
    weekId: recommendation.sourceEntityId,
  };

  writeTimesheetAgentDecision(context, entry);

  const auditAction =
    verb === "accept"
      ? AUDIT_ACTION_TYPES.APPROVED
      : verb === "reject"
        ? AUDIT_ACTION_TYPES.REJECTED
        : AUDIT_ACTION_TYPES.STATUS_CHANGED;

  recordAuditEvent({
    actionType: auditAction,
    entityType: AUDIT_ENTITY_TYPES.TIMESHEET_WEEK,
    entityId: recommendation.sourceEntityId,
    entityRef: recommendation.id,
    headline: `Timesheet recommendation ${verb}`,
    metadata: {
      decision: verb,
      summary: recommendation.summary,
      primaryAction: recommendation.primaryAction,
      source: "timesheet-intelligence-agent",
    },
  });

  if (shouldUseAiWorkIntelligenceApi() && recommendation.remoteRecommendationId) {
    try {
      await aiWorkIntelligenceService.decideRecommendation(
        recommendation.remoteRecommendationId,
        verb.toUpperCase(),
        recommendation.summary || "",
        { persona: "manager" }
      );
      entry.persistedRemote = true;
      entry.message = `${labels[verb]} (synced to AI work intelligence)`;
    } catch (e) {
      entry.persistedRemote = false;
    }
  }

  return entry;
}
