import React, { Component } from "react";
import { PersonaContext } from "context/PersonaContextProvider";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { onboardingService } from "_services/onboarding.service";
import { isOffboardingRouteEnabled } from "config/onboarding.config";
import LifecycleBackNav from "views/people/components/onboarding/LifecycleBackNav";
import CreateOffboardingCasePanel from "views/people/components/onboarding/CreateOffboardingCasePanel";
import CreateOffboardingTemplatePanel from "views/people/components/onboarding/CreateOffboardingTemplatePanel";
import LifecycleActionLink from "views/people/components/onboarding/LifecycleActionLink";
import LifecycleTemplateCatalogGrid from "views/people/components/onboarding/LifecycleTemplateCatalogGrid";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PeopleActionButton } from "views/people/components/PeopleLuxShared";
import { OFFBOARDING_TEMPLATES_PAGE_META } from "config/people-module-nav.config";

class OffboardingTemplatesPage extends Component {
  static contextType = PersonaContext;

  state = {
    templates: [],
    loading: true,
    loadError: null,
    caseCreateOpen: false,
    templateAuthorOpen: false,
    selectedTemplateCode: "",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Offboarding templates");
    this.loadTemplates();
  }

  loadTemplates = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const res = await onboardingService.listOffboardingTemplates();
      this.setState({ templates: res.payload || [], loading: false });
    } catch (_e) {
      this.setState({ loading: false, loadError: "Unable to load exit templates." });
    }
  };

  handleOpenCaseCreate = (templateCode = "") =>
    this.setState({ caseCreateOpen: true, selectedTemplateCode: templateCode });

  handleCloseCaseCreate = () => this.setState({ caseCreateOpen: false });

  handleOpenTemplateAuthor = () => this.setState({ templateAuthorOpen: true });

  handleCloseTemplateAuthor = () => this.setState({ templateAuthorOpen: false });

  render() {
    const personaCtx = this.context || {};
    if (!isOffboardingRouteEnabled(personaCtx.menuAccessControl)) {
      return (
        <PersonaAccessDenied
          moduleName="Offboarding templates"
          reason="Offboarding is not enabled for your organization."
        />
      );
    }

    const { templates, loading, loadError, caseCreateOpen, templateAuthorOpen } = this.state;

    return (
      <div className="lux-onb-page lux-register-page lux-people-page" data-testid="page-offboarding-templates">
        <LuxModuleIntro
                  meta={OFFBOARDING_TEMPLATES_PAGE_META}
                  actions={
                    <>
                      <PeopleActionButton variant="ghost" icon="fe fe-user-x" onClick={() => this.handleOpenCaseCreate()}>
                        Start exit case
                      </PeopleActionButton>
                      <PeopleActionButton variant="primary" icon="fe fe-plus" onClick={() => this.handleOpenTemplateAuthor()}>
                        Create template
                      </PeopleActionButton>
                    </>
                  }
                />

        <div className="lux-register-page__body">
<LifecycleBackNav lifecycle="offboarding" label="Exit templates" />

        {loadError && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-onb-empty"
            icon="fe fe-alert-circle"
            title="Templates unavailable"
            description={loadError}
          />
        )}

        <section className="lux-hrms-dash__panel lux-onb-queue-panel lux-onb-template-panel">
          <header className="lux-hrms-dash__panel-head">
            <div>
              <h2 className="lux-hrms-dash__panel-title">Exit template catalog</h2>
              <p className="lux-hrms-dash__panel-sub">
                Approved exit playbooks for access revocation, asset return, and settlement workflows.
              </p>
            </div>
          </header>
          <div className="lux-hrms-dash__panel-body">
            <LifecycleTemplateCatalogGrid
              templates={templates}
              loading={loading}
              lifecycle="offboarding"
              onUseTemplate={this.handleOpenCaseCreate}
            />
            {!loading && !templates.length && !loadError && (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact lux-onb-empty"
                variant="employees"
                title="No exit templates yet"
                description="Create your first exit checklist template to standardize access revocation, asset return, and settlement."
                showCreate
                createLabel="Create template"
                onCreate={this.handleOpenTemplateAuthor}
              />
            )}
          </div>
        </section>

        <CreateOffboardingTemplatePanel
          open={templateAuthorOpen}
          onClose={this.handleCloseTemplateAuthor}
          onCreated={this.loadTemplates}
        />

        <CreateOffboardingCasePanel
          open={caseCreateOpen}
          onClose={this.handleCloseCaseCreate}
          initialTemplateCode={this.state.selectedTemplateCode}
        />
        </div>
      </div>
    );
  }
}

export default OffboardingTemplatesPage;
