import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import OnboardingKpiStrip from "./OnboardingKpiStrip";
import LifecycleInsightsCharts from "./LifecycleInsightsCharts";

function getStorageKey(lifecycle) {
  return lifecycle === "offboarding"
    ? "famstack-offboarding-queue-summary-expanded"
    : "famstack-onboarding-queue-summary-expanded";
}

function buildCollapsedLine(metrics, lifecycle) {
  if (!metrics) return "";
  if (lifecycle === "offboarding") {
    return `${metrics.active} active exit${metrics.active === 1 ? "" : "s"} · ${metrics.blocked} blocked · ${metrics.dueThisWeek} due this week · ${metrics.avgProgress}% avg progress`;
  }
  return `${metrics.active} active case${metrics.active === 1 ? "" : "s"} · ${metrics.overdueTasks} overdue task${metrics.overdueTasks === 1 ? "" : "s"} · ${metrics.avgReadiness}% avg readiness`;
}

class LifecycleQueueSummary extends PureComponent {
  constructor(props) {
    super(props);
    const lifecycle = props.lifecycle || "onboarding";
    this.state = {
      expanded: readSummaryExpanded(getStorageKey(lifecycle)),
    };
  }

  toggleExpanded = () => {
    const lifecycle = this.props.lifecycle || "onboarding";
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(getStorageKey(lifecycle), this.state.expanded)
    );
  };

  render() {
    const {
      lifecycle = "onboarding",
      metrics,
      loading,
      cases,
    } = this.props;
    const { expanded } = this.state;
    const isOffboarding = lifecycle === "offboarding";
    const collapsedLine = buildCollapsedLine(metrics, lifecycle);

    return (
      <section
        className={classNames("lux-onb-summary", { "is-collapsed": !expanded })}
        aria-label={isOffboarding ? "Offboarding queue summary" : "Onboarding queue summary"}
      >
        <div className="lux-onb-summary__header-bar">
          <div className="lux-onb-summary__header-main">
            <LuxSummaryEyebrow
              variant={isOffboarding ? "offboarding" : "onboarding"}
              className="lux-onb-summary__eyebrow"
            >
              {isOffboarding ? "Exit queue intelligence" : "Onboarding intelligence"}
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--compact">
                {loading ? (
                  "Loading…"
                ) : (
                  <>
                    <CountUp end={metrics ? metrics.active : 0} duration={0.7} />{" "}
                    <span>{isOffboarding ? "active exits" : "active cases"}</span>
                  </>
                )}
              </h2>
            ) : (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--bar">
                {isOffboarding ? "Offboarding overview" : "Onboarding overview"}
              </h2>
            )}
          </div>
          <button
            type="button"
            className="lux-onb-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-onb-queue-summary-body"
            title={expanded ? "Collapse summary" : "Insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && !loading && collapsedLine && (
          <div className="lux-onb-summary__collapsed-strip">
            <p className="lux-onb-summary__collapsed-line">{collapsedLine}</p>
          </div>
        )}

        <div
          id="lux-onb-queue-summary-body"
          className="lux-onb-summary__body"
          aria-hidden={!expanded}
        >
          <OnboardingKpiStrip metrics={metrics} lifecycle={lifecycle} />
          <LifecycleInsightsCharts cases={cases} lifecycle={lifecycle} loading={loading} />
        </div>
      </section>
    );
  }
}

export default LifecycleQueueSummary;
