import React from "react";
import classNames from "classnames/bind";
import { resolveStatusMeta, resolveTaskStatusMeta } from "config/onboarding.utils";

function OnboardingStatusBadge({ status, lifecycle = "onboarding", variant = "case" }) {
  const meta =
    variant === "task"
      ? resolveTaskStatusMeta(status)
      : resolveStatusMeta(status, lifecycle);

  return (
    <span className={classNames("lux-onb-badge", `lux-onb-badge--${meta.tone}`)}>
      {meta.label}
    </span>
  );
}

export default OnboardingStatusBadge;
