import { axiosUtils } from "../_helpers";
import { commonUtils } from "../_helpers/common.utils";
import urlConfig from "url.config";
import { normalizeOrgUnit } from "config/org-structure.config";
import { buildReportingLinesFromEmployees } from "config/org-structure.utils";
import { appConfigService } from "./appconfig.service";

import { apiErrorResult } from "config/mock-fallback.utils";

export const orgStructureService = {
  listOrgUnits,
  getOrgChart,
  updateOrgUnitHead,
  reassignManager,
  listMasterValues,
  createMasterValue,
  removeMasterValue,
};

async function listOrgUnitsFromApi() {
  const response = await axiosUtils.getWithParam(`${urlConfig.ORG_STRUCTURE_API_PATH}/units`, {
    userTeamId: commonUtils.getCurrentUserTeamId(),
  });
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeOrgUnit(row)).filter(Boolean),
    source: "api",
  };
}

async function listOrgUnits() {
  try {
    return await listOrgUnitsFromApi();
  } catch (e) {
    return apiErrorResult(null);
  }
}

async function getOrgChartFromApi() {
  const response = await axiosUtils.getWithParam(`${urlConfig.ORG_STRUCTURE_API_PATH}/chart`, {
    userTeamId: commonUtils.getCurrentUserTeamId(),
  });
  const payload = (response && response.payload) || response || {};
  const employees = payload.employees || [];
  return {
    payload: {
      employees,
      reportingLines: payload.reportingLines || buildReportingLinesFromEmployees(employees),
      orgUnits: (payload.orgUnits || []).map((row) => normalizeOrgUnit(row)).filter(Boolean),
    },
    source: "api",
  };
}

async function getOrgChart() {
  try {
    return await getOrgChartFromApi();
  } catch (e) {
    return {
      payload: { employees: [], reportingLines: [], orgUnits: [] },
      source: "api-error",
    };
  }
}

/**
 * Persist reporting line: set employee.managerId = headEmployeeId on fs_employee_model.
 */
async function reassignManager(employeeId, headEmployeeId, headEmployeeName) {
  try {
    const teamId = commonUtils.getCurrentUserTeamId();
    const actorId = commonUtils.getCurrentUserId();
    const response = await axiosUtils.put(
      `${urlConfig.ORG_STRUCTURE_API_PATH}/managers/reassign?userTeamId=${teamId}&actorId=${actorId}`,
      { employeeId, headEmployeeId, managerId: headEmployeeId, headEmployeeName }
    );
    const row = (response && response.payload) || response;
    return { payload: row, source: "api" };
  } catch (e) {
    return apiErrorResult(null);
  }
}

async function updateOrgUnitHead(orgUnitId, headEmployeeId, headEmployeeName, employeeId) {
  const resolvedEmployeeId =
    employeeId != null && employeeId !== ""
      ? employeeId
      : resolveEmployeeIdFromOrgUnitId(orgUnitId);

  // Prefer direct EmployeeModel.managerId write when employeeId is known.
  if (resolvedEmployeeId != null && resolvedEmployeeId !== "") {
    try {
      const result = await reassignManager(resolvedEmployeeId, headEmployeeId, headEmployeeName);
      if (result && result.payload) {
        const row = result.payload || {};
        return {
          payload: normalizeOrgUnit({
            id: orgUnitId,
            name: row.employeeName,
            headEmployeeId: row.headEmployeeId || headEmployeeId,
            headEmployeeName: row.headEmployeeName || headEmployeeName,
            ...row,
          }),
          source: result.source || "api",
        };
      }
    } catch (e) {
      // fall through to unit-head endpoint
    }
  }

  try {
    const teamId = commonUtils.getCurrentUserTeamId();
    const actorId = commonUtils.getCurrentUserId();
    const response = await axiosUtils.put(
      `${urlConfig.ORG_STRUCTURE_API_PATH}/units/${orgUnitId}/head?userTeamId=${teamId}&actorId=${actorId}`,
      { headEmployeeId, headEmployeeName, employeeId: resolvedEmployeeId }
    );
    const row = (response && response.payload) || response;
    return { payload: normalizeOrgUnit(row), source: "api" };
  } catch (e) {
    return apiErrorResult(null);
  }
}

function resolveEmployeeIdFromOrgUnitId(orgUnitId) {
  if (orgUnitId == null || orgUnitId === "") {
    return null;
  }
  const text = String(orgUnitId);
  if (text.startsWith("emp-root-")) {
    return text.slice("emp-root-".length);
  }
  return /^\d+$/.test(text) ? text : null;
}

/**
 * W2-B02 / ADMIN-005 — read department/designation/teamName from Application Config HRMS lists.
 */
async function listMasterValues() {
  const teamId = commonUtils.getCurrentUserTeamId();
  try {
    const response = await appConfigService.getModuleConfig(teamId, "HRMS");
    const rows = (response && response.payload) || response || [];
    const list = Array.isArray(rows) ? rows : [];
    const pick = (name) => {
      const entry = list.find((row) => row && row.name === name);
      const value = entry && entry.value;
      return Array.isArray(value) ? value.filter(Boolean) : [];
    };
    return {
      payload: {
        department: pick("department"),
        designation: pick("designation"),
        teamName: pick("teamName"),
        costCenter: pick("costCenter"),
      },
      source: "application-config",
    };
  } catch (e) {
    return {
      payload: { department: [], designation: [], teamName: [], costCenter: [] },
      source: "api-error",
    };
  }
}

/**
 * W2-B02 / ADMIN-005 — create department/designation/teamName via Application Config list API.
 */
async function createMasterValue(listKey, value) {
  const teamId = commonUtils.getCurrentUserTeamId();
  const response = await appConfigService.appendModuleListValue(teamId, "HRMS", listKey, value);
  return { payload: (response && response.payload) || response || {}, source: "application-config" };
}

async function removeMasterValue(listKey, value) {
  const teamId = commonUtils.getCurrentUserTeamId();
  const response = await appConfigService.removeModuleListValue(teamId, "HRMS", listKey, value);
  return { payload: (response && response.payload) || response || {}, source: "application-config" };
}
