import React, { Component } from "react";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { performanceManagementService } from "_services/performanceManagement.service";
import { isPerformanceManagementEnabled, PERFORMANCE_ROUTES } from "config/performance-management.config";
import { getEmployeeDisplayName } from "config/employee360.utils";
import { buildPerformanceTabStats } from "config/employee360Tab.utils";
import { formatPerformanceRating } from "config/performance-management.utils";
import { isFieldVisible } from "config/employee360-field.utils";
import { PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default class Employee360PerformanceTab extends Component {
  state = { loading: true, loadError: null, snapshot: null, dataSource: null };

  componentDidMount() {
    this.loadSnapshot();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.employee && prevProps.employee.id;
    const nextId = this.props.employee && this.props.employee.id;
    const prevPerf = prevProps.summary && prevProps.summary.performance;
    const nextPerf = this.props.summary && this.props.summary.performance;
    if (prevId !== nextId || prevPerf !== nextPerf) {
      this.loadSnapshot();
    }
  }

  loadSnapshot = async () => {
    const { employee, summary } = this.props;
    if (!employee || !isPerformanceManagementEnabled()) {
      this.setState({ loading: false, snapshot: null, dataSource: null });
      return;
    }

    const aggregatePerformance =
      summary && summary.performance && typeof summary.performance === "object"
        ? summary.performance
        : null;
    if (aggregatePerformance && (aggregatePerformance.activeReview || aggregatePerformance.goals || aggregatePerformance.openGoals != null)) {
      this.setState({
        loading: false,
        loadError: null,
        snapshot: aggregatePerformance,
        dataSource: "api",
      });
      return;
    }

    const employeeName = getEmployeeDisplayName(employee);
    this.setState({ loading: true, loadError: null });
    try {
      const result = await performanceManagementService.getEmployeePerformanceSnapshot({ employeeName });
      this.setState({ loading: false, snapshot: result.payload || null, dataSource: result.source });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load performance snapshot.",
      });
    }
  };

  renderGoals(goals) {
    if (!goals || !goals.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__embed-empty"
          icon="fe fe-target"
          title="No active goals"
          description="Goals will appear when linked to a review cycle."
        />
      );
    }
    return (
      <ul className="lux-employee-360__perf-list">
        {goals.map((goal) => (
          <li key={goal.id} className="lux-employee-360__perf-item">
            <div>
              <strong>{goal.title}</strong>
              <span>{goal.progress}% · {goal.cycleName}</span>
            </div>
            <PerformanceStatusBadge status={goal.status} />
          </li>
        ))}
      </ul>
    );
  }

  renderFeedback(feedback) {
    if (!feedback || !feedback.length) {
      return <p className="lux-employee-360__panel-desc">No recent feedback entries.</p>;
    }
    return (
      <ul className="lux-employee-360__perf-list">
        {feedback.map((row) => (
          <li key={row.id} className="lux-employee-360__perf-item">
            <div>
              <strong>{row.fromName}</strong>
              <span>{row.message}</span>
            </div>
            <PerformanceStatusBadge status={row.type} />
          </li>
        ))}
      </ul>
    );
  }

  render() {
    const { employee, maskingPolicy } = this.props;
    const { loading, loadError, snapshot, dataSource } = this.state;

    if (!isPerformanceManagementEnabled()) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__embed-empty"
          icon="fe fe-award"
          title="Performance module disabled"
          description="Enable performance management to view goals and reviews here."
        />
      );
    }

    const stats = buildPerformanceTabStats(snapshot, maskingPolicy);
    const activeReview = snapshot && snapshot.activeReview;
    const ratingsVisible = isFieldVisible("performanceReview", maskingPolicy);
    const selfRating = ratingsVisible
      ? formatPerformanceRating(activeReview && activeReview.selfRating, maskingPolicy)
      : "Restricted";
    const managerRating = ratingsVisible
      ? formatPerformanceRating(activeReview && activeReview.managerRating, maskingPolicy)
      : "Restricted";

    return (
      <ProjectDetailsTabShell
        title="Performance"
        description="Goals, review cycle status, and continuous feedback for this employee."
        stats={stats}
        actions={
          <Link className="lux-onb-action lux-onb-action--ghost" to={PERFORMANCE_ROUTES.GOALS}>
            Open goals workspace
          </Link>
        }
      >
        {dataSource === "api" ? (
          <span className="lux-employee-360__source-pill">Live API</span>
        ) : dataSource ? (
          <span className="lux-employee-360__source-pill">Unavailable</span>
        ) : null}
        {loadError ? <div className="lux-perf-alert">{loadError}</div> : null}
        {loading ? <div className="lux-perf-skeleton lux-perf-skeleton--panel" /> : null}

        {!loading && snapshot ? (
          <div className="lux-employee-360__perf-grid">
            <section className="lux-employee-360__panel">
              <h3 className="lux-employee-360__panel-title">Active review</h3>
              {activeReview ? (
                <div className="lux-employee-360__perf-review">
                  <p className="lux-employee-360__panel-desc">{activeReview.cycleName}</p>
                  <div className="lux-employee-360__metrics lux-employee-360__metrics--compact">
                    <article className="lux-employee-360__metric">
                      <span className="lux-employee-360__metric-label">Status</span>
                      <strong className="lux-employee-360__metric-value">
                        <PerformanceStatusBadge status={activeReview.status} />
                      </strong>
                    </article>
                    <article className="lux-employee-360__metric">
                      <span className="lux-employee-360__metric-label">Self rating</span>
                      <strong className="lux-employee-360__metric-value">{selfRating}</strong>
                    </article>
                    <article className="lux-employee-360__metric">
                      <span className="lux-employee-360__metric-label">Manager rating</span>
                      <strong className="lux-employee-360__metric-value">{managerRating}</strong>
                    </article>
                  </div>
                  {activeReview.selfSummary ? (
                    <p className="lux-employee-360__panel-desc">{activeReview.selfSummary}</p>
                  ) : null}
                  <Link className="lux-onb-action lux-onb-action--ghost" to={PERFORMANCE_ROUTES.REVIEWS}>
                    Open review workspace
                  </Link>
                </div>
              ) : (
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact lux-employee-360__embed-empty"
                  icon="fe fe-clipboard"
                  title="No review in flight"
                  description="This employee has no active performance review."
                />
              )}
            </section>

            <section className="lux-employee-360__panel">
              <h3 className="lux-employee-360__panel-title">Goals / OKRs</h3>
              {this.renderGoals(snapshot.goals)}
            </section>

            <section className="lux-employee-360__panel">
              <h3 className="lux-employee-360__panel-title">Recent feedback</h3>
              {this.renderFeedback(snapshot.feedback)}
            </section>

            {snapshot.growthPlans && snapshot.growthPlans.length ? (
              <section className="lux-employee-360__panel">
                <h3 className="lux-employee-360__panel-title">Growth plan</h3>
                <div className="lux-employee-360__perf-review">
                  <strong>{snapshot.growthPlans[0].title}</strong>
                  <p className="lux-employee-360__panel-desc">
                    {snapshot.growthPlans[0].progress}% complete · Mentor: {snapshot.growthPlans[0].mentorName || "—"}
                  </p>
                  <Link className="lux-onb-action lux-onb-action--ghost" to={PERFORMANCE_ROUTES.GROWTH_PLANS}>
                    View growth plans
                  </Link>
                </div>
              </section>
            ) : null}
          </div>
        ) : null}

        {!loading && !snapshot && !loadError ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-employee-360__embed-empty"
            icon="fe fe-award"
            title="No performance records"
            description={`No goals or reviews found for ${getEmployeeDisplayName(employee)}.`}
          />
        ) : null}
      </ProjectDetailsTabShell>
    );
  }
}
