import React, { Component } from "react";
import classNames from "classnames/bind";
import Select from "react-select";
import {
  getQuestionTypeMeta,
  sortQuestions,
} from "./feedbackTemplateQuestions.utils";

class LuxFeedbackTemplateQuestions extends Component {
  getSortedQuestions = () => sortQuestions(this.props.questionDataList);

  onChangeList = (list) => {
    this.props.onChange("questionDataList", list);
  };

  onQuestionChange = (sortedIndex, question) => {
    const list = [...(this.props.questionDataList || [])];
    const sorted = sortQuestions(list);
    const targetId = sorted[sortedIndex] && sorted[sortedIndex].id;
    const idx = list.findIndex((q) => q.id === targetId);
    if (idx < 0) return;
    list[idx] = question;
    this.onChangeList(list);
  };

  onRemoveQuestion = (questionId) => {
    let list =
      (this.props.questionDataList || []).filter((q) => q.id !== questionId) || [];
    list = list.map((question, index) => ({ ...question, index }));
    this.onChangeList(list);
  };

  swapQuestionIndices = (sortedIndex, direction) => {
    const list = [...(this.props.questionDataList || [])];
    const sorted = sortQuestions(list);
    const partnerIndex = sortedIndex + direction;
    if (partnerIndex < 0 || partnerIndex >= sorted.length) return;
    const aId = sorted[sortedIndex].id;
    const bId = sorted[partnerIndex].id;
    const aIdx = list.findIndex((q) => q.id === aId);
    const bIdx = list.findIndex((q) => q.id === bId);
    if (aIdx < 0 || bIdx < 0) return;
    const aOrder = list[aIdx].index;
    list[aIdx] = { ...list[aIdx], index: list[bIdx].index };
    list[bIdx] = { ...list[bIdx], index: aOrder };
    this.onChangeList(list);
  };

  renderEmpty = () => (
    <div className="lux-fb-qt-empty">
      <div className="lux-fb-qt-empty__icon" aria-hidden="true">
        <i className="fe fe-message-square" />
      </div>
      <strong>No questions yet</strong>
      <p>Add your first question to define what recipients will answer.</p>
    </div>
  );

  render() {
    const {
      editMode,
      questionConfigureMode,
      typeOptions,
    } = this.props;
    const questions = this.getSortedQuestions();

    if (!questions.length) {
      return <div className="lux-fb-qt">{this.renderEmpty()}</div>;
    }

    return (
      <div className="lux-fb-qt" role="list" aria-label="Template questions">
        {questions.map((question, index) => (
          <LuxFeedbackTemplateQuestionCard
            key={question.id != null ? String(question.id) : `fb-qt-${index}`}
            question={question}
            index={index}
            total={questions.length}
            editMode={editMode}
            questionConfigureMode={questionConfigureMode}
            typeOptions={typeOptions}
            onQuestionChange={this.onQuestionChange}
            onRemoveQuestion={this.onRemoveQuestion}
            onMoveUp={() => this.swapQuestionIndices(index, -1)}
            onMoveDown={() => this.swapQuestionIndices(index, 1)}
          />
        ))}
      </div>
    );
  }
}

class LuxFeedbackTemplateQuestionCard extends Component {
  onFieldChange = (name, value) => {
    let next = { ...this.props.question, [name]: value };
    if (name === "type") {
      const meta = getQuestionTypeMeta(value, this.props.typeOptions);
      if (!meta.multi) {
        next = { ...next, questionOptions: null };
      }
    }
    this.props.onQuestionChange(this.props.index, next);
  };

  renderToggle = (name, label, icon) => {
    const { editMode, questionConfigureMode } = this.props;
    if (!editMode || !questionConfigureMode) return null;
    const checked = !!this.props.question[name];
    return (
      <label
        className={classNames("lux-fb-qt-toggle", { "is-on": checked })}
        title={label}
      >
        <input
          type="checkbox"
          checked={checked}
          disabled={!editMode}
          onChange={(e) => this.onFieldChange(name, e.target.checked)}
        />
        <i className={`fe ${icon}`} aria-hidden="true" />
        <span>{label}</span>
      </label>
    );
  };

  renderConfigureBody = () => {
    const { question, typeOptions, editMode } = this.props;
    const typeMeta = getQuestionTypeMeta(question.type, typeOptions);
    const options = typeOptions || [];
    const selectValue = options.find((t) => t.value === question.type) || null;

    return (
      <>
        <div className="lux-fb-qt-card__field lux-fb-qt-card__field--primary">
          <label className="lux-fb-qt-card__label" htmlFor={`fb-qt-text-${question.id}`}>
            Question text
          </label>
          <input
            id={`fb-qt-text-${question.id}`}
            type="text"
            className="lux-fb-qt-card__input"
            value={question.question || ""}
            disabled={!editMode}
            placeholder="e.g. How satisfied are you with delivery quality?"
            onChange={(e) => this.onFieldChange("question", e.target.value)}
          />
        </div>

        <div className="lux-fb-qt-card__toolbar">
          <div className="lux-fb-qt-card__field lux-fb-qt-card__field--type">
            <label className="lux-fb-qt-card__label">Answer type</label>
            <div className="lux-fb-qt-card__select">
              <Select
                isSearchable
                isClearable={false}
                isDisabled={!editMode}
                placeholder="Select type"
                classNamePrefix="custom-select"
                menuPlacement="auto"
                value={selectValue}
                options={options}
                onChange={(opt) => this.onFieldChange("type", opt && opt.value)}
              />
            </div>
            <span className={classNames("lux-fb-qt-type-pill", `is-${typeMeta.tone}`)}>
              <i className={typeMeta.icon} aria-hidden="true" />
              {typeMeta.label}
            </span>
          </div>

          <div className="lux-fb-qt-card__toggles">
            {this.renderToggle("mandatory", "Required", "fe-asterisk")}
            {this.renderToggle("hasComments", "Comments", "fe-message-circle")}
          </div>
        </div>

        {typeMeta.multi && (
          <div className="lux-fb-qt-card__field lux-fb-qt-card__field--options">
            <label className="lux-fb-qt-card__label" htmlFor={`fb-qt-opt-${question.id}`}>
              Answer choices
            </label>
            <input
              id={`fb-qt-opt-${question.id}`}
              type="text"
              className="lux-fb-qt-card__input"
              value={question.questionOptions || ""}
              disabled={!editMode}
              placeholder="Excellent, Good, Average, Poor"
              onChange={(e) => this.onFieldChange("questionOptions", e.target.value)}
            />
            <p className="lux-fb-qt-card__hint">Separate each option with a comma.</p>
          </div>
        )}
      </>
    );
  };

  renderPreviewBody = () => {
    const { question, typeOptions } = this.props;
    const typeMeta = getQuestionTypeMeta(question.type, typeOptions);
    const text = (question.question || "").trim();

    return (
      <div className="lux-fb-qt-card__preview-main">
        <p className="lux-fb-qt-card__preview-text">
          {text || <span className="lux-fb-qt-card__placeholder">Untitled question</span>}
          {question.mandatory && (
            <span className="lux-fb-qt-card__required" title="Required">
              Required
            </span>
          )}
        </p>
        <div className="lux-fb-qt-card__preview-meta">
          <span className={classNames("lux-fb-qt-type-pill", `is-${typeMeta.tone}`)}>
            <i className={typeMeta.icon} aria-hidden="true" />
            {typeMeta.label}
          </span>
          {question.hasComments && (
            <span className="lux-fb-qt-meta-chip">
              <i className="fe fe-message-circle" aria-hidden="true" />
              Comments allowed
            </span>
          )}
          {typeMeta.multi && question.questionOptions && (
            <span className="lux-fb-qt-meta-chip" title={question.questionOptions}>
              <i className="fe fe-list" aria-hidden="true" />
              {question.questionOptions}
            </span>
          )}
        </div>
      </div>
    );
  };

  render() {
    const {
      question,
      index,
      total,
      editMode,
      questionConfigureMode,
      onMoveUp,
      onMoveDown,
      onRemoveQuestion,
    } = this.props;
    const isConfigure = editMode && questionConfigureMode;
    const showReorder = editMode && total > 1;

    return (
      <article
        className={classNames("lux-fb-qt-card", {
          "lux-fb-qt-card--configure": isConfigure,
          "lux-fb-qt-card--preview": !isConfigure,
        })}
        role="listitem"
      >
        <div className="lux-fb-qt-card__rail" aria-hidden={!showReorder && !isConfigure}>
          <span className="lux-fb-qt-card__index">{index + 1}</span>
          {showReorder && (
            <div className="lux-fb-qt-card__reorder">
              <button
                type="button"
                className="lux-fb-qt-card__reorder-btn"
                disabled={index === 0}
                title="Move up"
                onClick={onMoveUp}
              >
                <i className="fe fe-chevron-up" aria-hidden="true" />
              </button>
              <button
                type="button"
                className="lux-fb-qt-card__reorder-btn"
                disabled={index >= total - 1}
                title="Move down"
                onClick={onMoveDown}
              >
                <i className="fe fe-chevron-down" aria-hidden="true" />
              </button>
            </div>
          )}
        </div>

        <div className="lux-fb-qt-card__content">
          {isConfigure ? this.renderConfigureBody() : this.renderPreviewBody()}
        </div>

        {editMode && isConfigure && (
          <button
            type="button"
            className="lux-fb-qt-card__remove"
            title="Remove question"
            onClick={() => onRemoveQuestion(question.id)}
          >
            <i className="fe fe-trash-2" aria-hidden="true" />
          </button>
        )}
      </article>
    );
  }
}

export default LuxFeedbackTemplateQuestions;
