/**
 * Persona-aware navigation (P00-T8) — role personaModules + org pagePersonaMap overrides.
 */

import { getPagePersonaOverride, filterPersonasByOrgPolicy } from "config/org-access-policy.config";

export const PERSONA_TYPES = [
  "EMPLOYEE",
  "MANAGER",
  "PROJECT_MANAGER",
  "RESOURCE_MANAGER",
  "HR_ADMIN",
  "PAYROLL_MANAGER",
  "FINANCE_MANAGER",
  "EXECUTIVE",
  "ADMIN",
  "CLIENT",
];

const PERSONA_STORAGE_KEY = "tracopus_active_persona";

/** Fired when active persona changes (header switcher or API refresh). */
export const PERSONA_CONTEXT_CHANGED = "famstack-persona-context-changed";

/** Human-readable labels for header switcher and scope badge. */
export const PERSONA_LABELS = {
  EMPLOYEE: "Employee",
  MANAGER: "Manager",
  PROJECT_MANAGER: "Project Manager",
  RESOURCE_MANAGER: "Resource Manager",
  HR_ADMIN: "HR Admin",
  PAYROLL_MANAGER: "Payroll Manager",
  FINANCE_MANAGER: "Finance Manager",
  EXECUTIVE: "Executive",
  ADMIN: "Admin",
  CLIENT: "Client",
};

export function getPersonaLabel(persona) {
  return PERSONA_LABELS[persona] || persona || "Employee";
}

export function setActivePersona(persona, allowedPersonas) {
  const allowed = allowedPersonas || [];
  if (!persona || !allowed.includes(persona)) {
    return false;
  }
  try {
    sessionStorage.setItem(PERSONA_STORAGE_KEY, persona);
    return true;
  } catch (e) {
    return false;
  }
}

export function clearActivePersona() {
  try {
    sessionStorage.removeItem(PERSONA_STORAGE_KEY);
  } catch (e) {
    // sessionStorage may be unavailable
  }
}

const PERSONA_PRIORITY = [
  "ADMIN",
  "EXECUTIVE",
  "FINANCE_MANAGER",
  "PAYROLL_MANAGER",
  "HR_ADMIN",
  "RESOURCE_MANAGER",
  "PROJECT_MANAGER",
  "MANAGER",
  "EMPLOYEE",
  "CLIENT",
];

/** Module groups visible per persona (§6.6). */
export const GROUP_PERSONA_VISIBILITY = {
  workspace: PERSONA_TYPES.filter((p) => p !== "CLIENT"),
  projects: ["EMPLOYEE", "MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER", "FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  people: ["EMPLOYEE", "MANAGER", "HR_ADMIN", "PAYROLL_MANAGER", "FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  resources: ["MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER", "EXECUTIVE", "ADMIN"],
  finance: ["FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  payroll: ["EMPLOYEE", "MANAGER", "PAYROLL_MANAGER", "FINANCE_MANAGER", "HR_ADMIN", "ADMIN"],
  performance: ["EMPLOYEE", "MANAGER", "HR_ADMIN", "EXECUTIVE", "ADMIN"],
  analytics: ["MANAGER", "HR_ADMIN", "PAYROLL_MANAGER", "FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  ai: ["MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER", "HR_ADMIN", "FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  integrations: ["MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER", "HR_ADMIN", "FINANCE_MANAGER", "EXECUTIVE", "ADMIN"],
  admin: ["ADMIN"],
  client: ["CLIENT"],
};

function normalizePersonaCode(value) {
  const code = String(value || "").trim().toUpperCase();
  if (code === "HR_MANAGER") {
    return "HR_ADMIN";
  }
  return code;
}

function orderPersonas(set) {
  return PERSONA_PRIORITY.filter((persona) => set.has(persona));
}

/** Heuristic fallback when role has no personaModules.allowedPersonas. */
export function resolveAllowedPersonasFromModules(menuAccessControl) {
  const personas = new Set();
  const hrms = (menuAccessControl && menuAccessControl.hrmsModules) || {};
  const admin = (menuAccessControl && menuAccessControl.adminModules) || {};
  const project = (menuAccessControl && menuAccessControl.projectModules) || {};
  const sales = (menuAccessControl && menuAccessControl.salesModules) || {};

  if (
    hrms.attendanceEnabled ||
    hrms.leavesEnabled ||
    hrms.timesheetEnabled ||
    hrms.dashboardEnabled
  ) {
    personas.add("EMPLOYEE");
  }
  if (hrms.employeesEnabled || project.dashboardEnabled || project.listEnabled) {
    personas.add("MANAGER");
  }
  if (project.dashboardEnabled || project.listEnabled || project.activitesEnabled) {
    personas.add("PROJECT_MANAGER");
  }
  if (project.capacityEnabled) {
    personas.add("RESOURCE_MANAGER");
  }
  if (hrms.employeesEnabled || hrms.dashboardEnabled) {
    personas.add("HR_ADMIN");
  }
  if (hrms.invoiceEnabled || sales.bidrequestsEnabled || sales.purchaseordersEnabled || project.accountsEnabled) {
    personas.add("FINANCE_MANAGER");
  }
  if (hrms.invoiceEnabled || hrms.employeesEnabled || project.reportsEnabled) {
    personas.add("PAYROLL_MANAGER");
  }
  if (project.reportsEnabled || project.portfolioEnabled || hrms.dashboardEnabled) {
    personas.add("EXECUTIVE");
  }
  if (hrms.appconfigEnabled || admin.leavePoliciesEnabled || admin.rolesEnabled) {
    personas.add("ADMIN");
  }

  if (personas.size === 0) {
    personas.add("EMPLOYEE");
  }

  return orderPersonas(personas);
}

export function getPersonaModulesConfig(menuAccessControl) {
  return (menuAccessControl && menuAccessControl.personaModules) || {};
}

/**
 * Prefer explicit role personaModules.allowedPersonas when configured;
 * otherwise fall back to module-flag heuristic (legacy roles).
 */
export function resolveAllowedPersonas(menuAccessControl) {
  const personaModules = getPersonaModulesConfig(menuAccessControl);
  let allowed;
  if (personaModules.configured === true && Array.isArray(personaModules.allowedPersonas)) {
    const set = new Set(
      personaModules.allowedPersonas.map(normalizePersonaCode).filter((p) => PERSONA_TYPES.includes(p))
    );
    if (set.size === 0) {
      set.add("EMPLOYEE");
    }
    allowed = orderPersonas(set);
  } else {
    allowed = resolveAllowedPersonasFromModules(menuAccessControl);
  }
  return filterPersonasByOrgPolicy(allowed);
}

export function isPersonaSwitchEnabled(menuAccessControl) {
  const personaModules = getPersonaModulesConfig(menuAccessControl);
  if (personaModules.configured === true) {
    return personaModules.personaSwitchEnabled !== false;
  }
  return true;
}

export function resolveConfiguredDefaultPersona(menuAccessControl, allowedPersonas) {
  const allowed = allowedPersonas || resolveAllowedPersonas(menuAccessControl);
  const personaModules = getPersonaModulesConfig(menuAccessControl);
  const preferred = normalizePersonaCode(personaModules.defaultPersona);
  if (preferred && allowed.includes(preferred)) {
    return preferred;
  }
  return allowed[0] || "EMPLOYEE";
}

export function resolveActivePersona(menuAccessControl) {
  const allowed = resolveAllowedPersonas(menuAccessControl);
  try {
    const stored = sessionStorage.getItem(PERSONA_STORAGE_KEY);
    if (stored && allowed.includes(stored)) {
      return stored;
    }
  } catch (e) {
    // sessionStorage may be unavailable in tests
  }
  return resolveConfiguredDefaultPersona(menuAccessControl, allowed);
}

export function isGroupVisibleForPersona(group, activePersona) {
  if (!group || !activePersona) {
    return true;
  }
  const allowed = group.personas || GROUP_PERSONA_VISIBILITY[group.id];
  if (!allowed || allowed.length === 0) {
    return true;
  }
  return allowed.includes(activePersona);
}

/** Effective personas for a sidebar item (org override ∪ catalog default). */
export function resolveItemPersonas(item) {
  if (!item) {
    return null;
  }
  const override = getPagePersonaOverride(item.path || item.aliasPath);
  // Explicit override (including []) wins — [] means deny all personas.
  if (override != null) {
    return Array.isArray(override) ? [...override] : [];
  }
  return item.personas && item.personas.length > 0 ? item.personas : null;
}

export function isItemVisibleForPersona(item, activePersona) {
  if (!item || !activePersona) {
    return true;
  }
  const personas = resolveItemPersonas(item);
  if (personas == null) {
    return true;
  }
  if (personas.length === 0) {
    return false;
  }
  const normalizedPersona = normalizePersonaCode(activePersona);
  return personas.some((persona) => {
    const code = normalizePersonaCode(persona);
    return code === normalizedPersona;
  });
}
