/**
 * F04-T1/T2: Client leave impact analysis until backend ships.
 */
import moment from "moment";
import {
  getLeaveTypeLabel,
  parseLeaveDate,
  isPendingLeave,
} from "views/hrms/components/leave/leave.utils";

const LWP_CODES = new Set(["UL", "LWP", "UNPAID"]);

export function isLwpLeaveType(code) {
  if (!code) return false;
  return LWP_CODES.has(String(code).toUpperCase());
}

function leaveDateRange(leave) {
  const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
  const to = parseLeaveDate(leave.applicationToDate || leave.application_to_date);
  if (!from || !to) return null;
  return { from: from.clone().startOf("day"), to: to.clone().endOf("day") };
}

function rangesOverlap(a, b) {
  if (!a || !b) return false;
  return a.from.isSameOrBefore(b.to) && b.from.isSameOrBefore(a.to);
}

function countTeamMembersOnLeave(calendarLeaves, range, excludeEmployeeId) {
  const seen = new Set();
  (calendarLeaves || []).forEach((leave) => {
    const employeeId = leave.employeeId || leave.employee_id;
    if (excludeEmployeeId && String(employeeId) === String(excludeEmployeeId)) return;
    const leaveRange = leaveDateRange(leave);
    if (leaveRange && rangesOverlap(leaveRange, range)) {
      seen.add(String(employeeId));
    }
  });
  return seen.size;
}

function suggestBackupResources(employees, leave, calendarLeaves) {
  const range = leaveDateRange(leave);
  const requesterId = leave.employeeId || leave.employee_id;
  const requester =
    (employees || []).find((emp) => String(emp.id) === String(requesterId)) || null;
  const teamId =
    requester &&
    requester.defaultUserTeamDetails &&
    requester.defaultUserTeamDetails.id;

  const candidates = (employees || []).filter((emp) => {
    if (String(emp.id) === String(requesterId)) return false;
    if (teamId && emp.defaultUserTeamDetails && String(emp.defaultUserTeamDetails.id) !== String(teamId)) {
      return false;
    }
    if (!range) return true;
    const onLeave = (calendarLeaves || []).some((calLeave) => {
      const eid = calLeave.employeeId || calLeave.employee_id;
      if (String(eid) !== String(emp.id)) return false;
      return rangesOverlap(leaveDateRange(calLeave), range);
    });
    return !onLeave;
  });

  return candidates.slice(0, 3).map((emp) => ({
    employeeId: emp.id,
    name: emp.name || `${emp.firstName || ""} ${emp.lastName || ""}`.trim(),
    role: (emp.userAccessDetails && emp.userAccessDetails.name) || "Team member",
    reason: "Available during requested dates",
  }));
}

export function buildLeaveImpactAnalysis(leave, context) {
  if (!leave) {
    return null;
  }

  const employees = (context && context.employees) || [];
  const calendarLeaves = (context && context.calendarLeaves) || [];
  const teamSize = Math.max(1, employees.length || 1);
  const range = leaveDateRange(leave);
  const employeeId = leave.employeeId || leave.employee_id;
  const overlapping = (calendarLeaves || []).filter((other) => {
    const otherId = other.employeeId || other.employee_id;
    if (String(otherId) === String(employeeId)) return false;
    return rangesOverlap(range, leaveDateRange(other));
  });

  const onLeaveCount = countTeamMembersOnLeave(calendarLeaves, range, employeeId);
  const coveragePct = Math.round(((teamSize - onLeaveCount - 1) / teamSize) * 100);
  const clampedCoverage = Math.max(0, Math.min(100, coveragePct));

  let riskLevel = "LOW";
  if (clampedCoverage < 40 || overlapping.length >= 2) {
    riskLevel = "HIGH";
  } else if (clampedCoverage < 65 || overlapping.length >= 1) {
    riskLevel = "MEDIUM";
  }

  const days = parseFloat(leave.numberOfDays || leave.number_of_days) || 1;
  const leaveTypeCode = leave.leaveTypeCode || leave.leave_type_code;

  return {
    leaveId: leave.id,
    employeeName: leave.employeeName || "Employee",
    leaveTypeLabel: getLeaveTypeLabel(leaveTypeCode, leave.leaveTypeDescription),
    dateRangeLabel:
      range && range.from.isValid()
        ? `${range.from.format("D MMM")} – ${range.to.format("D MMM YYYY")}`
        : "—",
    days,
    riskLevel,
    teamCoveragePct: clampedCoverage,
    overlappingLeaveCount: overlapping.length,
    lwpExposure: isLwpLeaveType(leaveTypeCode),
    deliveryImpactHint:
      riskLevel === "HIGH"
        ? "Multiple team members may be unavailable — review project commitments."
        : riskLevel === "MEDIUM"
          ? "Monitor delivery milestones during this window."
          : "Low delivery risk based on current team calendar.",
    backupSuggestions: suggestBackupResources(employees, leave, calendarLeaves),
    overlappingLeaves: overlapping.slice(0, 5).map((item) => ({
      employeeName: item.employeeName || "Team member",
      dateRange:
        leaveDateRange(item) && leaveDateRange(item).from.isValid()
          ? `${leaveDateRange(item).from.format("D MMM")} – ${leaveDateRange(item).to.format("D MMM")}`
          : "—",
      leaveType: getLeaveTypeLabel(item.leaveTypeCode || item.leave_type_code, item.leaveTypeDescription),
    })),
  };
}

export function buildTeamCoverageSummary(calendarLeaves, employees, monthDate) {
  const month = moment(monthDate || new Date()).startOf("month");
  const daysInMonth = month.daysInMonth();
  const teamSize = Math.max(1, (employees || []).length);
  const daily = [];

  for (let day = 1; day <= daysInMonth; day += 1) {
    const date = month.clone().date(day);
    const onLeave = new Set();
    (calendarLeaves || []).forEach((leave) => {
      const range = leaveDateRange(leave);
      if (range && date.isBetween(range.from, range.to, "day", "[]")) {
        onLeave.add(String(leave.employeeId || leave.employee_id));
      }
    });
    const available = Math.max(0, teamSize - onLeave.size);
    const coveragePct = Math.round((available / teamSize) * 100);
    daily.push({
      date: date.format("YYYY-MM-DD"),
      label: date.format("D"),
      onLeaveCount: onLeave.size,
      coveragePct,
      riskLevel: coveragePct < 40 ? "HIGH" : coveragePct < 65 ? "MEDIUM" : "LOW",
    });
  }

  const riskyDays = daily.filter((row) => row.riskLevel !== "LOW").length;
  return {
    monthLabel: month.format("MMMM YYYY"),
    teamSize,
    riskyDays,
    daily,
  };
}

export function buildImpactRecommendationDraft(impact) {
  if (!impact) {
    return null;
  }
  const backups =
    impact.backupSuggestions && impact.backupSuggestions.length > 0
      ? impact.backupSuggestions.map((b) => b.name).join(", ")
      : "No backup candidates identified";

  return {
    draftOnly: true,
    summary: `Leave impact is ${impact.riskLevel.toLowerCase()} with ${impact.teamCoveragePct}% team coverage.`,
    recommendation: `Consider approving with backup coverage from ${backups}. ${impact.deliveryImpactHint}`,
    confidence: impact.riskLevel === "LOW" ? 0.82 : impact.riskLevel === "MEDIUM" ? 0.71 : 0.63,
    disclaimer: "Draft recommendation — human approval required. Connected AI agents will be available in a future release.",
  };
}

export function filterPendingForImpact(pendingLeaves) {
  return (pendingLeaves || []).filter((leave) => isPendingLeave(leave));
}
