/**
 * EH16 — Client-side metrics, filters, and export for TaskModel-derived delivery sprints.
 * Source of truth remains TaskModel via GET /api/v2/delivery/sprints (no sprint truth table).
 */

export const DELIVERY_STATUS_SCOPES = [
  { id: "ALL", label: "All" },
  { id: "OPEN", label: "Open" },
  { id: "DONE", label: "Done" },
  { id: "OVERDUE", label: "Overdue" },
];

export const DELIVERY_VIEW_MODES = [
  { id: "board", label: "Board", icon: "fe-columns" },
  { id: "list", label: "Register", icon: "fe-list" },
  { id: "pulse", label: "Pulse", icon: "fe-activity" },
];

export const ASSIGNABLE_BUCKETS = [
  { id: "backlog", label: "Backlog" },
  { id: "active", label: "Active sprint" },
  { id: "closed", label: "Closed / done" },
  { id: "unscheduled", label: "Unscheduled" },
];

export function isDeliveryTaskClosed(status) {
  const normalized = String(status || "").toUpperCase();
  return normalized === "COMPLETED" || normalized === "CLOSED";
}

export function parseDeliveryDate(value) {
  if (!value) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

export function isDeliveryTaskOverdue(task, now = new Date()) {
  if (!task || isDeliveryTaskClosed(task.status)) return false;
  const end = parseDeliveryDate(task.estCompletionTime);
  return !!(end && end.getTime() < now.getTime());
}

export function flattenDeliveryTasks(overview) {
  const sprints = (overview && overview.sprints) || [];
  return sprints.flatMap((sprint) =>
    (sprint.tasks || []).map((task) => ({
      ...task,
      sprintId: task.sprintId || sprint.sprintId,
      sprintLabel: task.sprintLabel || sprint.sprintLabel,
    }))
  );
}

export function buildDeliveryMetrics(overview, now = new Date()) {
  const tasks = flattenDeliveryTasks(overview);
  const open = tasks.filter((task) => !isDeliveryTaskClosed(task.status)).length;
  const done = tasks.length - open;
  const overdue = tasks.filter((task) => isDeliveryTaskOverdue(task, now)).length;
  const sprints = (overview && overview.sprints) || [];
  const active = sprints.find((sprint) => sprint.sprintId === "active");
  const backlog = sprints.find((sprint) => sprint.sprintId === "backlog");
  const completionPct = tasks.length ? Math.round((done / tasks.length) * 100) : 0;

  return {
    taskCount: tasks.length,
    openCount: open,
    doneCount: done,
    overdueCount: overdue,
    sprintCount: (overview && overview.sprintCount) != null ? overview.sprintCount : sprints.length,
    activeCount: (active && active.taskCount) || 0,
    backlogCount: (backlog && backlog.taskCount) || 0,
    completionPct,
  };
}

export function buildDeliveryKpiCards(metrics) {
  const m = metrics || {};
  const taskCount = m.taskCount != null ? m.taskCount : 0;
  const openCount = m.openCount != null ? m.openCount : 0;
  const doneCount = m.doneCount != null ? m.doneCount : 0;
  const overdueCount = m.overdueCount != null ? m.overdueCount : 0;
  const activeCount = m.activeCount != null ? m.activeCount : 0;
  const backlogCount = m.backlogCount != null ? m.backlogCount : 0;
  const completionPct = m.completionPct != null ? m.completionPct : 0;
  return [
    {
      id: "deliverables",
      label: "Deliverables",
      value: taskCount,
      icon: "fe fe-check-square",
      tone: "indigo",
      hint: "Team tasks in derived buckets",
    },
    {
      id: "open",
      label: "Open",
      value: openCount,
      icon: "fe fe-circle",
      tone: "amber",
      hint: "Not completed or closed",
    },
    {
      id: "done",
      label: "Done",
      value: doneCount,
      icon: "fe fe-check-circle",
      tone: "green",
      hint: `${completionPct}% complete`,
    },
    {
      id: "overdue",
      label: "Overdue",
      value: overdueCount,
      icon: "fe fe-alert-triangle",
      tone: overdueCount ? "rose" : "slate",
      hint: "Past est. completion",
    },
    {
      id: "active",
      label: "Active sprint",
      value: activeCount,
      icon: "fe fe-zap",
      tone: "blue",
      hint: "In-progress bucket",
    },
    {
      id: "backlog",
      label: "Backlog",
      value: backlogCount,
      icon: "fe fe-inbox",
      tone: "violet",
      hint: "Unscheduled pipeline",
    },
  ];
}

export function buildDeliveryInsights(metrics, overview) {
  const m = metrics || {};
  const insights = [];
  const sprints = (overview && overview.sprints) || [];

  if (m.overdueCount > 0) {
    insights.push({
      id: "overdue",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${m.overdueCount} overdue deliverable${m.overdueCount === 1 ? "" : "s"}`,
      copy: "Filter to Overdue and re-bucket or update dates from the task board.",
      path: "/project/taskboard",
    });
  }

  if (m.backlogCount > 0 && m.activeCount === 0 && m.openCount > 0) {
    insights.push({
      id: "empty-active",
      tone: "amber",
      icon: "fe fe-zap",
      title: "Active sprint is empty",
      copy: `Move work from ${m.backlogCount} backlog item${m.backlogCount === 1 ? "" : "s"} into Active to focus delivery.`,
    });
  }

  if (m.completionPct >= 70 && m.openCount > 0) {
    insights.push({
      id: "closing-in",
      tone: "green",
      icon: "fe fe-trending-up",
      title: `${m.completionPct}% complete`,
      copy: "Most deliverables are done — clear the remaining open items or close the week bucket.",
    });
  }

  if (!m.taskCount) {
    insights.push({
      id: "empty",
      tone: "slate",
      icon: "fe fe-layers",
      title: "No deliverables derived yet",
      copy: "Create dated project tasks for this team to populate backlog, active, and week buckets.",
      path: "/project/list",
    });
  } else if (sprints.length === 1) {
    insights.push({
      id: "single-bucket",
      tone: "blue",
      icon: "fe fe-info",
      title: "Single sprint bucket",
      copy: "Assign sprint buckets or date tasks so derived ISO-week sprints appear alongside backlog/active.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check",
      title: "Delivery buckets look healthy",
      copy: `${m.sprintCount} bucket${m.sprintCount === 1 ? "" : "s"} · ${m.openCount} open · open the task board for day-to-day moves.`,
      path: "/project/taskboard",
    });
  }

  return insights.slice(0, 3);
}

