export function buildBucketOptions(sprints) {
  const fromApi = (sprints || []).map((sprint) => ({
    id: sprint.sprintId,
    label: sprint.sprintLabel || sprint.sprintId,
  }));
  const seen = new Set();
  return [...ASSIGNABLE_BUCKETS, ...fromApi].filter((bucket) => {
    if (!bucket.id || seen.has(bucket.id)) return false;
    seen.add(bucket.id);
    return true;
  });
}

export function buildProjectOptions(tasks) {
  const map = new Map();
  (tasks || []).forEach((task) => {
    if (task.projectId == null) return;
    const id = String(task.projectId);
    if (!map.has(id)) {
      map.set(id, {
        id,
        label: task.projectName || `Project ${id}`,
      });
    }
  });
  return Array.from(map.values()).sort((a, b) => a.label.localeCompare(b.label));
}

export function filterDeliveryTasks(tasks, filters = {}, now = new Date()) {
  const query = String(filters.query || "")
    .trim()
    .toLowerCase();
  const statusScope = filters.statusScope || "ALL";
  const projectId = filters.projectId ? String(filters.projectId) : "";
  const sprintId = filters.sprintId ? String(filters.sprintId) : "";
  const priority = filters.priority ? String(filters.priority).toUpperCase() : "";

  return (tasks || []).filter((task) => {
    if (projectId && String(task.projectId) !== projectId) return false;
    if (sprintId && String(task.sprintId) !== sprintId) return false;
    if (priority && String(task.priority || "").toUpperCase() !== priority) return false;

    if (statusScope === "OPEN" && isDeliveryTaskClosed(task.status)) return false;
    if (statusScope === "DONE" && !isDeliveryTaskClosed(task.status)) return false;
    if (statusScope === "OVERDUE" && !isDeliveryTaskOverdue(task, now)) return false;

    if (!query) return true;
    const haystack = [
      task.name,
      task.projectName,
      task.status,
      task.sprintLabel,
      task.sprintId,
      task.priority,
      task.taskCategory,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(query);
  });
}

export function groupTasksBySprint(tasks, sprints) {
  const order = (sprints || []).map((sprint) => sprint.sprintId);
  const byId = new Map();
  (sprints || []).forEach((sprint) => {
    byId.set(sprint.sprintId, {
      ...sprint,
      tasks: [],
      openCount: 0,
      doneCount: 0,
      taskCount: 0,
    });
  });

  (tasks || []).forEach((task) => {
    const sprintId = task.sprintId || "unscheduled";
    if (!byId.has(sprintId)) {
      byId.set(sprintId, {
        sprintId,
        sprintLabel: task.sprintLabel || sprintId,
        tasks: [],
        openCount: 0,
        doneCount: 0,
        taskCount: 0,
      });
      order.push(sprintId);
    }
    const bucket = byId.get(sprintId);
    bucket.tasks.push(task);
    bucket.taskCount += 1;
    if (isDeliveryTaskClosed(task.status)) bucket.doneCount += 1;
    else bucket.openCount += 1;
  });

  return order.filter((id) => byId.has(id) && byId.get(id).taskCount > 0).map((id) => byId.get(id));
}

export function sprintProgressPct(sprint) {
  const total = (sprint && sprint.taskCount) || 0;
  if (!total) return 0;
  return Math.round((((sprint && sprint.doneCount) || 0) / total) * 100);
}

export function buildDeliveryPulseRows(sprints) {
  return (sprints || []).map((sprint) => {
    const total = sprint.taskCount || 0;
    const done = sprint.doneCount || 0;
    const open = sprint.openCount != null ? sprint.openCount : Math.max(0, total - done);
    return {
      sprintId: sprint.sprintId,
      sprintLabel: sprint.sprintLabel || sprint.sprintId,
      total,
      open,
      done,
      donePct: total ? Math.round((done / total) * 100) : 0,
      openPct: total ? Math.round((open / total) * 100) : 0,
    };
  });
}

export function formatDeliveryDateLabel(value) {
  const date = parseDeliveryDate(value);
  if (!date) return "—";
  return date.toLocaleDateString(undefined, {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export function statusTone(status) {
  const normalized = String(status || "").toUpperCase();
  if (normalized === "COMPLETED" || normalized === "CLOSED") return "green";
  if (normalized === "INPROGRESS") return "blue";
  if (normalized === "ASSIGNED") return "amber";
  return "slate";
}

export function priorityTone(priority) {
  const normalized = String(priority || "").toUpperCase();
  if (normalized === "URGENT") return "rose";
  if (normalized === "HIGH") return "amber";
  if (normalized === "MEDIUM") return "blue";
  if (normalized === "LOW") return "slate";
  return "slate";
}

function csvEscape(value) {
  const text = value == null ? "" : String(value);
  if (/[",\n]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

export function buildDeliveryExportCsv(tasks) {
  const header = [
    "id",
    "name",
    "status",
    "priority",
    "projectId",
    "projectName",
    "sprintId",
    "sprintLabel",
    "estStartTime",
    "estCompletionTime",
    "taskCategory",
  ];
  const lines = [header.join(",")];
  (tasks || []).forEach((task) => {
    lines.push(
      [
        task.id,
        task.name,
        task.status,
        task.priority,
        task.projectId,
        task.projectName,
        task.sprintId,
        task.sprintLabel,
        task.estStartTime,
        task.estCompletionTime,
        task.taskCategory,
      ]
        .map(csvEscape)
        .join(",")
    );
  });
  return lines.join("\n");
}

export function downloadDeliveryCsv(tasks, filename = "delivery-sprints.csv") {
  if (typeof document === "undefined") return;
  const blob = new Blob([buildDeliveryExportCsv(tasks)], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  URL.revokeObjectURL(url);
}
