/** F19 — Ticket and service management (live API only; no mock/demo). */

export function isTicketManagementEnabled() {
  return shouldUseTicketManagement();
}

export function shouldUseTicketManagementApi() {
  return envconfig.USE_TICKET_MANAGEMENT_API !== false;
}

