/**
 * F13-T8 — Staffing intelligence recommendations (F17 gateway stub).
 */
import envconfig from "env.config";
import { isResourcePlanningEnabled } from "config/resource-planning.config";

export function isStaffingAiEnabled() {
  if (!isResourcePlanningEnabled()) {
    return false;
  }
  // RES-003 — require explicit staffing AI flag (fail-closed; do not inherit RP-only).
  return envconfig.STAFFING_AI_ENABLED === true;
}

export function shouldUseStaffingAiApi() {
  return envconfig.USE_STAFFING_AI_API === true && isStaffingAiEnabled();
}

export function normalizeStaffingAiBrief(row) {
  if (!row) {
    return null;
  }
  return {
    requestId: row.requestId || null,
    headline: row.headline || "",
    summary: row.summary || "",
    recommendation: row.recommendation || "",
    confidence: row.confidence != null ? row.confidence : 0,
    nextBestAction: row.nextBestAction || "",
    evidence: Array.isArray(row.evidence) ? row.evidence : [],
    candidates: (row.candidates || []).map((candidate) => ({
      id: candidate.id,
      employeeId: candidate.employeeId,
      employeeName: candidate.employeeName,
      role: candidate.role || "",
      matchScore: candidate.matchScore != null ? candidate.matchScore : 0,
      availabilityPct: candidate.availabilityPct != null ? candidate.availabilityPct : 0,
      benchStatus: candidate.benchStatus || "",
      rationale: candidate.rationale || "",
      matchedSkills: candidate.matchedSkills || [],
      tone: candidate.tone || "primary",
    })),
    disclaimer:
      row.disclaimer ||
      "Draft — staffing matches are rule-based today. Live AI integration will enrich recommendations without auto-assigning people.",
    source: row.source || "client",
  };
}
