import dateUtils from "_helpers/date.utils";
import { sumTaskStat } from "./projectDetailsTab.utils";

export function getDeliverableOverviewStats(item, workItemStatisticsByCategory) {
  const items = workItemStatisticsByCategory || [];
  const total =
    sumTaskStat(items, "completedCount") +
    sumTaskStat(items, "inProgressCount") +
    sumTaskStat(items, "assignedCount") +
    sumTaskStat(items, "newCount");

  const statusLabel = (item && item.status) || "—";
  const due =
    item && item.estCompletionTime
      ? dateUtils.convertDateFormat(item.estCompletionTime)
      : "—";

  return [
    {
      key: "status",
      label: "Status",
      value: statusLabel.replace(/_/g, " "),
      hint: "Deliverable lifecycle",
      tone: item && item.status === "COMPLETED" ? "green" : "amber",
    },
    {
      key: "due",
      label: "Due date",
      value: due,
      hint: "Estimated completion",
      tone: "slate",
    },
    {
      key: "workitems",
      label: "Work items",
      value: total || "—",
      hint: "Linked activities",
      tone: total > 0 ? "green" : "slate",
    },
    {
      key: "completed",
      label: "Completed",
      value: sumTaskStat(items, "completedCount"),
      hint: "Done on this deliverable",
      tone: "green",
    },
  ];
}

export function getDeliverableBreadcrumbLabel(item) {
  if (!item) return null;
  const ref = item.itemIdUserTeamPrefix || item.id;
  const name = item.name || "Deliverable";
  return item.code ? `${name} · ${item.code}` : `${ref} — ${name}`;
}
