import { Component } from "react";
import { withRouter } from "react-router-dom";
import {
  captureProjectDetailsReturn,
  isProjectDetailsPath,
} from "views/project/projectDetailsNavigation.utils";

/**
 * Remembers the in-app route visited immediately before opening full project details.
 */
class ProjectDetailsReturnTracker extends Component {
  componentDidUpdate(prevProps) {
    const { location } = this.props;
    const prev = prevProps.location;
    if (!location || !prev) return;

    const entering =
      isProjectDetailsPath(location.pathname) &&
      !isProjectDetailsPath(prev.pathname);

    if (entering) {
      captureProjectDetailsReturn(prev.pathname, prev.search);
    }
  }

  render() {
    return null;
  }
}

export default withRouter(ProjectDetailsReturnTracker);
