export const PO_STATUS_META = {
  NEW: { label: "New", tone: "sky" },
  CREATED: { label: "Created", tone: "indigo" },
  ASSIGNED: { label: "Assigned", tone: "indigo" },
  INPROGRESS: { label: "In progress", tone: "amber" },
  COMPLETED: { label: "Completed", tone: "green" },
  CLOSED: { label: "Closed", tone: "slate" },
};

export const PO_STATUS_OPTIONS = [
  { value: "NEW", label: "New" },
  { value: "CREATED", label: "Created" },
  { value: "ASSIGNED", label: "Assigned" },
  { value: "INPROGRESS", label: "In progress" },
  { value: "COMPLETED", label: "Completed" },
  { value: "CLOSED", label: "Closed" },
];

export function normalizePoStatus(status) {
  if (status == null || status === "") return "NEW";
  const key = String(status).trim().toUpperCase().replace(/[\s_\-]+/g, "");
  if (key === "INPROGRESS" || key === "IN_PROGRESS") return "INPROGRESS";
  return key;
}

export function getPoStatusMeta(status) {
  const key = normalizePoStatus(status);
  return PO_STATUS_META[key] || { label: status || "—", tone: "slate" };
}

export function getPoStatusSelectValue(status) {
  return normalizePoStatus(status) === "INPROGRESS" ? "INPROGRESS" : status;
}

const PROJECT_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

const PROJECT_TYPE_TONES = {
  ADHOC: "indigo",
  FTEMS: "violet",
  FTESA: "sky",
  SERVICES: "amber",
  PRODUCT: "teal",
  TRACKER: "green",
  TMHB: "slate",
};

export function getPoProjectTypeMeta(projectType) {
  if (!projectType) return null;
  const key = String(projectType).trim().toUpperCase();
  return {
    label: PROJECT_TYPE_LABELS[key] || projectType,
    tone: PROJECT_TYPE_TONES[key] || "slate",
  };
}

export function formatPoClientLine(item) {
  const parts = [];
  if (item.teamName) parts.push(item.teamName);
  if (item.clientNames && item.clientNames.length) {
    parts.push(
      Array.isArray(item.clientNames) ? item.clientNames.join(", ") : item.clientNames
    );
  }
  return parts.length ? parts.join(" · ") : null;
}
