import React, { Component } from "react";
import { createPortal } from "react-dom";
import { LEGACY_CONNECTION_LABELS } from "config/integrations-connections.config";
import { IntegrationActionButton } from "views/integrations/components/IntegrationsLuxShared";

function ConfigField({ field, value, onChange }) {
  const type = field.type || "text";
  if (type === "boolean") {
    return (
      <label className="lux-int-config-field lux-int-config-field--checkbox">
        <input
          type="checkbox"
          checked={value === true}
          onChange={(e) => onChange(field.key, e.target.checked)}
        />
        <span>{field.label}</span>
      </label>
    );
  }
  return (
    <label className="lux-int-config-field">
      <span>{field.label}{field.required ? " *" : ""}</span>
      <input
        type={type === "number" ? "number" : "text"}
        value={value == null ? "" : value}
        onChange={(e) => onChange(field.key, type === "number" ? Number(e.target.value) : e.target.value)}
      />
    </label>
  );
}

export default class IntegrationConnectionConfigDrawer extends Component {
  state = {
    config: {},
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open && this.props.connection) {
      this.setState({
        config: { ...(this.props.connection.config || {}) },
        saving: false,
        error: null,
      });
    }
  }

  handleChange = (key, value) => {
    this.setState((prev) => ({
      config: { ...prev.config, [key]: value },
    }));
  };

  handleSave = async () => {
    const { connection, onSave } = this.props;
    const { config } = this.state;
    if (!connection || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(connection.legacyKey, {
        enabled: connection.integrationCenterEnabled !== false,
        config,
      });
      if (this.props.onSaved) {
        this.props.onSaved();
      }
      if (this.props.onClose) {
        this.props.onClose();
      }
    } catch (error) {
      this.setState({
        saving: false,
        error: (error && error.message) || "Unable to save configuration.",
      });
    }
  };

  render() {
    const { open, onClose, connection } = this.props;
    const { config, saving, error } = this.state;
    if (!open || !connection) {
      return null;
    }
    const title = LEGACY_CONNECTION_LABELS[connection.legacyKey] || connection.name;
    const runtime = connection.runtimeConfig || {};
    const fields = connection.configFields || [];

    return createPortal(
      <div className="lux-dev-drawer-backdrop" role="presentation" onClick={onClose}>
        <aside
          className="lux-dev-drawer lux-dev-drawer--blue"
          role="dialog"
          aria-modal="true"
          onClick={(e) => e.stopPropagation()}
        >
          <header className="lux-dev-drawer__head">
            <div className="lux-dev-drawer__head-copy">
              <span className="lux-dev-drawer__eyebrow">Configure connection</span>
              <h2>{title}</h2>
            </div>
            <button type="button" className="lux-dev-drawer__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" />
            </button>
          </header>
          <div className="lux-dev-drawer__body">
            {error ? <p className="lux-integ-error">{error}</p> : null}
            <p className="lux-int-connection-intro">
              Settings saved here apply to the Integrations section. Legacy server environment variables
              and existing sync flows are not modified.
            </p>
            {runtime.serverConfigured ? (
              <p className="lux-int-connection-card__note">
                Server runtime: configured
                {runtime.passwordConfigured || runtime.tokenConfigured || runtime.clientSecretConfigured
                  ? " (credentials present on server)"
                  : ""}
              </p>
            ) : (
              <p className="lux-int-connection-card__note">
                Server runtime: not fully configured — set env vars or fill integration settings below.
              </p>
            )}
            <div className="lux-int-config-grid">
              {fields.map((field) => (
                <ConfigField
                  key={field.key}
                  field={field}
                  value={config[field.key]}
                  onChange={this.handleChange}
                />
              ))}
            </div>
          </div>
          <footer className="lux-dev-drawer__footer">
            <IntegrationActionButton onClick={onClose}>Cancel</IntegrationActionButton>
            <IntegrationActionButton variant="primary" onClick={this.handleSave} disabled={saving}>
              {saving ? "Saving…" : "Save configuration"}
            </IntegrationActionButton>
          </footer>
        </aside>
      </div>,
      document.body
    );
  }
}
