import React, { Component } from "react";
import classNames from "classnames/bind";
import {
  formatLeaveDateRange,
  formatLeaveDays,
  getLeaveTypeLabel,
  summarizePendingLeaves,
} from "./leave.utils";
import LeaveApprovalCommentField from "./LeaveApprovalCommentField";
import ApprovalActingForBadge from "../delegation/ApprovalActingForBadge";
import { getPendingInboxEyebrow } from "_helpers/approvalAuthority.utils";

class LeavePendingApprovals extends Component {
  constructor(props) {
    super(props);
    this.state = { comments: {}, rejectErrors: {}, collapsed: false };
  }

  getComment = (leaveId) => this.state.comments[leaveId] || "";

  setComment = (leaveId, value) => {
    this.setState((prev) => ({
      comments: { ...prev.comments, [leaveId]: value },
      rejectErrors: value.trim() ? {} : prev.rejectErrors,
    }));
  };

  toggleCollapsed = () => {
    this.setState((prev) => ({ collapsed: !prev.collapsed }));
  };

  handleApprove = (leave) => {
    const { onApprove, isLoading } = this.props;
    if (isLoading || !onApprove) return;
    onApprove(leave, this.getComment(leave.id).trim() || null);
  };

  handleReject = (leave) => {
    const { onReject, isLoading } = this.props;
    if (isLoading || !onReject) return;
    const comment = this.getComment(leave.id).trim();
    if (!comment) {
      this.setState({
        rejectErrors: {
          [leave.id]: "Add a rejection comment before rejecting.",
        },
      });
      return;
    }
    this.setState({ rejectErrors: { [leave.id]: null } });
    onReject(leave, comment);
  };

  renderCollapsedSummary = (summary) => (
    <button
      type="button"
      className="lux-leave-pending__collapsed-bar"
      onClick={this.toggleCollapsed}
      aria-expanded="false"
      aria-label={`${summary.total} pending leave requests. Click to expand.`}
    >
      <span className="lux-leave-pending__collapsed-icon" aria-hidden="true">
        <i className="fe fe-sun" />
      </span>
      <span className="lux-leave-pending__collapsed-copy">
        <strong>
          {summary.total} pending leave request{summary.total === 1 ? "" : "s"} need your review
        </strong>
        <em>
          {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
        </em>
      </span>
      <span className="lux-leave-pending__count">{summary.total}</span>
      <span className="lux-leave-pending__collapsed-expand">
        Expand
        <i className="fe fe-chevron-down" aria-hidden="true" />
      </span>
    </button>
  );

  render() {
    const { pending, isLoading, actingDelegations, employees, onViewImpact } = this.props;
    const summary = summarizePendingLeaves(pending);
    const { collapsed } = this.state;
    const eyebrow = getPendingInboxEyebrow(pending);

    if (!summary.total) return null;

    if (collapsed) {
      return (
        <section className="lux-leave-pending lux-leave-pending--collapsed" aria-label="Pending leave approvals">
          {this.renderCollapsedSummary(summary)}
        </section>
      );
    }

    return (
      <section className="lux-leave-pending" aria-label="Pending leave approvals">
        <header className="lux-leave-pending__head">
          <div>
            {eyebrow && <span className="lux-leave-pending__eyebrow">{eyebrow}</span>}
            <h3>Pending approvals</h3>
            <p>
              {summary.total} request{summary.total === 1 ? "" : "s"} across{" "}
              {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
            </p>
          </div>
          <div className="lux-leave-pending__head-actions">
            <span className="lux-leave-pending__count">{summary.total}</span>
            <button
              type="button"
              className="lux-leave-pending__toggle"
              onClick={this.toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse pending leave approvals"
            >
              Collapse
            </button>
          </div>
        </header>

        <div className="lux-leave-pending__list">
          {summary.groups.map((group) => (
            <div key={group.employeeId} className="lux-leave-pending__group">
              <h4 className="lux-leave-pending__employee">
                <span>{group.employeeName}</span>
                <ApprovalActingForBadge
                  record={group.items && group.items[0]}
                  actingDelegations={actingDelegations}
                  employees={employees}
                />
              </h4>
              {group.items.map((leave) => (
                <article key={leave.id} className="lux-leave-pending__card">
                  <div className="lux-leave-pending__card-head">
                    <div className="lux-leave-pending__card-main">
                      <strong>{getLeaveTypeLabel(leave.leaveTypeCode, leave.leaveTypeDescription)}</strong>
                      <span>
                        {formatLeaveDateRange(leave)} · {formatLeaveDays(leave)}
                      </span>
                      <em>{leave.reason || "No reason provided"}</em>
                    </div>
                  </div>
                  <LeaveApprovalCommentField
                    value={this.getComment(leave.id)}
                    onChange={(v) => this.setComment(leave.id, v)}
                    placeholder="Required for rejection · optional for approval"
                    error={this.state.rejectErrors[leave.id]}
                  />
                  <div className="lux-leave-pending__actions">
                    {onViewImpact && (
                      <button
                        type="button"
                        className="lux-leave-pending__btn is-ghost"
                        disabled={isLoading}
                        onClick={() => onViewImpact(leave)}
                      >
                        View impact
                      </button>
                    )}
                    <button
                      type="button"
                      className="lux-leave-pending__btn is-primary"
                      disabled={isLoading}
                      onClick={() => this.handleApprove(leave)}
                    >
                      Approve
                    </button>
                    <button
                      type="button"
                      className="lux-leave-pending__btn is-danger"
                      disabled={isLoading}
                      onClick={() => this.handleReject(leave)}
                    >
                      Reject
                    </button>
                  </div>
                </article>
              ))}
            </div>
          ))}
        </div>
      </section>
    );
  }
}

export default LeavePendingApprovals;
