import React, { Component } from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import LuxFeedbackRecipientsEmptyState from "./LuxFeedbackRecipientsEmptyState";
import { getRecipientInitials } from "./feedback.utils";

function recipientDomain(email) {
  const parts = String(email || "").split("@");
  return parts.length > 1 ? parts[1] : "";
}

export default class LuxFeedbackRecipientEmailPanel extends Component {
  constructor() {
    super();
    this.state = {
      draft: {},
      showAddForm: false,
    };
  }

  toggleAddForm = (show) => {
    this.setState({
      showAddForm: show,
      draft: show ? this.state.draft : {},
    });
  };

  onDraftChange = (name, value) => {
    this.setState({
      draft: { ...this.state.draft, [name]: value },
    });
  };

  onAdd = () => {
    const { draft } = this.state;
    const list = this.props.recipients || [];
    if (!draft.personEmail) return;

    this.props.onChange("feedbackRequestInfos", [
      ...list,
      {
        personName: draft.personName || "",
        personEmail: draft.personEmail,
      },
    ]);
    this.setState({ draft: {}, showAddForm: false });
  };

  onRemove = (email) => {
    const list = this.props.recipients || [];
    this.props.onChange(
      "feedbackRequestInfos",
      list.filter((r) => r.personEmail !== email)
    );
  };

  render() {
    const recipients = this.props.recipients || [];
    const isEmpty = recipients.length === 0;
    const { showAddForm, draft } = this.state;

    return (
      <section
        className={classNames("lux-fb-recipients", {
          "is-empty": isEmpty,
          "has-recipients": !isEmpty,
        })}
        aria-labelledby="lux-fb-recipients-title"
      >
        <header className="lux-fb-recipients__head">
          <div className="lux-fb-recipients__head-icon" aria-hidden="true">
            <i className="fe fe-users" />
          </div>
          <div className="lux-fb-recipients__head-copy">
            <h4 id="lux-fb-recipients-title">Recipients</h4>
            <p>
              {isEmpty
                ? "People who will receive the feedback request email."
                : `${recipients.length} recipient${recipients.length === 1 ? "" : "s"} ready to receive this request.`}
            </p>
          </div>
          <span className={classNames("lux-fb-recipients__count", { "is-filled": !isEmpty })}>
            {recipients.length}
          </span>
        </header>

        {!isEmpty && (
          <div className="lux-fb-recipients__summary" aria-hidden="true">
            <span className="lux-fb-recipients__summary-pill is-ready">
              <i className="fe fe-check-circle" />
              Ready to send
            </span>
            <span className="lux-fb-recipients__summary-pill">
              <i className="fe fe-mail" />
              {recipients.length} inbox{recipients.length === 1 ? "" : "es"}
            </span>
          </div>
        )}

        <div className="lux-fb-recipients__body">
          <div
            className={classNames("lux-fb-recipients__list-wrap", {
              "has-error": isEmpty,
              "is-filled": !isEmpty,
            })}
          >
            {isEmpty ? (
              <LuxFeedbackRecipientsEmptyState />
            ) : (
              <ul className="lux-fb-recipients__list" role="list">
                {recipients.map((row, index) => {
                  const domain = recipientDomain(row.personEmail);
                  const initials = getRecipientInitials(row.personName, row.personEmail);
                  return (
                    <li
                      key={row.personEmail || index}
                      className={classNames(
                        "lux-fb-recipients__row",
                        `is-tone-${(index % 5) + 1}`
                      )}
                    >
                      <span className="lux-fb-recipients__avatar" aria-hidden="true">
                        {initials}
                      </span>
                      <div className="lux-fb-recipients__identity">
                        <div className="lux-fb-recipients__name-row">
                          <strong title={row.personName}>
                            {row.personName || "Unnamed recipient"}
                          </strong>
                          <span className="lux-fb-recipients__ready-chip">
                            <i className="fe fe-check" aria-hidden="true" />
                            Added
                          </span>
                        </div>
                        <span className="lux-fb-recipients__email" title={row.personEmail}>
                          {row.personEmail}
                        </span>
                        {domain ? (
                          <span className="lux-fb-recipients__domain">{domain}</span>
                        ) : null}
                      </div>
                      <button
                        type="button"
                        className="lux-fb-recipients__remove"
                        title="Remove recipient"
                        aria-label={`Remove ${row.personEmail}`}
                        onClick={() => this.onRemove(row.personEmail)}
                      >
                        <i className="fe fe-trash-2" aria-hidden="true" />
                      </button>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        </div>

        {!showAddForm && (
          <div className="lux-fb-recipients__footer">
            <button
              type="button"
              className="lux-fb-recipients__add-trigger"
              onClick={() => this.toggleAddForm(true)}
            >
              <i className={isEmpty ? "fe fe-user-plus" : "fe fe-plus"} aria-hidden="true" />
              {isEmpty ? "Add first recipient" : "Add another recipient"}
            </button>
          </div>
        )}

        {showAddForm && (
          <div className="lux-fb-recipients__add-panel">
            <div className="lux-fb-recipients__add-panel-head">
              <span className="lux-fb-recipients__add-title">New recipient</span>
              <span className="lux-fb-recipients__add-hint">Name optional · email required</span>
            </div>
            <div className="lux-fb-recipients__add-fields">
              <CustomInput
                inputtype="text"
                label="Name"
                name="personName"
                fieldConfig={this.props.fieldConfig}
                mappingObject={draft}
                onChange={this.onDraftChange}
                onFormError={() => {}}
                placeholder="Full name"
                datatype="alpnumspl"
              />
              <CustomInput
                inputtype="email"
                label="Email"
                name="personEmail"
                fieldConfig={this.props.fieldConfig}
                mappingObject={draft}
                onChange={this.onDraftChange}
                onFormError={() => {}}
                placeholder="name@company.com"
                datatype="email"
              />
            </div>
            <div className="lux-fb-recipients__add-actions">
              <button
                type="button"
                className="lux-fb-recipients__btn is-primary"
                onClick={this.onAdd}
                disabled={!draft.personEmail}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add recipient
              </button>
              <button
                type="button"
                className="lux-fb-recipients__btn is-ghost"
                onClick={() => this.toggleAddForm(false)}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </section>
    );
  }
}
