import React from "react";
import classNames from "classnames";
import { getPersonaLabel } from "config/persona-navigation.utils";
import { usePersonaContext } from "hooks/usePersonaContext";
import LuxHeaderDropdownPanel, {
  LuxHeaderDropdownItem,
} from "views/common/fragments/LuxHeaderDropdownPanel";

const PERSONA_ICONS = {
  EMPLOYEE: "fe fe-user",
  MANAGER: "fe fe-users",
  PROJECT_MANAGER: "fe fe-layers",
  RESOURCE_MANAGER: "fe fe-pie-chart",
  HR_ADMIN: "fe fe-heart",
  PAYROLL_MANAGER: "fe fe-credit-card",
  FINANCE_MANAGER: "fe fe-briefcase",
  EXECUTIVE: "fe fe-trending-up",
  ADMIN: "fe fe-shield",
};

/**
 * P00-T5: Switch among allowed personas (header chip + dropdown).
 */
function PersonaSwitcher({ className }) {
  const {
    activePersona,
    activePersonaLabel,
    allowedPersonas,
    personaSwitchEnabled,
    switchPersona,
    isLoading,
  } = usePersonaContext();

  const closeDropdown = () => {
    if (typeof document === "undefined") {
      return;
    }
    const root = document.querySelector(".lux-persona-switcher.show");
    if (!root) {
      return;
    }
    root.classList.remove("show");
    const menu = root.querySelector(".dropdown-menu");
    if (menu) {
      menu.classList.remove("show");
    }
    const toggle = root.querySelector("[data-toggle='dropdown']");
    if (toggle) {
      toggle.setAttribute("aria-expanded", "false");
    }
  };

  const handleSwitch = async (event, persona) => {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
    const switched = await switchPersona(persona);
    if (switched) {
      closeDropdown();
    }
  };

  if (isLoading || !activePersona) {
    return null;
  }

  if (!allowedPersonas || allowedPersonas.length <= 1 || personaSwitchEnabled === false) {
    return (
      <span
        className={classNames("lux-persona-chip lux-persona-chip--static", className)}
        title={`Viewing as ${activePersonaLabel}`}
      >
        <i className={PERSONA_ICONS[activePersona] || "fe fe-user"} aria-hidden="true" />
        <span>{activePersonaLabel}</span>
      </span>
    );
  }

  return (
    <div className={classNames("dropdown lux-header-dropdown-wrap lux-persona-switcher", className)}>
      <button
        type="button"
        className="lux-persona-chip"
        data-toggle="dropdown"
        aria-haspopup="true"
        aria-expanded="false"
        aria-label={`Acting as ${activePersonaLabel}. Change persona.`}
        data-ga-action="persona_switcher_open"
        data-ga-category="navigation"
        data-ga-label={activePersona}
      >
        <i className={PERSONA_ICONS[activePersona] || "fe fe-user"} aria-hidden="true" />
        <span>{activePersonaLabel}</span>
        <i className="fe fe-chevron-down lux-persona-chip__caret" aria-hidden="true" />
      </button>
      <LuxHeaderDropdownPanel
        icon={PERSONA_ICONS[activePersona] || "fe fe-user"}
        eyebrow="Acting as"
        title={activePersonaLabel}
        subtitle="Switch your workspace view"
        tone="account"
        widthClass="lux-header-dropdown--account"
      >
        <span className="lux-header-dropdown__section-label">Available personas</span>
        {allowedPersonas.map((persona) => (
          <LuxHeaderDropdownItem
            key={persona}
            icon={PERSONA_ICONS[persona] || "fe fe-user"}
            iconTone={persona === activePersona ? "success" : undefined}
            title={getPersonaLabel(persona)}
            hint={persona === activePersona ? "Current view" : "Switch to this view"}
            onClick={(event) => handleSwitch(event, persona)}
            data-ga-action="persona_switch"
            data-ga-category="navigation"
            data-ga-label={persona}
          />
        ))}
      </LuxHeaderDropdownPanel>
    </div>
  );
}

export default PersonaSwitcher;
