import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { buildApprovalAgingBuckets } from "config/approval-analytics.utils";

export default function UniversalApprovalSlaBanner({ items, onReview, active }) {
  const aging = buildApprovalAgingBuckets(items || []);
  if (!aging.overdue && !aging.dueSoon) {
    return null;
  }

  const overdueFirst = aging.overdue > 0;
  const headline = overdueFirst
    ? `${aging.overdue} approval${aging.overdue === 1 ? "" : "s"} past SLA`
    : `${aging.dueSoon} approval${aging.dueSoon === 1 ? "" : "s"} due within 48 hours`;

  return (
    <div className="lux-appr-sla-banner" role="status">
      <i className="fe fe-clock" aria-hidden="true" />
      <div className="lux-appr-sla-banner__copy">
        <strong>{headline}</strong>
        <span>Review high-risk items first. Escalation rules apply per domain policy.</span>
      </div>
      <div className="lux-appr-sla-banner__actions">
        {typeof onReview === "function" && (
          <button
            type="button"
            className={classNames("lux-appr-sla-banner__cta", { "is-active": active })}
            onClick={onReview}
            aria-pressed={Boolean(active)}
          >
            {active ? "Clear high priority" : "Review high priority"}
          </button>
        )}
        <Link to="/admin/approval-policies" className="lux-appr-sla-banner__link">
          View policies
        </Link>
      </div>
    </div>
  );
}
