import { shouldUsePaychecks, shouldUsePayrollManagement } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const PAYROLL_RUN_STATUSES = {
  DRAFT: "Draft",
  CALCULATED: "Calculated",
  PENDING_APPROVAL: "Pending approval",
  APPROVED: "Approved",
  FINALIZED: "Finalized",
  LOCKED: "Locked",
  REOPENED: "Reopened",
};

export const PAYROLL_COMPONENT_TYPES = {
  EARNING: { id: "EARNING", label: "Earning" },
  DEDUCTION: { id: "DEDUCTION", label: "Deduction" },
  EMPLOYER: { id: "EMPLOYER", label: "Employer contribution" },
};

export const PAYROLL_EXCEPTION_SEVERITIES = {
  BLOCKER: "Blocker",
  WARNING: "Warning",
  INFO: "Info",
};

export const PAYCHECK_STATUSES = {
  DRAFT: "Draft",
  PUBLISHED: "Published",
  RETRACTED: "Retracted",
};

export function isPayrollManagementEnabled() {
  return shouldUsePayrollManagement();
}

export function isPaychecksEnabled() {
  return shouldUsePaychecks();
}

export function isPayslipPdfEnabled() {
  return envconfig.PAYSLIP_PDF_ENABLED === true && isPaychecksEnabled();
}

export function shouldUsePayrollApi() {
  return envconfig.USE_PAYROLL_API === true;
}

export function normalizePaycheckLine(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    type: row.type || "EARNING",
    code: row.code || "",
    label: row.label || "Line item",
    amount: row.amount != null ? row.amount : null,
  };
}

export function normalizePaycheck(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id || row.paycheckRef,
    runId: row.runId || null,
    runName: row.runName || "",
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    department: row.department || "",
    periodLabel: row.periodLabel || row.period || "",
    periodStart: row.periodStart || null,
    periodEnd: row.periodEnd || null,
    payDate: row.payDate || null,
    status: row.status || PAYCHECK_STATUSES.DRAFT,
    currency: row.currency || "USD",
    gross: row.gross != null ? row.gross : null,
    deductions: row.deductions != null ? row.deductions : null,
    net: row.net != null ? row.net : null,
    ytdGross: row.ytdGross != null ? row.ytdGross : null,
    ytdDeductions: row.ytdDeductions != null ? row.ytdDeductions : null,
    ytdNet: row.ytdNet != null ? row.ytdNet : null,
    paymentMethod: row.paymentMethod || "Direct deposit",
    publishedAt: row.publishedAt || null,
    lines: (row.lines || []).map((line) => normalizePaycheckLine(line)).filter(Boolean),
    hasPdf: row.hasPdf === true,
  };
}

export function normalizeSalaryStructure(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Salary structure",
    code: row.code || "",
    currency: row.currency || "USD",
    payFrequency: row.payFrequency || "Monthly",
    baseComponent: row.baseComponent || "BASE_SALARY",
    componentCount: row.componentCount != null ? row.componentCount : 0,
    employeeCount: row.employeeCount != null ? Number(row.employeeCount) : null,
    status: row.status || "Active",
    updatedAt: row.updatedAt || null,
  };
}

export function normalizePayrollGroup(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Payroll group",
    code: row.code || "",
    payFrequency: row.payFrequency || "Monthly",
    currency: row.currency || "USD",
    employeeCount: row.employeeCount != null ? Number(row.employeeCount) : null,
    nextPayDate: row.nextPayDate || null,
    currentPeriod: row.currentPeriod || "",
    lockDay: row.lockDay != null ? row.lockDay : null,
    status: row.status || "Active",
  };
}

export function normalizePayrollRun(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    userTeamId: row.userTeamId != null ? row.userTeamId : null,
    name: row.name || "Payroll run",
    groupId: row.groupId || null,
    groupName: row.groupName || "",
    periodStart: row.periodStart || null,
    periodEnd: row.periodEnd || null,
    payDate: row.payDate || null,
    status: row.status || PAYROLL_RUN_STATUSES.DRAFT,
    employeeCount: row.employeeCount != null ? row.employeeCount : 0,
    grossTotal: row.grossTotal != null ? row.grossTotal : null,
    netTotal: row.netTotal != null ? row.netTotal : null,
    exceptionCount: row.exceptionCount != null ? row.exceptionCount : 0,
    blockerCount: row.blockerCount != null ? row.blockerCount : 0,
    readinessScore: row.readinessScore != null ? row.readinessScore : null,
    updatedAt: row.updatedAt || null,
  };
}

export function normalizePayrollException(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    runId: row.runId || null,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    code: row.code || "",
    message: row.message || "",
    severity: row.severity || PAYROLL_EXCEPTION_SEVERITIES.WARNING,
    category: row.category || "General",
    resolved: row.resolved === true,
  };
}

export function normalizePayrollLine(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    runId: row.runId || null,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    department: row.department || "",
    gross: row.gross != null ? row.gross : null,
    deductions: row.deductions != null ? row.deductions : null,
    net: row.net != null ? row.net : null,
    status: row.status || "Calculated",
    exceptionCount: row.exceptionCount != null ? row.exceptionCount : 0,
  };
}
