import React from "react";
import classNames from "classnames/bind";
import { getApiErrorMessage } from "_helpers/apiError.utils";

const TONE_ICONS = {
  danger: "fe fe-alert-circle",
  warning: "fe fe-alert-triangle",
  info: "fe fe-info",
  success: "fe fe-check-circle",
};

/**
 * Compact luxury inline alert for module page bodies (replaces Bootstrap alert-danger).
 */
function LuxInlineAlert({
  children,
  message,
  error,
  tone = "danger",
  title,
  icon,
  onDismiss,
  className,
  testId,
}) {
  const resolvedMessage =
    message ||
    (typeof children === "string" || typeof children === "number"
      ? children
      : null) ||
    (error ? getApiErrorMessage(error, "Something went wrong.") : null);

  if (!resolvedMessage && !children) {
    return null;
  }

  const eyebrow =
    title ||
    (tone === "danger"
      ? "Unable to continue"
      : tone === "warning"
        ? "Attention needed"
        : tone === "success"
          ? "Success"
          : "Notice");

  return (
    <div
      className={classNames("lux-inline-alert", `lux-inline-alert--${tone}`, className)}
      role="alert"
      data-testid={testId || undefined}
    >
      <span className="lux-inline-alert__glow" aria-hidden="true" />
      <span className="lux-inline-alert__icon" aria-hidden="true">
        <i className={icon || TONE_ICONS[tone] || TONE_ICONS.danger} />
      </span>
      <div className="lux-inline-alert__copy">
        <span className="lux-inline-alert__eyebrow">{eyebrow}</span>
        <p className="lux-inline-alert__message">
          {resolvedMessage || children}
        </p>
      </div>
      {onDismiss ? (
        <button
          type="button"
          className="lux-inline-alert__dismiss"
          onClick={onDismiss}
          aria-label="Dismiss"
        >
          <i className="fe fe-x" aria-hidden="true" />
        </button>
      ) : null}
    </div>
  );
}

export default LuxInlineAlert;
