import React, { Component } from "react";
import classNames from "classnames/bind";

/**
 * Searchable chip multi-select for task access (skills, employees) — avoids react-select in panels.
 */
class ProjectAccessChipPicker extends Component {
  state = { query: "" };

  getOptions = () => this.props.options || [];

  getSelected = () => {
    const raw = this.props.value;
    if (!raw) return [];
    return Array.isArray(raw) ? raw : [raw];
  };

  toggle = (value) => {
    const selected = this.getSelected();
    const next = selected.includes(value)
      ? selected.filter((v) => v !== value)
      : [...selected, value];
    this.props.onChange(next.length ? next : null);
  };

  clearAll = () => {
    this.props.onChange(null);
    this.setState({ query: "" });
  };

  renderSelectedBar = () => {
    const selected = this.getSelected();
    if (!selected.length) return null;
    const options = this.getOptions();
    const labels = selected.map((id) => {
      const match = options.find((o) => o.value === id);
      return (match && match.label) || id;
    });

    return (
      <div className="lux-project-access__selected-bar">
        <span className="lux-project-access__selected-label">
          {selected.length} selected
        </span>
        <div className="lux-project-access__selected-chips">
          {labels.map((label, idx) => (
            <span key={`${label}-${idx}`} className="lux-project-access__selected-chip">
              {label}
            </span>
          ))}
        </div>
        {!this.props.readOnly && (
          <button
            type="button"
            className="lux-project-access__clear"
            onClick={this.clearAll}
          >
            Clear all
          </button>
        )}
      </div>
    );
  };

  render() {
    const {
      readOnly,
      emptyMessage,
      emptyHint,
      searchPlaceholder,
      ariaLabel,
      variant = "default",
    } = this.props;
    const options = this.getOptions();
    const selected = this.getSelected();
    const q = this.state.query.trim().toLowerCase();
    const filtered = q
      ? options.filter((o) => {
          const hay = `${o.label || ""} ${o.meta || ""} ${o.value || ""}`.toLowerCase();
          return hay.includes(q);
        })
      : options;

    if (!options.length) {
      return (
        <div className="lux-project-access__picker lux-project-access__picker--empty">
          <i className="fe fe-inbox" aria-hidden="true" />
          <p>{emptyMessage || "No options available for the current team scope."}</p>
          {emptyHint && <span>{emptyHint}</span>}
        </div>
      );
    }

    const showSearch = options.length > 5;

    return (
      <div className={classNames("lux-project-access__picker", `is-${variant}`)}>
        {this.renderSelectedBar()}
        {showSearch && (
          <div className="lux-project-access__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              value={this.state.query}
              onChange={(e) => this.setState({ query: e.target.value })}
              placeholder={searchPlaceholder || "Search…"}
              aria-label={searchPlaceholder || "Search options"}
              disabled={readOnly}
            />
            {this.state.query && (
              <button
                type="button"
                className="lux-project-access__search-clear"
                onClick={() => this.setState({ query: "" })}
                aria-label="Clear search"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            )}
          </div>
        )}
        <div className="lux-project-access__chip-grid" role="group" aria-label={ariaLabel}>
          {filtered.map((opt) => {
            const value = opt.value;
            const isOn = selected.includes(value);
            return (
              <button
                key={value}
                type="button"
                disabled={readOnly}
                className={classNames("lux-project-access__chip", {
                  "is-selected": isOn,
                })}
                onClick={() => this.toggle(value)}
                aria-pressed={isOn}
              >
                <span className="lux-project-access__chip-mark" aria-hidden="true">
                  {variant === "people" ? (
                    <span className="lux-project-access__avatar">
                      {(opt.label || "?").charAt(0).toUpperCase()}
                    </span>
                  ) : (
                    <i className={isOn ? "fe fe-check" : "fe fe-award"} />
                  )}
                </span>
                <span className="lux-project-access__chip-body">
                  <span className="lux-project-access__chip-label">{opt.label || value}</span>
                  {opt.meta && (
                    <span className="lux-project-access__chip-meta">{opt.meta}</span>
                  )}
                </span>
              </button>
            );
          })}
        </div>
        {!filtered.length && (
          <p className="lux-project-access__no-match">No matches for your search.</p>
        )}
      </div>
    );
  }
}

export default ProjectAccessChipPicker;
