import React, { Component } from "react";
import { commonUtils } from "_helpers";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isResourcePlanningEnabled,
  normalizeStaffingRequest,
  STAFFING_REQUEST_STATUSES,
} from "config/resource-planning.config";
import {
  buildStaffingRequestInsights,
  buildStaffingRequestMetrics,
  filterStaffingRequests,
  STAFFING_PRIORITY_FILTER_OPTIONS,
  STAFFING_STATUS_FILTER_OPTIONS,
} from "config/resource-planning.utils";
import { resourcePlanningService } from "_services/resourcePlanning.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminInsightStrip,
} from "views/admin/components/AdminLuxShared";
import {
  ResourcesActionButton,
  ResourcesHeroActions,
  ResourcesKpiStrip,
  ResourcesRegisterAtelier,
} from "views/resources/components/ResourcesLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import StaffingAiQueuePanel from "views/resources/components/StaffingAiQueuePanel";
import StaffingRequestDrawer from "views/resources/components/StaffingRequestDrawer";
import StaffingRequestRegister from "views/resources/components/StaffingRequestRegister";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class StaffingRequestsPage extends Component {
  state = {
    requests: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    statusFilter: "ALL",
    priorityFilter: "ALL",
    drawerOpen: false,
    drawerMode: "create",
    selectedRequest: null,
    aiRefreshKey: 0,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Staffing requests");
    this.loadRequests();
  }

  loadRequests = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await resourcePlanningService.listStaffingRequests();
      const payload = (result && result.payload) || [];
      this.setState((prev) => ({
        requests: Array.isArray(payload) ? payload : [],
        loading: false,
        dataSource: (result && result.source) || null,
        loadError:
          result && result.source === "api-error"
            ? "Unable to load staffing requests from the API."
            : null,
        aiRefreshKey: prev.aiRefreshKey + 1,
      }));
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load staffing requests.",
        requests: [],
      });
    }
  };

  getFilteredRequests = () => {
    const { requests, query, statusFilter, priorityFilter } = this.state;
    return filterStaffingRequests(requests, {
      query,
      status: statusFilter,
      priority: priorityFilter,
    });
  };

  openCreateDrawer = () => {
    this.setState({ drawerOpen: true, drawerMode: "create", selectedRequest: null });
  };

  openEditDrawer = (request) => {
    this.setState({ drawerOpen: true, drawerMode: "edit", selectedRequest: request });
  };

  openEditDrawerById = (requestId) => {
    const request = this.state.requests.find((row) => row.id === requestId);
    if (request) {
      this.openEditDrawer(request);
    }
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedRequest: null });
  };

  upsertLocalRequest = (row) => {
    if (!row) {
      return;
    }
    this.setState((prev) => {
      const exists = prev.requests.some((item) => item.id === row.id);
      const requests = exists
        ? prev.requests.map((item) => (item.id === row.id ? { ...item, ...row } : item))
        : [row, ...prev.requests];
      return {
        requests,
        dataSource: prev.dataSource === "api" ? "api" : "local",
        aiRefreshKey: prev.aiRefreshKey + 1,
      };
    });
  };

  handleCreate = async (payload) => {
    const result = await resourcePlanningService.createStaffingRequest({
      ...payload,
      requesterId: commonUtils.getCurrentUserId() || "current-user",
      requesterName: commonUtils.getCurrentUserName() || "Current user",
      submittedAt: new Date().toISOString().slice(0, 10),
      status: STAFFING_REQUEST_STATUSES.PENDING,
    });
    if (result && result.payload) {
      this.upsertLocalRequest(result.payload);
      return;
    }
    // Keep the flow usable when the API is unavailable.
    const local = normalizeStaffingRequest({
      id: `local-staff-${Date.now()}`,
      ...payload,
      requesterId: commonUtils.getCurrentUserId() || "current-user",
      requesterName: commonUtils.getCurrentUserName() || "Current user",
      submittedAt: new Date().toISOString().slice(0, 10),
      status: STAFFING_REQUEST_STATUSES.PENDING,
    });
    if (!local) {
      throw new Error("Unable to create staffing request.");
    }
    this.upsertLocalRequest(local);
  };

  handleUpdate = async (request, payload) => {
    const next = {
      title: payload.title || request.title,
      requesterId: request.requesterId,
      requesterName: request.requesterName,
      projectId: payload.projectId || request.projectId,
      projectName: payload.projectName || request.projectName,
      roleNeeded: payload.roleNeeded || request.roleNeeded,
      headcount: payload.headcount != null ? payload.headcount : request.headcount,
      priority: payload.priority || request.priority,
      status: payload.status || request.status,
      submittedAt: request.submittedAt,
      dueAt: payload.dueAt || request.dueAt,
      notes: payload.notes != null ? payload.notes : request.notes || "",
    };
    const result = await resourcePlanningService.updateStaffingRequest(request.id, next);
    if (result && result.payload) {
      this.upsertLocalRequest(result.payload);
      return;
    }
    const local = normalizeStaffingRequest({
      ...request,
      ...next,
      id: request.id,
    });
    if (!local) {
      throw new Error("Unable to update staffing request.");
    }
    this.upsertLocalRequest(local);
  };

  render() {
    if (!isResourcePlanningEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Resources"
          reason="Resource planning is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      query,
      statusFilter,
      priorityFilter,
      requests,
      drawerOpen,
      drawerMode,
      selectedRequest,
      aiRefreshKey,
    } = this.state;
    const filtered = this.getFilteredRequests();
    const metrics = buildStaffingRequestMetrics(requests);
    const insights = loading ? [] : buildStaffingRequestInsights(requests, metrics);

    const kpiCards = [
      {
        id: "open",
        label: "Open requests",
        value: metrics.openCount,
        hint: `${metrics.pendingCount} awaiting review`,
        tone: "amber",
        icon: "fe fe-inbox",
      },
      {
        id: "urgent",
        label: "High priority",
        value: metrics.highPriorityCount,
        hint: "Needs escalation",
        tone: metrics.highPriorityCount > 0 ? "rose" : "green",
        icon: "fe fe-alert-triangle",
      },
      {
        id: "headcount",
        label: "Roles needed",
        value: metrics.headcountNeeded,
        hint: "Across open requests",
        tone: "primary",
        icon: "fe fe-users",
      },
      {
        id: "fulfilled",
        label: "Fulfilled",
        value: metrics.fulfilledCount,
        hint: `${metrics.total} total requests`,
        tone: "green",
        icon: "fe fe-check-circle",
      },
    ];

    return (
      <div
        className="lux-staffing-page lux-register-page lux-staffing-lux"
        data-testid="page-resources-staffing"
      >
        <PageDataSourceReporter dataSource={dataSource} />
        <div className="lux-staffing-lux__ambient" aria-hidden="true">
          <span className="lux-staffing-lux__orb lux-staffing-lux__orb--a" />
          <span className="lux-staffing-lux__orb lux-staffing-lux__orb--b" />
        </div>

        <LuxModuleIntro
          meta={DENSE_PAGE_META.staffingRequests}
          className="lux-staffing-hero"
          actions={
            <ResourcesHeroActions dataSource={dataSource}>
<ResourcesActionButton to="/project/capacity" icon="fe fe-pie-chart" variant="ghost">
                Team capacity
              </ResourcesActionButton>
              <ResourcesActionButton
                icon="fe fe-plus"
                variant="primary"
                onClick={this.openCreateDrawer}
              >
                New request
              </ResourcesActionButton>
            </ResourcesHeroActions>
          }
          onRefresh={this.loadRequests}
          refreshLoading={loading}
        />

        <div className="lux-staffing-page__body">
          <ResourcesKpiStrip cards={kpiCards} loading={loading} className="lux-staffing-kpi-strip" />

          {loadError && (
            <div className="lux-employee-360__error lux-staffing__error" role="alert">
              <span>{loadError}</span>
              <ResourcesActionButton variant="ghost" onClick={this.loadRequests}>
                Retry
              </ResourcesActionButton>
            </div>
          )}

          <AdminInsightStrip insights={insights} className="lux-staffing-insights" />

          <StaffingAiQueuePanel
            refreshKey={aiRefreshKey}
            loading={loading}
            onSelectRequest={this.openEditDrawerById}
          />

          <ResourcesRegisterAtelier
            tone="amber"
            className="lux-staffing-panel--register"
            kickerIcon="fe fe-inbox"
            kicker="Demand queue"
            title="Staffing request register"
            subtitle="Compact view of open demand — filter, triage, and open a request to act"
            pulseCards={[
              { id: "shown", label: "Shown", value: filtered.length, tone: "amber" },
              { id: "high", label: "High", value: metrics.highPriorityCount, tone: "rose" },
              { id: "roles", label: "Roles", value: metrics.headcountNeeded, tone: "sky" },
              { id: "done", label: "Done", value: metrics.fulfilledCount, tone: "green" },
            ]}
            search={{
              placeholder: "Search title, project, role, requester…",
              value: query,
              onChange: (event) => this.setState({ query: event.target.value }),
            }}
            filterGroups={[
              {
                id: "status",
                ariaLabel: "Status filters",
                value: statusFilter,
                onChange: (value) => this.setState({ statusFilter: value }),
                options: STAFFING_STATUS_FILTER_OPTIONS,
              },
              {
                id: "priority",
                ariaLabel: "Priority filters",
                variant: "priority",
                value: priorityFilter,
                onChange: (value) => this.setState({ priorityFilter: value }),
                options: STAFFING_PRIORITY_FILTER_OPTIONS,
              },
            ]}
          >
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading staffing requests"
                description="Aggregating open and fulfilled staffing demand."
              />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="No staffing requests match"
                description="Create a new request or adjust filters to see the queue."
                showCreate
                createLabel="New request"
                onCreate={this.openCreateDrawer}
              />
            ) : (
              <StaffingRequestRegister
                rows={filtered}
                loading={loading}
                onSelect={this.openEditDrawer}
              />
            )}
          </ResourcesRegisterAtelier>
        </div>

        <StaffingRequestDrawer
          open={drawerOpen}
          mode={drawerMode}
          request={selectedRequest}
          onClose={this.closeDrawer}
          onCreate={this.handleCreate}
          onUpdate={this.handleUpdate}
        />
      </div>
    );
  }
}

export default StaffingRequestsPage;
