import React from 'react';
import { Link } from 'react-router-dom';
import classNames from 'classnames/bind';

const GLOBAL_BASE = '/admin/leave/global-policy-center';
const CLASSIC_BASE = '/admin/leave-policies';

/**
 * Shows which policy source drives monthly LEAVE_ACCRUAL for the team.
 */
export default function AccrualSourceBanner({ source, loading }) {
  if (loading && !source) {
    return (
      <div className="lux-glp-accrual-banner is-loading" role="status">
        <i className="fe fe-loader" aria-hidden="true" />
        <span>Checking accrual source…</span>
      </div>
    );
  }
  if (!source) return null;

  const isGlobal = String(source.source || '').toUpperCase() === 'GLOBAL';
  const policyLabel = source.policyName
    || source.policyRef
    || (source.policyId != null ? `Policy #${source.policyId}` : 'global policy');
  const versionLabel = source.versionNo != null ? `v${source.versionNo}` : null;

  return (
    <div
      className={classNames('lux-glp-accrual-banner', isGlobal ? 'is-global' : 'is-classic')}
      role="status"
      data-testid="accrual-source-banner"
    >
      <i className={isGlobal ? 'fe fe-globe' : 'fe fe-sliders'} aria-hidden="true" />
      <div className="lux-glp-accrual-banner__copy">
        <strong>{isGlobal ? 'Accrual source: Global policy' : 'Accrual source: Classic leave policies'}</strong>
        <p>
          {source.message
            || (isGlobal
              ? 'Published global rules drive the monthly leave balance job.'
              : 'No published global policy — classic entitlements drive accrual.')}
          {isGlobal && versionLabel ? ` (${policyLabel} · ${versionLabel})` : null}
        </p>
      </div>
      {isGlobal ? (
        <Link
          className="lux-glp-accrual-banner__cta"
          to={source.policyId ? `${GLOBAL_BASE}/policies/${source.policyId}` : GLOBAL_BASE}
        >
          Open global policy
        </Link>
      ) : (
        <Link className="lux-glp-accrual-banner__cta" to={CLASSIC_BASE}>
          Manage classic policies
        </Link>
      )}
    </div>
  );
}
