import React from "react";
import { WorkflowLuxPanel } from "views/automation/components/WorkflowLuxShared";

export default function WorkflowAiSuggestionPanel({ suggestion, loading, onApply }) {
  if (loading) {
    return (
      <WorkflowLuxPanel title="AI rule suggestions" meta="Loading suggestions…" icon="fe fe-cpu" accent="violet">
        <div className="lux-wf-skeleton lux-wf-skeleton--panel" />
      </WorkflowLuxPanel>
    );
  }

  if (!suggestion) {
    return null;
  }

  const items = suggestion.suggestions || [];

  return (
    <WorkflowLuxPanel title="AI rule suggestions" meta="Admin publish required" icon="fe fe-cpu" accent="violet">
      <p className="lux-wf-ai-summary">{suggestion.summary}</p>
      <ul className="lux-wf-ai-list">
        {items.map((item, index) => (
          <li key={index} className="lux-wf-ai-card">
            <div className="lux-wf-ai-card__head">
              <strong>{item.name}</strong>
              <span>{Math.round((item.confidence || 0) * 100)}% confidence</span>
            </div>
            <p>{item.description}</p>
            <span className="lux-wf-ai-card__trigger">{item.triggerLabel}</span>
            {onApply ? (
              <button type="button" className="lux-onb-action lux-onb-action--ghost lux-wf-action" onClick={() => onApply(item)}>
                Use suggestion
              </button>
            ) : null}
          </li>
        ))}
      </ul>
      <p className="lux-wf-ai-disclaimer">{suggestion.disclaimer}</p>
    </WorkflowLuxPanel>
  );
}
