import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { NavLink } from "react-router-dom";
import CountUp from "react-countup";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import AttendanceEmployeeFilter from "./AttendanceEmployeeFilter";
import {
  ATTENDANCE_CALENDAR_WEEKDAYS,
  buildAttendanceCalendarWeeks,
  canMarkAttendanceFor,
  formatAttendanceTimeDisplay,
  getEmployeeStats,
  isAttendanceLeave,
  isAttendanceMarked,
} from "./attendance.utils";

function densityTone(density) {
  if (density >= 0.85) return "high";
  if (density >= 0.55) return "medium";
  if (density > 0) return "low";
  return "none";
}

function monthPulse(calendar, stats) {
  const inMonth = (calendar.weeks || []).flat().filter((c) => c.inMonth && !c.meta.isFuture);
  const presentDays = inMonth.filter((c) => c.statusMeta && c.statusMeta.tone === "present").length;
  const leaveDays = inMonth.filter((c) => c.statusMeta && c.statusMeta.tone === "leave").length;
  const pendingDays = inMonth.filter(
    (c) => c.statusMeta && (c.statusMeta.tone === "pending" || c.statusMeta.tone === "pending-removal")
  ).length;
  const absentDays = inMonth.filter(
    (c) =>
      c.statusMeta &&
      c.statusMeta.tone === "absent" &&
      !c.meta.isWeekend &&
      !c.meta.isHoliday
  ).length;
  const avgDensity =
    inMonth.filter((c) => c.possible > 0).reduce((sum, c) => sum + c.density, 0) /
    Math.max(inMonth.filter((c) => c.possible > 0).length, 1);

  return {
    presentDays,
    leaveDays,
    pendingDays,
    absentDays,
    avgDensityPct: Math.round(avgDensity * 100),
    rate: stats ? stats.rate : 0,
    present: stats ? stats.present : presentDays,
    absent: stats ? stats.absent : absentDays,
  };
}

/**
 * Luxury month calendar for people/attendance — rich atelier default view.
 */
class AttendanceCalendarView extends PureComponent {
  state = {
    selectedDayKey: null,
  };

  componentDidUpdate(prevProps) {
    if (
      prevProps.selectedDate !== this.props.selectedDate ||
      prevProps.focusEmployeeId !== this.props.focusEmployeeId
    ) {
      this.setState({ selectedDayKey: null });
    }
  }

  handleDayActivate = (cell) => {
    const {
      focusEmployee,
      isLoading,
      permission,
      currentUserId,
      onRequestMark,
      onRequestViewDetails,
    } = this.props;
    if (!focusEmployee || !cell || !cell.inMonth || cell.meta.isFuture || isLoading) return;

    this.setState({ selectedDayKey: cell.key });

    const item = cell.focusItem;
    const canMark = canMarkAttendanceFor(permission, focusEmployee.id, currentUserId);
    const leaveLocked = isAttendanceLeave(item);
    const canViewMarked = isAttendanceMarked(item) && item && item.id != null;

    if (leaveLocked || canViewMarked) {
      if (onRequestViewDetails) {
        onRequestViewDetails(focusEmployee.id, focusEmployee.name, cell.day, item);
      }
      return;
    }
    if (canMark && onRequestMark) {
      onRequestMark(focusEmployee.id, focusEmployee.name, cell.day);
    }
  };

  renderMonthNav = () => {
    const { isLoading, goToBack, goToCurrent, goToNext, selectedDate } = this.props;
    const monthLabel = selectedDate ? selectedDate.format("MMM YYYY") : "This month";
    return (
      <div className="lux-att-cal__nav" role="group" aria-label="Change month">
        <button
          type="button"
          className="lux-att-cal__nav-arrow"
          onClick={goToBack}
          disabled={isLoading}
          aria-label="Previous month"
        >
          <i className="fe fe-chevron-left" aria-hidden="true" />
        </button>
        <div className="lux-att-cal__nav-center">
          <span className="lux-att-cal__nav-eyebrow">Month</span>
          <strong className="lux-att-cal__nav-month">{monthLabel}</strong>
        </div>
        <button
          type="button"
          className="lux-att-cal__nav-arrow"
          onClick={goToNext}
          disabled={isLoading}
          aria-label="Next month"
        >
          <i className="fe fe-chevron-right" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-att-cal__nav-today"
          onClick={goToCurrent}
          disabled={isLoading}
        >
          Today
        </button>
      </div>
    );
  };

  renderQuickActions = (selectedCell) => {
    const { leaveApplyPath, onRequestRegularize, isViewingSelf, isLoading } = this.props;
    if (!isViewingSelf) return null;
    const showLeave = !!leaveApplyPath;
    const showReg = typeof onRequestRegularize === "function";
    if (!showLeave && !showReg) return null;

    return (
      <div className="lux-att-cal__quick" role="group" aria-label="Leave and regularization">
        {showLeave ? (
          <NavLink
            to={leaveApplyPath}
            className="lux-att-cal__quick-btn is-leave"
            data-testid="att-cal-apply-leave"
          >
            <i className="fe fe-sun" aria-hidden="true" />
            <span>Apply leave</span>
          </NavLink>
        ) : null}
        {showReg ? (
          <button
            type="button"
            className="lux-att-cal__quick-btn is-reg"
            disabled={isLoading}
            data-testid="att-cal-regularize"
            onClick={() =>
              onRequestRegularize(
                selectedCell && selectedCell.day ? selectedCell.day : null,
                selectedCell && selectedCell.focusItem ? selectedCell.focusItem : null
              )
            }
          >
            <i className="fe fe-edit-2" aria-hidden="true" />
            <span>Regularize</span>
          </button>
        ) : null}
      </div>
    );
  };

  renderPulse = (pulse) => (
    <div className="lux-att-cal__pulse" aria-label="Month pulse">
      {[
        {
          key: "rate",
          label: "Attendance",
          value: pulse.rate,
          suffix: "%",
          hint: "Focus rate",
          tone: "emerald",
          icon: "fe fe-trending-up",
          meter: true,
        },
        {
          key: "present",
          label: "Present",
          value: pulse.present,
          hint: "Accounted days",
          tone: "green",
          icon: "fe fe-check-circle",
        },
        {
          key: "absent",
          label: "Absent",
          value: pulse.absent,
          hint: "Needs attention",
          tone: pulse.absent ? "rose" : "slate",
          icon: "fe fe-alert-circle",
        },
        {
          key: "team",
          label: "Team density",
          value: pulse.avgDensityPct,
          suffix: "%",
          hint: "Avg presence",
          tone: "sky",
          icon: "fe fe-users",
          meter: true,
        },
      ].map((card) => (
        <article key={card.key} className={classNames("lux-att-cal__pulse-card", `is-${card.tone}`)}>
          <span className="lux-att-cal__pulse-accent" aria-hidden="true" />
          <div className="lux-att-cal__pulse-top">
            <span className="lux-att-cal__pulse-icon" aria-hidden="true">
              <i className={card.icon} />
            </span>
            <em>{card.label}</em>
          </div>
          <strong className="lux-att-cal__pulse-value">
            <CountUp end={card.value || 0} duration={0.7} />
            {card.suffix || ""}
          </strong>
          <span className="lux-att-cal__pulse-hint">{card.hint}</span>
          {card.meter ? (
            <span className="lux-att-cal__pulse-meter" aria-hidden="true">
              <i style={{ width: `${Math.min(Math.max(card.value || 0, 0), 100)}%` }} />
            </span>
          ) : (
            <span className="lux-att-cal__pulse-meter is-flat" aria-hidden="true">
              <i style={{ width: "100%" }} />
            </span>
          )}
        </article>
      ))}
    </div>
  );

  renderFocus = (focusEmployee, stats, canMark) => {
    if (!focusEmployee) {
      return (
        <div className="lux-att-cal__focus lux-att-cal__focus--empty">
          <span className="lux-att-cal__focus-empty-icon" aria-hidden="true">
            <i className="fe fe-user" />
          </span>
          <p className="lux-att-cal__no-focus">
            Select an employee to focus the calendar, or keep yourself as default.
          </p>
        </div>
      );
    }
    return (
      <div className="lux-att-cal__focus">
        <div className="lux-att-cal__focus-identity">
          <div className="lux-att-cal__avatar-ring">
            <EmployeeImage employee={focusEmployee} classes="lux-att-cal__avatar" />
          </div>
          <div className="lux-att-cal__focus-copy">
            <strong>{focusEmployee.name}</strong>
            <span className="lux-att-cal__focus-meta">
              <em>{focusEmployee.designation || "Employee"}</em>
              <span className="lux-att-cal__focus-badge">
                {canMark ? "Can mark" : "View only"}
              </span>
            </span>
          </div>
        </div>
        {stats ? (
          <div className="lux-att-cal__focus-stats" aria-label="Focus attendance stats">
            <span className="is-present">
              <strong>
                <CountUp end={stats.present} duration={0.6} />
              </strong>
              <em>Present</em>
            </span>
            <span className="is-absent">
              <strong>
                <CountUp end={stats.absent} duration={0.6} />
              </strong>
              <em>Absent</em>
            </span>
            <span className="is-rate">
              <strong>
                <CountUp end={stats.rate} duration={0.6} />%
              </strong>
              <em>Rate</em>
            </span>
          </div>
        ) : null}
      </div>
    );
  };

  renderLegend = () => (
    <ul className="lux-att-cal__legend" aria-label="Attendance legend">
      {[
        { tone: "present", label: "Present", icon: "fe fe-check" },
        { tone: "pending", label: "Pending", icon: "fe fe-clock" },
        { tone: "leave", label: "Leave", icon: "fe fe-sun" },
        { tone: "absent", label: "Absent", icon: "fe fe-minus" },
        { tone: "upcoming", label: "Upcoming", icon: "fe fe-sunrise" },
        { tone: "rejected", label: "Rejected", icon: "fe fe-x" },
        { tone: "holiday", label: "Org holiday", icon: "fe fe-flag" },
        { tone: "holiday-marked", label: "Marked holiday", icon: "fe fe-sun" },
        { tone: "weekend", label: "Off day", icon: "fe fe-moon" },
      ].map((row) => (
        <li key={row.tone} className={`lux-att-cal__legend-item is-${row.tone}`}>
          <i className={row.icon} aria-hidden="true" />
          {row.label}
        </li>
      ))}
    </ul>
  );

  renderSelectedRail = (selectedCell, stats, pulse) => {
    const {
      focusEmployee,
      onRequestRegularize,
      leaveApplyPath,
      isViewingSelf,
      permission,
      currentUserId,
      onRequestMark,
      onRequestViewDetails,
    } = this.props;

    if (!selectedCell) {
      return (
        <div className="lux-att-cal__rail-stack">
          <div className="lux-att-cal__rail-hero is-idle">
            <span className="lux-att-cal__rail-orb" aria-hidden="true">
              <i className="fe fe-calendar" />
            </span>
            <p className="lux-att-cal__eyebrow">Day atelier</p>
            <strong>Pick a day on the grid</strong>
            <p>
              Mark presence, open pending details, or jump into leave / regularization from this
              rail.
            </p>
          </div>
          {this.renderQuickActions(null)}
          <div className="lux-att-cal__insight-card">
            <i className="fe fe-activity" aria-hidden="true" />
            <div>
              <strong>Month pulse</strong>
              <em>
                {pulse.present} present · {pulse.absent} absent · {pulse.avgDensityPct}% team
                density
              </em>
            </div>
          </div>
          <div className="lux-att-cal__insight-card is-sky">
            <i className="fe fe-info" aria-hidden="true" />
            <div>
              <strong>How to use</strong>
              <em>Absent workdays open mark · marked days open details · leave stays leave-owned</em>
            </div>
          </div>
        </div>
      );
    }

    const item = selectedCell.focusItem;
    const timeLabel = item
      ? formatAttendanceTimeDisplay(item.markTime || item.markDate)
      : null;
    const checkoutLabel =
      item && item.checkoutTime ? formatAttendanceTimeDisplay(item.checkoutTime) : null;
    const canMark = canMarkAttendanceFor(
      permission,
      focusEmployee && focusEmployee.id,
      currentUserId
    );
    const canView = isAttendanceMarked(item) && item && item.id != null;
    const densityPct = Math.min(100, Math.round((selectedCell.density || 0) * 100));
    const holidayInfo = selectedCell.holidayInfo;
    const railTone =
      (holidayInfo && (holidayInfo.marked ? "holiday-marked" : "holiday")) ||
      selectedCell.statusMeta.tone;

    return (
      <div className="lux-att-cal__rail-stack">
        <div
          className={classNames(
            "lux-att-cal__rail-hero",
            `is-${railTone}`
          )}
        >
          <div className="lux-att-cal__rail-hero-top">
            <p className="lux-att-cal__eyebrow">Selected day</p>
            {selectedCell.meta.isToday ? (
              <span className="lux-att-cal__today-chip">Today</span>
            ) : null}
          </div>
          <h4>{selectedCell.day.format("dddd")}</h4>
          <p className="lux-att-cal__rail-date">{selectedCell.day.format("MMMM D, YYYY")}</p>
          <span
            className={classNames(
              "lux-att-cal__status-pill",
              `is-${selectedCell.statusMeta.tone}`,
              holidayInfo && holidayInfo.marked && "is-holiday-marked"
            )}
          >
            <i className={selectedCell.statusMeta.icon} aria-hidden="true" />
            {selectedCell.statusMeta.label}
          </span>
        </div>

        {holidayInfo ? (
          <div
            className={classNames(
              "lux-att-cal__insight-card",
              holidayInfo.marked ? "is-holiday-marked" : "is-holiday"
            )}
          >
            <i className={holidayInfo.marked ? "fe fe-sun" : "fe fe-flag"} aria-hidden="true" />
            <div>
              <strong>
                {holidayInfo.marked ? "Marked holiday" : "Organization holiday"}
              </strong>
              <em>
                {holidayInfo.name}
                {holidayInfo.marked
                  ? " · from task activity"
                  : " · calendar holiday"}
              </em>
            </div>
          </div>
        ) : null}

        {(timeLabel || checkoutLabel || (item && item.hours != null)) && (
          <div className="lux-att-cal__time-cards">
            {timeLabel ? (
              <article>
                <em>Clock in</em>
                <strong>{timeLabel}</strong>
              </article>
            ) : null}
            {checkoutLabel ? (
              <article>
                <em>Clock out</em>
                <strong>{checkoutLabel}</strong>
              </article>
            ) : null}
            {item && item.hours != null ? (
              <article>
                <em>Hours</em>
                <strong>{item.hours}h</strong>
              </article>
            ) : null}
          </div>
        )}

        {selectedCell.possible > 0 ? (
          <div className="lux-att-cal__density">
            <div className="lux-att-cal__density-head">
              <span>Team presence</span>
              <strong>
                {selectedCell.present}/{selectedCell.possible} · {densityPct}%
              </strong>
            </div>
            <div className="lux-att-cal__density-track" aria-hidden="true">
              <span style={{ width: `${Math.max(densityPct, selectedCell.present ? 8 : 0)}%` }} />
            </div>
          </div>
        ) : (
          <div className="lux-att-cal__insight-card is-slate">
            <i
              className={
                selectedCell.meta.isHoliday || holidayInfo
                  ? "fe fe-flag"
                  : selectedCell.meta.isWeekend
                    ? "fe fe-moon"
                    : "fe fe-slash"
              }
              aria-hidden="true"
            />
            <div>
              <strong>
                {holidayInfo
                  ? holidayInfo.name
                  : selectedCell.meta.isHoliday
                    ? "Holiday"
                    : selectedCell.meta.isWeekend
                      ? "Non-working day"
                      : "No roster day"}
              </strong>
              <em>
                {holidayInfo && holidayInfo.marked
                  ? "Person marked this day as holiday via task activity"
                  : "Team density is not counted on off days"}
              </em>
            </div>
          </div>
        )}

        {stats ? (
          <div className="lux-att-cal__mini-stats">
            <span className="is-present">
              <strong>{stats.present}</strong>
              <em>Present</em>
            </span>
            <span className="is-absent">
              <strong>{stats.absent}</strong>
              <em>Absent</em>
            </span>
            <span className="is-rate">
              <strong>{stats.rate}%</strong>
              <em>Rate</em>
            </span>
          </div>
        ) : null}

        <div className="lux-att-cal__rail-actions">
          {canView && onRequestViewDetails && focusEmployee ? (
            <button
              type="button"
              className="lux-att-cal__rail-btn is-primary"
              onClick={() =>
                onRequestViewDetails(
                  focusEmployee.id,
                  focusEmployee.name,
                  selectedCell.day,
                  selectedCell.focusItem
                )
              }
            >
              <i className="fe fe-eye" aria-hidden="true" />
              Open details
            </button>
          ) : null}
          {!canView && canMark && onRequestMark && focusEmployee && !selectedCell.meta.isFuture ? (
            <button
              type="button"
              className="lux-att-cal__rail-btn is-primary"
              onClick={() =>
                onRequestMark(focusEmployee.id, focusEmployee.name, selectedCell.day)
              }
            >
              <i className="fe fe-plus" aria-hidden="true" />
              Mark attendance
            </button>
          ) : null}
          {leaveApplyPath && isViewingSelf ? (
            <NavLink className="lux-att-cal__rail-link" to={leaveApplyPath}>
              <i className="fe fe-calendar" aria-hidden="true" />
              Apply leave
            </NavLink>
          ) : null}
          {onRequestRegularize && isViewingSelf ? (
            <button
              type="button"
              className="lux-att-cal__rail-btn"
              onClick={() => onRequestRegularize(selectedCell.day, selectedCell.focusItem)}
            >
              <i className="fe fe-edit-2" aria-hidden="true" />
              Regularize
            </button>
          ) : null}
        </div>

        {focusEmployee ? (
          <p className="lux-att-cal__focus-hint">
            Focused on <strong>{focusEmployee.name}</strong>
          </p>
        ) : null}
      </div>
    );
  };

  render() {
    const {
      selectedDate,
      monthDays,
      employees,
      items,
      focusEmployee,
      focusEmployeeId,
      permission,
      currentUserId,
      isLoading,
      employeeFilterEmployees,
      selectedEmployeeId,
      onEmployeeFilterChange,
      workdays,
      holidayDates,
      activityHolidayItems,
      goToBack,
      goToCurrent,
      goToNext,
    } = this.props;
    const { selectedDayKey } = this.state;

    const calendar = buildAttendanceCalendarWeeks({
      selectedDate,
      monthDays,
      employees,
      items,
      focusEmployeeId: focusEmployeeId || (focusEmployee && focusEmployee.id),
      workdays,
      holidayDates,
      activityHolidayItems,
    });
    const stats = focusEmployee && getEmployeeStats(focusEmployee.id, items, monthDays);
    const pulse = monthPulse(calendar, stats);
    const selectedCell =
      calendar.weeks.flat().find((cell) => cell.key === selectedDayKey) ||
      calendar.weeks.flat().find((cell) => cell.inMonth && cell.meta.isToday) ||
      null;
    const canMark = canMarkAttendanceFor(
      permission,
      focusEmployee && focusEmployee.id,
      currentUserId
    );

    return (
      <section
        className="lux-att-cal lux-admin-atelier lux-admin-atelier--attendance"
        data-testid="attendance-calendar-view"
        aria-label="Attendance calendar"
      >
        <div className="lux-att-cal__glow" aria-hidden="true" />
        <header className="lux-att-cal__masthead">
          <div className="lux-att-cal__masthead-main">
            <div>
              <p className="lux-att-cal__eyebrow">Presence atelier</p>
              <h2 className="lux-att-cal__title">{calendar.monthLabel}</h2>
              <p className="lux-att-cal__lede">
                Rich month canvas for{" "}
                <strong>{focusEmployee ? focusEmployee.name : "your team"}</strong> — mark,
                review, and feel team density at a glance
              </p>
            </div>
          </div>
          <div className="lux-att-cal__masthead-aside">
            <AttendanceEmployeeFilter
              employees={employeeFilterEmployees || employees}
              selectedEmployeeId={selectedEmployeeId}
              onChange={onEmployeeFilterChange}
              isLoading={isLoading}
            />
          </div>
        </header>

        <div className="lux-att-cal__command">
          <div className="lux-att-cal__strip">
            {this.renderFocus(focusEmployee, stats, canMark)}
            {this.renderQuickActions(selectedCell)}
            {this.renderMonthNav()}
          </div>
          {this.renderPulse(pulse)}
        </div>

        <div className="lux-att-cal__body">
          <div className="lux-att-cal__stage">
            {this.renderLegend()}

            <div
              className="lux-att-cal__grid"
              role="grid"
              aria-label={`${calendar.monthLabel} attendance`}
            >
              <div className="lux-att-cal__weekdays" role="row">
                {ATTENDANCE_CALENDAR_WEEKDAYS.map((label) => (
                  <span key={label} role="columnheader">
                    {label}
                  </span>
                ))}
              </div>
              {calendar.weeks.map((week, wi) => (
                <div key={`week-${wi}`} className="lux-att-cal__week" role="row">
                  {week.map((cell) => {
                    const interactive =
                      !!focusEmployee && cell.inMonth && !cell.meta.isFuture && !isLoading;
                    const leaveLocked = isAttendanceLeave(cell.focusItem);
                    const holidayInfo = cell.holidayInfo;
                    const isSelected =
                      (selectedDayKey || (selectedCell && selectedCell.key)) === cell.key;
                    const chipTone =
                      holidayInfo && holidayInfo.marked
                        ? "holiday-marked"
                        : holidayInfo
                          ? "holiday"
                          : cell.statusMeta.tone;
                    return (
                      <button
                        key={cell.key}
                        type="button"
                        role="gridcell"
                        className={classNames("lux-att-cal__cell", {
                          "is-out": !cell.inMonth,
                          "is-today": cell.meta.isToday,
                          "is-future": cell.meta.isFuture,
                          "is-weekend": cell.meta.isWeekend && !cell.meta.isHoliday && !holidayInfo,
                          "is-holiday": Boolean(cell.meta.isHoliday || holidayInfo),
                          "is-holiday-marked": Boolean(holidayInfo && holidayInfo.marked),
                          "is-selected": isSelected,
                          "is-clickable": interactive,
                          [`is-${cell.statusMeta.tone}`]: cell.inMonth && !holidayInfo,
                          [`is-density-${densityTone(cell.density)}`]:
                            cell.inMonth && cell.possible > 0,
                        })}
                        disabled={!interactive}
                        onClick={() => this.handleDayActivate(cell)}
                        aria-label={`${cell.statusMeta.label} ${cell.day.format("MMM D")}${
                          leaveLocked ? " (leave)" : ""
                        }${holidayInfo ? ` (${holidayInfo.name})` : ""}`}
                        data-testid={`att-cal-day-${cell.key}`}
                      >
                        <span className="lux-att-cal__cell-top">
                          <span className="lux-att-cal__day-num">{cell.day.format("D")}</span>
                          {cell.meta.isToday ? (
                            <span className="lux-att-cal__cell-today">Now</span>
                          ) : null}
                          {holidayInfo && holidayInfo.marked ? (
                            <span className="lux-att-cal__holiday-mark is-marked" title="Marked holiday">
                              <i className="fe fe-sun" aria-hidden="true" />
                            </span>
                          ) : cell.meta.isHoliday || holidayInfo ? (
                            <span className="lux-att-cal__holiday-mark is-org" title="Organization holiday">
                              <i className="fe fe-flag" aria-hidden="true" />
                            </span>
                          ) : null}
                        </span>
                        {cell.inMonth ? (
                          <>
                            <span
                              className={classNames(
                                "lux-att-cal__day-chip",
                                `is-${chipTone}`
                              )}
                            >
                              <i
                                className={
                                  holidayInfo
                                    ? holidayInfo.marked
                                      ? "fe fe-sun"
                                      : "fe fe-flag"
                                    : cell.statusMeta.icon
                                }
                                aria-hidden="true"
                              />
                              <em>
                                {holidayInfo
                                  ? holidayInfo.name
                                  : cell.statusMeta.label}
                              </em>
                            </span>
                            {cell.possible > 0 ? (
                              <span className="lux-att-cal__day-team">
                                <span
                                  className="lux-att-cal__day-bar"
                                  aria-hidden="true"
                                >
                                  <i style={{ width: `${Math.min(100, Math.max(cell.density * 100, 6))}%` }} />
                                </span>
                                <em>
                                  {cell.present}/{cell.possible}
                                </em>
                              </span>
                            ) : (
                              <span
                                className={classNames("lux-att-cal__day-team is-muted", {
                                  "is-holiday-caption": Boolean(holidayInfo || cell.meta.isHoliday),
                                  "is-marked": Boolean(holidayInfo && holidayInfo.marked),
                                })}
                              >
                                {holidayInfo
                                  ? holidayInfo.marked
                                    ? "Marked"
                                    : "Holiday"
                                  : cell.meta.isHoliday
                                    ? "Holiday"
                                    : cell.meta.isFuture
                                      ? cell.meta.isWeekend
                                        ? "Off day"
                                        : "Upcoming"
                                      : cell.meta.isWeekend
                                        ? "Off day"
                                        : "—"}
                              </span>
                            )}
                          </>
                        ) : null}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>

          <aside className="lux-att-cal__rail" aria-label="Day details">
            {this.renderSelectedRail(
              selectedDayKey
                ? calendar.weeks.flat().find((cell) => cell.key === selectedDayKey)
                : selectedCell,
              stats,
              pulse
            )}
          </aside>
        </div>
      </section>
    );
  }
}

export default AttendanceCalendarView;
