//https://gist.github.com/Godofbrowser/bf118322301af3fc334437c683887c5f - auth refresh parallel call
import Axios from "axios";
import { store, commonUtils, userUtils } from "../_helpers";
import { authGetItem, authSetItem } from "./authStorage.utils";
import { trackEvent, sanitizeApiUrl } from "./analytics.utils";
import { returnUrlUtils } from "./returnUrl.utils";
import envconfig from "env.config";
import urlConfig from "url.config";
import { notificationActions, userActions } from "../_actions";
import { normalizeApiError } from "./apiError.utils";

export const axiosUtils = {
  get,
  getWithParam,
  post,
  remove,
  put,
  patch,
};

const { dispatch } = store;

function getRequestHeaders() {
  let currentUser = commonUtils.getCurrentUser();
  let currentActiveTeamId = localStorage.getItem("currentActiveTeamId");
  if (currentUser) {
    return {
      headers: {
        Uid: currentUser.id,
        "Current-User-Team-Id": currentUser.userTeamId,
        "Current-Active-Team-Id":
          currentActiveTeamId === null
            ? currentUser.userTeamId
            : currentActiveTeamId,
        "Request-Origin": "gi",
      },
    };
  }
}
Axios.defaults.timeout = envconfig.API_TIMEOUT_MS || 60000;
Axios.defaults.API_KEY = envconfig.API_KEY;

/**
 * Spring MVC binds repeated keys (`userTeamIds=1&userTeamIds=2`).
 * Axios default serializes arrays as `userTeamIds[]=1`, which Spring ignores → empty scope / 403.
 */
function serializeParamsForSpring(params) {
  if (!params || typeof params !== "object") {
    return "";
  }
  const parts = [];
  Object.keys(params).forEach((key) => {
    const value = params[key];
    if (value === undefined || value === null) {
      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item) => {
        if (item === undefined || item === null) {
          return;
        }
        parts.push(
          `${encodeURIComponent(key)}=${encodeURIComponent(String(item))}`
        );
      });
      return;
    }
    parts.push(
      `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`
    );
  });
  return parts.join("&");
}
Axios.interceptors.request.use(
  (config) => {
    config.params = config.params || {};
    config.params["api-key"] = config.API_KEY;
    config.headers["content-type"] = "application/json";
    config.headers["login-type"] = userUtils.getLoginType();
    config.headers["email"] = userUtils.getCurrentUserEmail();
    const webWearchParams = new URLSearchParams(window.location.search);
    const tk = webWearchParams.get("tk");
    if (isWhiteListUrl() && isWhiteListApi(config.url) && tk !== null) {
      config.headers = {
        ...config.headers,
        tk: tk,
      };
    }

    const authTokenRaw = authGetItem("authToken");
    let authToken = authTokenRaw != null ? JSON.parse(authTokenRaw) : null;
    if (authToken != null) {
      config.headers.Authorization = "Bearer " + authToken;
    }
    if (envconfig.ENV !== "prod") {
      console.log("REQUEST API " + config.url);
    }
    return config;
  },
  async (error) => {
    //console.log('Request was not send ' + error);
    return Promise.reject(error);
  }
);

let isRefreshing = false;
let failedQueue = [];
let consecutiveNetworkFailures = 0;
let networkFailureResetTimer = null;

const NETWORK_FAILURE_THRESHOLD = 2;
const NETWORK_FAILURE_WINDOW_MS = 12000;

const processQueue = (error, token = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });

  failedQueue = [];
};

function isWhiteListUrl() {
  const webPathName = window.location.pathname;
  return (
    urlConfig.witelistUrls.filter((url) => webPathName.includes(url)).length > 0
  );
}

function isWhiteListApi(configUrl) {
  return (
    urlConfig.witelistApis.filter((url) => configUrl.includes(url)).length > 0
  );
}

function isRequestTimeout(error) {
  if (!error || error.response) {
    return false;
  }
  if (error.code === "ECONNABORTED") {
    return true;
  }
  const message = String(error.message || "").toLowerCase();
  return message.includes("timeout");
}

function isBackendConnectionFailure(error) {
  if (!error || isRequestTimeout(error)) {
    return false;
  }
  const status = error.response && error.response.status;
  if (status === 502 || status === 503 || status === 504) {
    return true;
  }
  if (error.response) {
    return false;
  }
  if (error.code === "ERR_NETWORK") {
    return true;
  }
  return error.message === "Network Error";
}

let lastTimeoutNotificationAt = 0;
const TIMEOUT_NOTIFICATION_DEBOUNCE_MS = 8000;

function dispatchTimeoutNotification(error) {
  const now = Date.now();
  if (now - lastTimeoutNotificationAt < TIMEOUT_NOTIFICATION_DEBOUNCE_MS) {
    return;
  }
  lastTimeoutNotificationAt = now;
  const apiPath =
    error && error.config && error.config.url
      ? sanitizeApiUrl(error.config.url)
      : "API request";
  dispatch(
    notificationActions.warning(
      `Request timed out (${apiPath}). The server is taking longer than expected — try again in a moment.`
    )
  );
}

function resetNetworkFailureCounter() {
  consecutiveNetworkFailures = 0;
  if (networkFailureResetTimer) {
    clearTimeout(networkFailureResetTimer);
    networkFailureResetTimer = null;
  }
}

function registerNetworkFailure() {
  consecutiveNetworkFailures += 1;
  if (networkFailureResetTimer) {
    clearTimeout(networkFailureResetTimer);
  }
  networkFailureResetTimer = setTimeout(() => {
    consecutiveNetworkFailures = 0;
    networkFailureResetTimer = null;
  }, NETWORK_FAILURE_WINDOW_MS);
  return consecutiveNetworkFailures >= NETWORK_FAILURE_THRESHOLD;
}

function shouldDispatchConnectionError(error) {
  if (!isBackendConnectionFailure(error)) {
    return false;
  }
  const status = error.response && error.response.status;
  if (status === 502 || status === 503 || status === 504) {
    return true;
  }
  return registerNetworkFailure();
}

function clearConnectionErrorIfNeeded() {
  resetNetworkFailureCounter();
  const hasConnectionError = store.getState().notification
    && store.getState().notification.connectionError;
  if (hasConnectionError) {
    dispatch(notificationActions.clearConnectionError());
  }
}

function dispatchConnectionError() {
  dispatch(notificationActions.clear());
  dispatch(notificationActions.connectionError());
}

function createAxiosResponseInterceptor() {
  //console.log('Initializing interceptor');
  const interceptor = Axios.interceptors.response.use(
    (response) => {
      clearConnectionErrorIfNeeded();
      const config = response && response.config;
      if (config && config.url) {
        const method = (config.method || 'get').toUpperCase();
        trackEvent('api_request', 'api', `${method} ${sanitizeApiUrl(config.url)}`, response.status, {
          api_method: method,
          api_url: sanitizeApiUrl(config.url),
          api_status: response.status,
        });
      }
      return response;
    },
    async (error) => {
      const originalRequest = error.config;
      if (
        error.response &&
        error.response.status === 401 &&
        !originalRequest._retry &&
        originalRequest.url.indexOf("/users/") === -1 &&
        originalRequest.url.indexOf("/authrefresh") === -1 &&
        !isWhiteListUrl()
      ) {
        //Axios.interceptors.response.eject(interceptor);

        if (isRefreshing) {
          return new Promise(function (resolve, reject) {
            failedQueue.push({ resolve, reject });
          })
            .then((token) => {
              originalRequest.headers["Authorization"] = "Bearer " + token;
              return Axios(originalRequest);
            })
            .catch((err) => {
              return Promise.reject(err);
            });
        }

        originalRequest._retry = true;
        isRefreshing = true;

        //console.log('Refreshing auth token');
        authSetItem("authToken", authGetItem("authRefreshToken"));
        return new Promise((resolve, reject) => {
          Axios.get(
            envconfig.BACK_END_API_ENDPOINT +
              urlConfig.USER_AUTH_REFRESH +
              "/" +
              commonUtils.getCurrentUserId(),
            {}
          )
            .then(
              (res) => {
                authSetItem("cu", res.data.payload.encryptedEmployee);
                authSetItem("ac", res.data.payload.accessControl);
                authSetItem(
                  "authToken",
                  JSON.stringify(res.data.payload.authToken)
                );
                authSetItem(
                  "authRefreshToken",
                  JSON.stringify(res.data.payload.authRefreshToken)
                );
                //error.response.config.headers.Authorization = 'Bearer ' + res.data.payload.authToken;
                //resolve(Axios(error.response.config));
                processQueue(null, res.data.payload.authToken);
                resolve(Axios(originalRequest));
              },
              (error) => {
                if (error.response && error.response.status === 401) {
                  returnUrlUtils.saveReturnUrlFromWindow();
                  userActions.logout();
                  window.location.reload();
                }
              }
            )
            .catch((err) => {
              processQueue(err, null);
              reject(err);

              returnUrlUtils.saveReturnUrlFromWindow();
              userActions.logout();
              window.location.reload();
            })
            .finally(() => {
              isRefreshing = false;
            });
        });
      } else if (isRequestTimeout(error)) {
        dispatchTimeoutNotification(error);
      } else if (shouldDispatchConnectionError(error)) {
        dispatchConnectionError();
      }
      if (
        error.response &&
        error.response.status === 412 &&
        error.response.data
      ) {
        return Promise.reject(normalizeApiError(error));
      }
      return Promise.reject(normalizeApiError(error));
    }
  );
}
createAxiosResponseInterceptor();

function insertBasicInfoToBody(requestBody) {
  let currentUser = commonUtils.getCurrentUser();
  const safeBody = requestBody && typeof requestBody === "object" ? requestBody : {};

  if (currentUser != null) {
    return {
      ...safeBody,
      createdBy: currentUser.id,
      userTeamId: currentUser.userteamId,
      modifiedBy: currentUser.id,
    };
  }
  return safeBody;
}

async function post(relativeUrl, requestBody) {
  try {
    const response = await Axios.post(
      envconfig.BACK_END_API_ENDPOINT + relativeUrl,
      insertBasicInfoToBody(requestBody),
      getRequestHeaders()
    );
    return await handleResponse(response);
  } catch (error) {
    // Re-throw so callers (actions) can surface the real failure.
    // Previously Axios errors were swallowed and callers treated "Network error" as success.
    return Promise.reject(normalizeApiError(error));
  }
}

async function get(relativeUrl) {
  try {
    const response = await Axios.get(
      envconfig.BACK_END_API_ENDPOINT + relativeUrl,
      getRequestHeaders()
    );
    return await handleResponse(response);
  } catch (error) {
    return Promise.reject(normalizeApiError(error));
  }
}

async function getWithParam(relativeUrl, params) {
  let requestBody = {
    headers: getRequestHeaders().headers,
    params: params,
    paramsSerializer: serializeParamsForSpring,
  };
  const response = await Axios.get(
    envconfig.BACK_END_API_ENDPOINT + relativeUrl,
    requestBody
  );
  return await handleResponse(response);
}
async function remove(relativeUrl) {
  try {
    const response = await Axios.delete(
      envconfig.BACK_END_API_ENDPOINT + relativeUrl,
      getRequestHeaders()
    );
    return await handleResponse(response);
  } catch (error) {
    return Promise.reject(normalizeApiError(error));
  }
}
async function put(relativeUrl, requestBody) {
  const response = await Axios.put(
    envconfig.BACK_END_API_ENDPOINT + relativeUrl,
    insertBasicInfoToBody(requestBody),
    getRequestHeaders()
  );
  return await handleResponse(response);
}

async function patch(relativeUrl, requestBody) {
  const response = await Axios.patch(
    envconfig.BACK_END_API_ENDPOINT + relativeUrl,
    insertBasicInfoToBody(requestBody || {}),
    getRequestHeaders()
  );
  return await handleResponse(response);
}

function handleResponse(response) {
  if (response && response.status === 500) {
    window.location = "/error/error500";
    return "Network error";
  } else if (response && response.status !== 200 && response.status !== 201) {
    const payload = response.data || {};
    const errorList = payload.error || (payload.payload && payload.payload.error);
    const firstError = Array.isArray(errorList) ? errorList[0] : errorList;
    const message =
      (firstError && typeof firstError === "object" && firstError.message) ||
      (typeof firstError === "string" ? firstError : null) ||
      `Request failed with status ${response.status}`;
    return Promise.reject(normalizeApiError(message));
  } else if (!response) {
    return "Network error";
  }
  return response.data;
}
