import React, { Component, createContext } from "react";
import { accessUtils, authGetItem, history } from "_helpers";
import envconfig from "env.config";
import { personaService } from "_services/persona.service";
import { navigationService } from "_services/navigation.service";
import {
  buildClientPersonaContext,
  isValidPersonaContextPayload,
  normalizeApiPersonaContext,
  PERSONA_DEFAULT_SCOPE,
  getScopeLabel,
  resolveMaskingPolicyForPersona,
  PERSONA_LANDING_ROUTES,
} from "config/persona-context.utils";
import {
  resolveAllowedPersonas,
  setActivePersona,
  clearActivePersona,
  PERSONA_CONTEXT_CHANGED,
  isPersonaSwitchEnabled,
  getPersonaLabel,
} from "config/persona-navigation.utils";
import { loadPersonaPageMapFromAppConfig } from "config/persona-page-map.config";
import {
  filterPersonasByOrgPolicy,
  ORG_ACCESS_POLICY_CHANGED,
} from "config/org-access-policy.config";
import { loadTracopusPilotConfig } from "config/tracopus-pilot.config";

export const PersonaContext = createContext(null);

const defaultState = {
  isLoading: true,
  error: null,
  context: null,
  menuAccessControl: null,
};

/**
 * P00-T5: App-wide persona context. Fetches API when enabled; falls back to client derivation.
 */
class PersonaContextProvider extends Component {
  state = { ...defaultState };

  componentDidMount() {
    this.loadPersonaContext();
    this._storageListener = (event) => {
      if (event.key === "cu" && !event.newValue) {
        this.handleLogout();
      }
    };
    this._orgPolicyListener = () => {
      this.applyOrgAccessPolicyToContext();
    };
    window.addEventListener("storage", this._storageListener);
    window.addEventListener(ORG_ACCESS_POLICY_CHANGED, this._orgPolicyListener);
  }

  componentWillUnmount() {
    window.removeEventListener("storage", this._storageListener);
    window.removeEventListener(ORG_ACCESS_POLICY_CHANGED, this._orgPolicyListener);
  }

  /**
   * Re-apply org kill switches (disabled personas/paths/modules) without a full
   * navigation reload so the header switcher updates immediately after Save.
   */
  applyOrgAccessPolicyToContext = () => {
    const { menuAccessControl, context } = this.state;
    if (!menuAccessControl || !context) {
      this.loadPersonaContext();
      return;
    }
    const prevActive = context.activePersona;
    let nextContext;
    if (context.source === "api") {
      nextContext = normalizeApiPersonaContext(
        {
          ...context,
          activePersona: prevActive,
          allowedPersonas: context.allowedPersonas,
        },
        menuAccessControl
      );
    } else {
      nextContext = buildClientPersonaContext(menuAccessControl, prevActive);
    }
    setActivePersona(nextContext.activePersona, nextContext.allowedPersonas);
    this.setState({ context: nextContext });
    window.dispatchEvent(new CustomEvent(PERSONA_CONTEXT_CHANGED, { detail: nextContext }));
    if (
      prevActive &&
      nextContext.activePersona &&
      nextContext.activePersona !== prevActive &&
      nextContext.landingRoute &&
      history.location.pathname !== nextContext.landingRoute
    ) {
      history.push(nextContext.landingRoute);
    }
  };

  handleLogout = () => {
    clearActivePersona();
    this.setState({ ...defaultState, isLoading: false, context: null });
  };

  loadPersonaContext = async () => {
    if (!authGetItem("cu")) {
      this.setState({ ...defaultState, isLoading: false });
      return;
    }

    accessUtils.reload();
    try {
      await loadTracopusPilotConfig();
    } catch (pilotErr) {
      console.warn("[PersonaContext] Tracopus pilot config load failed, using env/RBAC defaults.", pilotErr);
    }
    try {
      await loadPersonaPageMapFromAppConfig();
    } catch (mapErr) {
      console.warn("[PersonaContext] Persona page map load failed, using local defaults.", mapErr);
    }
    const clientMenuAccessControl = accessUtils.getMenuAccessControl();
    this.setState({ isLoading: true, error: null, menuAccessControl: clientMenuAccessControl });

    let menuAccessControl = clientMenuAccessControl;

    try {
      const navPayload = await navigationService.loadMergedMenuAccess(
        clientMenuAccessControl,
        null
      );
      if (navPayload && navPayload.menuAccessControl) {
        menuAccessControl = navPayload.menuAccessControl;
      }
    } catch (navErr) {
      console.warn("[PersonaContext] Navigation menu load failed, using client RBAC.", navErr);
    }

    if (envconfig.USE_PERSONA_API === true) {
      try {
        const apiPayload = await personaService.getPersonaContext();
        const context = normalizeApiPersonaContext(apiPayload, menuAccessControl);
        setActivePersona(context.activePersona, context.allowedPersonas);
        this.setState({ isLoading: false, context, menuAccessControl, error: null });
        return;
      } catch (err) {
        // Fall through to client derivation when API is not yet deployed.
        console.warn("[PersonaContext] API unavailable, using client derivation.", err);
      }
    }

    const context = buildClientPersonaContext(menuAccessControl);
    this.setState({ isLoading: false, context, menuAccessControl, error: null });
  };

  applyPersonaContext = (nextContext) => {
    if (!nextContext) {
      return;
    }
    setActivePersona(nextContext.activePersona, nextContext.allowedPersonas);
    this.setState({ context: nextContext });
    window.dispatchEvent(
      new CustomEvent(PERSONA_CONTEXT_CHANGED, { detail: nextContext })
    );
    const landingRoute = nextContext.landingRoute;
    if (landingRoute && history.location.pathname !== landingRoute) {
      history.push(landingRoute);
    }
  };

  resolveEffectiveAllowedPersonas(context, menuAccessControl) {
    const clientAllowed = resolveAllowedPersonas(menuAccessControl);
    if (!context || !Array.isArray(context.allowedPersonas) || context.allowedPersonas.length === 0) {
      return filterPersonasByOrgPolicy(clientAllowed);
    }
    return filterPersonasByOrgPolicy([...new Set([...context.allowedPersonas, ...clientAllowed])]);
  }

  switchPersona = async (persona) => {
    const { context, menuAccessControl } = this.state;
    if (!isPersonaSwitchEnabled(menuAccessControl)) {
      return false;
    }
    const allowedPersonas = this.resolveEffectiveAllowedPersonas(context, menuAccessControl);
    if (!context || !allowedPersonas.includes(persona)) {
      return false;
    }

    if (envconfig.USE_PERSONA_API === true) {
      try {
        const apiPayload = await personaService.switchPersona(persona);
        if (!isValidPersonaContextPayload(apiPayload)) {
          throw new Error("Invalid persona switch response");
        }
        const nextContext = normalizeApiPersonaContext(apiPayload, menuAccessControl);
        this.applyPersonaContext(nextContext);
        return true;
      } catch (err) {
        console.warn("[PersonaContext] Persona switch API failed, using client switch.", err);
      }
    }

    if (!setActivePersona(persona, allowedPersonas)) {
      return false;
    }

    const nextContext = buildClientPersonaContext(menuAccessControl, persona);
    this.applyPersonaContext(nextContext);
    return true;
  };

  refreshPersonaContext = () => {
    this.loadPersonaContext();
  };

  render() {
    const { children } = this.props;
    const { context, isLoading, error, menuAccessControl } = this.state;
    const allowedPersonas = context
      ? filterPersonasByOrgPolicy(context.allowedPersonas || [])
      : [];
    let activePersona = context ? context.activePersona : null;
    if (activePersona && allowedPersonas.length > 0 && !allowedPersonas.includes(activePersona)) {
      activePersona = allowedPersonas[0];
    }

    const personaForcedOff = Boolean(
      context && activePersona && context.activePersona !== activePersona
    );
    const value = {
      context,
      isLoading,
      error,
      menuAccessControl,
      activePersona,
      activePersonaLabel: activePersona
        ? personaForcedOff
          ? getPersonaLabel(activePersona)
          : context.activePersonaLabel
        : null,
      allowedPersonas,
      personaSwitchEnabled: context
        ? context.personaSwitchEnabled !== false && allowedPersonas.length > 1
        : true,
      scopeType: personaForcedOff
        ? PERSONA_DEFAULT_SCOPE[activePersona] || "SELF"
        : context
          ? context.scopeType
          : null,
      scopeLabel: personaForcedOff
        ? getScopeLabel(PERSONA_DEFAULT_SCOPE[activePersona] || "SELF")
        : context
          ? context.scopeLabel
          : null,
      maskingPolicy: personaForcedOff
        ? resolveMaskingPolicyForPersona(activePersona)
        : context
          ? context.maskingPolicy
          : {},
      landingRoute: personaForcedOff
        ? PERSONA_LANDING_ROUTES[activePersona] || "/project/dashboard"
        : context
          ? context.landingRoute
          : null,
      switchPersona: this.switchPersona,
      refreshPersonaContext: this.refreshPersonaContext,
    };

    return (
      <PersonaContext.Provider value={value}>
        {children}
      </PersonaContext.Provider>
    );
  }
}

export default PersonaContextProvider;
