import React, { Component } from "react";
import classNames from "classnames/bind";
import { summarizeRegularizationPending } from "config/attendance-regularization.utils";
import { getExceptionTypeLabel } from "config/attendance-regularization.config";
import AttendanceApprovalCommentField from "./AttendanceApprovalCommentField";
import { getPendingInboxEyebrow } from "_helpers/approvalAuthority.utils";

function formatPunchWindow(request) {
  const inTime = request.requestedInTime || "—";
  const outTime = request.requestedOutTime || "—";
  return `${inTime} → ${outTime}`;
}

function getExceptionIcon(exceptionType) {
  switch (String(exceptionType || "").toUpperCase()) {
    case "MISSING_PUNCH":
      return "fe fe-alert-circle";
    case "LATE_ARRIVAL":
      return "fe fe-sunrise";
    case "EARLY_DEPARTURE":
      return "fe fe-sunset";
    case "WRONG_SHIFT":
      return "fe fe-shuffle";
    case "WORK_FROM_HOME":
      return "fe fe-home";
    case "ON_DUTY_TRAVEL":
      return "fe fe-map-pin";
    case "OUTDOOR":
      return "fe fe-cloud";
    default:
      return "fe fe-edit-3";
  }
}

export default class RegularizationPendingApprovals extends Component {
  state = { comments: {}, rejectErrors: {}, collapsed: false, collapsedEmployees: {} };

  getComment = (id) => this.state.comments[id] || "";

  setComment = (id, value) => {
    this.setState((prev) => ({
      comments: { ...prev.comments, [id]: value },
      rejectErrors: value.trim() ? {} : prev.rejectErrors,
    }));
  };

  toggleCollapsed = () => {
    this.setState((prev) => ({ collapsed: !prev.collapsed }));
  };

  isEmployeeCollapsed = (employeeId) => !!this.state.collapsedEmployees[String(employeeId)];

  toggleEmployeeCollapsed = (employeeId) => {
    const key = String(employeeId);
    this.setState((prev) => ({
      collapsedEmployees: {
        ...prev.collapsedEmployees,
        [key]: !prev.collapsedEmployees[key],
      },
    }));
  };

  handleApprove = (request) => {
    const { onApprove, isLoading } = this.props;
    if (isLoading || !onApprove || request.payrollLocked) return;
    onApprove(request, this.getComment(request.id).trim() || null);
  };

  handleReject = (request) => {
    const { onReject, isLoading } = this.props;
    if (isLoading || !onReject) return;
    const comment = this.getComment(request.id).trim();
    if (!comment) {
      this.setState({ rejectErrors: { [request.id]: "Add a rejection comment." } });
      return;
    }
    onReject(request, comment);
  };

  renderCollapsedSummary = (summary) => (
    <button
      type="button"
      className="lux-att-reg-pending__collapsed-bar"
      onClick={this.toggleCollapsed}
      aria-expanded="false"
      aria-label={`${summary.total} pending regularization requests. Click to expand.`}
    >
      <span className="lux-att-reg-pending__collapsed-icon" aria-hidden="true">
        <i className="fe fe-edit-3" />
      </span>
      <span className="lux-att-reg-pending__collapsed-copy">
        <strong>
          {summary.total} regularization request{summary.total === 1 ? "" : "s"} need your review
        </strong>
        <em>
          {summary.employeeCount} team member{summary.employeeCount === 1 ? "" : "s"}
        </em>
      </span>
      <span className="lux-att-reg-pending__count">{summary.total}</span>
      <span className="lux-att-reg-pending__collapsed-expand">
        Expand
        <i className="fe fe-chevron-down" aria-hidden="true" />
      </span>
    </button>
  );

  renderEmployeeMeta = (group) =>
    [
      group.empCode ? `Code ${group.empCode}` : null,
      group.employeeId != null ? `ID ${group.employeeId}` : null,
      `${group.items.length} request${group.items.length === 1 ? "" : "s"}`,
    ]
      .filter(Boolean)
      .join(" · ");

  render() {
    const { pending, employees, isLoading, actingDelegations } = this.props;
    const summary = summarizeRegularizationPending(pending, employees);
    const { collapsed } = this.state;
    const eyebrow = getPendingInboxEyebrow(actingDelegations);

    if (!summary.total) return null;

    if (collapsed) {
      return (
        <section
          className="lux-att-reg-pending lux-att-reg-pending--collapsed"
          aria-label="Pending regularization approvals"
        >
          {this.renderCollapsedSummary(summary)}
        </section>
      );
    }

    return (
      <section className="lux-att-reg-pending" aria-label="Pending regularization approvals">
        <div className="lux-att-reg-pending__glow" aria-hidden="true" />
        <header className="lux-att-reg-pending__head">
          <div>
            {eyebrow && <span className="lux-att-reg-pending__eyebrow">{eyebrow}</span>}
            <h3>Regularization approvals</h3>
            <p>
              {summary.total} request{summary.total === 1 ? "" : "s"} · {summary.employeeCount}{" "}
              employee{summary.employeeCount === 1 ? "" : "s"}
            </p>
          </div>
          <div className="lux-att-reg-pending__head-actions">
            <span className="lux-att-reg-pending__count">{summary.total}</span>
            <button
              type="button"
              className="lux-att-reg-pending__toggle"
              onClick={this.toggleCollapsed}
              aria-expanded="true"
              aria-label="Collapse regularization approvals"
            >
              Collapse
            </button>
          </div>
        </header>

        <div className="lux-att-reg-pending__list">
          {summary.groups.map((group) => {
            const employeeCollapsed = this.isEmployeeCollapsed(group.employeeId);
            return (
              <div
                key={group.employeeId}
                className={classNames("lux-att-reg-pending__group", {
                  "is-collapsed": employeeCollapsed,
                })}
              >
                <button
                  type="button"
                  className="lux-att-reg-pending__employee"
                  onClick={() => this.toggleEmployeeCollapsed(group.employeeId)}
                  aria-expanded={!employeeCollapsed}
                  aria-label={`${employeeCollapsed ? "Expand" : "Collapse"} ${group.employeeName}`}
                >
                  <span className="lux-att-reg-pending__employee-avatar" aria-hidden="true">
                    {(group.employeeName || "?").charAt(0).toUpperCase()}
                  </span>
                  <span className="lux-att-reg-pending__employee-copy">
                    <strong>{group.employeeName}</strong>
                    <em>{this.renderEmployeeMeta(group)}</em>
                  </span>
                  <span className="lux-att-reg-pending__employee-count" aria-hidden="true">
                    {group.items.length}
                  </span>
                  <i
                    className={classNames(
                      "lux-att-reg-pending__employee-chevron",
                      employeeCollapsed ? "fe fe-chevron-down" : "fe fe-chevron-up"
                    )}
                    aria-hidden="true"
                  />
                </button>

                {!employeeCollapsed &&
                  group.items.map((request) => (
                    <article
                      key={request.id}
                      className={classNames("lux-att-reg-pending__card", {
                        "is-locked": !!request.payrollLocked,
                        "has-conflict": !!request.timesheetConflict,
                      })}
                    >
                      <div className="lux-att-reg-pending__card-main">
                        <span className="lux-att-reg-pending__type-icon" aria-hidden="true">
                          <i className={getExceptionIcon(request.exceptionType)} />
                        </span>
                        <div className="lux-att-reg-pending__card-copy">
                          <div className="lux-att-reg-pending__card-title-row">
                            <strong>{getExceptionTypeLabel(request.exceptionType)}</strong>
                            <div className="lux-att-reg-pending__flags">
                              {request.payrollLocked && (
                                <span className="lux-att-reg-pending__flag is-lock">
                                  <i className="fe fe-lock" aria-hidden="true" />
                                  Locked
                                </span>
                              )}
                              {request.timesheetConflict && (
                                <span className="lux-att-reg-pending__flag is-conflict">
                                  <i className="fe fe-alert-triangle" aria-hidden="true" />
                                  Conflict
                                </span>
                              )}
                            </div>
                          </div>
                          <span className="lux-att-reg-pending__meta">
                            <i className="fe fe-calendar" aria-hidden="true" />
                            {request.markDate}
                            <span className="lux-att-reg-pending__meta-sep" aria-hidden="true">
                              ·
                            </span>
                            <i className="fe fe-clock" aria-hidden="true" />
                            {formatPunchWindow(request)}
                          </span>
                          <p className="lux-att-reg-pending__reason">
                            {request.reason || "No reason provided"}
                          </p>
                        </div>
                      </div>

                      <AttendanceApprovalCommentField
                        value={this.getComment(request.id)}
                        onChange={(value) => this.setComment(request.id, value)}
                        disabled={isLoading}
                        required
                        error={this.state.rejectErrors[request.id]}
                        id={`lux-att-reg-pending-comment-${request.id}`}
                      />

                      <div className="lux-att-reg-pending__actions">
                        <button
                          type="button"
                          className={classNames("lux-att-reg-pending__btn is-primary", {
                            "is-loading": isLoading,
                          })}
                          disabled={isLoading || !!request.payrollLocked}
                          title={request.payrollLocked ? "Payroll period is locked" : undefined}
                          onClick={() => this.handleApprove(request)}
                        >
                          Approve
                        </button>
                        <button
                          type="button"
                          className={classNames("lux-att-reg-pending__btn is-danger", {
                            "is-loading": isLoading,
                          })}
                          disabled={isLoading}
                          onClick={() => this.handleReject(request)}
                        >
                          Reject
                        </button>
                      </div>
                    </article>
                  ))}
              </div>
            );
          })}
        </div>
      </section>
    );
  }
}
