import React from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip, AdminQuickNav } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export default function ExpensesLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo expense data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  testId,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "green",
    icon: "fe fe-credit-card",
    eyebrow: "Expenses",
    titleLead: "Expense",
    titleAccent: "workspace",
    lede: "Claims, approvals, and reimbursements",
  };

  return (
    <div
      className={classNames("lux-register-page", "lux-expense-module", "lux-expense-lux", meta.tone && `is-${meta.tone}`)}
      {...(testId ? { "data-testid": testId } : {})}
    >
      <div className="lux-expense-lux__ambient" aria-hidden="true">
        <span className="lux-expense-lux__orb lux-expense-lux__orb--a" />
        <span className="lux-expense-lux__orb lux-expense-lux__orb--b" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-expense-lux__kpi-strip" />
        ) : null}

        <div className="lux-expense-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function ExpenseActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames(
    "lux-onb-action",
    "lux-expense-action",
    `lux-onb-action--${variant}`,
    className
  );
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function ExpenseLuxPanel({ title, meta, icon, accent, actions, children }) {
  return (
    <section className={classNames("lux-hrms-dash__panel", "lux-expense-lux__panel", accent && `is-${accent}`)}>
      <header className="lux-hrms-dash__panel-head lux-expense-lux__panel-head">
        <div className="lux-expense-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-expense-lux__panel-body">{children}</div>
    </section>
  );
}

export function ExpenseInsightPanel({ insights = [] }) {
  return <AdminInsightStrip insights={insights} className="lux-expense-lux__insights" />;
}

export function ExpenseQuickNav({ links = [], eyebrow = "Expense drill-down" }) {
  return <AdminQuickNav eyebrow={eyebrow} links={links} className="lux-expense-lux__quick-nav" />;
}
