import {
  API_KEY_STATUSES,
  APP_REGISTRY_STATUSES,
  MARKETPLACE_LISTING_STATUSES,
  WEBHOOK_DELIVERY_STATUSES,
  WEBHOOK_STATUSES,
  isCatalogApiKeyScope,
} from "config/developer-portal.config";

export function normalizeApiKey(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled key",
    prefix: row.prefix || "",
    scopes: (Array.isArray(row.scopes) ? row.scopes : []).filter(isCatalogApiKeyScope),
    status: row.status || API_KEY_STATUSES.ACTIVE,
    createdAt: row.createdAt || null,
    lastUsedAt: row.lastUsedAt || null,
    requestCount: Number(row.requestCount) || 0,
    ownerName: row.ownerName || "",
    appName: row.appName || "",
    tone: row.tone || "indigo",
  };
}

export function normalizeWebhookSubscription(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled webhook",
    url: row.url || "",
    events: row.events || [],
    status: row.status || WEBHOOK_STATUSES.ACTIVE,
    successRate: Number(row.successRate) || 0,
    lastDeliveryAt: row.lastDeliveryAt || null,
    secretRotatedAt: row.secretRotatedAt || null,
    tone: row.tone || "violet",
  };
}

export function normalizeWebhookDelivery(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    subscriptionId: row.subscriptionId,
    subscriptionName: row.subscriptionName || "",
    eventType: row.eventType || "",
    status: row.status || WEBHOOK_DELIVERY_STATUSES.SUCCESS,
    httpStatus: Number(row.httpStatus) || 0,
    durationMs: Number(row.durationMs) || 0,
    deliveredAt: row.deliveredAt || null,
    errorMessage: row.errorMessage || "",
    tone: row.tone || "slate",
  };
}

export function normalizeMarketplaceListing(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled listing",
    vendor: row.vendor || "",
    category: row.category || "",
    description: row.description || "",
    status: row.status || MARKETPLACE_LISTING_STATUSES.PUBLISHED,
    installCount: Number(row.installCount) || 0,
    rating: Number(row.rating) || 0,
    certified: row.certified === true,
    installed: row.installed === true,
    tone: row.tone || "emerald",
  };
}

export function normalizeAppRegistryEntry(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled app",
    listingId: row.listingId || "",
    status: row.status || APP_REGISTRY_STATUSES.INSTALLED,
    environment: row.environment || "production",
    installedAt: row.installedAt || null,
    apiCalls30d: Number(row.apiCalls30d) || 0,
    webhookCount: Number(row.webhookCount) || 0,
    ownerName: row.ownerName || "",
    tone: row.tone || "cyan",
  };
}

export function filterApiKeys(rows, filters) {
  const list = (rows || []).map(normalizeApiKey).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    if (f.query) {
      const q = String(f.query).toLowerCase();
      const hay = `${row.name} ${row.appName} ${row.prefix}`.toLowerCase();
      if (hay.indexOf(q) === -1) {
        return false;
      }
    }
    return true;
  });
}

export function filterWebhooks(rows, filters) {
  const list = (rows || []).map(normalizeWebhookSubscription).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    return true;
  });
}

export function filterWebhookDeliveries(rows, filters) {
  const list = (rows || []).map(normalizeWebhookDelivery).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.subscriptionId && row.subscriptionId !== f.subscriptionId) {
      return false;
    }
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    return true;
  });
}

export function filterMarketplaceListings(rows, filters) {
  const list = (rows || []).map(normalizeMarketplaceListing).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.category && f.category !== "ALL" && row.category !== f.category) {
      return false;
    }
    if (f.installedOnly && !row.installed) {
      return false;
    }
    if (f.query) {
      const q = String(f.query).toLowerCase();
      const hay = `${row.name} ${row.vendor} ${row.description}`.toLowerCase();
      if (hay.indexOf(q) === -1) {
        return false;
      }
    }
    return true;
  });
}

export function buildDeveloperPortalKpiCards(keys, webhooks, apps, listings) {
  const activeKeys = (keys || []).filter((row) => row.status === API_KEY_STATUSES.ACTIVE).length;
  const activeHooks = (webhooks || []).filter((row) => row.status === WEBHOOK_STATUSES.ACTIVE).length;
  const installedApps = (apps || []).filter((row) => row.status === APP_REGISTRY_STATUSES.INSTALLED).length;
  const certifiedListings = (listings || []).filter((row) => row.certified).length;
  return [
    { id: "keys", label: "Active API keys", value: String(activeKeys), hint: "Scoped credentials", tone: "indigo" },
    { id: "webhooks", label: "Webhook subscriptions", value: String(activeHooks), hint: "Event delivery", tone: "violet" },
    { id: "apps", label: "Installed apps", value: String(installedApps), hint: "Registry entries", tone: "cyan" },
    { id: "marketplace", label: "Certified listings", value: String(certifiedListings), hint: "Marketplace catalog", tone: "emerald" },
  ];
}

export function buildDeveloperPortalInsights(keys, webhooks, deliveries) {
  const failedDeliveries = (deliveries || []).filter((row) => row.status === WEBHOOK_DELIVERY_STATUSES.FAILED).length;
  const staleKeys = (keys || []).filter((row) => !row.lastUsedAt).length;
  const degradedHooks = (webhooks || []).filter((row) => row.successRate > 0 && row.successRate < 95).length;
  const insights = [];
  if (failedDeliveries) {
    insights.push({
      id: "failed-deliveries",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${failedDeliveries} webhook deliveries failed recently`,
      detail: "Inspect delivery logs and rotate secrets if endpoints changed.",
    });
  }
  if (degradedHooks) {
    insights.push({
      id: "degraded-hooks",
      tone: "amber",
      icon: "fe fe-activity",
      title: `${degradedHooks} subscriptions below 95% success`,
      detail: "Review endpoint health and retry policies.",
    });
  }
  if (staleKeys) {
    insights.push({
      id: "stale-keys",
      tone: "blue",
      icon: "fe fe-key",
      title: `${staleKeys} API keys never used`,
      detail: "Revoke unused credentials to reduce exposure.",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "emerald",
      icon: "fe fe-check-circle",
      title: "Extensibility platform healthy",
      detail: "API usage, webhooks, and marketplace installs are within expected ranges.",
    });
  }
  return insights;
}

export function buildDeveloperPortalAnalytics(keys, deliveries) {
  const totalRequests = (keys || []).reduce((sum, row) => sum + (Number(row.requestCount) || 0), 0);
  const successDeliveries = (deliveries || []).filter((row) => row.status === WEBHOOK_DELIVERY_STATUSES.SUCCESS).length;
  const failedDeliveries = (deliveries || []).filter((row) => row.status === WEBHOOK_DELIVERY_STATUSES.FAILED).length;
  const deliveryTotal = successDeliveries + failedDeliveries;
  return {
    totalApiRequests: totalRequests,
    webhookSuccessRate: deliveryTotal ? Math.round((successDeliveries / deliveryTotal) * 100) : 100,
    webhookFailureRate: deliveryTotal ? Math.round((failedDeliveries / deliveryTotal) * 100) : 0,
    topScopes: buildScopeDistribution(keys),
  };
}

export function normalizeDeveloperPortalAnalytics(analytics, keys) {
  const fallback = buildDeveloperPortalAnalytics(keys || [], []);
  if (!analytics || typeof analytics !== "object") {
    return fallback;
  }
  const topScopes = Array.isArray(analytics.topScopes)
    ? analytics.topScopes
        .map((row) => ({
          label: row && row.label != null ? String(row.label) : "",
          count: Number(row && row.count) || 0,
        }))
        .filter((row) => row.label)
    : fallback.topScopes;
  return {
    totalApiRequests: Number(analytics.totalApiRequests) || 0,
    webhookSuccessRate: Number(analytics.webhookSuccessRate) || 0,
    webhookFailureRate: Number(analytics.webhookFailureRate) || 0,
    topScopes,
  };
}

export function normalizeDeveloperPortalOverview(payload) {
  const raw = payload && typeof payload === "object" && !Array.isArray(payload) ? payload : {};
  const keys = (raw.keys || []).map(normalizeApiKey).filter(Boolean);
  const webhooks = (raw.webhooks || []).map(normalizeWebhookSubscription).filter(Boolean);
  const apps = (raw.apps || []).map(normalizeAppRegistryEntry).filter(Boolean);
  const listings = (raw.listings || []).map(normalizeMarketplaceListing).filter(Boolean);
  const deliveries = (raw.deliveries || []).map(normalizeWebhookDelivery).filter(Boolean);
  return {
    keys,
    webhooks,
    apps,
    listings,
    deliveries,
    kpiCards:
      Array.isArray(raw.kpiCards) && raw.kpiCards.length
        ? raw.kpiCards
        : buildDeveloperPortalKpiCards(keys, webhooks, apps, listings),
    insights:
      Array.isArray(raw.insights) && raw.insights.length
        ? raw.insights
        : buildDeveloperPortalInsights(keys, webhooks, deliveries),
    analytics: normalizeDeveloperPortalAnalytics(raw.analytics, keys),
  };
}

function buildScopeDistribution(keys) {
  const counts = {};
  (keys || []).forEach((row) => {
    (row.scopes || []).forEach((scope) => {
      counts[scope] = (counts[scope] || 0) + 1;
    });
  });
  return Object.keys(counts).map((label) => ({ label, count: counts[label] }));
}

export function exportApiKeysCsv(rows) {
  const header = "id,name,prefix,status,scopes,requestCount,lastUsedAt";
  const lines = (rows || []).map((row) => {
    const normalized = normalizeApiKey(row);
    return [
      normalized.id,
      normalized.name,
      normalized.prefix,
      normalized.status,
      (normalized.scopes || []).join("|"),
      normalized.requestCount,
      normalized.lastUsedAt || "",
    ].join(",");
  });
  return [header].concat(lines).join("\n");
}
