import React from "react";
import classNames from "classnames/bind";

function LuxCreateFieldGroup({ title, description, children, columns = 2, className }) {
  return (
    <div className={classNames("lux-create-field-group", className)}>
      {(title || description) && (
        <header className="lux-create-field-group__head">
          {title && <h4 className="lux-create-field-group__title">{title}</h4>}
          {description && <p className="lux-create-field-group__desc">{description}</p>}
        </header>
      )}
      <div
        className={classNames("lux-create-field-group__grid", {
          "lux-create-field-group__grid--3": columns === 3,
          "lux-create-field-group__grid--1": columns === 1,
        })}
      >
        {children}
      </div>
    </div>
  );
}

export function LuxCreateField({ span = 1, children, className }) {
  return (
    <div
      className={classNames("lux-create-field", className, {
        "lux-create-field--span-2": span === 2,
        "lux-create-field--span-full": span === "full",
      })}
    >
      <div className="lux-create-field__inner">{children}</div>
    </div>
  );
}

export default LuxCreateFieldGroup;
