import React from 'react';
import { Link } from 'react-router-dom';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const ADMIN_BASE = '/admin/leave/absence-cases';
const PEOPLE_BASE = '/people/leave/absence-cases';
const EMPTY_CASE = {
  employeeId: '',
  caseType: 'LONG_TERM',
  expectedStart: '',
  expectedEnd: '',
};

class AbsenceCasesPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    cases: [],
    rtwCases: [],
    saving: false,
    caseForm: { ...EMPTY_CASE },
  };

  isWorkspace = () => this.props.location.pathname.startsWith('/people/');

  basePath = () => (this.isWorkspace() ? PEOPLE_BASE : ADMIN_BASE);

  fetchSectionData = async (teamId) => {
    const employeeId = this.isWorkspace() ? this.actorId() : null;
    const cases = (await api.listAbsenceCases(teamId, employeeId)) || [];
    const list = Array.isArray(cases) ? cases : [];
    const rtwCases = list.filter((c) => {
      const s = String(c.status || c.caseStatus || '').toUpperCase();
      return s.includes('RTW') || s.includes('RETURN') || c.returnToWorkRequired === true;
    });
    this.setState({ cases: list, rtwCases });
  };

  openCase = (event) => {
    event.preventDefault();
    const { caseForm } = this.state;
    const employeeId = Number(caseForm.employeeId);
    if (!employeeId) {
      this.setState({ error: 'Employee ID is required.' });
      return;
    }
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .createAbsenceCase({
        userTeamId: teamId,
        actorId: this.actorId(),
        employeeId,
        caseType: caseForm.caseType || 'LONG_TERM',
        expectedStart: caseForm.expectedStart || null,
        expectedEnd: caseForm.expectedEnd || null,
        status: 'OPEN',
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Absence case opened.',
          caseForm: { ...EMPTY_CASE },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not open case.'),
        });
      });
  };

  render() {
    const { loading, cases, rtwCases, caseForm, saving } = this.state;
    const path = this.props.location.pathname;
    const showRtw = path.includes('return-to-work');
    const rows = showRtw ? rtwCases : cases;
    const base = this.basePath();
    const isAdmin = !this.isWorkspace();

    const kpiCards = [
      { id: 'cases', label: 'Open cases', value: cases.length, tone: 'primary', icon: 'fe fe-briefcase' },
      { id: 'rtw', label: 'RTW pending', value: rtwCases.length, tone: 'amber', icon: 'fe fe-check-circle' },
    ];

    return this.renderChrome({
      testId: 'page-leave-absence-cases',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-briefcase',
        eyebrow: this.isWorkspace() ? 'My work · Leave' : 'Admin · Leave',
        titleLead: 'Absence',
        titleAccent: 'Cases',
        lede: 'Long-term leave, intermittent absence, and return-to-work registers — minimal open-case form; detail writes via API where forms are absent.',
      },
      children: (
        <>
          {isAdmin ? (
            <nav className="lux-glp-tabs" aria-label="Absence sections">
              <Link
                to={ADMIN_BASE}
                className={`lux-glp-tab${!showRtw ? ' is-active' : ''}`}
              >
                <i className="fe fe-list" aria-hidden="true" /> All cases
              </Link>
              <Link
                to="/admin/leave/return-to-work"
                className={`lux-glp-tab${showRtw ? ' is-active' : ''}`}
              >
                <i className="fe fe-check-circle" aria-hidden="true" /> Return to work
              </Link>
            </nav>
          ) : null}
          {isAdmin && !showRtw ? (
            <LeavePhase2Panel title="Open case" subtitle="Minimal admin create — medical details stay masked." testId="glp17-open-case">
              <form className="lux-glp-form" onSubmit={this.openCase} data-testid="glp17-open-case-form">
                <label>
                  Employee ID
                  <input
                    required
                    value={caseForm.employeeId}
                    onChange={(e) =>
                      this.setState({ caseForm: { ...caseForm, employeeId: e.target.value } })
                    }
                  />
                </label>
                <label>
                  Case type
                  <select
                    value={caseForm.caseType}
                    onChange={(e) =>
                      this.setState({ caseForm: { ...caseForm, caseType: e.target.value } })
                    }
                  >
                    <option value="LONG_TERM">Long-term</option>
                    <option value="INTERMITTENT">Intermittent</option>
                    <option value="REDUCED_SCHEDULE">Reduced schedule</option>
                  </select>
                </label>
                <label>
                  Start
                  <input
                    type="date"
                    value={caseForm.expectedStart}
                    onChange={(e) =>
                      this.setState({ caseForm: { ...caseForm, expectedStart: e.target.value } })
                    }
                  />
                </label>
                <label>
                  End
                  <input
                    type="date"
                    value={caseForm.expectedEnd}
                    onChange={(e) =>
                      this.setState({ caseForm: { ...caseForm, expectedEnd: e.target.value } })
                    }
                  />
                </label>
                <div className="lux-glp-form__actions">
                  <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                    Open case
                  </AdminActionButton>
                </div>
              </form>
            </LeavePhase2Panel>
          ) : null}
          <LeavePhase2Panel
            title={showRtw ? 'Return-to-work queue' : 'Absence case register'}
            subtitle={
              showRtw
                ? 'Cases awaiting fit-to-work clearance and RTW documentation.'
                : 'Confidential case timeline with masked medical summaries.'
            }
            testId="glp17-cases"
          >
            <LeavePhase2Register
              loading={loading}
              rows={rows}
              testId="glp17-cases-register"
              emptyTitle={showRtw ? 'No RTW cases' : 'No absence cases'}
              emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
              columns={[
                { key: 'id', label: 'Case' },
                { key: 'employeeId', label: 'Employee' },
                { key: 'caseType', label: 'Type', render: (r) => cell(r.caseType || r.absenceType) },
                { key: 'status', label: 'Status' },
                { key: 'startDate', label: 'Start', render: (r) => cell(r.startDate || r.expectedStart) },
                {
                  key: 'actions',
                  label: '',
                  render: (r) =>
                    r.id ? (
                      <Link to={`${base}/${r.id}`} className="lux-leave-register__action">
                        Open
                      </Link>
                    ) : null,
                },
              ]}
            />
          </LeavePhase2Panel>
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(AbsenceCasesPage));
