import {
  COMPLIANCE_PACK_SECTIONS,
  getCompliancePackSectionMeta,
  normalizeCompliancePackSection,
} from "config/compliance-pack.config";

export function buildCompliancePackMetrics(sections) {
  const rows = (sections || []).map(normalizeCompliancePackSection).filter(Boolean);
  const ready = rows.filter((row) => row.ready);
  const records = rows.reduce((sum, row) => sum + (row.recordCount || 0), 0);
  const readinessPct = rows.length > 0 ? Math.round((ready.length / rows.length) * 100) : 0;

  return {
    totalSections: rows.length,
    readySections: ready.length,
    recordCount: records,
    readinessPct,
    notReady: rows.length - ready.length,
  };
}

export function buildCompliancePackInsights(sections, selectedIds = []) {
  const rows = (sections || []).map(normalizeCompliancePackSection).filter(Boolean);
  const metrics = buildCompliancePackMetrics(rows);
  const insights = [];
  const selected = selectedIds.length > 0 ? selectedIds : rows.map((row) => row.id);
  const notReady = rows.filter((row) => selected.includes(row.id) && !row.ready);

  if (notReady.length > 0) {
    insights.push({
      id: "gaps",
      tone: "amber",
      icon: "fe fe-alert-triangle",
      title: `${notReady.length} section(s) need attention`,
      copy: "Resolve data gaps before submitting to auditors.",
    });
  }

  if (metrics.readinessPct >= 90) {
    insights.push({
      id: "ready",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${metrics.readinessPct}% compliance readiness`,
      copy: "Selected domains are aligned for export.",
    });
  } else if (metrics.readinessPct > 0) {
    insights.push({
      id: "partial",
      tone: "blue",
      icon: "fe fe-activity",
      title: `${metrics.readinessPct}% pack readiness`,
      copy: "Include additional sections to improve coverage.",
    });
  }

  const largeSections = rows.filter((row) => row.recordCount > 1000);
  if (largeSections.length > 0) {
    insights.push({
      id: "volume",
      tone: "violet",
      icon: "fe fe-database",
      title: `${largeSections.length} high-volume section(s)`,
      copy: "Large exports may take longer to assemble.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "baseline",
      tone: "slate",
      icon: "fe fe-download",
      title: "Compliance pack ready",
      copy: "Select sections and generate your regulator export.",
    });
  }

  return insights.slice(0, 3);
}

export function buildComplianceReadinessSeries(sections) {
  const rows = (sections || []).map(normalizeCompliancePackSection).filter(Boolean);
  const ready = rows.filter((row) => row.ready).length;
  const notReady = rows.length - ready;
  return [
    { id: "ready", label: "Ready", value: ready, tone: "green" },
    { id: "gaps", label: "Gaps", value: notReady, tone: "amber" },
  ].filter((row) => row.value > 0);
}

export function buildComplianceVolumeSeries(sections) {
  return (sections || [])
    .map(normalizeCompliancePackSection)
    .filter(Boolean)
    .map((row) => ({
      id: row.id,
      label: row.label,
      value: row.recordCount || 0,
      tone: row.tone || "slate",
    }))
    .filter((row) => row.value > 0)
    .sort((a, b) => b.value - a.value)
    .slice(0, 6);
}

export function filterCompliancePackSections(sections, query = "") {
  const normalizedQuery = String(query || "").trim().toLowerCase();
  return (sections || [])
    .map(normalizeCompliancePackSection)
    .filter(Boolean)
    .filter((row) => {
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [row.label, row.description, row.id].join(" ").toLowerCase();
      return haystack.includes(normalizedQuery);
    });
}

export function toggleComplianceSectionSelection(selectedIds, sectionId) {
  const set = new Set(selectedIds || []);
  if (set.has(sectionId)) {
    set.delete(sectionId);
  } else {
    set.add(sectionId);
  }
  return Array.from(set);
}

export function assembleCompliancePackManifest(sections, selectedIds, packPayload) {
  const selected = (selectedIds || []).filter((id) => COMPLIANCE_PACK_SECTIONS[id]);
  const exportedAt = new Date().toISOString();
  return {
    schemaVersion: "1.0",
    product: "Tracopus",
    packType: "compliance-export",
    exportedAt,
    sectionCount: selected.length,
    sections: selected.map((id) => {
      const row = (sections || []).find((item) => item.id === id);
      return {
        id,
        label: getCompliancePackSectionMeta(id).label,
        recordCount: (row && row.recordCount) || 0,
        checksum: (row && row.checksum) || null,
      };
    }),
    data: packPayload || {},
  };
}

export function downloadCompliancePackJson(manifest, filename) {
  const json = JSON.stringify(manifest, null, 2);
  const blob = new Blob([json], { type: "application/json;charset=utf-8;" });
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename || `tracopus-compliance-pack-${new Date().toISOString().slice(0, 10)}.json`;
  link.click();
  window.URL.revokeObjectURL(url);
}

export function simpleChecksum(value) {
  const str = JSON.stringify(value || "");
  let hash = 0;
  for (let i = 0; i < str.length; i += 1) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return `cp-${Math.abs(hash).toString(16)}`;
}
