import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
const BASE = `${urlConfig.WORKSPACE_API_PATH}/notification-templates`;

function teamQueryString(extra = {}) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId(), ...extra };
  return Object.keys(query)
    .filter((key) => query[key] != null && query[key] !== "")
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

export const notificationTemplateService = {
  listTemplates,
  saveTemplate,
  deleteTemplate,
  previewTemplate,
  sendTestTemplate,
};

async function listTemplates() {
  const response = await axiosUtils.getWithParam(BASE, {
    userTeamId: commonUtils.getCurrentUserTeamId(),
  });
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function saveTemplate(payload) {
  const response = await axiosUtils.post(
    `${BASE}?${teamQueryString({ actorId: commonUtils.getCurrentUserId(), adminPersona: true })}`,
    payload
  );
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function deleteTemplate(templateRef) {
  const response = await axiosUtils.remove(
    `${BASE}/${encodeURIComponent(templateRef)}?${teamQueryString({ adminPersona: true })}`
  );
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function previewTemplate(payload) {
  const response = await axiosUtils.post(`${BASE}/preview?${teamQueryString()}`, payload || {});
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function sendTestTemplate(payload) {
  const response = await axiosUtils.post(
    `${BASE}/send-test?${teamQueryString({ actorId: commonUtils.getCurrentUserId(), adminPersona: true })}`,
    payload || {}
  );
  return { payload: (response && response.payload) || response || {}, source: "api" };
}
