import React, { Component } from "react";
import { recruitingService } from "_services/recruiting/recruiting.service";
import RecruitingLuxPage, {
  RecruitingActionButton,
  RecruitingLuxPanel,
} from "views/recruiting/components/RecruitingLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class OffersPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    saving: false,
    form: { candidateRef: "", title: "", roleTitle: "" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Offers");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await recruitingService.listOffers();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load offers"),
      });
    }
  };

  runOfferAction = async (actionPromise, failLabel) => {
    this.setState({ loadError: null });
    const result = await actionPromise;
    if (result && result.source === "api") {
      await this.load();
      return;
    }
    this.setState({
      loadError: (result && result.error) || new Error(failLabel),
    });
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.candidateRef) return;
    this.setState({ saving: true });
    const result = await recruitingService.createOfferFromCandidate({
      candidateRef: form.candidateRef,
      title: form.title || null,
      roleTitle: form.roleTitle || null,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { candidateRef: "", title: "", roleTitle: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  render() {
    const { loading, loadError, rows, saving, form } = this.state;
    return (
      <RecruitingLuxPage
        testId="recruiting-offers-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        onRefresh={this.load}
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-award",
          eyebrow: "People · ATS",
          titleLead: "Offer",
          titleAccent: "management",
          lede: "Accept creates an onboarding case only — Employee is created later via HR-ONB convert.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Offer action unavailable">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <RecruitingLuxPanel title="Create offer from candidate" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.handleCreate}>
            <div className="form-row">
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Candidate ref"
                  value={form.candidateRef}
                  onChange={(e) => this.setState({ form: { ...form, candidateRef: e.target.value } })}
                />
              </div>
              <div className="col-md-3">
                <input
                  className="form-control"
                  placeholder="Offer title"
                  value={form.title}
                  onChange={(e) => this.setState({ form: { ...form, title: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <input
                  className="form-control"
                  placeholder="Role title"
                  value={form.roleTitle}
                  onChange={(e) => this.setState({ form: { ...form, roleTitle: e.target.value } })}
                />
              </div>
              <div className="col-md-2">
                <RecruitingActionButton type="submit" disabled={saving}>
                  Create from candidate
                </RecruitingActionButton>
              </div>
            </div>
          </form>
        </RecruitingLuxPanel>
        <RecruitingLuxPanel title="Offers" meta={`${rows.length} record${rows.length === 1 ? "" : "s"}`} icon="fe fe-list">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && rows.length === 0 ? (
            <LuxRegisterEmptyState
              title="No offers yet"
              description="Create an offer from a candidate to begin approval."
              showCreate={false}
            />
          ) : !loading ? (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Candidate id</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((o) => (
                    <tr key={o.offerRef || o.id}>
                      <td>{o.offerRef}</td>
                      <td>{o.title}</td>
                      <td>{o.candidateId || "—"}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(o.status || "draft").toLowerCase()}`}>
                          {o.status || "Draft"}
                        </span>
                      </td>
                      <td>
                        {(o.status === "DRAFT" || o.status === "OPEN" || o.status === "SUBMITTED") && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              this.runOfferAction(
                                recruitingService.approveOffer(o.offerRef),
                                "Unable to approve offer"
                              )
                            }
                          >
                            Approve
                          </RecruitingActionButton>
                        )}
                        {o.status === "APPROVED" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              this.runOfferAction(
                                recruitingService.acceptOffer(o.offerRef),
                                "Unable to accept offer — onboarding was not created"
                              )
                            }
                          >
                            Accept → onboarding
                          </RecruitingActionButton>
                        )}
                        {o.status !== "ACCEPTED" && o.status !== "DECLINED" && (
                          <RecruitingActionButton
                            type="button"
                            variant="ghost"
                            className="lux-onb-action--compact"
                            onClick={() =>
                              this.runOfferAction(
                                recruitingService.declineOffer(o.offerRef),
                                "Unable to decline offer"
                              )
                            }
                          >
                            Decline
                          </RecruitingActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </RecruitingLuxPanel>
      </RecruitingLuxPage>
    );
  }
}

export default OffersPage;
