export function isMaskingPolicyAdminEnabled() {
  return shouldUseMaskingPolicyAdmin();
}

export function normalizeMaskingPolicyRule(row) {
  if (!row) {
    return null;
  }
  const levels = row.levels && typeof row.levels === "object" ? row.levels : {};
  return {
    id: row.id,
    fieldKey: row.fieldKey || row.id,
    name: row.name || row.fieldKey || "Field",
    domain: row.domain || "People",
    levels,
    exportLevel: row.exportLevel || MASKING_LEVELS.MASKED,
    exportRestricted: row.exportRestricted === true,
    risk: row.risk || "medium",
    owner: row.owner || "Compliance",
    description: row.description || "",
    updatedAt: row.updatedAt || null,
  };
}
