import React from "react";
import classNames from "classnames/bind";
import { buildAssetAnalyticsRows } from "config/asset-register.utils";

export default function AssetAnalyticsPanel({ metrics, assets }) {
  const chartRows = buildAssetAnalyticsRows(assets);
  const cards = [
    { id: "total", label: "Total assets", value: metrics.total || 0, hint: "Inventory", tone: "primary" },
    { id: "assigned", label: "Assigned", value: metrics.assigned || 0, hint: `${metrics.utilizationPct || 0}% utilization`, tone: "green" },
    { id: "available", label: "Available", value: metrics.available || 0, hint: "Ready to assign", tone: "slate" },
    { id: "warranty", label: "Warranty expiring", value: metrics.expiringWarranty || 0, hint: "Next 60 days", tone: "amber" },
  ];

  return (
    <div className="lux-asset-analytics">
      <div className="lux-hrms-dash__kpi-strip lux-asset-kpi-strip" role="list">
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-asset-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            <strong className="lux-hrms-dash__kpi-value">{card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>

      <div className="lux-asset-analytics__chart">
        <h3 className="lux-asset-analytics__title">Inventory by type</h3>
        {chartRows.length === 0 ? (
          <p className="lux-asset-analytics__empty">No asset data to chart yet.</p>
        ) : (
          <ul className="lux-asset-analytics__bars">
            {chartRows.map((row) => {
              const assignedPct = row.total ? Math.round((row.assigned / row.total) * 100) : 0;
              return (
                <li key={row.label} className="lux-asset-analytics__bar-row">
                  <div className="lux-asset-analytics__bar-label">
                    <span>{row.label}</span>
                    <strong>{row.total}</strong>
                  </div>
                  <div className="lux-asset-analytics__bar-track" aria-hidden="true">
                    <span style={{ width: `${assignedPct}%` }} />
                  </div>
                  <span className="lux-asset-analytics__bar-meta">{row.assigned} assigned · {row.available} available</span>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}
