import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { FinanceActionButton } from "views/finance/components/FinanceLuxShared";
import { formatFinanceUsd } from "config/finance-intelligence.utils";

const STATUS_TONE = {
  ACTIVE: "green",
  DRAFT: "slate",
  COMPLETED: "blue",
  CANCELLED: "rose",
};

const MS_TONE = {
  BILLED: "green",
  READY: "amber",
  OVERDUE: "rose",
  PLANNED: "slate",
};

const MILESTONE_STATUSES = ["PLANNED", "READY", "BILLED", "OVERDUE"];

export default function BillingPlansPanel({
  plans = [],
  projects = [],
  loading,
  filters = {},
  createForm = {},
  onFilterChange,
  onCreateFormChange,
  onCreatePlan,
  onUpdateMilestone,
  saving,
}) {
  return (
    <div className="lux-finance-snapshots">
      <div className="lux-finance-snapshots__toolbar">
        <div className="lux-finance-snapshots__filters">
          <label className="lux-finance-snapshots__field">
            <span>Search</span>
            <input
              type="search"
              placeholder="Plan or project…"
              value={filters.search || ""}
              onChange={(event) => onFilterChange({ search: event.target.value })}
            />
          </label>
          <label className="lux-finance-snapshots__field">
            <span>Status</span>
            <select value={filters.status || "ALL"} onChange={(event) => onFilterChange({ status: event.target.value })}>
              <option value="ALL">All statuses</option>
              <option value="ACTIVE">Active</option>
              <option value="DRAFT">Draft</option>
              <option value="COMPLETED">Completed</option>
            </select>
          </label>
        </div>
      </div>

      <div className="lux-finance-plan-create" data-testid="billing-plan-create-form">
        <label className="lux-finance-snapshots__field">
          <span>Live project</span>
          <select
            value={createForm.projectId || ""}
            onChange={(event) => onCreateFormChange({ projectId: event.target.value })}
            data-testid="billing-plan-project"
          >
            <option value="">Select project…</option>
            {projects.map((project) => (
              <option key={project.id} value={project.id}>
                {project.code ? `${project.code} · ` : ""}
                {project.name}
              </option>
            ))}
          </select>
        </label>
        <label className="lux-finance-snapshots__field">
          <span>Plan name</span>
          <input
            type="text"
            value={createForm.name || ""}
            placeholder="Milestone billing plan"
            onChange={(event) => onCreateFormChange({ name: event.target.value })}
          />
        </label>
        <label className="lux-finance-snapshots__field">
          <span>Total value (USD)</span>
          <input
            type="number"
            min="0"
            value={createForm.totalValueUsd || ""}
            placeholder="From PO est. cost when blank"
            onChange={(event) => onCreateFormChange({ totalValueUsd: event.target.value })}
          />
        </label>
        <label className="lux-finance-snapshots__field">
          <span>First milestone</span>
          <input
            type="text"
            value={createForm.milestoneName || ""}
            onChange={(event) => onCreateFormChange({ milestoneName: event.target.value })}
          />
        </label>
        <div className="lux-finance-toolbar__actions">
          <FinanceActionButton
            icon="fe fe-plus"
            variant="primary"
            onClick={onCreatePlan}
            disabled={saving || !createForm.projectId}
          >
            {saving ? "Saving…" : "New billing plan"}
          </FinanceActionButton>
        </div>
      </div>

      {loading ? (
        <div className="lux-finance-register__skeleton" aria-busy="true" />
      ) : !plans.length ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No billing plans"
          description="Select a live project and create a milestone billing plan linked to PO/Project."
        />
      ) : (
        <div className="lux-finance-plans">
          {plans.map((plan) => (
            <article key={plan.id} className="lux-finance-plan-card">
              <header>
                <div>
                  <strong>{plan.name}</strong>
                  <small>
                    {plan.projectName} · {(plan.recognitionMethod || "MILESTONE").replace(/_/g, " ")}
                    {plan.purchaseOrderNumber ? ` · PO ${plan.purchaseOrderNumber}` : ""}
                  </small>
                </div>
                <span className={classNames("lux-portfolio-badge", `is-${STATUS_TONE[plan.status] || "slate"}`)}>
                  {plan.status}
                </span>
              </header>
              <div className="lux-finance-plan-card__metrics">
                <div>
                  <span>Total value</span>
                  <strong>{formatFinanceUsd(plan.totalValueUsd)}</strong>
                </div>
                <div>
                  <span>Recognized (milestone)</span>
                  <strong>{formatFinanceUsd(plan.recognizedUsd)}</strong>
                </div>
                <div>
                  <span>Readiness</span>
                  <strong>{plan.readinessPct != null ? `${plan.readinessPct}%` : "—"}</strong>
                </div>
                <div>
                  <span>Next billing</span>
                  <strong>{plan.nextBillingDate || "—"}</strong>
                </div>
              </div>
              <ul className="lux-finance-plan-card__milestones">
                {(plan.milestones || []).map((ms) => (
                  <li key={ms.id}>
                    <span>{ms.name}</span>
                    <span>{formatFinanceUsd(ms.amountUsd)}</span>
                    <label className="lux-finance-snapshots__field lux-finance-snapshots__field--inline">
                      <span className="sr-only">Milestone status</span>
                      <select
                        value={ms.status || "PLANNED"}
                        disabled={saving}
                        onChange={(event) => onUpdateMilestone && onUpdateMilestone(plan, ms.id, event.target.value)}
                        data-testid={`billing-milestone-status-${ms.id}`}
                      >
                        {MILESTONE_STATUSES.map((status) => (
                          <option key={status} value={status}>
                            {status}
                          </option>
                        ))}
                      </select>
                    </label>
                    <span className={classNames("lux-portfolio-badge", `is-${MS_TONE[ms.status] || "slate"}`)}>
                      {ms.status}
                    </span>
                  </li>
                ))}
              </ul>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}
