/**
 * F20-T1 — Client audit write rollout (org auditEnabled + dev env override).
 */
import envconfig from "env.config";
import { isAuditOrgEnabled } from "_helpers/audit.config";

export const AUDIT_WRITE_CHANGED = "famstack-audit-write-changed";

export function shouldUseAuditWrite() {
  if (envconfig.AUDIT_WRITE_ENABLED === true) {
    return true;
  }
  return isAuditOrgEnabled();
}

export function shouldUseAuditWriteApi() {
  return envconfig.USE_AUDIT_WRITE_API === true && shouldUseAuditWrite();
}
