import React from "react";
import classNames from "classnames/bind";
import { enrichNotificationTemplateRows } from "config/notification-template.config";

function rowKey(row) {
  return row.templateRef || `${row.eventType || "evt"}-${row.channel || "EMAIL"}`;
}

/**
 * Compact luxury notification template register.
 */
export default function NotificationTemplateRegister({ templates, onView, onEdit, onClone }) {
  const rows = enrichNotificationTemplateRows(templates);

  return (
    <ul className="lux-ntpl-register lux-ntpl-register--compact" data-testid="ntpl-register">
      {rows.map((row) => {
        const open = () => (row.system ? onView && onView(row) : onEdit && onEdit(row));
        const key = rowKey(row);
        return (
          <li
            key={key}
            className={classNames("lux-ntpl-register__row", {
              "is-system": row.system,
              "is-override": !row.system,
              "is-disabled": !row.enabled,
            })}
          >
            <button
              type="button"
              className="lux-ntpl-register__main"
              onClick={open}
              onDoubleClick={open}
              data-testid={`ntpl-open-primary-${key}`}
            >
              <span
                className={classNames("lux-ntpl-register__avatar", `is-${row.family.tone}`)}
                aria-hidden="true"
              >
                <i className={row.family.icon} />
              </span>
              <span className="lux-ntpl-register__copy">
                <span className="lux-ntpl-register__meta">
                  <span className={classNames("lux-ntpl-pill", `is-${row.family.tone}`)}>
                    {row.family.label}
                  </span>
                  <span
                    className={classNames(
                      "lux-ntpl-pill",
                      row.system ? "is-sky" : "is-violet"
                    )}
                    title={row.sourceTip}
                  >
                    {row.sourceLabel}
                  </span>
                  <span className="lux-ntpl-pill is-slate">{row.channelLabel}</span>
                  <span
                    className={classNames(
                      "lux-ntpl-pill",
                      row.enabled ? "is-green" : "is-amber"
                    )}
                  >
                    {row.enabled ? "Enabled" : "Disabled"}
                  </span>
                </span>
                <strong className="lux-ntpl-register__title">{row.eventType || "—"}</strong>
                <em className="lux-ntpl-register__subject" title={row.subject || ""}>
                  {row.subject || "No subject line"}
                </em>
                <span className="lux-ntpl-register__ref" title={row.classpathTemplateName || row.templateRef || ""}>
                  {row.classpathTemplateName || row.templateRef || (row.system ? "Classpath default" : "Workspace override")}
                </span>
              </span>
            </button>

            <div className="lux-ntpl-register__actions">
              <button
                type="button"
                className="lux-ntpl-register__action"
                onClick={open}
                data-testid={`ntpl-open-${key}`}
                title={row.system ? "View system template" : "Edit org override"}
              >
                <i className={row.system ? "fe fe-eye" : "fe fe-edit-2"} aria-hidden="true" />
                {row.system ? "View" : "Edit"}
              </button>
              {row.system && typeof onClone === "function" ? (
                <button
                  type="button"
                  className="lux-ntpl-register__action is-secondary"
                  onClick={() => onClone(row)}
                  data-testid={`ntpl-clone-${key}`}
                  title="Create org override from this system default"
                >
                  <i className="fe fe-copy" aria-hidden="true" />
                  Clone
                </button>
              ) : null}
            </div>
          </li>
        );
      })}
    </ul>
  );
}
