import { shouldUseDocumentVault } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const DOCUMENT_TYPES = {
  CONTRACT: { id: "CONTRACT", label: "Employment agreement" },
  ID_PROOF: { id: "ID_PROOF", label: "ID proof" },
  WORK_AUTH: { id: "WORK_AUTH", label: "Work authorization" },
  TAX: { id: "TAX", label: "Tax document" },
  PAYROLL: { id: "PAYROLL", label: "Payroll form" },
  CERTIFICATION: { id: "CERTIFICATION", label: "Certification" },
  POLICY_ACK: { id: "POLICY_ACK", label: "Policy acknowledgment" },
  OTHER: { id: "OTHER", label: "Other" },
};

export const DOCUMENT_VISIBILITY = {
  EMPLOYEE: "EMPLOYEE",
  MANAGER: "MANAGER",
  HR_ONLY: "HR_ONLY",
  FINANCE_ONLY: "FINANCE_ONLY",
  ADMIN: "ADMIN",
};

export const DOCUMENT_STATUSES = {
  PENDING: "Pending review",
  VERIFIED: "Verified",
  REJECTED: "Rejected",
  EXPIRED: "Expired",
};

export const POLICY_ACK_STATUSES = {
  PENDING: "Pending",
  ACKNOWLEDGED: "Acknowledged",
  OVERDUE: "Overdue",
};

export function isDocumentVaultEnabled() {
  return shouldUseDocumentVault();
}

export function shouldUseDocumentVaultApi() {
  return envconfig.USE_DOCUMENT_VAULT_API === true;
}

export function getDocumentTypeLabel(typeId) {
  const meta = DOCUMENT_TYPES[typeId];
  return (meta && meta.label) || typeId || "Document";
}

export function normalizeDocument(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    title: row.title || "Untitled document",
    type: row.type || "OTHER",
    typeLabel: row.typeLabel || getDocumentTypeLabel(row.type),
    category: row.category || "",
    status: row.status || DOCUMENT_STATUSES.PENDING,
    visibility: row.visibility || DOCUMENT_VISIBILITY.HR_ONLY,
    version: row.version != null ? row.version : 1,
    uploadedAt: row.uploadedAt || null,
    uploadedBy: row.uploadedBy || "",
    expiresAt: row.expiresAt || null,
    verifiedAt: row.verifiedAt || null,
    verifiedBy: row.verifiedBy || "",
    fileName: row.fileName || "",
    fileSizeKb: row.fileSizeKb != null ? row.fileSizeKb : null,
    piiMasked: row.piiMasked === true,
    notes: row.notes || "",
    legalHold: row.legalHold === true,
    sourceEntityType: row.sourceEntityType || null,
    projectId: row.projectId || null,
  };
}

export function normalizePolicyAcknowledgment(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    policyId: row.policyId,
    title: row.title || "Policy",
    version: row.version || "1.0",
    status: row.status || POLICY_ACK_STATUSES.PENDING,
    dueDate: row.dueDate || null,
    acknowledgedAt: row.acknowledgedAt || null,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    assignedCount: row.assignedCount != null ? row.assignedCount : null,
    acknowledgedCount: row.acknowledgedCount != null ? row.acknowledgedCount : null,
    description: row.description || "",
  };
}
