/** Integration connections — Salesforce, ZingHR, email field metadata. */

export const LEGACY_CONNECTION_KEYS = {
  SALESFORCE: "salesforce",
  ZINGHR: "zinghr",
  EMAIL: "email",
};

export const LEGACY_CONNECTION_LABELS = {
  [LEGACY_CONNECTION_KEYS.SALESFORCE]: "Salesforce",
  [LEGACY_CONNECTION_KEYS.ZINGHR]: "ZingHR",
  [LEGACY_CONNECTION_KEYS.EMAIL]: "Email service",
};

export function summarizeConnectionConfig(connection) {
  const config = (connection && connection.config) || {};
  const runtime = (connection && connection.runtimeConfig) || {};
  switch (connection && connection.legacyKey) {
    case LEGACY_CONNECTION_KEYS.SALESFORCE:
      return config.host || runtime.host || "Host not set";
    case LEGACY_CONNECTION_KEYS.ZINGHR:
      return config.subscriptionName || runtime.subscriptionName || config.host || runtime.host || "Not configured";
    case LEGACY_CONNECTION_KEYS.EMAIL:
      return config.fromEmail || runtime.fromEmail || config.host || runtime.host || "SMTP not configured";
    default:
      return "—";
  }
}

export function isServerRuntimeConfigured(connection) {
  const runtime = (connection && connection.runtimeConfig) || {};
  return runtime.serverConfigured === true;
}
