import React from "react";
import classNames from "classnames/bind";
import LifecycleActionLink from "./LifecycleActionLink";

function getTemplateInitials(name = "") {
  return name
    .split(/[\s·]+/)
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function LifecycleTemplateCard({ template, lifecycle, onUse }) {
  const isOffboarding = lifecycle === "offboarding";

  return (
    <article
      className={classNames("lux-onb-template-card", {
        "lux-onb-template-card--exit": isOffboarding,
      })}
    >
      <div className="lux-onb-template-card__top">
        <div className="lux-onb-template-card__identity">
          <span className="lux-onb-template-card__icon" aria-hidden="true">
            {getTemplateInitials(template.name)}
          </span>
          <div className="lux-onb-template-card__head-copy">
            <h3 className="lux-onb-template-card__name">{template.name}</h3>
            <span className="lux-onb-template-card__code">{template.code}</span>
          </div>
        </div>
        <span className="lux-onb-template-card__count">
          <strong>{template.taskCount || 0}</strong>
          <span>tasks</span>
        </span>
      </div>

      {template.description && (
        <p className="lux-onb-template-card__desc">{template.description}</p>
      )}

      <div className="lux-onb-template-card__chips">
        <span>
          <i className="fe fe-briefcase" aria-hidden="true" />
          {template.department || "All departments"}
        </span>
        {template.roleFilter && (
          <span>
            <i className="fe fe-user" aria-hidden="true" />
            {template.roleFilter}
          </span>
        )}
        <span>
          <i className="fe fe-map-pin" aria-hidden="true" />
          {template.locationFilter || "Any location"}
        </span>
      </div>

      <footer className="lux-onb-template-card__foot">
        <span className="lux-onb-template-card__status">
          <i className="fe fe-check-circle" aria-hidden="true" />
          {template.active === false ? "Draft" : "Active template"}
        </span>
        <LifecycleActionLink variant="ghost" icon="fe-arrow-right" onClick={() => onUse(template.code)}>
          Use template
        </LifecycleActionLink>
      </footer>
    </article>
  );
}

export default function LifecycleTemplateCatalogGrid({ templates, loading, lifecycle, onUseTemplate }) {
  if (loading) {
    return (
      <div className="lux-onb-template-grid lux-onb-template-grid--loading" aria-busy="true">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-onb-template-card lux-onb-template-card--skeleton" />
        ))}
      </div>
    );
  }

  if (!templates.length) {
    return null;
  }

  return (
    <div className="lux-onb-template-grid">
      {templates.map((template) => (
        <LifecycleTemplateCard
          key={template.code}
          template={template}
          lifecycle={lifecycle}
          onUse={onUseTemplate}
        />
      ))}
    </div>
  );
}
