import React, { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { commonUtils } from "_helpers";
import envconfig from "env.config";
import {
  countTreeNodes,
  getConfigFlaggedItems,
  getConfigModuleStats,
  getOrgNodeIcon,
} from "./appConfigTree.utils";
import ApplicationConfigIdentityBar from "./ApplicationConfigIdentityBar";
import AppConfigFlagGuideModal from "views/common/AppConfigFlagGuideModal";
import { CONFIG_GUIDE_MODES } from "config/app-config-flag-guide.utils";
import { appConfigService } from "_services/appconfig.service";

function HeroStat({ icon, label, value, hint }) {
  return (
    <div className="lux-appconfig-hero__stat" title={hint || label}>
      <span className="lux-appconfig-hero__stat-icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </span>
      <span className="lux-appconfig-hero__stat-body">
        <strong>{value}</strong>
        <span>{label}</span>
      </span>
    </div>
  );
}

function ConfigFlagPopover({
  type,
  label,
  count,
  items,
  emptyMessage,
  icon,
  selectionKey,
}) {
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState(null);
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);

  const updatePosition = () => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    const width = 280;
    const left = Math.max(8, Math.min(rect.left, window.innerWidth - width - 8));

    setPosition({
      top: rect.bottom + 6,
      left,
      width,
    });
  };

  useEffect(() => {
    setOpen(false);
  }, [selectionKey]);

  useEffect(() => {
    if (!open) {
      setPosition(null);
      return undefined;
    }

    updatePosition();

    const handlePointer = (event) => {
      const inTrigger = triggerRef.current && triggerRef.current.contains(event.target);
      const inPopover = popoverRef.current && popoverRef.current.contains(event.target);
      if (!inTrigger && !inPopover) {
        setOpen(false);
      }
    };

    const handleEscape = (event) => {
      if (event.key === "Escape") setOpen(false);
    };

    const handleReposition = () => updatePosition();

    document.addEventListener("mousedown", handlePointer);
    document.addEventListener("keydown", handleEscape);
    window.addEventListener("resize", handleReposition);
    window.addEventListener("scroll", handleReposition, true);

    return () => {
      document.removeEventListener("mousedown", handlePointer);
      document.removeEventListener("keydown", handleEscape);
      window.removeEventListener("resize", handleReposition);
      window.removeEventListener("scroll", handleReposition, true);
    };
  }, [open]);

  const popoverNode =
    open &&
    position &&
    createPortal(
      <div
        ref={popoverRef}
        className={`lux-appconfig-hero__popover lux-appconfig-hero__popover--${type}`}
        role="dialog"
        aria-label={`${label} settings`}
        style={{
          position: "fixed",
          top: position.top,
          left: position.left,
          width: position.width,
          zIndex: 10050,
        }}
      >
        <div className="lux-appconfig-hero__popover-head">
          <i className={`fe ${icon}`} aria-hidden="true" />
          <div>
            <strong>{label}</strong>
            <span>
              {count} setting{count === 1 ? "" : "s"}
            </span>
          </div>
        </div>

        {items.length === 0 ? (
          <p className="lux-appconfig-hero__popover-empty">{emptyMessage}</p>
        ) : (
          <ul className="lux-appconfig-hero__popover-list">
            {items.map((item) => (
              <li key={item.id} className="lux-appconfig-hero__popover-list-item">
                <span className="lux-appconfig-hero__popover-module">{item.moduleLabel}</span>
                <span className="lux-appconfig-hero__popover-setting">{item.settingLabel}</span>
              </li>
            ))}
          </ul>
        )}
      </div>,
      document.body
    );

  return (
    <div className="lux-appconfig-hero__meta-item lux-appconfig-hero__meta-item--popover">
      <button
        ref={triggerRef}
        type="button"
        className={`lux-appconfig-hero__meta-trigger lux-appconfig-hero__meta-trigger--${type}${open ? " is-open" : ""}${count > 0 ? " has-items" : ""}`}
        onClick={() => setOpen((value) => !value)}
        aria-expanded={open}
        aria-haspopup="dialog"
        title={`View ${label.toLowerCase()} settings`}
      >
        <span className="lux-appconfig-hero__meta-trigger-icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
        <span className="lux-appconfig-hero__meta-trigger-text">
          <span className="lux-appconfig-hero__meta-trigger-label">{label}</span>
          <span className="lux-appconfig-hero__meta-trigger-value">{count}</span>
        </span>
        <i
          className={`fe fe-chevron-${open ? "up" : "down"} lux-appconfig-hero__meta-trigger-chevron`}
          aria-hidden="true"
        />
      </button>
      {popoverNode}
    </div>
  );
}

function ApplicationConfigHero({
  configMenuData,
  appConfigMenuSelection,
  selectedConfigData,
  parentMenuOptions,
  showConfigProperty,
  onChangeShowAddtionalOption,
  handleSaveConfigProperty,
}) {
  const orgCount = countTreeNodes(configMenuData && configMenuData.org);
  const roleCount = countTreeNodes(configMenuData && configMenuData.role);
  const isRole = appConfigMenuSelection && appConfigMenuSelection.type === "role";
  const selectionType = isRole ? "role" : "org";
  const selectionLabel = isRole ? "Role & permissions" : "Organization unit";
  const category =
    (selectedConfigData && selectedConfigData.category) ||
    (appConfigMenuSelection && appConfigMenuSelection.category);
  const moduleStats = getConfigModuleStats(selectedConfigData);
  const overriddenItems = getConfigFlaggedItems(selectedConfigData, "overridden");
  const parentOverriddenItems = getConfigFlaggedItems(selectedConfigData, "parentOverridden");
  const lockedItems = getConfigFlaggedItems(selectedConfigData, "locked");
  const selectionKey =
    appConfigMenuSelection &&
    `${appConfigMenuSelection.type}-${appConfigMenuSelection.id}`;
  const isCurrentContext =
    selectedConfigData &&
    appConfigMenuSelection &&
    (isRole
      ? appConfigMenuSelection.id === commonUtils.getCurrentUser().userRole
      : appConfigMenuSelection.id === commonUtils.getCurrentUserTeamId());
  const contextIcon = isRole ? "fe-shield" : getOrgNodeIcon(category);
  const [guideMode, setGuideMode] = useState(null);
  const [cacheBusy, setCacheBusy] = useState(false);
  const [cacheMessage, setCacheMessage] = useState(null);

  const openConfigGuide = (initialMode) => setGuideMode(initialMode);
  const closeConfigGuide = () => setGuideMode(null);

  const handleInvalidateCache = async () => {
    if (cacheBusy) return;
    setCacheBusy(true);
    setCacheMessage(null);
    try {
      await appConfigService.invalidateListCache();
      setCacheMessage("Config cache cleared across cluster members.");
    } catch (_error) {
      setCacheMessage("Unable to clear config cache. Org admin access required.");
    } finally {
      setCacheBusy(false);
    }
  };

  return (
    <header className="lux-appconfig-hero">
      <div className="lux-appconfig-hero__glow" aria-hidden="true" />

      <div className="lux-appconfig-hero__top">
        <div className="lux-appconfig-hero__brand">
          <div className="lux-appconfig-hero__icon" aria-hidden="true">
            <i className="fe fe-sliders" />
          </div>
          <div className="lux-appconfig-hero__intro">
            <p className="lux-appconfig-hero__kicker">
              <i className="fe fe-settings" aria-hidden="true" /> Admin workspace
            </p>
            <h2 className="lux-appconfig-hero__title">Application configuration</h2>
            <p className="lux-appconfig-hero__subtitle">
              Customize organization structure, role permissions, module settings, and inherited
              defaults across your {envconfig.APP_NAME} workspace.
            </p>
            <div className="lux-appconfig-hero__guide-links">
              <button
                type="button"
                className="lux-appconfig-hero__guide-link lux-appconfig-hero__guide-link--compact"
                onClick={() => openConfigGuide(CONFIG_GUIDE_MODES.ORG)}
                title="Open Config guide"
                aria-label="Open Config guide"
              >
                <i className="fe fe-book-open" aria-hidden="true" />
                <span>Config guide</span>
                <i className="fe fe-external-link lux-appconfig-hero__guide-link-ext" aria-hidden="true" />
              </button>
              <button
                type="button"
                className="lux-appconfig-hero__guide-link lux-appconfig-hero__guide-link--ghost lux-appconfig-hero__guide-link--compact"
                onClick={() => openConfigGuide(CONFIG_GUIDE_MODES.FLAGS)}
                title="Open Feature flags guide"
                aria-label="Open Feature flags guide"
              >
                <i className="fe fe-flag" aria-hidden="true" />
                <span>Feature flags</span>
                <i className="fe fe-external-link lux-appconfig-hero__guide-link-ext" aria-hidden="true" />
              </button>
              <button
                type="button"
                className="lux-appconfig-hero__guide-link lux-appconfig-hero__guide-link--ghost lux-appconfig-hero__guide-link--compact"
                onClick={handleInvalidateCache}
                disabled={cacheBusy}
                title="Clear the in-memory Application Config list cache on all app instances"
                aria-label="Reload Application Config cache"
              >
                <i className={`fe ${cacheBusy ? "fe-loader" : "fe-refresh-cw"}`} aria-hidden="true" />
                <span>{cacheBusy ? "Clearing…" : "Reload cache"}</span>
              </button>
            </div>
            {cacheMessage ? (
              <p className="lux-appconfig-hero__cache-msg" role="status">
                {cacheMessage}
              </p>
            ) : null}
          </div>
        </div>

        <div className="lux-appconfig-hero__stats" aria-label="Workspace overview">
          <HeroStat
            icon="fe-git-branch"
            label="Org units"
            value={orgCount || "—"}
            hint="Total organization nodes in the structure tree"
          />
          <HeroStat
            icon="fe-shield"
            label="Roles"
            value={roleCount || "—"}
            hint="Total roles available for permission configuration"
          />
          <HeroStat
            icon="fe-layers"
            label="Modules"
            value={selectedConfigData ? moduleStats.moduleCount : "—"}
            hint={
              selectedConfigData
                ? "Configurable modules for the selected item"
                : "Select an item to view module count"
            }
          />
          <HeroStat
            icon="fe-list"
            label="Settings"
            value={selectedConfigData ? moduleStats.settingCount : "—"}
            hint={
              selectedConfigData
                ? "Visible settings exposed for the selected item"
                : "Select an item to view setting count"
            }
          />
        </div>
      </div>

      {selectedConfigData && appConfigMenuSelection ? (
        <div className="lux-appconfig-hero__context">
          <div className="lux-appconfig-hero__context-row">
            <div className="lux-appconfig-hero__context-left">
              <div className="lux-appconfig-hero__context-icon" aria-hidden="true">
                <i className={`fe ${contextIcon}`} />
              </div>
              <div className="lux-appconfig-hero__context-copy">
                <div className="lux-appconfig-hero__pills">
                  <span className={`lux-appconfig-hero__pill lux-appconfig-hero__pill--${selectionType}`}>
                    {selectionLabel}
                  </span>
                  {isCurrentContext && (
                    <span className="lux-appconfig-hero__pill lux-appconfig-hero__pill--current">
                      Your active context
                    </span>
                  )}
                </div>
                {showConfigProperty && onChangeShowAddtionalOption && handleSaveConfigProperty && (
                  <ApplicationConfigIdentityBar
                    data={selectedConfigData}
                    menuSelection={appConfigMenuSelection}
                    parentMenuOptions={parentMenuOptions}
                    showConfigProperty={showConfigProperty}
                    onChangeShowAddtionalOption={onChangeShowAddtionalOption}
                    handleSaveConfigProperty={handleSaveConfigProperty}
                  />
                )}
              </div>
            </div>

            <div className="lux-appconfig-hero__context-actions">
              <ConfigFlagPopover
                type="overridden"
                label="Overrides"
                count={moduleStats.overriddenCount}
                items={overriddenItems}
                selectionKey={selectionKey}
                icon="fe-edit-3"
                emptyMessage="No overridden settings at this level. All values inherit from the parent."
              />
              <ConfigFlagPopover
                type="parent-overridden"
                label="Parent overrides"
                count={moduleStats.parentOverriddenCount}
                items={parentOverriddenItems}
                selectionKey={selectionKey}
                icon="fe-git-merge"
                emptyMessage="No ancestor overrides in the inheritance chain for this level."
              />
              <ConfigFlagPopover
                type="locked"
                label="Locked"
                count={moduleStats.lockedCount}
                items={lockedItems}
                selectionKey={selectionKey}
                icon="fe-lock"
                emptyMessage="No locked settings at this level. All settings can be edited here."
              />
              <div className="lux-appconfig-hero__meta-item lux-appconfig-hero__meta-item--static lux-appconfig-hero__meta-item--compact">
                <div className="lux-appconfig-hero__meta-static lux-appconfig-hero__meta-static--compact">
                  <span className="lux-appconfig-hero__meta-label">Config ID</span>
                  <span className="lux-appconfig-hero__meta-value">#{appConfigMenuSelection.id}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="lux-appconfig-hero__guide">
          <p className="lux-appconfig-hero__guide-lead">
            Select an organization unit or role from the navigator to inspect modules, permissions,
            and inherited settings.
          </p>
          <ul className="lux-appconfig-hero__tips">
            <li>
              <i className="fe fe-book-open" aria-hidden="true" />
              <button
                type="button"
                className="lux-appconfig-hero__tip-link"
                onClick={() => openConfigGuide(CONFIG_GUIDE_MODES.ORG)}
              >
                Open Config guide
              </button>{" "}
              for what each org setting does
            </li>
            <li>
              <i className="fe fe-search" aria-hidden="true" />
              Search the tree to jump to any unit or role
            </li>
            <li>
              <i className="fe fe-maximize-2" aria-hidden="true" />
              Expand all to review deep hierarchy levels quickly
            </li>
            <li>
              <i className="fe fe-lock" aria-hidden="true" />
              Locked settings inherit values from parent levels
            </li>
            <li>
              <i className="fe fe-edit-3" aria-hidden="true" />
              Overrides let this level customize parent defaults
            </li>
          </ul>
        </div>
      )}

      {guideMode != null && (
        <AppConfigFlagGuideModal
          key={guideMode}
          show
          initialMode={guideMode}
          onRequestClose={closeConfigGuide}
        />
      )}
    </header>
  );
}

export default ApplicationConfigHero;
