import React from "react";
import classNames from "classnames/bind";
import { getRiskSeverityTone } from "config/project-governance.utils";

export default function RiskHeatmapPanel({ heatmap, loading }) {
  if (loading || !heatmap || !heatmap.rows.length) {
    return (
      <div className="lux-gov-risk-heatmap lux-gov-risk-heatmap--empty">
        <p>No open risks to chart. Add risks or adjust filters to populate the heatmap.</p>
      </div>
    );
  }

  return (
    <div className="lux-gov-risk-heatmap">
      <div className="lux-gov-risk-heatmap__head">
        <span>Project</span>
        {heatmap.severities.map((severity) => (
          <span key={severity}>{severity.toLowerCase()}</span>
        ))}
        <span>Exposure</span>
      </div>
      {heatmap.rows.map((row) => (
        <div key={row.projectId} className="lux-gov-risk-heatmap__row">
          <span className="lux-gov-risk-heatmap__project">{row.projectLabel}</span>
          {heatmap.severities.map((severity) => {
            const count = row.counts[severity] || 0;
            const tone = getRiskSeverityTone(severity);
            return (
              <span
                key={`${row.projectId}-${severity}`}
                className={classNames("lux-gov-risk-heatmap__cell", `is-${tone}`, {
                  "is-active": count > 0,
                })}
                title={`${severity}: ${count}`}
              >
                {count || "·"}
              </span>
            );
          })}
          <span className="lux-gov-risk-heatmap__score">{row.exposureScore}</span>
        </div>
      ))}
    </div>
  );
}
