import React from 'react';

function LeaveApprovalCommentField({ value, onChange, placeholder, error }) {
  return (
    <div className="lux-leave-comment">
      <label className="lux-leave-comment__label" htmlFor="leave-approval-comment">
        Comment for approver
      </label>
      <textarea
        id="leave-approval-comment"
        className={`lux-leave-comment__input${error ? ' is-error' : ''}`}
        rows={2}
        value={value || ''}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder || 'Optional note for your manager…'}
      />
      {error && <p className="lux-leave-comment__error">{error}</p>}
    </div>
  );
}

export default LeaveApprovalCommentField;
