/**
 * Persona-aware route guards (P00-T8).
 * Reuses sidebar catalog as the source of persona restrictions.
 */

import {
  SIDEBAR_GROUPS,
  isSidebarItemRouteAccessible,
  pathMatchesSidebarGroup,
} from "config/sidebar-menu.config";
import { resolveItemPersonas } from "config/persona-navigation.utils";
import { isOrgPathDisabled, isOrgSidebarGroupDisabled } from "config/org-access-policy.config";

function normalizePath(pathname) {
  return (pathname || "").split("?")[0].replace(/\/+$/, "") || "/";
}

/** Profile + Employee 360 — page-level scope/RBAC; not the employees register. */
const EMPLOYEE_DETAIL_PATH_RE = /^\/(people|hrms)\/employees\/[^/]+(\/360)?$/;

export function isEmployeeDetailOr360Path(pathname) {
  return EMPLOYEE_DETAIL_PATH_RE.test(normalizePath(pathname));
}

/** Find the best-matching sidebar item for a URL path. */
export function findSidebarItemForPath(pathname) {
  const path = normalizePath(pathname);
  let bestMatch = null;

  for (const group of SIDEBAR_GROUPS) {
    if (!pathMatchesSidebarGroup(path, group)) {
      continue;
    }
    for (const item of group.items || []) {
      const itemPath = normalizePath(item.path);
      const aliasPath = item.aliasPath ? normalizePath(item.aliasPath) : null;
      const matches =
        path === itemPath ||
        path.startsWith(`${itemPath}/`) ||
        (aliasPath && (path === aliasPath || path.startsWith(`${aliasPath}/`)));

      if (matches) {
        if (!bestMatch || itemPath.length > normalizePath(bestMatch.item.path).length) {
          bestMatch = { group, item };
        }
      }
    }
  }

  return bestMatch;
}

/**
 * Returns true when the user may access this path for the active persona.
 * Paths outside the sidebar catalog are allowed (existing RBAC handles them).
 * {@code hideWhenFlag} only affects sidebar display — not deep-link access.
 */
export function isPathAllowedForPersona(pathname, activePersona, menuAccessControl) {
  if (isOrgPathDisabled(pathname)) {
    return false;
  }

  const match = findSidebarItemForPath(pathname);
  if (match && isOrgSidebarGroupDisabled(match.group && match.group.id)) {
    return false;
  }

  if (!activePersona) {
    return true;
  }

  if (isEmployeeDetailOr360Path(pathname)) {
    return true;
  }

  if (!match) {
    return true;
  }

  return isSidebarItemRouteAccessible(
    match.item,
    menuAccessControl,
    activePersona,
    match.group && match.group.id
  );
}

export function getPathAccessDenialReason(pathname, activePersona, menuAccessControl) {
  if (isOrgPathDisabled(pathname)) {
    return {
      code: "ORG_PATH_DISABLED",
      pageName: pathname,
      moduleName: "Organization",
      message: "This page is disabled for the organization.",
    };
  }

  if (isEmployeeDetailOr360Path(pathname)) {
    return null;
  }

  const match = findSidebarItemForPath(pathname);
  if (!match) {
    return null;
  }

  if (isOrgSidebarGroupDisabled(match.group && match.group.id)) {
    return {
      code: "ORG_SIDEBAR_GROUP_DISABLED",
      path: normalizePath(pathname),
      pageName: match.item.name,
      moduleName: match.group.menuName,
      message: `${match.group.menuName} is disabled for the organization.`,
      requiredPersonas: resolveItemPersonas(match.item) || match.item.personas || null,
    };
  }

  if (isPathAllowedForPersona(pathname, activePersona, menuAccessControl)) {
    return null;
  }

  const mod = menuAccessControl && match.item.flagModule
    ? menuAccessControl[match.item.flagModule]
    : null;
  const replacedByGlobalLeave =
    match.item.hideWhenFlag === "globalLeavePoliciesEnabled"
    && mod
    && mod.globalLeavePoliciesEnabled === true
    && mod.leavePoliciesEnabled !== true;

  if (replacedByGlobalLeave) {
    return {
      path: normalizePath(pathname),
      pageName: "Classic Leave policies",
      moduleName: match.group.menuName,
      code: "REPLACED_BY_GLOBAL_LEAVE",
      message:
        "Classic Leave policies are not available as a separate admin entry because Global Leave Policy Center is enabled. Use Leave admin → Global policies (and Types & fallback when classic leave types are still enabled).",
      requiredPersonas: resolveItemPersonas(match.item) || match.item.personas || null,
    };
  }

  return {
    path: normalizePath(pathname),
    pageName: match.item.name,
    moduleName: match.group.menuName,
    requiredPersonas: resolveItemPersonas(match.item) || match.item.personas || null,
  };
}
