import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled, shouldUsePayrollApi } from "config/payroll.config";
import { isPayrollReadinessAiEnabled } from "config/payroll-readiness-ai.config";
import {
  formatPayrollCurrency,
  formatPayrollDate,
  getNextRunActions,
  buildPayrollCostByDepartment,
} from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import PayrollExceptionQueue from "views/payroll/components/PayrollExceptionQueue";
import PayrollReadinessAgentPanel from "views/payroll/components/PayrollReadinessAgentPanel";
import { PayrollLinesRegister } from "views/payroll/components/PayrollRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
  PayrollStatusBadge,
  PayrollLifecycleStepper,
} from "views/payroll/components/PayrollLuxShared";

class PayrollRunDetailPage extends Component {
  state = {
    run: null,
    lines: [],
    exceptions: [],
    loading: true,
    loadError: null,
    dataSource: null,
    acting: false,
    exporting: false,
    activeView: "lines",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Payroll run");
    this.loadRun();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.match && prevProps.match.params && prevProps.match.params.runId;
    const nextId = this.props.match && this.props.match.params && this.props.match.params.runId;
    if (prevId !== nextId) {
      this.loadRun();
    }
  }

  getRunId = () => this.props.match && this.props.match.params && this.props.match.params.runId;

  getRunUserTeamId = () => {
    const search = (this.props.location && this.props.location.search) || "";
    const params = new URLSearchParams(search);
    const fromQuery = params.get("userTeamId");
    if (fromQuery != null && fromQuery !== "") {
      return fromQuery;
    }
    return this.state.run && this.state.run.userTeamId != null ? this.state.run.userTeamId : null;
  };

  loadRun = async () => {
    const runId = this.getRunId();
    if (!runId) {
      return;
    }
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.getPayrollRun(runId, this.getRunUserTeamId());
      const payload = result.payload || {};
      const run = payload.run || null;
      this.setState({
        run,
        lines: payload.lines || [],
        exceptions: payload.exceptions || [],
        loading: false,
        dataSource: result.source || null,
      });
      if (run && run.name) {
        this.props.pageHeaderNameChangeHandler(run.name);
      }
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load payroll run.", run: null, lines: [], exceptions: [] });
    }
  };

  handleAction = async (nextStatus, action) => {
    const runId = this.getRunId();
    const userTeamId = this.getRunUserTeamId();
    this.setState({ acting: true, loadError: null });
    try {
      if (action === "calculate") {
        const result = await payrollService.calculateRun(runId, userTeamId);
        if (!result || result.source === "api-error" || !result.payload) {
          this.setState({ loadError: "Unable to calculate payroll run from live employee data." });
          return;
        }
        const payload = result.payload || {};
        this.setState({
          run: payload.run || null,
          lines: payload.lines || [],
          exceptions: payload.exceptions || [],
          dataSource: result.source || null,
        });
        return;
      }
      await payrollService.updateRunStatus(runId, nextStatus, userTeamId);
      await this.loadRun();
    } catch (e) {
      this.setState({ loadError: "Unable to complete payroll run action." });
    } finally {
      this.setState({ acting: false });
    }
  };

  handlePayoutExport = async () => {
    const runId = this.getRunId();
    if (!runId || !shouldUsePayrollApi()) {
      return;
    }
    this.setState({ exporting: true, loadError: null });
    try {
      const result = await payrollService.downloadPayoutExport(runId);
      if (!result || result.source === "api-error" || !result.payload) {
        this.setState({ loadError: "Unable to download payout export." });
      }
    } catch (e) {
      this.setState({ loadError: "Unable to download payout export." });
    } finally {
      this.setState({ exporting: false });
    }
  };

  getActionVariant = (action) => {
    if (action === "approve" || action === "finalize" || action === "lock") {
      return "success";
    }
    if (action === "reopen") {
      return "ghost";
    }
    return "primary";
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Payroll run" reason="Payroll management is not enabled." />;
    }

    const { run, lines, exceptions, loading, loadError, dataSource, acting, exporting, activeView } = this.state;
    const actions = run ? getNextRunActions(run.status) : [];
    const canExportPayout = shouldUsePayrollApi() && run && run.status && run.status !== "Draft";
    const deptRows = buildPayrollCostByDepartment(lines);
    const openExceptions = exceptions.filter((row) => !row.resolved).length;
    const kpiCards = run ? [
      { id: "gross", label: "Gross payroll", value: formatPayrollCurrency(run.grossTotal), hint: `${run.employeeCount} employees`, tone: "primary", icon: "fe fe-dollar-sign" },
      { id: "net", label: "Net payout", value: formatPayrollCurrency(run.netTotal), hint: "After deductions", tone: "green", icon: "fe fe-credit-card" },
      { id: "readiness", label: "Readiness", value: run.readinessScore != null ? `${run.readinessScore}%` : "—", hint: "Pre-approval score", tone: run.readinessScore >= 90 ? "green" : "amber", icon: "fe fe-activity" },
      { id: "exceptions", label: "Exceptions", value: openExceptions, hint: `${run.blockerCount || 0} blocker(s)`, tone: openExceptions > 0 ? "rose" : "green", icon: "fe fe-alert-triangle" },
    ] : [];

    const runTitle = run && run.name ? run.name : "Payroll run";
    return (
      <PayrollLuxPage
        testId="page-payroll-run-detail"
        dataSource={dataSource}
        pageMeta={{
          tone: "green",
          icon: "fe fe-layers",
          eyebrow: "Payroll · Run detail",
          titleLead: runTitle,
          titleAccent: run && run.status ? run.status : "detail",
          lede: "Calculation lines, exceptions, and readiness for this payroll cycle.",
        }}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton to="/payroll/runs" icon="fe fe-arrow-left" variant="ghost">
              All runs
            </PayrollActionButton>
            {canExportPayout && (
              <PayrollActionButton
                variant="ghost"
                icon="fe fe-download"
                disabled={acting || loading || exporting}
                onClick={this.handlePayoutExport}
                data-testid="payroll-run-payout-export"
              >
                {exporting ? "Exporting…" : "Payout CSV"}
              </PayrollActionButton>
            )}
            {actions.map((item) => (
              <PayrollActionButton
                key={item.action}
                variant={this.getActionVariant(item.action)}
                disabled={acting || loading}
                onClick={() => this.handleAction(item.nextStatus, item.action)}
                data-testid={item.action === "calculate" ? "payroll-run-calculate" : undefined}
              >
                {acting ? "Processing…" : item.label}
              </PayrollActionButton>
            ))}
          </>
        }
      >
        {run && (
          <div className="lux-payroll-run-detail__meta-strip">
            <span>
              {run.groupName} · {formatPayrollDate(run.periodStart)} – {formatPayrollDate(run.periodEnd)} · Pay{" "}
              {formatPayrollDate(run.payDate)}
            </span>
            <PayrollStatusBadge status={run.status} />
          </div>
        )}
        {run && <PayrollLifecycleStepper status={run.status} />}
        {loadError && <div className="lux-employee-360__error" role="alert">{loadError}</div>}

        <div className="lux-payroll-run-detail__grid">
          <section className="lux-hrms-dash__panel lux-payroll-panel lux-payroll-run-detail__main">
            <header className="lux-hrms-dash__panel-head lux-payroll-panel__tabs-head">
              <LuxSegmentNav
                items={[
                  { id: "lines", label: "Calculation lines", icon: "fe fe-list" },
                  { id: "exceptions", label: "Exceptions", icon: "fe fe-alert-triangle", count: openExceptions },
                  { id: "cost", label: "Cost by dept", icon: "fe fe-bar-chart-2" },
                ]}
                activeId={activeView}
                onChange={(next) => this.setState({ activeView: next })}
                ariaLabel="Run detail views"
                tabList
                testId="payroll-run-view-nav"
              />
            </header>

            <div className="lux-hrms-dash__panel-body">
              {loading ? (
                <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading run" description="Fetching payroll run detail." />
              ) : activeView === "lines" ? (
                lines.length === 0 ? (
                  <LuxRegisterEmptyState className="lux-register-empty--compact" title="No calculation lines" description="Calculate the run to generate employee payroll lines." />
                ) : (
                  <PayrollLinesRegister lines={lines} />
                )
              ) : activeView === "exceptions" ? (
                <PayrollExceptionQueue exceptions={exceptions} loading={loading} />
              ) : deptRows.length === 0 ? (
                <LuxRegisterEmptyState className="lux-register-empty--compact" title="No cost breakdown" description="Department totals appear after calculation." />
              ) : (
                <div className="lux-payroll-cost-grid">
                  {deptRows.map((row) => (
                    <article key={row.label} className="lux-payroll-cost-card">
                      <h3 className="lux-payroll-cost-card__title">{row.label}</h3>
                      <dl className="lux-payroll-cost-card__stats">
                        <div><dt>Employees</dt><dd>{row.count}</dd></div>
                        <div><dt>Gross</dt><dd>{formatPayrollCurrency(row.gross)}</dd></div>
                        <div><dt>Net</dt><dd>{formatPayrollCurrency(row.net)}</dd></div>
                      </dl>
                    </article>
                  ))}
                </div>
              )}
            </div>
          </section>

          {run && isPayrollReadinessAiEnabled() && (
            <section className="lux-hrms-dash__panel lux-payroll-panel lux-payroll-run-detail__aside">
              <PayrollPanelHead title="Readiness assistant" subtitle="AI draft — review before approval" />
              <div className="lux-hrms-dash__panel-body">
                <PayrollReadinessAgentPanel run={run} exceptions={exceptions} />
              </div>
            </section>
          )}
        </div>
      </PayrollLuxPage>
    );
  }
}

export default PayrollRunDetailPage;
