import React, { PureComponent } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import dateUtils from "_helpers/date.utils";
import { buildPlannerSummaryModel, formatPlannerSummaryHours, getPlannerAttentionFilters, filterUtilizationByAttention } from "./plannerSummary.utils";
import {
  buildUtilizationBarChart,
  buildStatusDonutChart,
  buildDailyLoadAreaChart,
  buildFreeCapacityChart,
} from "./plannerSummary.charts";
import {
  buildPlanningAlerts,
  buildTeamHeatmap,
  buildProjectPortfolio,
  computePlanningHealthScore,
  getUtilizationTone,
  UTIL_TONES,
} from "./plannerAnalytics.utils";
import { buildProjectDetailsLookup } from "./planner.utils";
import PlannerViewHero from "./components/PlannerViewHero";
import PlannerUtilLegend from "./components/PlannerUtilLegend";
import PlannerTopProjectsPanel from "./components/PlannerTopProjectsPanel";

const STORAGE_KEY = "famstack-team-capacity-summary-expanded";

const KPI_DEFS = [
  { label: "Team members", key: "rosterSize", icon: "fe-users", suffix: "" },
  { label: "Assignments", key: "assignmentCount", icon: "fe-layers", suffix: "" },
  { label: "Avg utilization", key: "avgUtilization", icon: "fe-activity", suffix: "%" },
  { label: "Allocated", key: "allocatedHours", icon: "fe-clock", suffix: "h", hintKey: "allocatedDetail" },
  { label: "Free capacity", key: "freeHours", icon: "fe-sun", suffix: "h" },
  { label: "At risk", key: "overbookedResources", icon: "fe-alert-triangle", suffix: "", tone: "critical" },
];

export default class TeamCapacitySummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(STORAGE_KEY),
      attentionFilter: "",
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  onAttention = (key) => {
    this.setState((prev) => ({
      attentionFilter: prev.attentionFilter === key ? "" : key,
    }));
  };

  renderHealthRing = (score) => {
    const tone = score >= 80 ? "good" : score >= 60 ? "fair" : "poor";
    return (
      <div className={`lux-planner-health is-${tone}`}>
        <div className="lux-planner-health__ring" style={{ "--score": score }}>
          <strong>{score}</strong>
          <span>Health</span>
        </div>
        <p>
          {score >= 80
            ? "Team load is well balanced for this horizon."
            : score >= 60
              ? "Some rebalance recommended — review alerts below."
              : "High overload or overdue risk — act on alerts first."}
        </p>
      </div>
    );
  };

  render() {
    const {
      employees,
      workItems,
      startMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      isLoading,
      executiveSummaryOnly,
      onNavigateTab,
    } = this.props;

    const {
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    } = this.props;

    const model = buildPlannerSummaryModel({
      employees,
      workItems,
      startMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    });

    const heatmap = buildTeamHeatmap({
      employees,
      workItems,
      startMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    });

    const alerts = buildPlanningAlerts({
      heatmapRows: heatmap.rows,
      workItems,
      startMoment,
      horizonWeeks,
    });

    const projectLookup = buildProjectDetailsLookup(this.props.projects);
    const portfolio = buildProjectPortfolio(workItems, filterOptions, projectLookup).slice(0, 6);
    const healthScore = computePlanningHealthScore(model.kpis, alerts.length);

    const utilRows = filterUtilizationByAttention(
      model.utilizationRows,
      workItems,
      this.state.attentionFilter
    );

    const utilChart = buildUtilizationBarChart(utilRows);
    const statusChart = buildStatusDonutChart(model.statusCounts);
    const dailyChart = buildDailyLoadAreaChart(model.dailyAllocated);
    const freeChart = buildFreeCapacityChart(model.utilizationRows);

    const { kpis } = model;
    const kpiValues = {
      ...kpis,
      allocatedHours: Math.round(kpis.totalAllocatedMinutes / 60),
      freeHours: Math.round(kpis.freeMinutes / 60),
      allocatedDetail: formatPlannerSummaryHours(kpis.totalAllocatedMinutes),
    };

    const rangeLabel = `${startMoment.format("DD MMM")} – ${startMoment
      .clone()
      .add(horizonWeeks * 7 - 1, "days")
      .format("DD MMM YYYY")}`;

    return (
      <section className="lux-planner-overview">
        <PlannerViewHero
          eyebrow="Resource planning intelligence"
          eyebrowVariant="team-capacity"
          title="Team capacity overview"
          description="Live utilization, workload heatmap, and planning signals for your selected teams and horizon."
          meta={rangeLabel}
          badge={{
            label: `${healthScore}/100 health`,
            tone: healthScore >= 80 ? "good" : healthScore >= 60 ? "warn" : "bad",
          }}
          actions={
            <>
              <Link className="lux-planner-btn lux-planner-btn--ghost" to="/project/reports">
                <i className="fe fe-pie-chart" /> Reports
              </Link>
              {!executiveSummaryOnly && onNavigateTab && (
                <>
                  <button type="button" className="lux-planner-btn lux-planner-btn--ghost" onClick={() => onNavigateTab("roster")}>
                    <i className="fe fe-grid" /> Heatmap
                  </button>
                  <button type="button" className="lux-planner-btn lux-planner-btn--primary" onClick={() => onNavigateTab("gantt")}>
                    <i className="fe fe-bar-chart-2" /> Gantt
                  </button>
                </>
              )}
            </>
          }
        />

        <div className="lux-planner-overview__top">
          {isLoading ? (
            <Skeleton height={120} />
          ) : (
            this.renderHealthRing(healthScore)
          )}

          <div className="lux-planner-overview__alerts">
            <LuxSummaryEyebrow variant="planning-alerts" className="lux-planner-summary__eyebrow">
              Planning alerts
            </LuxSummaryEyebrow>
            {alerts.length === 0 && (
              <p className="lux-planner-overview__alerts-empty">No critical signals for this horizon.</p>
            )}
            <div className="lux-planner-alert-grid">
              {alerts.map((alert) => (
                <article
                  key={alert.id}
                  className={classNames("lux-planner-alert-card", `is-${alert.severity}`)}
                >
                  <i
                    className={`fe ${
                      alert.severity === "critical"
                        ? "fe-alert-octagon"
                        : alert.severity === "warning"
                          ? "fe-alert-circle"
                          : "fe-info"
                    }`}
                  />
                  <div>
                    <strong>{alert.title}</strong>
                    <span>{alert.detail}</span>
                  </div>
                </article>
              ))}
            </div>
          </div>
        </div>

        <div className="lux-planner-kpi-grid">
          {KPI_DEFS.map((def) => (
            <article key={def.label} className={classNames("lux-planner-kpi-card", def.tone && `is-${def.tone}`)}>
              <div className="lux-planner-kpi-card__icon">
                <i className={def.icon} />
              </div>
              <span className="lux-planner-kpi-card__label">{def.label}</span>
              <strong className="lux-planner-kpi-card__value">
                {isLoading ? "—" : (
                  <>
                    <CountUp end={kpiValues[def.key] || 0} duration={0.7} />
                    {def.suffix}
                  </>
                )}
              </strong>
              {def.hintKey && kpiValues[def.hintKey] && (
                <small>{kpiValues[def.hintKey]}</small>
              )}
            </article>
          ))}
        </div>

        <div className="lux-planner-overview__heatmap-preview">
          <div className="lux-planner-panel-head">
            <div>
              <h3>Team workload heatmap</h3>
              <p>Color shows daily utilization vs 8h capacity (weekends included).</p>
            </div>
            <PlannerUtilLegend compact />
          </div>
          {isLoading ? (
            <Skeleton height={160} />
          ) : (
            <div className="lux-planner-heatmap-preview">
              <div className="lux-planner-heatmap-preview__days">
                <span className="lux-planner-heatmap-preview__days-corner" aria-hidden="true" />
                <div className="lux-planner-heatmap-preview__days-track">
                  {heatmap.days.map((d) => (
                    <span
                      key={d.format("YYYY-MM-DD")}
                      className={classNames("lux-planner-heatmap-preview__day", {
                        "is-weekend": d.isoWeekday() >= 6,
                        "is-today": d.isSame(dateUtils.getCurrentTime(), "day"),
                      })}
                    >
                      {d.format("ddd")}
                    </span>
                  ))}
                </div>
                <span className="lux-planner-heatmap-preview__days-pct-corner" aria-hidden="true" />
              </div>
              {heatmap.rows.slice(0, 8).map((row) => (
                <div key={row.employee.id} className="lux-planner-heatmap-preview__row">
                  <span className="lux-planner-heatmap-preview__name">{row.employee.name}</span>
                  <div className="lux-planner-heatmap-preview__cells">
                    {row.dayCells.map((cell) => (
                      <span
                        key={cell.dayKey}
                        className={`is-${cell.tone}`}
                        title={`${cell.dateLabel}: ${cell.utilization}%`}
                        style={{ background: UTIL_TONES[cell.tone].color }}
                      />
                    ))}
                  </div>
                  <span className={`lux-planner-heatmap-preview__pct is-${getUtilizationTone(row.horizonUtilization)}`}>
                    {row.horizonUtilization}%
                  </span>
                </div>
              ))}
              {heatmap.rows.length > 8 && (
                <p className="lux-planner-heatmap-preview__more text-muted fsize12">
                  +{heatmap.rows.length - 8} more in Team roster view
                </p>
              )}
            </div>
          )}
        </div>

        {!executiveSummaryOnly && (
          <PlannerTopProjectsPanel
            projects={portfolio}
            isLoading={isLoading}
            totalHorizonMinutes={model.kpis.totalAllocatedMinutes}
          />
        )}

        <div className="lux-planner-overview__charts-toggle">
          <button type="button" className="lux-planner-btn lux-planner-btn--ghost" onClick={this.toggleExpanded}>
            {getSummaryToggleLabel(this.state.expanded)}
          </button>
        </div>

        {this.state.expanded && (
          <div className="lux-planner-overview__charts">
            <div className="lux-planner-attention">
              {getPlannerAttentionFilters().map((chip) => (
                <button
                  key={chip.key}
                  type="button"
                  className={classNames("lux-planner-attention__chip", {
                    "is-active": this.state.attentionFilter === chip.key,
                  })}
                  onClick={() => this.onAttention(chip.key)}
                >
                  {chip.label}
                </button>
              ))}
            </div>

            <div className="lux-planner-chart-grid">
              <div className="lux-planner-chart-card">
                <h4>Utilization by person</h4>
                <DashboardApexChart {...utilChart} />
              </div>
              <div className="lux-planner-chart-card">
                <h4>Status mix</h4>
                {Object.keys(model.statusCounts).length === 0 ? (
                  <p className="text-muted fsize12 mb-0">No assignments in range.</p>
                ) : (
                  <DashboardApexChart {...statusChart} />
                )}
              </div>
              <div className="lux-planner-chart-card lux-planner-chart-card--wide">
                <h4>Daily load vs capacity</h4>
                <DashboardApexChart {...dailyChart} />
              </div>
              {!executiveSummaryOnly && (
                <div className="lux-planner-chart-card">
                  <h4>Available hours</h4>
                  <DashboardApexChart {...freeChart} />
                </div>
              )}
            </div>

            <div className="lux-planner-report-links">
              <Link to="/project/reports">Resource allocation report</Link>
              <span>·</span>
              <Link to="/project/reports">Employee utilization report</Link>
            </div>
          </div>
        )}
      </section>
    );
  }
}
