import React from "react";
import classNames from "classnames/bind";
import { WorkflowLuxPanel } from "views/automation/components/WorkflowLuxShared";

export default function RuleBuilderPanel({ rule, actions, onFieldChange, loading }) {
  const current = rule || {};
  const actionList = actions || [];
  const conditions = current.conditions || [];
  const ruleActions = current.actions || [];

  if (loading) {
    return (
      <WorkflowLuxPanel title="Rule builder" meta="Trigger · conditions · actions" icon="fe fe-sliders" accent="violet" featured>
        <div className="lux-wf-skeleton lux-wf-skeleton--panel" />
      </WorkflowLuxPanel>
    );
  }

  return (
    <WorkflowLuxPanel title="Rule builder" meta="Trigger · conditions · actions" icon="fe fe-sliders" accent="violet" featured>
      <div className="lux-wf-builder">
        <label className="lux-wf-builder__field">
          <span>Rule name</span>
          <input
            type="text"
            className="lux-wf-builder__input"
            value={current.name || ""}
            onChange={(e) => onFieldChange && onFieldChange("name", e.target.value)}
          />
        </label>
        <label className="lux-wf-builder__field">
          <span>Description</span>
          <textarea
            className="lux-wf-builder__textarea"
            rows={2}
            value={current.description || ""}
            onChange={(e) => onFieldChange && onFieldChange("description", e.target.value)}
          />
        </label>

        <section className="lux-wf-builder__section">
          <h3>Conditions</h3>
          <ul className="lux-wf-builder__list">
            {conditions.map((cond, index) => (
              <li key={`c-${index}`} className="lux-wf-builder__chip">
                <span>{cond.field}</span>
                <strong>{cond.operator}</strong>
                <span>{cond.value}</span>
              </li>
            ))}
          </ul>
        </section>

        <section className="lux-wf-builder__section">
          <h3>Actions</h3>
          <ul className="lux-wf-builder__list">
            {ruleActions.map((act, index) => (
              <li key={`a-${index}`} className="lux-wf-builder__chip is-action">
                <i className="fe fe-play" aria-hidden="true" />
                <span>{act.label || act.type}</span>
              </li>
            ))}
          </ul>
        </section>

        <section className="lux-wf-builder__section">
          <h3>Available actions</h3>
          <div className="lux-wf-action-grid">
            {actionList.map((item) => (
              <article key={item.id} className={classNames("lux-wf-action-card", item.tone && `is-${item.tone}`)}>
                <strong>{item.label}</strong>
                <p>{item.description}</p>
              </article>
            ))}
          </div>
        </section>
      </div>
    </WorkflowLuxPanel>
  );
}
