import React, { Component } from "react";
import classNames from "classnames/bind";
import { EXPENSE_CATEGORIES } from "config/expenses.config";
import { validateExpenseClaimPayload } from "config/expenses.utils";
import PayrollLuxDrawerShell from "views/payroll/components/PayrollLuxDrawerShell";
import {
  PayrollDrawerBanner,
  PayrollDrawerCard,
  PayrollDrawerField,
  PayrollDrawerMeta,
  PayrollDrawerStatStrip,
  PayrollDrawerStepRail,
} from "views/payroll/components/PayrollLuxDrawerShared";
import { PayrollActionButton } from "views/payroll/components/PayrollLuxShared";
import ReceiptUploader from "views/expenses/components/ReceiptUploader";
import { ExpenseActionButton } from "views/expenses/components/ExpensesLuxShared";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { expensesService } from "_services/expenses.service";
import { commonUtils } from "_helpers";
import "./ExpenseFormDrawer.css";

const EMPTY_LINE = { description: "", category: EXPENSE_CATEGORIES.OTHER, amountUsd: "", receiptAttached: false };

const WIZARD_STEPS = [
  { id: "details", label: "Claim details", hint: "Title & category" },
  { id: "lines", label: "Line items", hint: "Amounts & receipts" },
  { id: "review", label: "Review", hint: "Submit or save" },
];

const CATEGORY_OPTIONS = [
  { id: EXPENSE_CATEGORIES.TRAVEL, label: "Travel", hint: "Flights, hotels, mileage", icon: "fe fe-map" },
  { id: EXPENSE_CATEGORIES.MEALS, label: "Meals", hint: "Client or team meals", icon: "fe fe-coffee" },
  { id: EXPENSE_CATEGORIES.SUPPLIES, label: "Supplies", hint: "Office or project supplies", icon: "fe fe-package" },
  { id: EXPENSE_CATEGORIES.SOFTWARE, label: "Software", hint: "Subscriptions and tools", icon: "fe fe-monitor" },
  { id: EXPENSE_CATEGORIES.OTHER, label: "Other", hint: "Miscellaneous expenses", icon: "fe fe-more-horizontal" },
];

const DRAWER_LINKS = [
  { to: "/workspace/approvals", label: "Approvals", hint: "Track claim sign-off", icon: "fe fe-inbox" },
  { to: "/payroll/reimbursements", label: "Reimbursements", hint: "Payout status", icon: "fe fe-dollar-sign" },
];

function formatUsd(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) {
    return "—";
  }
  return new Intl.NumberFormat(undefined, { style: "currency", currency: "USD", maximumFractionDigits: 2 }).format(amount);
}

function sumLineAmounts(lines = []) {
  return lines.reduce((total, line) => total + (Number(line.amountUsd) || 0), 0);
}

function getActiveStep(state) {
  if (!state.title.trim()) {
    return "details";
  }
  if (!state.lines.some((line) => line.description.trim() && Number(line.amountUsd) > 0)) {
    return "lines";
  }
  return "review";
}

class ExpenseFormDrawer extends Component {
  state = {
    title: "",
    category: EXPENSE_CATEGORIES.OTHER,
    billable: false,
    projectCode: "",
    notes: "",
    lines: [{ ...EMPTY_LINE }],
    receipts: [],
    error: null,
    saving: false,
    savedClaimRef: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({
        title: "",
        category: EXPENSE_CATEGORIES.OTHER,
        billable: false,
        projectCode: "",
        notes: "",
        lines: [{ ...EMPTY_LINE }],
        receipts: [],
        error: null,
        saving: false,
        savedClaimRef: this.props.claimRef || null,
      });
    }
  }

  handleLineChange = (index, field, value) => {
    const lines = [...this.state.lines];
    lines[index] = { ...lines[index], [field]: value };
    this.setState({ lines, error: null });
  };

  addLine = () => {
    this.setState({ lines: [...this.state.lines, { ...EMPTY_LINE }] });
  };

  removeLine = (index) => {
    if (this.state.lines.length <= 1) {
      return;
    }
    this.setState({ lines: this.state.lines.filter((_, i) => i !== index) });
  };

  handleAttachReceipt = async () => {
    const claimRef = this.props.claimRef || this.state.savedClaimRef;
    if (!claimRef) {
      this.setState({ error: "Save the claim before attaching a vault receipt." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      const result = await expensesService.attachExpenseReceipt(claimRef, {
        employeeId: this.props.employeeId || commonUtils.getCurrentUserId(),
        employeeName: this.props.employeeName,
        title: `Receipt for ${this.state.title || claimRef}`,
        fileName: `receipt-${(this.state.receipts.length || 0) + 1}.pdf`,
      });
      if (!result || !result.payload) {
        this.setState({ error: "Receipt upload failed. Ensure document vault is enabled." });
        return;
      }
      const doc = result.payload;
      const receipts = [
        ...this.state.receipts,
        {
          id: doc.id,
          fileName: doc.fileName || doc.title || `receipt-${this.state.receipts.length + 1}.pdf`,
          uploadedAt: (doc.uploadedAt || new Date().toISOString()).slice(0, 10),
          sourceEntityType: "EXPENSE_CLAIM",
          sourceEntityId: claimRef,
        },
      ];
      const lines = this.state.lines.map((line) => ({ ...line, receiptAttached: true }));
      this.setState({ receipts, lines });
    } catch (error) {
      this.setState({ error: (error && error.message) || "Unable to attach receipt." });
    } finally {
      this.setState({ saving: false });
    }
  };

  buildPayload = (submit) => ({
    title: this.state.title,
    category: this.state.category,
    billable: this.state.billable,
    projectCode: this.state.billable ? this.state.projectCode : null,
    notes: this.state.notes,
    employeeId: "emp-elena",
    employeeName: "Elena Rossi",
    department: "Sales",
    lines: this.state.lines.map((line, index) => ({
      id: `ln-new-${index}`,
      description: line.description,
      category: line.category,
      amountUsd: Number(line.amountUsd),
      receiptAttached: line.receiptAttached || this.state.receipts.length > 0,
      billable: this.state.billable,
    })),
    receipts: this.state.receipts,
    submit,
  });

  handleSave = async (submit = false) => {
    const payload = this.buildPayload(submit);
    const validation = validateExpenseClaimPayload(payload);
    if (!validation.valid) {
      this.setState({ error: validation.message });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      const saved = await this.props.onSave(payload, submit);
      const savedClaimRef =
        (saved && (saved.claimRef || saved.id)) ||
        (saved && saved.payload && (saved.payload.claimRef || saved.payload.id));
      if (savedClaimRef) {
        this.setState({ savedClaimRef });
      }
      this.props.onClose();
    } catch (error) {
      this.setState({ error: (error && error.message) || "Unable to save claim." });
    } finally {
      this.setState({ saving: false });
    }
  };

  render() {
    const { open, onClose } = this.props;
    if (!open) {
      return null;
    }

    const { title, category, billable, projectCode, notes, lines, receipts, error, saving } = this.state;
    const totalUsd = sumLineAmounts(lines);
    const lineCount = lines.filter((line) => line.description.trim() || Number(line.amountUsd) > 0).length;
    const activeStep = getActiveStep(this.state);
    const categoryMatch = CATEGORY_OPTIONS.find((row) => row.id === category);
    const categoryLabel = (categoryMatch && categoryMatch.label) || category;

    const footer = (
      <>
        <ExpenseActionButton variant="ghost" onClick={onClose} disabled={saving}>
          Cancel
        </ExpenseActionButton>
        <ExpenseActionButton variant="ghost" onClick={() => this.handleSave(false)} disabled={saving}>
          Save draft
        </ExpenseActionButton>
        <PayrollActionButton variant="primary" type="submit" form="expense-claim-form" disabled={saving}>
          {saving ? "Submitting…" : "Submit claim"}
        </PayrollActionButton>
      </>
    );

    return (
      <PayrollLuxDrawerShell
        open={open}
        onClose={onClose}
        accent="green"
        wide
        icon="fe-credit-card"
        eyebrow="Expense claim"
        title="New expense claim"
        subtitle="Capture line items, attach receipts, and route through manager and finance approval."
        badges={
          <>
            <span className="lux-doc-badge is-warning">Draft</span>
            <span>Canonical source: expense claim workflow</span>
          </>
        }
        quickLinks={DRAWER_LINKS}
        footer={footer}
      >
        <form
          id="expense-claim-form"
          onSubmit={(event) => {
            event.preventDefault();
            this.handleSave(true);
          }}
        >
          <PayrollDrawerStepRail steps={WIZARD_STEPS} activeStep={activeStep} />

          {error ? (
            <LuxInlineAlert tone="warning" title="Unable to save claim">
              {error}
            </LuxInlineAlert>
          ) : null}

          <PayrollDrawerBanner icon="fe-shield" tone="info">
            Claims are validated against expense policy before approval. Attach receipts for audit-ready reimbursement
            processing.
          </PayrollDrawerBanner>

          <PayrollDrawerStatStrip
            stats={[
              { label: "Claim total", value: formatUsd(totalUsd), hint: `${lineCount} line item(s)`, tone: "green" },
              { label: "Receipts", value: receipts.length, hint: receipts.length ? "Attached" : "Required for submit", tone: receipts.length ? "blue" : "amber" },
              { label: "Billable", value: billable ? "Yes" : "No", hint: billable ? projectCode || "Project linked" : "Employee expense", tone: billable ? "indigo" : "slate" },
            ]}
          />

          <PayrollDrawerCard title="Claim details" subtitle="How the claim appears in registers and approvals">
            <PayrollDrawerField label="Title" hint="Short label for approvers and finance queue">
              <input
                value={title}
                onChange={(e) => this.setState({ title: e.target.value, error: null })}
                placeholder="e.g. Client visit travel — Mumbai"
                required
                data-testid="expense-claim-title"
              />
            </PayrollDrawerField>

            <PayrollDrawerField label="Category" hint="Primary expense classification">
              <div className="lux-expense-claim__category-grid">
                {CATEGORY_OPTIONS.map((option) => (
                  <button
                    key={option.id}
                    type="button"
                    className={classNames("lux-expense-claim__category-card", { "is-selected": category === option.id })}
                    onClick={() => this.setState({ category: option.id })}
                  >
                    <span className="lux-expense-claim__category-icon" aria-hidden="true">
                      <i className={option.icon} />
                    </span>
                    <strong>{option.label}</strong>
                    <small>{option.hint}</small>
                  </button>
                ))}
              </div>
            </PayrollDrawerField>

            <label className="lux-expense-claim__toggle">
              <input type="checkbox" checked={billable} onChange={(e) => this.setState({ billable: e.target.checked })} />
              <span>Billable to project</span>
            </label>

            {billable ? (
              <PayrollDrawerField label="Project code" hint="Links claim to project financials">
                <input
                  value={projectCode}
                  onChange={(e) => this.setState({ projectCode: e.target.value })}
                  placeholder="AUR-2026"
                />
              </PayrollDrawerField>
            ) : null}
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Line items" subtitle="Itemize amounts — totals roll up to the claim header">
            <div className="lux-expense-claim__lines-head">
              <strong>{lines.length} line(s)</strong>
              <ExpenseActionButton variant="ghost" icon="fe fe-plus" onClick={this.addLine}>
                Add line
              </ExpenseActionButton>
            </div>
            <div className="lux-expense-claim__lines">
              {lines.map((line, index) => (
                <div key={`line-${index}`} className="lux-expense-claim__line">
                  <PayrollDrawerField label={`Line ${index + 1}`}>
                    <input
                      value={line.description}
                      placeholder="Description"
                      onChange={(e) => this.handleLineChange(index, "description", e.target.value)}
                    />
                  </PayrollDrawerField>
                  <PayrollDrawerField label="Amount (USD)">
                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      value={line.amountUsd}
                      placeholder="0.00"
                      onChange={(e) => this.handleLineChange(index, "amountUsd", e.target.value)}
                    />
                  </PayrollDrawerField>
                  {lines.length > 1 ? (
                    <button
                      type="button"
                      className="lux-expense-claim__line-remove"
                      onClick={() => this.removeLine(index)}
                      aria-label={`Remove line ${index + 1}`}
                    >
                      <i className="fe fe-trash-2" aria-hidden="true" />
                    </button>
                  ) : null}
                </div>
              ))}
            </div>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Receipts & notes" subtitle="Supporting documents and context for approvers">
            <ReceiptUploader
              receipts={receipts}
              onUpload={this.handleAttachReceipt}
              disabled={saving}
              claimRef={this.props.claimRef || this.state.savedClaimRef}
            />
            <PayrollDrawerField label="Notes" hint="Optional context for manager or finance reviewer">
              <textarea value={notes} onChange={(e) => this.setState({ notes: e.target.value })} rows={3} placeholder="Business purpose, attendees, policy exceptions…" />
            </PayrollDrawerField>
          </PayrollDrawerCard>

          <PayrollDrawerCard title="Review" subtitle="Confirm before save or submit" className="is-review">
            <PayrollDrawerMeta
              items={[
                { label: "Title", value: title.trim() || "—" },
                { label: "Category", value: categoryLabel },
                { label: "Total", value: formatUsd(totalUsd) },
                { label: "Receipts", value: receipts.length },
                { label: "Billable", value: billable ? `Yes · ${projectCode || "project"}` : "No" },
              ]}
            />
          </PayrollDrawerCard>
        </form>
      </PayrollLuxDrawerShell>
    );
  }
}

export default ExpenseFormDrawer;
