import React from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import {
  formatCurrency,
  getInvoiceNumber,
  getUserCount,
  INVOICE_STATUS_META,
} from "./invoice.utils";
import { mergeParty, mergePayment, mergeSignatory } from "./invoicePresentation.defaults";

function resolveSupplier(item) {
  return (
    mergeParty((item && item.supplier) || {
      name: item && (item.accountName || item.legalEntityName),
    }) || { name: "Supplier not configured", address: [], emails: [], phones: [] }
  );
}

function resolveClient(item) {
  return (
    mergeParty((item && item.client) || {
      name: item && (item.clientName || item.billToName),
    }) || { name: "Client not configured", address: [], emails: [], phones: [] }
  );
}

function resolvePayment(item) {
  const raw =
    (item && (item.paymentDetails || item.bankDetails || item.legalEntityPayment || item.payment)) ||
    {};
  return mergePayment(raw);
}

function resolveSignatory(item) {
  return mergeSignatory((item && item.signatory) || {
    name: item && item.signatoryName,
    title: item && item.signatoryTitle,
  });
}

function buildLineItems(item) {
  if (!item) return [];

  const rows = [];
  const userCount = getUserCount(item);
  const billingMonth = item.invoiceMonthYear
    ? dateUtils
        .convertDateStringToMoment(item.invoiceMonthYear)
        .format(dateUtils.DATE_MONTH_FORMAT)
    : "—";
  const unitPrice = Number.isFinite(Number(item.ratePerUser)) ? Number(item.ratePerUser) : 400;

  rows.push({
    key: "monthly-fee",
    title: `Monthly User fee (${billingMonth})`,
    description: `Recurring monthly licence fee for ${item.numberOfUsers || userCount} users.`,
    unitPrice,
    quantity: userCount,
    total: parseAmountSafe(item.totalAmount),
  });

  if (item.additionalItems && item.additionalItems.items) {
    item.additionalItems.items.forEach((additionalItem, index) => {
      rows.push({
        key: `additional-${index}`,
        title: additionalItem.name,
        description: additionalItem.description,
        unitPrice: null,
        quantity: null,
        total: parseAmountSafe(additionalItem.totalAmount),
      });
    });
  }

  return rows;
}

function parseAmountSafe(value) {
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
}

/**
 * Layout matches the previous InvoiceDocumentView (main / May hard-coded page).
 * Identity fields are resolved from API snapshot / Tracopus client registry.
 */
function InvoiceDocumentView({ item, sheetRef }) {
  if (!item) return null;

  const invoiceNumber = getInvoiceNumber(item);
  const invoiceDate = dateUtils
    .convertDateStringToMoment(item.revisedInvoiceDateTime || item.invoiceDateTime)
    .format("DD MMM YYYY");
  const additional = item.additionalItems || {};
  const cgst = parseAmountSafe(additional.cgst);
  const sgst = parseAmountSafe(additional.sgst);
  const igst = parseAmountSafe(additional.igst);
  const taxTotal = cgst + sgst + igst;
  const lineSubTotal =
    parseAmountSafe(item.totalAmount) +
    (additional.items || []).reduce((sum, row) => sum + parseAmountSafe(row && row.totalAmount), 0);
  const grandTotal =
    taxTotal > 0 ? lineSubTotal + taxTotal : parseAmountSafe(item.subTotal) || lineSubTotal;
  const lineItems = buildLineItems(item);
  const statusMeta = INVOICE_STATUS_META[item.status] || INVOICE_STATUS_META.DRAFT;
  const gstRate = additional.gstRate;
  const supplier = resolveSupplier(item);
  const client = resolveClient(item);
  const payment = resolvePayment(item);
  const signatory = resolveSignatory(item);
  const terms = ((item.terms || item.paymentTerms || "") + "").trim() || null;

  return (
    <article
      ref={sheetRef}
      className="lux-inv-detail__sheet"
      aria-label={`Invoice ${invoiceNumber}`}
      data-testid="invoice-document"
    >
      <div className="lux-inv-detail__accent print-exact" aria-hidden="true" />

      <div className="lux-inv-detail__sheet-body">
        <header className="lux-inv-detail__brand print-exact">
          <div className="lux-inv-detail__brand-top">
            <div className="lux-inv-detail__brand-main">
              {supplier.logo ? (
                <div className="lux-inv-detail__logo-wrap">
                  <img className="lux-inv-detail__logo" src={supplier.logo} alt="" />
                </div>
              ) : null}
              <div className="lux-inv-detail__brand-copy">
                <span className="lux-inv-detail__brand-eyebrow">Issued by</span>
                <h1 className="lux-inv-detail__supplier-name">{supplier.name}</h1>
                {supplier.registration ? (
                  <p className="lux-inv-detail__supplier-reg">{supplier.registration}</p>
                ) : null}
                {supplier.address && supplier.address.length > 0 ? (
                  <p className="lux-inv-detail__supplier-line">
                    {supplier.address.join(" · ")}
                  </p>
                ) : null}
              </div>
            </div>
          </div>

          <div className="lux-inv-detail__brand-contacts">
            {supplier.emails && supplier.emails[0] ? (
              <div className="lux-inv-detail__contact-chip">
                <i className="fe fe-mail" aria-hidden="true" />
                <span>{supplier.emails[0]}</span>
              </div>
            ) : null}
            {supplier.phones && supplier.phones[0] ? (
              <div className="lux-inv-detail__contact-chip">
                <i className="fe fe-phone" aria-hidden="true" />
                <span>{supplier.phones[0]}</span>
              </div>
            ) : null}
            {supplier.website ? (
              <div className="lux-inv-detail__contact-chip">
                <i className="fe fe-globe" aria-hidden="true" />
                <span>{supplier.website}</span>
              </div>
            ) : null}
            {supplier.hours ? (
              <div className="lux-inv-detail__contact-chip is-muted">
                <i className="fe fe-clock" aria-hidden="true" />
                <span>{supplier.hours}</span>
              </div>
            ) : null}
          </div>
        </header>

        <div className="lux-inv-detail__hero">
          <div className="lux-inv-detail__bill-to">
            <span className="lux-inv-detail__section-label">
              <i className="fe fe-user" aria-hidden="true" />
              Invoice to
            </span>
            <h2>{client.name}</h2>
            {client.registration ? (
              <p className="lux-inv-detail__bill-reg">{client.registration}</p>
            ) : null}
            {(client.address || []).map((line) => (
              <p key={line} className="lux-inv-detail__bill-line">
                {line}
              </p>
            ))}
            {client.email || client.phone ? (
              <div className="lux-inv-detail__bill-links">
                {client.email ? (
                  <a href={`mailto:${client.email}`}>
                    <i className="fe fe-mail" aria-hidden="true" />
                    {client.email}
                  </a>
                ) : null}
                {client.phone ? (
                  <span>
                    <i className="fe fe-phone" aria-hidden="true" />
                    {client.phone}
                  </span>
                ) : null}
              </div>
            ) : null}
          </div>

          <div className="lux-inv-detail__summary">
            <div className="lux-inv-detail__summary-title">Invoice</div>
            <div className="lux-inv-detail__summary-grid">
              <div className="lux-inv-detail__summary-card is-primary print-exact">
                <span>Total due</span>
                <strong>{formatCurrency(grandTotal)}</strong>
              </div>
              <div className="lux-inv-detail__summary-card">
                <span>Invoice date</span>
                <strong>{invoiceDate}</strong>
              </div>
              <div className="lux-inv-detail__summary-card">
                <span>Invoice number</span>
                <strong>#{invoiceNumber}</strong>
              </div>
              <div
                className={classNames(
                  "lux-inv-detail__summary-card",
                  "is-status",
                  `is-${statusMeta.tone}`
                )}
              >
                <span>Status</span>
                <strong>{statusMeta.label}</strong>
              </div>
            </div>
          </div>
        </div>

        <section className="lux-inv-detail__items print-exact" aria-label="Line items">
          <div className="lux-inv-detail__items-head" role="row">
            <span role="columnheader">Item description</span>
            <span role="columnheader">Unit price</span>
            <span role="columnheader">Qty</span>
            <span role="columnheader">Total</span>
          </div>
          <div className="lux-inv-detail__items-body">
            {lineItems.map((row) => (
              <div key={row.key} className="lux-inv-detail__item-row" role="row">
                <div className="lux-inv-detail__item-desc" role="cell">
                  <strong>{row.title}</strong>
                  {row.description && <p>{row.description}</p>}
                </div>
                <div role="cell">
                  {row.unitPrice != null ? formatCurrency(row.unitPrice) : "—"}
                </div>
                <div role="cell">{row.quantity != null ? row.quantity : "—"}</div>
                <div className="lux-inv-detail__item-total" role="cell">
                  {formatCurrency(row.total)}
                </div>
              </div>
            ))}
          </div>
        </section>

        <div className="lux-inv-detail__settlement">
          <section className="lux-inv-detail__payment" aria-label="Payment details">
            <h3>
              <i className="fe fe-credit-card" aria-hidden="true" />
              Payment method
            </h3>
            {!payment ? (
              <p className="lux-inv-detail__config-hint no-print">
                Payment details are missing on this client registry payment config.
              </p>
            ) : (
              <>
                <p className="lux-inv-detail__payment-method">{payment.method}</p>

                <div className="lux-inv-detail__tax-grid">
                  {payment.pan ? (
                    <div>
                      <span>PAN</span>
                      <strong>{payment.pan}</strong>
                    </div>
                  ) : null}
                  {payment.gst ? (
                    <div>
                      <span>GST</span>
                      <strong>{payment.gst}</strong>
                    </div>
                  ) : null}
                  {payment.lutArn ? (
                    <div>
                      <span>LUT ARN</span>
                      <strong>{payment.lutArn}</strong>
                    </div>
                  ) : null}
                </div>

                <div className="lux-inv-detail__bank-card print-exact">
                  <span className="lux-inv-detail__bank-label">Bank account</span>
                  {payment.accountName ? <strong>{payment.accountName}</strong> : null}
                  {payment.accountNumber ? <p>Account number: {payment.accountNumber}</p> : null}
                  {payment.ifsc ? <p>IFSC: {payment.ifsc}</p> : null}
                  {(payment.bank || payment.branch) && (
                    <p>{[payment.bank, payment.branch].filter(Boolean).join(", ")}</p>
                  )}
                  {payment.branchLocation ? <p>{payment.branchLocation}</p> : null}
                </div>
              </>
            )}
          </section>

          <section className="lux-inv-detail__totals" aria-label="Invoice totals">
            <div className="lux-inv-detail__totals-rows">
              <div className="lux-inv-detail__totals-row">
                <span>Subtotal</span>
                <strong>{formatCurrency(lineSubTotal)}</strong>
              </div>
              {gstRate != null && Number(gstRate) > 0 && (
                <div className="lux-inv-detail__totals-row">
                  <span>GST rate</span>
                  <strong>{Number(gstRate)}%</strong>
                </div>
              )}
              {cgst > 0 && (
                <div className="lux-inv-detail__totals-row">
                  <span>CGST</span>
                  <strong>{formatCurrency(cgst)}</strong>
                </div>
              )}
              {sgst > 0 && (
                <div className="lux-inv-detail__totals-row">
                  <span>SGST</span>
                  <strong>{formatCurrency(sgst)}</strong>
                </div>
              )}
              {igst > 0 && (
                <div className="lux-inv-detail__totals-row">
                  <span>IGST</span>
                  <strong>{formatCurrency(igst)}</strong>
                </div>
              )}
              <div className="lux-inv-detail__totals-row">
                <span>Tax</span>
                <strong>{formatCurrency(taxTotal)}</strong>
              </div>
              <div className="lux-inv-detail__totals-row is-discount">
                <span>Discount</span>
                <strong>-{formatCurrency(0)}</strong>
              </div>
            </div>
            <div className="lux-inv-detail__totals-due print-exact">
              <span>Total due</span>
              <strong>{formatCurrency(grandTotal)}</strong>
            </div>

            <div className="lux-inv-detail__signature print-exact">
              {signatory && signatory.image ? (
                <img src={signatory.image} alt="" data-testid="invoice-signatory-image" />
              ) : null}
              {signatory && signatory.name ? <p>{signatory.name}</p> : null}
              {signatory && signatory.title ? <strong>{signatory.title}</strong> : null}
            </div>
          </section>
        </div>

        <section className="lux-inv-detail__terms print-exact">
          <h3>Terms</h3>
          <p>{terms || "—"}</p>
        </section>

        <footer className="lux-inv-detail__footer print-exact">
          {supplier.logo ? <img src={supplier.logo} alt="" /> : null}
          <div>
            {(supplier.emails || []).map((email) => (
              <span key={email}>{email}</span>
            ))}
          </div>
          <div>
            {supplier.phones && supplier.phones[0] ? (
              <span>{supplier.phones[0]}</span>
            ) : null}
            {supplier.hours ? <span>{supplier.hours}</span> : null}
          </div>
          <div>{supplier.website ? <span>{supplier.website}</span> : null}</div>
        </footer>
      </div>
    </article>
  );
}

export default InvoiceDocumentView;
