import React from "react";
import classNames from "classnames/bind";

export function HolidayActionButton({
  onClick,
  children,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  testId,
}) {
  return (
    <button
      type={type}
      className={classNames("lux-onb-action lux-holiday-action", `lux-onb-action--${variant}`, className)}
      onClick={onClick}
      disabled={disabled}
      data-testid={testId}
    >
      {icon && <i className={icon} aria-hidden="true" />}
      <span>{children}</span>
    </button>
  );
}

export function HolidayKpiStrip({ cards, loading }) {
  return (
    <div className="lux-hrms-dash__kpi-strip lux-holiday-kpi-strip" role="list" aria-busy={loading}>
      {cards.map((card, index) => (
        <article
          key={card.id}
          className={classNames("lux-hrms-dash__kpi lux-holiday-kpi", card.tone && `is-${card.tone}`)}
          role="listitem"
          style={{ "--holiday-kpi-i": index }}
        >
          <span className="lux-holiday-kpi__shine" aria-hidden="true" />
          <div className="lux-holiday-kpi__top">
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            {card.icon && (
              <span className={classNames("lux-holiday-kpi__icon", card.tone && `is-${card.tone}`)} aria-hidden="true">
                <i className={card.icon} />
              </span>
            )}
          </div>
          <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
          <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
        </article>
      ))}
    </div>
  );
}

export function HolidayInsightStrip({ insights }) {
  if (!insights || insights.length === 0) {
    return null;
  }
  return (
    <div className="lux-holiday-insights" role="list">
      {insights.map((insight, index) => (
        <article
          key={insight.id}
          className={classNames("lux-hrms-dash__alert lux-holiday-insight", `is-${insight.tone}`)}
          role="listitem"
          style={{ "--holiday-insight-i": index }}
        >
          <span className="lux-holiday-insight__glow" aria-hidden="true" />
          <span className="lux-hrms-dash__alert-icon lux-holiday-insight__icon" aria-hidden="true">
            <i className={insight.icon} />
          </span>
          <span className="lux-holiday-insight__copy">
            <strong>{insight.title}</strong>
            <small>{insight.copy}</small>
          </span>
        </article>
      ))}
    </div>
  );
}
