import { shouldUseExpenseManagement } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const EXPENSE_ROUTE_IDS = {
  EMPLOYEE: "employee",
  FINANCE: "finance",
  REIMBURSEMENTS: "reimbursements",
};

export const EXPENSE_CANONICAL_ROUTES = {
  [EXPENSE_ROUTE_IDS.EMPLOYEE]: "/payroll/expenses",
  [EXPENSE_ROUTE_IDS.FINANCE]: "/finance/expenses",
  [EXPENSE_ROUTE_IDS.REIMBURSEMENTS]: "/payroll/reimbursements",
};

export const EXPENSE_CLAIM_STATUSES = {
  DRAFT: "DRAFT",
  SUBMITTED: "SUBMITTED",
  MANAGER_APPROVED: "MANAGER_APPROVED",
  FINANCE_APPROVED: "FINANCE_APPROVED",
  REJECTED: "REJECTED",
  REIMBURSED: "REIMBURSED",
};

export const EXPENSE_CATEGORIES = {
  TRAVEL: "TRAVEL",
  MEALS: "MEALS",
  SUPPLIES: "SUPPLIES",
  SOFTWARE: "SOFTWARE",
  OTHER: "OTHER",
};

export const EXPENSE_AUDIT_CODES = {
  EXPENSE_SUBMITTED: "EXPENSE_SUBMITTED",
  EXPENSE_APPROVED: "EXPENSE_APPROVED",
  EXPENSE_REJECTED: "EXPENSE_REJECTED",
  EXPENSE_REIMBURSED: "EXPENSE_REIMBURSED",
  RECEIPT_UPLOADED: "RECEIPT_UPLOADED",
  POLICY_OVERRIDE: "POLICY_OVERRIDE",
};

export const REIMBURSEMENT_STATUSES = {
  PENDING: "PENDING",
  SCHEDULED: "SCHEDULED",
  PAID: "PAID",
  FAILED: "FAILED",
};

export function isExpenseManagementEnabled() {
  return shouldUseExpenseManagement();
}

export function shouldUseExpensesApi() {
  return envconfig.USE_EXPENSES_API === true;
}

export function normalizeExpenseLine(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    description: row.description || "",
    category: row.category || EXPENSE_CATEGORIES.OTHER,
    amountUsd: row.amountUsd != null ? Number(row.amountUsd) : null,
    receiptAttached: row.receiptAttached === true,
    billable: row.billable === true,
    projectId: row.projectId || null,
    projectName: row.projectName || null,
  };
}

export function normalizeExpenseReceipt(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    fileName: row.fileName || "receipt",
    uploadedAt: row.uploadedAt || null,
    sizeKb: row.sizeKb != null ? Number(row.sizeKb) : null,
  };
}

export function normalizeExpenseClaim(row) {
  if (!row) {
    return null;
  }
  const lines = (row.lines || []).map((line) => normalizeExpenseLine(line)).filter(Boolean);
  const totalUsd =
    row.totalUsd != null
      ? Number(row.totalUsd)
      : lines.reduce((sum, line) => sum + (line.amountUsd || 0), 0);
  return {
    id: row.id,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    department: row.department || "",
    title: row.title || "Expense claim",
    status: row.status || EXPENSE_CLAIM_STATUSES.DRAFT,
    category: row.category || EXPENSE_CATEGORIES.OTHER,
    totalUsd,
    billable: row.billable === true,
    projectId: row.projectId || null,
    projectCode: row.projectCode || null,
    projectName: row.projectName || null,
    submittedAt: row.submittedAt || null,
    managerApprovedAt: row.managerApprovedAt || null,
    financeApprovedAt: row.financeApprovedAt || null,
    reimbursedAt: row.reimbursedAt || null,
    rejectedAt: row.rejectedAt || null,
    rejectionReason: row.rejectionReason || null,
    policyViolations: Array.isArray(row.policyViolations) ? row.policyViolations : [],
    approvalId: row.approvalId || null,
    payrollRunId: row.payrollRunId || null,
    lines,
    receipts: (row.receipts || []).map((item) => normalizeExpenseReceipt(item)).filter(Boolean),
    notes: row.notes || "",
    updatedAt: row.updatedAt || null,
  };
}

export function normalizeReimbursement(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    claimId: row.claimId || null,
    employeeId: row.employeeId || null,
    employeeName: row.employeeName || "",
    amountUsd: row.amountUsd != null ? Number(row.amountUsd) : null,
    status: row.status || REIMBURSEMENT_STATUSES.PENDING,
    scheduledPayDate: row.scheduledPayDate || null,
    paidAt: row.paidAt || null,
    payrollRunId: row.payrollRunId || null,
    payrollRunLabel: row.payrollRunLabel || null,
    paymentMethod: row.paymentMethod || "Direct deposit",
    projectId: row.projectId || null,
    projectName: row.projectName || null,
    billable: row.billable === true,
    agingDays: row.agingDays != null ? Number(row.agingDays) : null,
  };
}

export function normalizeExpensePolicyRule(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    category: row.category || EXPENSE_CATEGORIES.OTHER,
    maxAmountUsd: row.maxAmountUsd != null ? Number(row.maxAmountUsd) : null,
    requiresReceipt: row.requiresReceipt === true,
    requiresProject: row.requiresProject === true,
    financeThresholdUsd: row.financeThresholdUsd != null ? Number(row.financeThresholdUsd) : null,
    label: row.label || "",
  };
}

export function normalizeExpenseLeakageFlag(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    claimId: row.claimId || null,
    employeeName: row.employeeName || "",
    leakageType: row.leakageType || "DUPLICATE",
    severity: row.severity || "MEDIUM",
    estimatedUsd: row.estimatedUsd != null ? Number(row.estimatedUsd) : null,
    recommendation: row.recommendation || "",
    status: row.status || "OPEN",
    flaggedAt: row.flaggedAt || null,
  };
}

export function getExpenseStatusTone(status) {
  switch (status) {
    case EXPENSE_CLAIM_STATUSES.REIMBURSED:
      return "green";
    case EXPENSE_CLAIM_STATUSES.FINANCE_APPROVED:
    case EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED:
      return "blue";
    case EXPENSE_CLAIM_STATUSES.SUBMITTED:
      return "amber";
    case EXPENSE_CLAIM_STATUSES.REJECTED:
      return "rose";
    default:
      return "slate";
  }
}
