import React from "react";
import classNames from "classnames/bind";
import { GATE_STATUSES } from "config/project-governance.config";
import { getGateStatusTone } from "config/project-governance.utils";

export default function GateRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--gates">
        <thead>
          <tr>
            <th>Gate</th>
            <th>Project</th>
            <th>Stage</th>
            <th>Approver</th>
            <th>Due</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const tone = getGateStatusTone(row.status);
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", {
                  "is-critical": row.status === GATE_STATUSES.PENDING,
                  "is-risk": row.status === GATE_STATUSES.REJECTED,
                })}
              >
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect(row)}>
                    <strong>{row.name}</strong>
                    {row.criteria ? <span>{row.criteria}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>{row.stage || "—"}</td>
                <td>{row.approverName || "—"}</td>
                <td>{row.dueDate || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${tone}`)}>{row.status}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
