import classNames from "classnames/bind";
import React, { Component } from "react";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import { validationUtils } from "_helpers";
import QuestionaireTable from "../fragments/QuestionaireTable";
import { store } from "_helpers";
import { checklistConstants } from "_constants";
import { commonUtils } from "_helpers";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { checklistActions } from "_actions";
import { accessUtils } from "_helpers";
import { appConfigActions } from "_actions";
import ItemChecklistInput from "../fragments/ItemChecklistInput";

function getChecklistEditorMode(checklistRequest, editMode) {
  if (!checklistRequest || !checklistRequest.id) {
    return {
      tone: "create",
      icon: "fe-plus-circle",
      kicker: "New template",
      title: checklistRequest && checklistRequest.name
        ? checklistRequest.name
        : "Untitled checklist",
      subtitle: "Name the template, add questions, and restrict by team.",
    };
  }
  if (editMode) {
    return {
      tone: "edit",
      icon: "fe-edit-3",
      kicker: "Editing",
      title: checklistRequest.name || "Untitled checklist",
      subtitle: "Update questions, teams, and description — then save.",
    };
  }
  return {
    tone: "view",
    icon: "fe-eye",
    kicker: "Viewing",
    title: checklistRequest.name || "Untitled checklist",
    subtitle: "Read-only preview. Use Edit to change this template.",
  };
}

function countQuestions(checklistRequest) {
  const list = checklistRequest && checklistRequest.questionDataList;
  return list && list.length ? list.length : 0;
}

function countRestrictedTeams(checklistRequest) {
  const ids = checklistRequest && checklistRequest.restrictedByUserTeamIds;
  if (!ids) return 0;
  if (Array.isArray(ids)) return ids.length;
  return String(ids).split(",").filter(Boolean).length;
}

class ConfigureChecklistSidebar extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
      permission: accessUtils.getChecklistAccessControl(),
    };
  }

  onCloseItemClick = () => {
    store.dispatch({ type: checklistConstants.CLOSE_CHECKLIST_ANSWER_WINDOW });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onResetFormError = () => {
    this.setState({ hasFormError: false });
  };

  submitCallBackFunction = () => {
    this.setState({ checklistRequest: {} });
  };

  handleSubmit = (checklistRequest) => {
    let isValidForm = validationUtils.isValidRequest(
      this.props.fieldConfig,
      checklistRequest,
      this.state.formErrors
    );
    isValidForm =
      checklistRequest.questionDataList !== undefined &&
      checklistRequest.questionDataList.length > 0;
    if (isValidForm === true) {
      checklistRequest.questionDataList.forEach((question) => {
        if (question.question === "") {
          isValidForm = false;
        }
      });
    }
    if (isValidForm) {
      if (!checklistRequest.id) {
        store.dispatch(
          this.props.createChecklist(checklistRequest, this.submitCallBackFunction)
        );
      } else {
        store.dispatch(
          this.props.updateChecklist(checklistRequest, this.submitCallBackFunction)
        );
      }
    } else {
      this.setState({ hasFormError: true });
    }
  };

  handleRemoveChecklist = (checklistId) => {
    store.dispatch(this.props.removeChecklist(checklistId));
  };

  updateItemChecklistData = (checklistData) => {
    store.dispatch(
      this.props.updateItemChecklistData(
        checklistData,
        this.props.selectedItemInfo.id,
        this.props.type
      )
    );
  };

  render() {
    const isConfigMode =
      this.props.showConfigWindow === true &&
      this.props.showChecklistQuestionsWindow === false;
    const isFillMode =
      this.props.showChecklistQuestionsWindow === true &&
      this.props.showConfigWindow === false;
    const title = isFillMode
      ? "Fill work item checklist"
      : "Configure checklist templates";
    const subtitle = isFillMode
      ? "Answer required questions for this work item."
      : "Design reusable checklists — questions, answer types, and team access.";

    const panel = (
      <LuxCreatePanelShell
        show={this.props.show === true}
        onClose={this.onCloseItemClick}
        panelId="configchecklistsidebar"
        className={classNames(
          "lux-create-panel--checklist config_checklist_right_sidebar",
          { "lux-create-panel--checklist-wide": isConfigMode }
        )}
        kicker="Checklist workspace"
        title={title}
        subtitle={subtitle}
      >
        {this.props.show === true && isConfigMode && (
          <ConfigureChecklistSidebarSection
            permission={this.state.permission}
            fieldConfig={this.props.fieldConfig}
            onFormError={this.onFormError}
            onResetFormError={this.onResetFormError}
            hasFormError={this.state.hasFormError}
            getAllChecklists={this.props.getAllChecklists}
            handleRemoveChecklist={this.handleRemoveChecklist}
            checklistDataList={this.props.checklistDataList}
            type={this.props.type}
            selectedItemInfo={this.props.selectedItemInfo}
            submitChecklist={this.handleSubmit}
            allUserTeams={this.props.allUserTeams}
            typeOptions={this.props.typeOptions}
          />
        )}
        {this.props.show === true &&
          isFillMode &&
          this.props.selectedItemInfo && (
            <div className="lux-checklist-sidebar__fill">
              <ItemChecklistInput
                handleUpdateChecklist={this.updateItemChecklistData}
                type={this.props.type}
                isSidebar={true}
                readOnly={false}
                permission={this.props.permission}
                checklistData={this.props.selectedItemInfo.checklistData}
                itemUserTeamId={this.props.selectedItemInfo.userTeamId}
              />
            </div>
          )}
      </LuxCreatePanelShell>
    );

    if (typeof document !== "undefined") {
      return createPortal(panel, document.body);
    }
    return panel;
  }
}

class ConfigureChecklistSidebarSection extends Component {
  constructor() {
    super();
    this.state = {
      checklistRequest: {},
      questionConfigureMode: true,
      editMode: true,
      filterText: "",
    };
  }

  componentDidMount() {
    store.dispatch(this.props.getAllChecklists({ itemType: this.props.type }));
    store.dispatch(appConfigActions.getAllTeams(false));
    this.resetToNewChecklist();
  }

  resetToNewChecklist = () => {
    this.setState({
      checklistRequest: {
        userTeamId: commonUtils.getCurrentUserTeamId(),
        type: this.props.type,
        questionDataList: [],
      },
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onNewChecklist = () => {
    this.props.onResetFormError();
    this.resetToNewChecklist();
  };

  addNewQuesiton = () => {
    const questionDataList = [
      ...(this.state.checklistRequest.questionDataList || []),
    ];
    questionDataList.push({
      index: questionDataList.length,
      id: Date.now(),
      question: "",
      type: "boolean",
      mandatory: false,
    });
    this.setState({
      checklistRequest: {
        ...this.state.checklistRequest,
        questionDataList,
      },
      questionConfigureMode: true,
      editMode: true,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.props.onFormError(fieldName, hasError);
  };

  onResetFormError = () => {
    this.props.onResetFormError();
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    this.setState({
      checklistRequest: {
        ...this.state.checklistRequest,
        [fieldName]: value,
      },
    });
  };

  togglequestionConfigureMode = (questionConfigureMode) => {
    this.setState({ questionConfigureMode });
  };

  onRestChecklist = () => {
    this.props.onResetFormError();
    this.resetToNewChecklist();
  };

  onSaveChecklist = () => {
    this.props.submitChecklist(this.state.checklistRequest);
  };

  applyChecklistToEditor = (checklistData, { editMode, questionConfigureMode }) => {
    this.props.onResetFormError();
    this.setState({
      checklistRequest: {
        ...checklistData,
        questionDataList: [...(checklistData.questionDataList || [])],
      },
      editMode,
      questionConfigureMode,
    });
  };

  onEditChecklist = (checklistData) => {
    this.applyChecklistToEditor(checklistData, {
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onDuplicateChecklist = (checklistData) => {
    const { id, ...checklistDataCopy } = checklistData;
    this.applyChecklistToEditor(checklistDataCopy, {
      editMode: true,
      questionConfigureMode: true,
    });
  };

  onSelectChecklist = (checklistData) => {
    this.applyChecklistToEditor(checklistData, {
      editMode: false,
      questionConfigureMode: false,
    });
  };

  onFilterTextChange = (filterText) => {
    this.setState({ filterText });
  };

  getFilteredChecklists = () => {
    const list = this.props.checklistDataList || [];
    const sorted = commonUtils.sortArrayOfObjects([...list], true);
    const q = (this.state.filterText || "").trim();
    if (!q) return sorted;
    return sorted.filter(
      (item) => item && commonUtils.stringContainsString(item.name, q)
    );
  };

  canSave = () => {
    const { permission } = this.props;
    const req = this.state.checklistRequest;
    if (!this.state.editMode) return false;
    if (!req.id) return permission.createEnabled;
    return permission.editEnabled;
  };

  render() {
    const filtered = this.getFilteredChecklists();
    const totalTemplates = (this.props.checklistDataList || []).length;
    const req = this.state.checklistRequest;
    const questionCount = countQuestions(req);
    const teamCount = countRestrictedTeams(req);
    const mode = getChecklistEditorMode(req, this.state.editMode);
    const canSave = this.canSave();

    return (
      <div className="lux-checklist-editor lux-checklist-editor--luxury">
        <div className="lux-checklist-editor__layout">
          <aside className="lux-checklist-editor__list-pane">
            <div className="lux-checklist-editor__list-head">
              <div className="lux-checklist-editor__list-title-row">
                <span className="lux-checklist-editor__list-label">
                  <i className="fe fe-check-square" aria-hidden="true" />
                  Templates
                </span>
                <span className="lux-checklist-editor__count">{totalTemplates}</span>
              </div>
              <div className="lux-checklist-editor__filter">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  placeholder="Search templates…"
                  value={this.state.filterText}
                  onChange={(e) => this.onFilterTextChange(e.target.value)}
                  aria-label="Filter templates"
                />
              </div>
              {this.props.permission.createEnabled && (
                <button
                  type="button"
                  className="lux-checklist-editor__new"
                  onClick={this.onNewChecklist}
                >
                  <i className="fe fe-plus" aria-hidden="true" />
                  New template
                </button>
              )}
            </div>
            <div className="lux-checklist-editor__list-body">
              {filtered.length > 0 ? (
                <ul className="lux-checklist-editor__list" role="list">
                  {filtered.map(
                    (checklistData) =>
                      checklistData && (
                        <ChecklistItem
                          key={checklistData.id}
                          selectedChecklistId={req.id}
                          handleRemoveChecklist={this.props.handleRemoveChecklist}
                          onEditChecklist={this.onEditChecklist}
                          onDuplicateChecklist={this.onDuplicateChecklist}
                          onSelectChecklist={this.onSelectChecklist}
                          permission={this.props.permission}
                          checklistData={checklistData}
                        />
                      )
                  )}
                </ul>
              ) : (
                <div className="lux-checklist-editor__list-empty">
                  <i className="fe fe-inbox" aria-hidden="true" />
                  <strong>No templates found</strong>
                  <span>
                    {this.state.filterText
                      ? "Try a different search or create a new template."
                      : "Create your first checklist template to get started."}
                  </span>
                  {this.props.permission.createEnabled && (
                    <button
                      type="button"
                      className="lux-checklist-editor__new is-inline"
                      onClick={this.onNewChecklist}
                    >
                      <i className="fe fe-plus" aria-hidden="true" />
                      New template
                    </button>
                  )}
                </div>
              )}
            </div>
          </aside>

          <div className="lux-checklist-editor__form-pane">
            <header
              className={classNames("lux-cl-hero", `lux-cl-hero--${mode.tone}`)}
              aria-label="Checklist editor status"
            >
              <div className="lux-cl-hero__glow" aria-hidden="true" />
              <div className="lux-cl-hero__inner">
                <div className="lux-cl-hero__main">
                  <div className="lux-cl-hero__badges">
                    <span
                      className={classNames(
                        "lux-cl-hero__mode-pill",
                        `is-${mode.tone}`
                      )}
                    >
                      <i className={`fe ${mode.icon}`} aria-hidden="true" />
                      {mode.kicker}
                    </span>
                  </div>
                  <h2 className="lux-cl-hero__title">{mode.title}</h2>
                  <p className="lux-cl-hero__subtitle">{mode.subtitle}</p>
                  <ul className="lux-cl-hero__chips" aria-label="Template summary">
                    <li className="lux-cl-hero__chip">
                      <i className="fe fe-help-circle" aria-hidden="true" />
                      {questionCount} question{questionCount === 1 ? "" : "s"}
                    </li>
                    <li className="lux-cl-hero__chip">
                      <i className="fe fe-users" aria-hidden="true" />
                      {teamCount > 0
                        ? `${teamCount} team${teamCount === 1 ? "" : "s"}`
                        : "All teams"}
                    </li>
                    {!this.state.editMode && req.id && (
                      <li className="lux-cl-hero__chip is-muted">
                        <i className="fe fe-lock" aria-hidden="true" />
                        Read-only
                      </li>
                    )}
                  </ul>
                </div>
                <div className="lux-cl-hero__aside">
                  {req.id && this.props.permission.createEnabled && (
                    <button
                      type="button"
                      className="lux-cl-hero__action"
                      onClick={this.onNewChecklist}
                      title="Start a new checklist template"
                    >
                      <i className="fe fe-plus" aria-hidden="true" />
                      New template
                    </button>
                  )}
                  {req.id && this.props.permission.editEnabled && !this.state.editMode && (
                    <button
                      type="button"
                      className="lux-cl-hero__action is-primary"
                      onClick={() => this.onEditChecklist(req)}
                    >
                      <i className="fe fe-edit-2" aria-hidden="true" />
                      Edit
                    </button>
                  )}
                </div>
              </div>
            </header>

            <section className="lux-checklist-editor__card">
              <header className="lux-checklist-editor__card-head">
                <i className="fe fe-file-text" aria-hidden="true" />
                <div>
                  <h3>Template details</h3>
                  <p>Name, description, and team restrictions.</p>
                </div>
              </header>
              <div className="lux-checklist-editor__card-body">
                <div className="lux-checklist-editor__grid">
                  <CustomInput
                    inputtype="text"
                    label="Name"
                    name="name"
                    fieldConfig={this.props.fieldConfig}
                    mappingObject={req}
                    onChange={this.onChange}
                    onFormError={this.onFormError}
                    placeholder="e.g. Project kickoff checklist"
                    datatype="alpnumspl"
                    readOnly={!this.state.editMode}
                  />
                  <CustomInput
                    label="Description"
                    name="description"
                    type="textarea"
                    height="72px"
                    fieldConfig={this.props.fieldConfig}
                    mappingObject={req}
                    onChange={this.onChange}
                    onFormError={this.onFormError}
                    placeholder="Optional summary for this template…"
                    datatype="alpnumspl"
                    readOnly={!this.state.editMode}
                  />
                  <div className="lux-checklist-editor__grid-full">
                    <CustomInput
                      type="select"
                      label="Restricted for user teams"
                      name="restrictedByUserTeamIds"
                      fieldConfig={this.props.fieldConfig}
                      mappingObject={req}
                      onChange={this.onChange}
                      placeholder="All teams (no restriction)"
                      options={
                        this.props.allUserTeams &&
                        commonUtils.convertObjectToSelectObject(
                          this.props.allUserTeams
                        )
                      }
                      onFormError={this.onFormError}
                      multi={true}
                      readOnly={!this.state.editMode}
                    />
                  </div>
                </div>
              </div>
            </section>

            <section className="lux-checklist-editor__card lux-checklist-editor__card--questions">
              <header className="lux-checklist-editor__card-head lux-checklist-editor__card-head--tools">
                <div>
                  <i className="fe fe-help-circle" aria-hidden="true" />
                  <h3>Questions</h3>
                  <span className="lux-checklist-editor__card-hint">
                    Build the checks teams complete on delivery work
                  </span>
                </div>
                {this.state.editMode && (
                  <div className="lux-checklist-editor__card-tools">
                    <button
                      type="button"
                      className="lux-checklist-editor__tool-btn is-accent"
                      title="Add question"
                      onClick={this.addNewQuesiton}
                    >
                      <i className="fe fe-plus" aria-hidden="true" />
                      Add question
                    </button>
                    <button
                      type="button"
                      className={classNames("lux-checklist-editor__tool-btn", {
                        "is-active": this.state.questionConfigureMode,
                      })}
                      title="Edit question fields and types"
                      onClick={() => this.togglequestionConfigureMode(true)}
                    >
                      <i className="fe fe-edit-3" aria-hidden="true" />
                      Configure
                    </button>
                    <button
                      type="button"
                      className={classNames("lux-checklist-editor__tool-btn", {
                        "is-active": !this.state.questionConfigureMode,
                      })}
                      title="Preview question list"
                      onClick={() => this.togglequestionConfigureMode(false)}
                    >
                      <i className="fe fe-list" aria-hidden="true" />
                      Preview
                    </button>
                  </div>
                )}
              </header>
              <div className="lux-checklist-editor__card-body lux-checklist-editor__questions-scroll">
                <QuestionaireTable
                  typeOptions={this.props.typeOptions}
                  onChange={this.onChange}
                  dragMode={true}
                  editMode={this.state.editMode}
                  questionConfigureMode={this.state.questionConfigureMode}
                  questionDataList={req.questionDataList}
                />
              </div>
            </section>

            {this.props.hasFormError && (
              <div className="lux-checklist-editor__error" role="alert">
                <i className="fe fe-alert-triangle" aria-hidden="true" />
                <span>
                  Please complete the mandatory fields and add at least one
                  question before saving.
                </span>
                <button
                  type="button"
                  className="lux-checklist-editor__error-dismiss"
                  onClick={() => this.onResetFormError()}
                  aria-label="Dismiss"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </div>
            )}

            <footer className="lux-checklist-editor__foot">
              <p className="lux-checklist-editor__foot-hint">
                Templates can be applied to projects, tasks, and work items where
                checklist is enabled.
              </p>
              <div className="lux-checklist-editor__foot-actions">
                <button
                  type="button"
                  className="lux-checklist-editor__btn is-ghost"
                  onClick={this.onRestChecklist}
                >
                  Reset
                </button>
                {canSave && (
                  <button
                    type="button"
                    className="lux-checklist-editor__btn is-primary"
                    onClick={this.onSaveChecklist}
                  >
                    <i className="fe fe-check" aria-hidden="true" />
                    {req.id ? "Save changes" : "Create template"}
                  </button>
                )}
              </div>
            </footer>
          </div>
        </div>
      </div>
    );
  }
}

class ChecklistItem extends Component {
  constructor() {
    super();
    this.state = {
      confrimDelete: false,
    };
  }

  handleRemoveChecklist = (isConfrimDelete) => {
    if (isConfrimDelete) {
      this.props.handleRemoveChecklist(this.props.checklistData.id);
      this.setState({ confrimDelete: false });
    } else {
      this.setState({ confrimDelete: true });
    }
  };

  render() {
    const { checklistData, permission } = this.props;
    const isSelected =
      this.props.selectedChecklistId &&
      this.props.selectedChecklistId === checklistData.id;
    const qCount =
      (checklistData.questionDataList && checklistData.questionDataList.length) ||
      0;

    return (
      <li
        className={classNames("lux-checklist-editor__item", {
          "is-selected": isSelected,
        })}
      >
        <div className="lux-checklist-editor__item-main">
          <button
            type="button"
            className="lux-checklist-editor__item-select"
            onClick={() => this.props.onSelectChecklist(checklistData)}
          >
            <span className="lux-checklist-editor__item-icon" aria-hidden="true">
              <i className="fe fe-check-square" />
            </span>
            <span className="lux-checklist-editor__item-copy">
              <span className="lux-checklist-editor__item-name">
                {checklistData.name || "Untitled checklist"}
              </span>
              <span className="lux-checklist-editor__item-meta">
                {qCount} question{qCount === 1 ? "" : "s"}
                {checklistData.description
                  ? ` · ${String(checklistData.description).slice(0, 42)}${
                      String(checklistData.description).length > 42 ? "…" : ""
                    }`
                  : ""}
              </span>
            </span>
          </button>
          <div className="lux-checklist-editor__item-actions">
            {permission.editEnabled === true && (
              <button
                type="button"
                className="lux-checklist-editor__item-action"
                title="Edit"
                aria-label="Edit"
                onClick={() => this.props.onEditChecklist(checklistData)}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            {permission.duplicateEnabled === true && (
              <button
                type="button"
                className="lux-checklist-editor__item-action"
                title="Duplicate"
                aria-label="Duplicate"
                onClick={() => this.props.onDuplicateChecklist(checklistData)}
              >
                <i className="fe fe-copy" aria-hidden="true" />
              </button>
            )}
            {permission.removeEnabled === true && !isSelected && (
              <button
                type="button"
                className={classNames(
                  "lux-checklist-editor__item-action",
                  "is-danger",
                  { blink_text: this.state.confrimDelete }
                )}
                title={
                  this.state.confrimDelete ? "Confirm remove" : "Remove"
                }
                aria-label={
                  this.state.confrimDelete ? "Confirm remove" : "Remove"
                }
                onClick={() =>
                  this.handleRemoveChecklist(this.state.confrimDelete)
                }
              >
                <i
                  className={`fe ${
                    this.state.confrimDelete ? "fe-check" : "fe-trash-2"
                  }`}
                  aria-hidden="true"
                />
              </button>
            )}
          </div>
        </div>
      </li>
    );
  }
}

const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  allUserTeams: state.appconfig.allTeams,
  allEmployees: state.employees.allEmployees,
  checklistDataList: state.checklist.items,
  fieldConfig: state.checklist.checklistFieldConfig,
  typeOptions: state.checklist.typeOptions,
});

const mapDispatchToProps = (dispatch) => ({
  getAllChecklists: checklistActions.getAllChecklists,
  createChecklist: checklistActions.createChecklist,
  updateChecklist: checklistActions.updateChecklist,
  removeChecklist: checklistActions.removeChecklist,
  activateChecklist: checklistActions.activateChecklist,
  updateItemChecklistData: checklistActions.updateItemChecklistData,
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(ConfigureChecklistSidebar);
