import React, { Component } from "react";
import CountUp from "react-countup";
import { store } from "_helpers";

/** Work item KPI strip — same shell as project deliverable summary stats */
export default class DeliverableDetailsSummaryStats extends Component {
  componentDidMount() {
    if (this.props.itemId && this.props.loadData) {
      store.dispatch(this.props.loadData(this.props.itemId));
    }
  }

  sum = (key) => {
    if (!this.props.items) return 0;
    return this.props.items.reduce((total, item) => total + (item[key] || 0), 0);
  };

  render() {
    const tiles = [
      {
        key: "completedCount",
        label: "Completed",
        hint: "Done or closed",
        tone: "mint",
        icon: "fe fe-check-circle",
      },
      {
        key: "inProgressCount",
        label: "In Progress",
        hint: "Active work",
        tone: "sky",
        icon: "fe fe-loader",
      },
      {
        key: "assignedCount",
        label: "Assigned",
        hint: "Queued for owners",
        tone: "violet",
        icon: "fe fe-user-check",
      },
      {
        key: "newCount",
        label: "New",
        hint: "Not started",
        tone: "sun",
        icon: "fe fe-star",
      },
    ];

    return (
      <section className="pd-summary-stats" aria-label="Work item status summary">
        {tiles.map((tile) => (
          <article key={tile.key} className={`pd-stat-tile pd-stat-tile--${tile.tone}`}>
            <span className="pd-stat-tile__icon" aria-hidden="true">
              <i className={tile.icon} />
            </span>
            <div className="pd-stat-tile__body">
              <span className="pd-stat-tile__value">
                <CountUp end={this.sum(tile.key)} duration={0.8} />
              </span>
              <span className="pd-stat-tile__label">{tile.label}</span>
              <span className="pd-stat-tile__hint">{tile.hint}</span>
            </div>
          </article>
        ))}
      </section>
    );
  }
}
