/**
 * EH02 — Offer master FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseOfferApi } from "config/offer-requisition.config";

export const offerService = {
  listOffers,
  createOffer,
  acceptOffer,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

async function listOffers() {
  if (!shouldUseOfferApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(urlConfig.OFFERS_API_PATH, {
      userTeamId: resolveUserTeamId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[Offer] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function createOffer(body = {}) {
  if (!shouldUseOfferApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.post(urlConfig.OFFERS_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || commonUtils.getCurrentUserId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[Offer] create unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

/**
 * HR-ONB-005 — Accept offer → onboarding case (idempotent).
 */
async function acceptOffer(offerRef, body = {}) {
  if (!shouldUseOfferApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  if (!offerRef) {
    return { ...API_ERROR, reason: "missing-offer-ref" };
  }
  try {
    const response = await axiosUtils.post(`${urlConfig.OFFERS_API_PATH}/${encodeURIComponent(offerRef)}/accept`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || commonUtils.getCurrentUserId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[Offer] accept unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
