import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import LuxPageHeaderPopoverPortal from "./LuxPageHeaderPopoverPortal";

class PageInnerHeaderTeamsSelectionMenu extends PureComponent {
  constructor() {
    super();
    this.state = {
      showTeamPanel: false,
      selectedUserTeamsIds: [],
      teamFilterText: "",
      selectAll: false,
    };
    this.teamTriggerRef = React.createRef();
    this.teamPanelRef = React.createRef();
  }

  componentDidMount() {
    this.initializeUserTeamIds();
    document.addEventListener("mousedown", this.handleOutsideClick, true);
  }

  getTeamSelectionKey = (teams) => {
    if (!teams || !teams.length) return "";
    return teams
      .filter((team) => team.isChecked)
      .map((team) => String(team.id))
      .sort()
      .join(",");
  };

  componentDidUpdate(prevProps) {
    if (
      !this.state.showTeamPanel &&
      this.getTeamSelectionKey(prevProps.userTeams) !==
        this.getTeamSelectionKey(this.props.userTeams)
    ) {
      this.initializeUserTeamIds();
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick, true);
  }

  handleOutsideClick = (event) => {
    if (!this.state.showTeamPanel) return;
    const panel = this.teamPanelRef.current;
    const trigger = this.teamTriggerRef.current;
    if (trigger && trigger.contains(event.target)) return;
    if (panel && panel.contains(event.target)) return;
    this.closeTeamPanel();
  };

  initializeUserTeamIds = () => {
    const selectedIds =
      this.props.userTeams &&
      this.props.userTeams.map((userItem) => ({
        id: userItem.id,
        name: userItem.name,
        isChecked: !!userItem.isChecked,
        default: userItem.default,
      }));

    this.setState({ selectedUserTeamsIds: selectedIds || [] });
  };

  getSelectedTeamCount = () =>
    (this.state.selectedUserTeamsIds || []).filter((item) => item.isChecked).length;

  getTotalTeamCount = () => (this.state.selectedUserTeamsIds || []).length;

  toggleTeamPanel = () => {
    if (this.props.isLoading) return;
    if (this.state.showTeamPanel) {
      this.closeTeamPanel();
      return;
    }
    this.initializeUserTeamIds();
    this.setState({ showTeamPanel: true, teamFilterText: "" });
  };

  closeTeamPanel = () => {
    this.initializeUserTeamIds();
    this.setState({ showTeamPanel: false, teamFilterText: "", selectAll: false });
  };

  applyTeamSelection = () => {
    const selectedUserTeamsIds = this.state.selectedUserTeamsIds;
    if (!selectedUserTeamsIds.filter((item) => item.isChecked).length) return;
    this.props.handleUserTeamsSelection(selectedUserTeamsIds);
    this.setState({ showTeamPanel: false, teamFilterText: "", selectAll: false });
  };

  onSelectAllTeams = (event) => {
    this.setState({
      selectAll: event.target.checked,
      selectedUserTeamsIds: this.state.selectedUserTeamsIds.map((userItem) => ({
        ...userItem,
        isChecked: event.target.checked,
      })),
    });
  };

  onTeamCheckChange = (event) => {
    const teamId = event.target.value;
    const isChecked = event.target.checked;
    const singleSelection = this.props.enableSingleSelection === true;

    this.setState((prevState) => {
      const selectedUserTeamsIds = prevState.selectedUserTeamsIds.map((userItem) => {
        if (String(userItem.id) === String(teamId)) {
          return { ...userItem, isChecked };
        }
        if (singleSelection && isChecked) {
          return { ...userItem, isChecked: false };
        }
        return userItem;
      });

      return {
        selectedUserTeamsIds,
        selectAll:
          !singleSelection &&
          selectedUserTeamsIds.length > 0 &&
          selectedUserTeamsIds.every((item) => item.isChecked),
      };
    });
  };

  onTeamFilterChange = (event) => {
    this.setState({ teamFilterText: event.target.value });
  };

  render() {
    const { userTeams, enabled, isLoading } = this.props;
    const canSwitch = enabled && userTeams && userTeams.length > 1;

    if (!canSwitch) return null;

    const selectedCount = this.getSelectedTeamCount();
    const totalCount = this.getTotalTeamCount();
    const filteredTeams = this.state.selectedUserTeamsIds.filter(
      (team) =>
        !this.state.teamFilterText ||
        commonUtils.stringContainsString(team.name, this.state.teamFilterText)
    );

    return (
      <div className="lux-page-header__team-wrap" ref={this.teamTriggerRef}>
        <button
          type="button"
          className={classNames("lux-page-header__team-btn", {
            "is-open": this.state.showTeamPanel,
          })}
          onClick={this.toggleTeamPanel}
          disabled={isLoading}
          aria-expanded={this.state.showTeamPanel}
          title="Select teams"
        >
          <i className="fe fe-briefcase" aria-hidden="true" />
          <span>Teams</span>
          <span className="lux-page-header__team-count">{selectedCount}</span>
        </button>

        {this.state.showTeamPanel && (
          <LuxPageHeaderPopoverPortal
            isOpen={this.state.showTeamPanel}
            anchorRef={this.teamTriggerRef}
            align="left"
            popoverRef={this.teamPanelRef}
            className="lux-page-header__team-panel"
          >
            <header className="lux-page-header__team-panel-head">
              <div className="lux-page-header__team-panel-head-main">
                <span className="lux-page-header__team-panel-icon" aria-hidden="true">
                  <i className="fe fe-layers" />
                </span>
                <div>
                  <span className="lux-page-header__team-panel-eyebrow">Scope</span>
                  <strong>Select teams</strong>
                  <span className="lux-page-header__team-panel-meta">
                    {selectedCount} of {totalCount} teams selected
                  </span>
                </div>
              </div>
              <button
                type="button"
                className="lux-page-header__team-panel-close"
                onClick={this.closeTeamPanel}
                aria-label="Close team selector"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </header>

            <div className="lux-page-header__team-panel-body">
              <label className="lux-page-header__team-search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  value={this.state.teamFilterText}
                  onChange={this.onTeamFilterChange}
                  placeholder="Search teams..."
                />
              </label>

              {!this.props.enableSingleSelection && (
                <label className="lux-page-header__team-all">
                  <input
                    type="checkbox"
                    className="lux-page-header__team-checkbox"
                    checked={this.state.selectAll}
                    onChange={this.onSelectAllTeams}
                    disabled={isLoading}
                  />
                  <span className="lux-page-header__team-all-label">Select all teams</span>
                </label>
              )}

              <ul className="lux-page-header__team-list">
                {filteredTeams.length > 0 ? (
                  filteredTeams.map((team) => (
                    <li key={team.id}>
                      <label
                        className={classNames("lux-page-header__team-item", {
                          "is-selected": team.isChecked,
                        })}
                      >
                        <input
                          type="checkbox"
                          className="lux-page-header__team-checkbox"
                          checked={team.isChecked}
                          onChange={this.onTeamCheckChange}
                          value={team.id}
                          disabled={isLoading}
                        />
                        <span className="lux-page-header__team-item-mark" aria-hidden="true">
                          <i className="fe fe-check" />
                        </span>
                        <span className="lux-page-header__team-item-name">{team.name}</span>
                      </label>
                    </li>
                  ))
                ) : (
                  <li className="lux-page-header__team-empty">No teams match your search.</li>
                )}
              </ul>
            </div>

            <footer className="lux-page-header__team-footer">
              <button type="button" className="lux-page-header__team-cancel" onClick={this.closeTeamPanel}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-page-header__team-apply"
                onClick={this.applyTeamSelection}
                disabled={selectedCount === 0}
              >
                Apply selection
              </button>
            </footer>
          </LuxPageHeaderPopoverPortal>
        )}
      </div>
    );
  }
}

export default PageInnerHeaderTeamsSelectionMenu;
