/**
 * App Config Guide — search/group for feature flags + org settings catalogs.
 */
import {
  APP_CONFIG_FLAG_GUIDE,
  FLAG_GUIDE_FEATURE_AREAS,
  flagGuideKeyPath,
  getFlagGuideById,
} from "./app-config-flag-guide.config";
import {
  APP_CONFIG_ORG_GUIDE,
  ORG_GUIDE_FEATURE_AREAS,
  getOrgGuideById,
  orgGuideKeyPath,
} from "./app-config-org-guide.config";
import { getTracopusPilotOrgFlags } from "config/tracopus-pilot.config";
import { isTimesheetApprovalOrgEnabled } from "_helpers/timesheetApproval.config";
import { accessUtils } from "_helpers";

export const CONFIG_GUIDE_MODES = {
  FLAGS: "flags",
  ORG: "org",
};

function normalizeQuery(query) {
  return String(query || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function entryKeyPath(entry) {
  if (!entry) return "";
  if (entry.module) {
    return orgGuideKeyPath(entry);
  }
  return flagGuideKeyPath(entry);
}

function entrySearchBlob(entry) {
  return [
    entry.name,
    entry.key,
    entry.group,
    entry.module,
    entry.kind,
    entryKeyPath(entry),
    entry.description,
    entry.audience,
    entry.whereUsed,
    entry.whenEnabled,
    entry.whenDisabled,
    entry.configPathHint,
    entry.whereToSet,
    entry.featureArea,
    entry.scope,
    ...(entry.pages || []),
    ...(entry.keywords || []),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

/**
 * Score an entry against a search query (higher is better).
 */
export function scoreFlagGuideEntry(entry, query) {
  const q = normalizeQuery(query);
  if (!q) {
    return 1;
  }
  const tokens = q.split(" ").filter(Boolean);
  const blob = entrySearchBlob(entry);
  if (!tokens.every((token) => blob.includes(token))) {
    return 0;
  }
  let score = 10;
  const name = String(entry.name || "").toLowerCase();
  const key = String(entry.key || "").toLowerCase();
  const path = entryKeyPath(entry).toLowerCase();
  if (name === q || key === q || path === q) score += 100;
  if (name.startsWith(q) || key.startsWith(q)) score += 40;
  if (name.includes(q)) score += 25;
  if (key.includes(q) || path.includes(q)) score += 20;
  (entry.keywords || []).forEach((kw) => {
    if (String(kw).toLowerCase().includes(q)) score += 15;
  });
  (entry.pages || []).forEach((page) => {
    if (String(page).toLowerCase().includes(q)) score += 12;
  });
  return score;
}

export function searchFlagGuide(query, options = {}) {
  const area = options.featureArea && options.featureArea !== "ALL" ? options.featureArea : null;
  const scope = options.scope || null;
  const catalog = options.catalog || APP_CONFIG_FLAG_GUIDE;

  return catalog
    .filter((entry) => {
      if (area && entry.featureArea !== area) return false;
      if (scope && entry.scope !== scope) return false;
      if (options.kind && entry.kind && entry.kind !== options.kind) return false;
      return scoreFlagGuideEntry(entry, query) > 0;
    })
    .map((entry) => ({ entry, score: scoreFlagGuideEntry(entry, query) }))
    .sort((a, b) => b.score - a.score || a.entry.name.localeCompare(b.entry.name))
    .map((row) => row.entry);
}

export function searchOrgGuide(query, options = {}) {
  return searchFlagGuide(query, {
    ...options,
    catalog: options.catalog || APP_CONFIG_ORG_GUIDE,
  });
}

function groupEntries(entries, areaDefs) {
  const order = (areaDefs || []).filter((a) => a.id !== "ALL").map((a) => a.id);
  const groups = new Map();
  (entries || []).forEach((entry) => {
    const area = entry.featureArea || "Other";
    if (!groups.has(area)) groups.set(area, []);
    groups.get(area).push(entry);
  });
  const sortedAreas = [
    ...order.filter((id) => groups.has(id)),
    ...[...groups.keys()].filter((id) => !order.includes(id)).sort(),
  ];
  return sortedAreas.map((id) => ({
    id,
    label: (areaDefs.find((a) => a.id === id) || {}).label || id,
    icon: (areaDefs.find((a) => a.id === id) || {}).icon || "fe fe-book-open",
    entries: groups.get(id) || [],
  }));
}

export function groupFlagGuideEntries(entries) {
  return groupEntries(entries, FLAG_GUIDE_FEATURE_AREAS);
}

export function groupOrgGuideEntries(entries) {
  return groupEntries(entries, ORG_GUIDE_FEATURE_AREAS);
}

export function resolveRelatedFlags(entry, catalog = APP_CONFIG_FLAG_GUIDE) {
  if (!entry || !Array.isArray(entry.relatedFlagIds)) {
    return [];
  }
  return entry.relatedFlagIds
    .map((id) => {
      const fromCatalog = (catalog || []).find((row) => row.id === id);
      if (fromCatalog) return fromCatalog;
      const fromFlags = getFlagGuideById(id);
      if (fromFlags) return fromFlags;
      return getOrgGuideById(id);
    })
    .filter(Boolean);
}

function readNestedFlag(root, path) {
  if (!root || !path) return undefined;
  const parts = String(path).split(".");
  let cur = root;
  for (const part of parts) {
    if (cur == null || typeof cur !== "object") return undefined;
    cur = cur[part];
  }
  return cur;
}

/**
 * Best-effort live On/Off for the current session. Returns null when unknown.
 */
export function resolveFlagGuideLiveStatus(entry) {
  if (!entry) return null;
  try {
    if (entry.orgPilotKey === "timesheetApprovalEnabled" || entry.key === "timesheetApprovalEnabled") {
      return isTimesheetApprovalOrgEnabled() === true;
    }
    const pilotKey = entry.orgPilotKey || (entry.kind === "flag" ? entry.key : null);
    if (pilotKey) {
      const flags = getTracopusPilotOrgFlags() || {};
      if (Object.prototype.hasOwnProperty.call(flags, pilotKey)) {
        return flags[pilotKey] === true;
      }
    }
    if (entry.roleModuleKey && accessUtils && typeof accessUtils.getMenuAccessControl === "function") {
      const menu = accessUtils.getMenuAccessControl() || {};
      const value = readNestedFlag(menu, entry.roleModuleKey);
      if (typeof value === "boolean") {
        return value;
      }
    }
  } catch (e) {
    return null;
  }
  return null;
}

export function enrichFlagGuideEntry(entry) {
  if (!entry) return null;
  const liveEnabled = resolveFlagGuideLiveStatus(entry);
  return {
    ...entry,
    keyPath: entryKeyPath(entry),
    liveEnabled,
    related: resolveRelatedFlags(entry),
  };
}

export function enrichOrgGuideEntry(entry) {
  if (!entry) return null;
  const liveEnabled = entry.kind === "flag" ? resolveFlagGuideLiveStatus(entry) : null;
  return {
    ...entry,
    keyPath: orgGuideKeyPath(entry),
    liveEnabled,
    related: resolveRelatedFlags(entry, [
      ...APP_CONFIG_FLAG_GUIDE,
      ...APP_CONFIG_ORG_GUIDE,
    ]),
  };
}

export function buildFlagGuideViewModel(query, options = {}) {
  const matches = searchFlagGuide(query, options).map(enrichFlagGuideEntry);
  return {
    mode: CONFIG_GUIDE_MODES.FLAGS,
    query: normalizeQuery(query),
    featureArea: options.featureArea || "ALL",
    total: matches.length,
    groups: groupFlagGuideEntries(matches),
    entries: matches,
    itemLabel: "flag",
    areas: FLAG_GUIDE_FEATURE_AREAS,
  };
}

export function buildOrgGuideViewModel(query, options = {}) {
  const matches = searchOrgGuide(query, options).map(enrichOrgGuideEntry);
  return {
    mode: CONFIG_GUIDE_MODES.ORG,
    query: normalizeQuery(query),
    featureArea: options.featureArea || "ALL",
    total: matches.length,
    groups: groupOrgGuideEntries(matches),
    entries: matches,
    itemLabel: "setting",
    areas: ORG_GUIDE_FEATURE_AREAS,
  };
}

/** Unified view model for Config guide tabs. */
export function buildConfigGuideViewModel(query, options = {}) {
  const mode = options.mode === CONFIG_GUIDE_MODES.ORG ? CONFIG_GUIDE_MODES.ORG : CONFIG_GUIDE_MODES.FLAGS;
  if (mode === CONFIG_GUIDE_MODES.ORG) {
    return buildOrgGuideViewModel(query, options);
  }
  return buildFlagGuideViewModel(query, options);
}
