import React from "react";

const INSIGHTS = [
  { key: "completed", label: "Completed tasks", icon: "fe-check-square" },
  { key: "overdue", label: "Overdue", icon: "fe-clock" },
  { key: "template", label: "Template", icon: "fe-layers" },
  { key: "owner", label: "Case owner", icon: "fe-user" },
];

function LifecycleInsightStrip({ progress, caseData }) {
  const values = {
    completed: progress ? `${progress.completed}/${progress.total}` : "—",
    overdue: progress ? progress.overdue : "—",
    template: (caseData && caseData.templateName) || "—",
    owner: (caseData && caseData.owner) || "—",
  };

  return (
    <div className="lux-onb-insight-strip">
      {INSIGHTS.map((item) => (
        <article key={item.key} className="lux-onb-insight">
          <span className="lux-onb-insight__icon" aria-hidden>
            <i className={`fe ${item.icon}`} />
          </span>
          <div>
            <span className="lux-onb-insight__label">{item.label}</span>
            <strong className="lux-onb-insight__value">{values[item.key]}</strong>
          </div>
        </article>
      ))}
    </div>
  );
}

export default LifecycleInsightStrip;
