  "LEAVE",
  "TIMESHEET",
  "ATTENDANCE",
  "ATTENDANCE_REGULARIZATION",
  "ONBOARDING",
  "OFFBOARDING",
  "DOCUMENT",
  "EXPENSE",
  "PAYROLL_RUN",
