import {
  WORKFLOW_ACTION_TYPES,
  WORKFLOW_RULE_STATUSES,
  WORKFLOW_RUN_STATUSES,
  WORKFLOW_TRIGGER_TYPES,
} from "config/workflow-automation.config";

export function normalizeWorkflowRule(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    name: row.name || "Untitled rule",
    description: row.description || "",
    status: row.status || WORKFLOW_RULE_STATUSES.DRAFT,
    triggerType: row.triggerType || "",
    triggerLabel: row.triggerLabel || row.triggerType || "",
    conditions: row.conditions || [],
    actions: row.actions || [],
    successRate: Number(row.successRate) || 0,
    runCount: Number(row.runCount) || 0,
    manualMinutesSaved: Number(row.manualMinutesSaved) || 0,
    lastRunAt: row.lastRunAt || null,
    ownerName: row.ownerName || "",
    publishedAt: row.publishedAt || null,
    tone: row.tone || "indigo",
  };
}

export function normalizeWorkflowRun(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    ruleId: row.ruleId,
    ruleName: row.ruleName || "",
    status: row.status || WORKFLOW_RUN_STATUSES.RUNNING,
    startedAt: row.startedAt || null,
    completedAt: row.completedAt || null,
    durationMs: Number(row.durationMs) || 0,
    stepsExecuted: Number(row.stepsExecuted) || 0,
    errorMessage: row.errorMessage || "",
    debugLog: row.debugLog || [],
    tone: row.tone || "slate",
  };
}

export function filterWorkflowRules(rows, filters) {
  const list = (rows || []).map(normalizeWorkflowRule).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    if (f.triggerType && f.triggerType !== "ALL" && row.triggerType !== f.triggerType) {
      return false;
    }
    if (f.query) {
      const q = String(f.query).toLowerCase();
      const hay = `${row.name} ${row.description} ${row.triggerLabel}`.toLowerCase();
      if (hay.indexOf(q) === -1) {
        return false;
      }
    }
    return true;
  });
}

export function filterWorkflowRuns(rows, filters) {
  const list = (rows || []).map(normalizeWorkflowRun).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    if (f.ruleId && row.ruleId !== f.ruleId) {
      return false;
    }
    return true;
  });
}

export function buildWorkflowKpiCards(rules, runs) {
  const ruleList = (rules || []).map(normalizeWorkflowRule).filter(Boolean);
  const runList = (runs || []).map(normalizeWorkflowRun).filter(Boolean);
  const published = ruleList.filter((r) => r.status === WORKFLOW_RULE_STATUSES.PUBLISHED).length;
  const successRuns = runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.SUCCESS).length;
  const failedRuns = runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.FAILED).length;
  const minutesSaved = ruleList.reduce((sum, r) => sum + r.manualMinutesSaved, 0);

  return [
    { id: "published", label: "Published rules", value: published, hint: `${ruleList.length} total`, tone: "violet", icon: "fe fe-check-circle" },
    { id: "runs", label: "Runs (7d)", value: runList.length, hint: `${successRuns} success`, tone: "indigo", icon: "fe fe-activity" },
    { id: "failures", label: "Failures", value: failedRuns, hint: "Needs review", tone: failedRuns ? "rose" : "emerald", icon: "fe fe-alert-triangle" },
    { id: "saved", label: "Manual min saved", value: minutesSaved, hint: "Estimated per week", tone: "emerald", icon: "fe fe-clock" },
  ];
}

export function buildWorkflowInsights(rules, runs) {
  const ruleList = (rules || []).map(normalizeWorkflowRule).filter(Boolean);
  const runList = (runs || []).map(normalizeWorkflowRun).filter(Boolean);
  const insights = [];

  const paused = ruleList.filter((r) => r.status === WORKFLOW_RULE_STATUSES.PAUSED);
  if (paused.length) {
    insights.push({
      id: "paused-rules",
      tone: "amber",
      icon: "fe fe-pause-circle",
      title: `${paused.length} rule(s) paused`,
      copy: "Review paused automations before month-end compliance freeze.",
    });
  }

  const failed = runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.FAILED);
  if (failed.length) {
    insights.push({
      id: "failed-runs",
      tone: "rose",
      icon: "fe fe-alert-circle",
      title: `${failed.length} failed run(s)`,
      copy: "Open run history to inspect connector and notification action errors.",
    });
  }

  const drafts = ruleList.filter((r) => r.status === WORKFLOW_RULE_STATUSES.DRAFT);
  if (drafts.length) {
    insights.push({
      id: "draft-rules",
      tone: "indigo",
      icon: "fe fe-edit-3",
      title: `${drafts.length} draft rule(s)`,
      copy: "Publish after admin review — AI suggestions require explicit approval.",
    });
  }

  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "emerald",
      icon: "fe fe-check",
      title: "Automation health on track",
      copy: "Published rules are executing within SLA with no open failures.",
    });
  }

  return insights;
}

export function buildWorkflowAnalytics(rules, runs) {
  const runList = (runs || []).map(normalizeWorkflowRun).filter(Boolean);
  const ruleList = (rules || []).map(normalizeWorkflowRule).filter(Boolean);
  const byTrigger = {};
  ruleList.forEach((rule) => {
    const key = rule.triggerLabel || rule.triggerType || "Other";
    byTrigger[key] = (byTrigger[key] || 0) + 1;
  });

  const successCount = runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.SUCCESS).length;
  const failedCount = runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.FAILED).length;
  const total = runList.length || 1;

  return {
    successRate: Math.round((successCount / total) * 100),
    failureRate: Math.round((failedCount / total) * 100),
    triggerDistribution: Object.keys(byTrigger).map((label) => ({
      label,
      count: byTrigger[label],
    })),
    recentFailures: runList.filter((r) => r.status === WORKFLOW_RUN_STATUSES.FAILED).slice(0, 5),
  };
}

export function buildWorkflowAiSuggestion(rules) {
  const ruleList = (rules || []).map(normalizeWorkflowRule).filter(Boolean);
  const hasSlaRule = ruleList.some((r) => r.triggerType === WORKFLOW_TRIGGER_TYPES.TICKET_SLA_BREACHED);
  const suggestions = [];

  if (!hasSlaRule) {
    suggestions.push({
      name: "Escalate breached SLA tickets",
      triggerType: WORKFLOW_TRIGGER_TYPES.TICKET_SLA_BREACHED,
      triggerLabel: "Ticket SLA breached",
      description: "Notify assignee manager and post to Slack when P1/P2 tickets breach SLA.",
      conditions: [{ field: "priority", operator: "in", value: "P1,P2" }],
      actions: [
        { type: WORKFLOW_ACTION_TYPES.NOTIFY, label: "Notify manager" },
        { type: WORKFLOW_ACTION_TYPES.CONNECTOR, label: "Post to Slack #ops" },
      ],
      confidence: 0.82,
    });
  }

  suggestions.push({
    name: "Route overdue approvals",
    triggerType: WORKFLOW_TRIGGER_TYPES.APPROVAL_OVERDUE,
    triggerLabel: "Approval overdue",
    description: "Re-route approvals past SLA to delegate approver and send reminder.",
    conditions: [{ field: "hoursOverdue", operator: "gte", value: "24" }],
    actions: [
      { type: WORKFLOW_ACTION_TYPES.APPROVAL_ROUTE, label: "Route to delegate" },
      { type: WORKFLOW_ACTION_TYPES.NOTIFY, label: "Send reminder" },
    ],
    confidence: 0.76,
  });

  return {
    summary: "AI analyzed approval, ticket, and integration patterns to suggest high-impact automations.",
    suggestions,
    disclaimer: "Suggestions require admin publish — no auto-deployment.",
  };
}

export function exportWorkflowRulesCsv(rules) {
  const header = "Name,Status,Trigger,Runs,Success %,Owner";
  const lines = (rules || []).map((row) => {
    const r = normalizeWorkflowRule(row);
    return [
      r.name,
      r.status,
      r.triggerLabel,
      r.runCount,
      r.successRate,
      r.ownerName,
    ].join(",");
  });
  return [header].concat(lines).join("\n");
}
